 width:auto!important;min-width:0!important;height:auto!important;min-height:124px!important;max-height:none!important;margin:0!important;padding:12px 12px 0!important;overflow:hidden!important;
 background:#fff!important;border:1px solid var(--tl)!important;border-top:4px solid var(--tc)!important;border-radius:14px!important;
 box-shadow:0 1px 2px rgba(7,42,20,.05),0 4px 12px rgba(7,42,20,.05)!important;backdrop-filter:none!important;transition:box-shadow .15s,transform .15s}
