function lifeCcApplyFinalDesktopArrangement(){
 const tabs=[
  byId("tb1"),
  byId("tb2"),
  byId("tb3"),
  byId("tb4")
 ].filter(Boolean);

 /*
  * Keep all four main report tabs on exactly one row.
  */
 if(tabs.length===4){
  const parent=tabs[0].parentElement;

  if(
   parent&&
   tabs.every(tab=>tab.parentElement===parent)
  ){
   parent.classList.add(
    "life-main-tabs-one-row"
   );
  }
 }

 /*
  * Keep Branch report quick filters / view toggle / Print button
  * in one compact desktop row.
  */
 const today=byId("ccQuickToday");

 if(today){
  const row=
   today.closest(".cc-filter-action-row")||
   today.parentElement;

  if(row){
   row.classList.add(
    "life-cc-actions-final-row"
   );
  }
 }

 const viewGroup=
  byId("gB")
   ?byId("gB").closest(".grp")
   :null;

 if(viewGroup){
  viewGroup.classList.add(
   "life-cc-view-final"
  );
 }

 /*
  * Re-apply after Consultant rerenders.
  */
 lifeCcFixOneLineLayout();
}

