function ensureLifeCcPopupShell(){
 let overlay=byId("ovl");
 let title=byId("mT");
 let body=byId("mB");

 if(overlay&&title&&body){
  return {
   overlay:overlay,
   title:title,
   body:body
  };
 }

 /*
  * Older/minimal dashboard HTML versions may not include the
  * shared details modal. Create it automatically when required.
  */
 if(overlay){
  overlay.remove();
 }

 overlay=document.createElement("div");
 overlay.className="ovl";
 overlay.id="ovl";
 overlay.setAttribute("role","dialog");
 overlay.setAttribute("aria-modal","true");
 overlay.setAttribute("aria-labelledby","mT");

 overlay.innerHTML=`
  <div class="modal">
   <div class="m-hd">
    <h4 id="mT">—</h4>
    <button
     type="button"
     class="m-x"
     aria-label="Close details"
    >✕</button>
   </div>
