/* ===== Lead appointment-status mapping =====
 * Supports LIFE values plus common spelling/separator variations.
 * Falls back to Lead.status when custom_appointment_status is blank.
 */
const CATS=[
 "Visited – Booked",
 "Visited – Not Booked",
 "Not Visited",
 "Scheduled / Awaiting Visit",
 "Not Booked",
 "Cancelled",
 "Other / Not Set",
 "Visited"
];

function normalizeAppointmentStatus(value){
 return String(value||"")
  .trim()
  .toLowerCase()
  .replace(/&/g," and ")
  .replace(/[–—_-]+/g," ")
  .replace(/[\/]+/g," ")
  .replace(/\s+/g," ");
}

function mapCat(status){
 const value=normalizeAppointmentStatus(status);

 if(!value)return CATS[6];

 if([
  "visited booked",
  "visited and booked",
  "booked visited",
  "booked and visited"
 ].includes(value))return CATS[0];

 if(value==="visited")return CATS[7];

 if([
  "visited not booked",
  "visited and not booked",
  "visited unbooked",
  "not booked visited"
 ].includes(value))return CATS[1];

 if([
  "not visited",
  "no show",
  "no visit",
  "did not visit"
 ].includes(value))return CATS[2];

 if([
  "booked",
  "appointment booked",
  "scheduled",
  "appointment scheduled",
  "confirmed",
  "re confirm",
  "reconfirmed",
  "awaiting visit",
  "open",
  "pending"
 ].includes(value))return CATS[3];

 if([
  "not booked",
  "unbooked",
  "appointment not booked"
 ].includes(value))return CATS[4];

 if([
  "cancelled",
  "canceled",
  "appointment cancelled",
  "appointment canceled"
 ].includes(value))return CATS[5];

 return CATS[6];
}

function bookLabel(status){
 const cat=mapCat(status);

 /*
  * Booking Status is separate from Visit Status.
  */
 if(cat===CATS[0])return "BOOKED";
 if(cat===CATS[1])return "NOT BOOKED";
 if(cat===CATS[7])return "PENDING";
 if(cat===CATS[2])return "NO SHOW";
 if(cat===CATS[3])return "AWAITING";
 if(cat===CATS[4])return "NOT BOOKED";
 if(cat===CATS[5])return "CANCELLED";

 return "NOT SET";
}

