function lifeCc3mRange(endIso){
 /*
  * IMPORTANT:
  * Last 3 Months cards are GLOBAL rolling cards.
  * They must NEVER follow the selected report date filter.
  *
  * Always anchor the range to TODAY.
  * Example on 16-Sep-2026:
  *   17-Jun-2026 → 16-Sep-2026
  */
 const end=ccDateFromISO(
  String(TODAY)
 );

 const start=new Date(
  end.getFullYear(),
  end.getMonth()-3,
  end.getDate()+1
 );

 return {
  from:ccISOFromDate(start),
  to:ccISOFromDate(end)
 };
}

async function lifeCcEnsure3mAppointments(endIso){
 const range=lifeCc3mRange(endIso);
 const key=range.from+"|"+range.to;

 if(LIFE_CC_3M_APPOINTMENT_CACHE.has(key)){
  return LIFE_CC_3M_APPOINTMENT_CACHE.get(key);
 }

 if(LIFE_CC_3M_APPOINTMENT_PROMISES.has(key)){
  return LIFE_CC_3M_APPOINTMENT_PROMISES.get(key);
 }

 const promise=(async()=>{
  try{
   const raw=await fetchLeads(range.from,range.to);
   const unique=[
    ...new Map(
     (raw||[])
      .filter(row=>row&&row.name)
      .map(row=>[row.name,row])
    ).values()
   ];

   const records=unique.map(leadRowToRecord);

   const result={range,records};
   LIFE_CC_3M_APPOINTMENT_CACHE.set(key,result);

   setTimeout(lifeCcRefresh3mFunnelCards,0);

   return result;
  }catch(error){
   console.warn("Last 3 Months funnel load failed",error);
   const result={range,records:[],error:true};
   LIFE_CC_3M_APPOINTMENT_CACHE.set(key,result);
   return result;
  }finally{
   LIFE_CC_3M_APPOINTMENT_PROMISES.delete(key);
  }
 })();

 LIFE_CC_3M_APPOINTMENT_PROMISES.set(key,promise);
 return promise;
}

function lifeCc3mScopedRecords(endIso,opts){
 opts=opts||{};
 const range=lifeCc3mRange(endIso);
 const key=range.from+"|"+range.to;
 const cached=LIFE_CC_3M_APPOINTMENT_CACHE.get(key);

 if(!cached){
  lifeCcEnsure3mAppointments(endIso);
  return null;
 }

 const agent=String(opts.agent||"").trim();
 const branch=String(opts.branch||"").trim();

 return (cached.records||[]).filter(record=>{
  if(!record)return false;

  if(
   agent&&
   !sameAgentOwner(
    record.agent||record.lead_owner,
    agent
   )
  ){
   return false;
  }

  if(
   branch&&
   normalizedBranchKey(
    record.br||
    record.consultantReportBranch||
    ""
   )!==normalizedBranchKey(branch)
  ){
   return false;
  }

  return true;
 });
}

