const LIFE_CC_FUNNEL_JUNK_LEAD_STATUSES=new Set([
 "do not contact","not enquired","nid","wrong number",
 "job enquiry","other clinic","existing client"
]);
const LIFE_CC_FUNNEL_JUNK_CC_SUB_STATUSES=new Set([
 "invalid number","junk/wrong call","existing client","wrong number",
 "job enquiry","other clinic","not enquired","do not contact","nid"
]);
const LIFE_CC_FUNNEL_CONNECTED_LEAD_STATUSES=new Set([
 "replied","opportunity","quotation","lost quotation","interested",
 "converted","call back","get back","consultation done",
 "appointment booked","joined","not interested","existing client",
 "followup","do not contact"
]);
const LIFE_CC_FUNNEL_CONNECTED_CC_SUB_STATUSES=new Set([
 "appointment booked","walked in & booked","very positive","existing client",
 "call & confirm","callback: scheduled","price negotiation","out station",
 "walked in: not booked","joined competition","not interested",
 "distance","do not contact"
]);
const LIFE_CC_FUNNEL_APPOINTMENT_OUTCOMES=new Set([
 "booked","cancelled","not visited","visited",
 "visited not booked","visited booked"
]);

function lifeCcFunnelNorm(v){
 return String(v||"").trim().toLowerCase();
}
function lifeCcFunnelReceivedDate(r){
 return String(r&&(r.custom_posting_date||r.creation)||"").slice(0,10);
}
function lifeCcFunnelVisitDate(r){
 return String(r&&r.custom_appointment_date_and_time||"").slice(0,10);
}
function lifeCcFunnelIsJunk(r){
 const stage=lifeCcFunnelNorm(r&&r.custom_cc_stage);
 const status=lifeCcFunnelNorm(r&&r.status);
 const sub=lifeCcFunnelNorm(r&&r.custom_cc_sub_status);
 return stage==="invalid"||
  LIFE_CC_FUNNEL_JUNK_LEAD_STATUSES.has(status)||
  LIFE_CC_FUNNEL_JUNK_CC_SUB_STATUSES.has(sub);
}
function lifeCcFunnelIsConnected(r){
 const stage=lifeCcFunnelNorm(r&&r.custom_cc_stage);
 const status=lifeCcFunnelNorm(r&&r.status);
 const sub=lifeCcFunnelNorm(r&&r.custom_cc_sub_status);
 return LIFE_CC_FUNNEL_CONNECTED_LEAD_STATUSES.has(status)||
  LIFE_CC_FUNNEL_CONNECTED_CC_SUB_STATUSES.has(sub)||
  stage==="follow-up"||
  stage==="success";
}
function lifeCcFunnelHasAppointment(r){
 const ap=lifeCcFunnelNorm(r&&r.custom_appointment_status);
 const status=lifeCcFunnelNorm(r&&r.status);
 const sub=lifeCcFunnelNorm(r&&r.custom_cc_sub_status);
 if(status==="appointment booked"||sub==="appointment booked"||sub==="call & confirm")return true;
 return Boolean(r&&r.custom_appointment_date_and_time&&LIFE_CC_FUNNEL_APPOINTMENT_OUTCOMES.has(ap));
}
function lifeCcFunnelVisitOutcome(r){
 const ap=lifeCcFunnelNorm(r&&r.custom_appointment_status);
 const sub=lifeCcFunnelNorm(r&&r.custom_cc_sub_status);
 if(ap==="visited booked")return "booked";
 if(ap==="visited not booked")return "unbooked";
 if(ap==="visited")return "visited";
 if(sub==="walked in & booked")return "booked";
 if(sub==="walked in: not booked")return "unbooked";
 return "";
}
function lifeCcStoreFunnelRows(from,to,rows,agentOwner){
 const key=String(from||"")+"|"+String(to||"");
 const incoming=Array.isArray(rows)?rows:[];
 if(!agentOwner||isLifeCcAgentLogin()){
  LIFE_CC_FUNNEL_ROWS_MAP.set(key,incoming.map(r=>Object.assign({},r)));
  return;
 }
 const merged=new Map();
 (LIFE_CC_FUNNEL_ROWS_MAP.get(key)||[]).forEach(r=>{if(r&&r.name)merged.set(r.name,r);});
 incoming.forEach(r=>{if(r&&r.name)merged.set(r.name,r);});
 LIFE_CC_FUNNEL_ROWS_MAP.set(key,[...merged.values()]);
}
function lifeCcFunnelMetrics(from,to,opts){
 opts=opts||{};

 /*
  * SAME SOURCE AS LEAD & DIGITAL MARKETING REPORT
  * ------------------------------------------------
  * Once Marketing data is ready, use its exact decorated Lead rows.
  * This keeps Raw / Connected / Visits / Booked / Unbooked identical
  * across Branch, Agent and Consultant tabs.
  */
 if(
  typeof window.LIFE_CC_MARKETING_FUNNEL_METRICS==="function"
 ){
  const exact=
   window.LIFE_CC_MARKETING_FUNNEL_METRICS(
    from,
    to,
    opts
   );

  if(exact){
   return exact;
  }
 }

 const rows=LIFE_CC_FUNNEL_ROWS_MAP.get(String(from||"")+"|"+String(to||""))||[];
 const agent=String(opts.agent||"").trim();
 const branch=String(opts.branch||"").trim();

 const scoped=[...new Map(
  rows.filter(r=>{
   if(!r||!r.name)return false;
   if(agent&&!sameAgentOwner(r.lead_owner,agent))return false;
   if(
    branch&&
    normalizedBranchKey(r.branch||r.lead_assign_to_branch||"")!==
    normalizedBranchKey(branch)
   )return false;
   return true;
  }).map(r=>[r.name,r])
 ).values()];

 const received=scoped.filter(r=>{
  const d=lifeCcFunnelReceivedDate(r);
  return d&&d>=from&&d<=to;
 });

 const visits=scoped.filter(r=>{
  const d=lifeCcFunnelVisitDate(r);
  return d&&d>=from&&d<=to&&Boolean(lifeCcFunnelVisitOutcome(r));
 });

 let quality=0,junk=0,connected=0,appointments=0,booked=0,unbooked=0;

 received.forEach(r=>{
  if(lifeCcFunnelIsJunk(r))junk++; else quality++;
  if(lifeCcFunnelIsConnected(r))connected++;
  if(lifeCcFunnelHasAppointment(r))appointments++;
 });

 visits.forEach(r=>{
  const o=lifeCcFunnelVisitOutcome(r);
  if(o==="booked")booked++;
  if(o==="unbooked")unbooked++;
 });

 return {
  raw:received.length,
  quality,junk,connected,appointments,
  visits:visits.length,
  booked,unbooked
 };
}
function lifeCcFunnelPercent(a,b){
 const numerator=Number(a||0);
 const denominator=Number(b||0);

 if(
  !Number.isFinite(numerator)||
  !Number.isFinite(denominator)||
  !denominator
 ){
  return "—";
 }

 return Math.round(
  numerator/denominator*100
 )+"%";
}

function lifeCcFunnelDisplayValue(value){
 if(
  typeof value==="string"&&
  (
   value.includes("%")||
   value==="—"
  )
 ){
  return value;
 }

 const number=Number(value||0);

 return Number.isFinite(number)
  ?number.toLocaleString("en-IN")
  :"0";
}

/* ============================================================
   Funnel KPI cards — Lead → Walk-in % uses QUALITY LEADS
   as denominator (Raw − Junk), never Raw.
   ============================================================ */
/* ============================================================
   Funnel KPI cards
   — Lead → Walk-in %      : Visits ÷ Quality Leads
   — Walk-in → Booked %    : Booked ÷ Visits
   — Quality → Booked %    : Booked ÷ Quality Leads
   — Total Leads → Booked %: Booked ÷ Raw Leads  ← NEW
   ============================================================ */
function lifeCcFunnelCardsHtml(m,meta){
  m=m||{};
  meta=meta||{};

  var qualityLeads =
    (typeof m.quality === "number" && m.quality > 0)
      ? m.quality
      : Math.max(Number(m.raw || 0) - Number(m.junk || 0), 0);

  var rawLeads = Number(m.raw || 0);

  var leadToWalkin =
    lifeCcFunnelPercent(m.visits, qualityLeads);

  var walkinToBooked =
    lifeCcFunnelPercent(m.booked, m.visits);

  var qualityToBooked =
    lifeCcFunnelPercent(m.booked, qualityLeads);

  /* NEW: Total Leads → Booked % */
  var totalToBooked =
    lifeCcFunnelPercent(m.booked, rawLeads);

  var cards=[
    ["Raw Leads",              m.raw          ||0,""],
    ["Quality Leads",          qualityLeads      ,"gr"],
    ["Junk Leads",             m.junk         ||0,"rd"],
    ["Connected",              m.connected    ||0,"gr"],
    ["Appointments",           m.appointments ||0,""],
    ["Visits / Walk-ins",      m.visits       ||0,"gr"],
    ["Booked",                 m.booked       ||0,"gr"],
    ["Unbooked",               m.unbooked     ||0,"or"],
    ["Lead → Walk-in %",       leadToWalkin      ,""],
    ["Walk-in → Booked %",     walkinToBooked   ,"gr"],
    ["Quality → Booked %",     qualityToBooked  ,"gr"],
    ["Total → Booked %",       totalToBooked    ,"gr"]
  ];

  var attrs=[
    ["data-from",   meta.from   ||""],
    ["data-to",     meta.to     ||""],
    ["data-agent",  meta.agent  ||""],
    ["data-branch", meta.branch ||""]
  ].map(function(pair){
    return pair[0]+'="'+lifeCcEsc(pair[1])+'"';
  }).join(" ");

  return '<div class="life-cc-funnel-grid" '+attrs+'>'+
    cards.map(function(c){
      return '<div class="life-cc-funnel-card">'+
        '<b class="num '+c[2]+'">'+lifeCcFunnelDisplayValue(c[1])+'</b>'+
        '<span>'+lifeCcEsc(c[0])+'</span>'+
      '</div>';
    }).join("")+
  '</div>';
}/*
 * After the Marketing tab finishes loading, refresh any funnel cards that
 * are already visible in the other tabs with the exact Marketing metrics.
 */
function lifeCcRefreshExactMarketingFunnels(){
