/* ===== FORCE ALL CC FILTER ACTIONS INTO ONE LINE ===== */
function lifeCcKeepCcFiltersOneLine(){
 const today=byId("ccQuickToday");
 if(!today)return;

 const row=
  today.closest(".cc-filter-action-row")||
  today.parentElement;

 if(!row)return;

 const viewGroup=
  byId("gB")
   ?byId("gB").closest(".grp")
   :null;

 const printButton=
  byId("ccPrintCurrentReport");

 if(
  viewGroup&&
  viewGroup.parentElement!==row
 ){
  row.appendChild(viewGroup);
 }

 if(
  printButton&&
  printButton.parentElement!==row
 ){
  row.appendChild(printButton);
 }

 row.classList.add(
  "cc-all-actions-one-line"
 );

 if(viewGroup){
  viewGroup.classList.add(
   "cc-view-toggle-inline"
  );
 }

 /*
  * Hide only the obsolete Report View wrapper.
  * Do not hide the actual moved viewGroup.
  */
 const hiddenSearch=byId("fSearch");
 const oldField=
  hiddenSearch
   ?hiddenSearch.closest(".fg")
   :null;

 if(
  oldField&&
  (!viewGroup||!oldField.contains(viewGroup))
 ){
  oldField.style.display="none";
 }
}

