function lifeCcNormalizeHeaderText(value){
 return String(value||"")
  .replace(/\s+/g," ")
  .trim()
  .toLowerCase();
}

function lifeCcCompactReportColumns(){
 const widthMap=[
  {
   match:[
    "total appointment",
    "total appointments"
   ],
   cls:"life-col-total-appointment"
  },
  {
   match:[
    "visit but pending in branch",
    "visit but pending",
    "visit pending in branch"
   ],
   cls:"life-col-visit-pending"
  },
  {
   match:[
    "total visit count",
    "total visits"
   ],
   cls:"life-col-total-visit"
  },
  {
   match:["booked"],
   cls:"life-col-booked"
  },
  {
   match:[
    "not booked",
    "unbooked"
   ],
   cls:"life-col-not-booked"
  },
  {
   match:["not visited"],
   cls:"life-col-not-visited"
  },
  {
   match:[
    "new package with gst",
    "new package with gst amount"
   ],
   cls:"life-col-new-with-gst"
  },
  {
   match:[
    "new package w/o gst",
    "new package without gst",
    "new package without gst amount"
   ],
   cls:"life-col-new-without-gst"
  },
  {
   match:[
    "new package paid",
    "new package paid amount"
   ],
   cls:"life-col-new-paid"
  },
  {
   match:[
    "old package paid",
    "old package paid amount"
   ],
   cls:"life-col-old-paid"
  },
  {
   match:[
    "new package balance",
    "new package balance amount"
   ],
   cls:"life-col-new-balance"
  },
  {
   match:[
    "book %",
    "booking conversion"
   ],
   cls:"life-col-book-percent"
  }
 ];

 document
  .querySelectorAll(
   "#tabv1 table,#tabv2 table,#tabv3 table,#tabv4 table"
  )
  .forEach(table=>{
   const headerRow=
    table.querySelector("thead tr");

   if(!headerRow)return;

   const headers=[
    ...headerRow.querySelectorAll("th")
   ];

   headers.forEach((th,index)=>{
    const label=
     lifeCcNormalizeHeaderText(
      th.textContent
     );

    /*
     * Avoid treating combined Marketing headers such as
     * "Booked / Unbooked" as the standalone Booked column.
     */
    const config=
     widthMap.find(item=>
      item.match.some(match=>
       label===match
      )
     );

    if(!config)return;

    th.classList.add(
     "life-report-compact-col",
     config.cls
    );

    /*
     * Apply the same width to every body/footer cell
     * in the matching column.
     */
    table
     .querySelectorAll("tbody tr,tfoot tr")
     .forEach(row=>{
      const cells=[
       ...row.children
      ];

      const cell=
       cells[index];

      if(!cell)return;

      cell.classList.add(
       "life-report-compact-col",
       config.cls
      );
     });
   });
  });
}

(function(){
 let timer=null;

 const schedule=function(){
  if(timer){
   clearTimeout(timer);
  }

  timer=setTimeout(()=>{
   lifeCcCompactReportColumns();
  },80);
 };

 if(document.readyState==="loading"){
  document.addEventListener(
   "DOMContentLoaded",
   schedule,
   {once:true}
  );
 }else{
  schedule();
 }

 /*
  * Tables are rerendered when filters / tabs / date buttons change.
  * Re-apply after user interactions without running a heavy observer.
  */
 document.addEventListener(
  "click",
  schedule,
  true
 );

 document.addEventListener(
  "change",
  schedule,
  true
 );

 document.addEventListener(
  "input",
  event=>{
   if(
    event&&
    event.target&&
    (
     event.target.tagName==="SELECT"||
     event.target.type==="date"
    )
   ){
    schedule();
   }
  },
  true
 );

 setTimeout(schedule,500);
 setTimeout(schedule,1500);
 setTimeout(schedule,3000);
})();


