function lifeGlobalHeaderKey(value){
 return String(value||"")
  .replace(/[↕▲▼⇅]/g," ")
  .replace(/\s+/g," ")
  .trim()
  .toLowerCase();
}

function lifeGlobalColumnType(label,index,total){
 const text=lifeGlobalHeaderKey(label);

 const exact={
  "total appointment":"md",
  "total appointments":"md",
  "appointments":"md",
  "visit but pending in branch":"md",
  "visit but pending":"md",
  "total visit count":"sm",
  "total visits":"sm",
  "visited":"xs",
  "booked":"xs",
  "not booked":"sm",
  "unbooked":"sm",
  "not visited":"sm",
  "new package with gst":"money",
  "new package with gst amount":"money",
  "with gst":"money",
  "new package w/o gst":"money",
  "new package without gst":"money",
  "new package without gst amount":"money",
  "without gst":"money",
  "new package paid":"money",
  "new package paid amount":"money",
  "paid":"money",
  "old package paid":"money",
  "old package paid amount":"money",
  "new package balance":"money",
  "new package balance amount":"money",
  "balance":"money",
  "book %":"percent",
  "booking %":"percent",
  "booking conversion":"percent"
 };

 if(exact[text]){
  return exact[text];
 }

 /*
  * Text/name columns should expand:
  * Branch, Consultant, Manager, Designation, Team Members,
  * Owner, Agent, Category, Source, etc.
  */
 if(
  text.includes("branch")||
  text.includes("consultant")||
  text.includes("manager")||
  text.includes("designation")||
  text.includes("team member")||
  text.includes("agent")||
  text.includes("owner")||
  text.includes("source")||
  text.includes("category")||
  text.includes("name")
 ){
  return "flex";
 }

 /*
  * First column of a report table is normally a label/name column.
  */
 if(index===0){
  return "flex";
 }

 /*
  * Unknown middle columns remain flexible rather than creating blank
  * unused width after the final column.
  */
 return "flex";
}

function lifeGlobalNormalizeOneTable(table){
 if(!table||table.dataset.lifeNormalized==="1"){
  /*
   * Still re-apply parent width because frameworks may replace inline
   * wrapper styles after render.
   */
 }

 const head=
  table.querySelector("thead tr");

 if(!head)return;

 const headers=[
  ...head.querySelectorAll("th")
 ];

 if(headers.length<2)return;

 /*
  * Only normalize report/data tables, not tiny internal control tables.
  */
 const tab=
  table.closest(
   "#tabv1,#tabv2,#tabv3,#tabv4"
  );

 if(!tab)return;

 table.classList.add(
  "life-fill-report-table"
 );

 /*
  * Remove previous fixed total widths that caused the empty space.
  */
 table.style.setProperty(
  "width",
  "100%",
  "important"
 );
 table.style.setProperty(
  "max-width",
  "100%",
  "important"
 );
 table.style.setProperty(
  "min-width",
  "100%",
  "important"
 );
 table.style.setProperty(
  "table-layout",
  "fixed",
  "important"
 );

 /*
  * Make table wrapper + nearby generic holders fill the report card.
  */
 let parent=table.parentElement;
 let depth=0;

 while(
  parent&&
  depth<3&&
  parent!==tab
 ){
  parent.classList.add(
   "life-fill-table-wrap"
  );

  parent.style.setProperty(
   "width",
   "100%",
   "important"
  );
  parent.style.setProperty(
   "max-width",
   "100%",
   "important"
  );
  parent.style.setProperty(
   "min-width",
   "0",
   "important"
  );

  parent=parent.parentElement;
  depth++;
 }

 /*
  * Remove prior width classes set by earlier patches from cells,
  * then apply final semantic width classes.
  */
 headers.forEach((th,index)=>{
  const type=
   lifeGlobalColumnType(
    th.textContent,
    index,
    headers.length
   );

  const cls=
   type==="xs"
    ?"life-gcol-xs"
    :type==="sm"
     ?"life-gcol-sm"
     :type==="md"
      ?"life-gcol-md"
      :type==="money"
       ?"life-gcol-money"
       :type==="percent"
        ?"life-gcol-percent"
        :"life-gcol-flex";

  th.classList.add(
   "life-global-col",
   cls
  );

  table
   .querySelectorAll("tbody tr,tfoot tr")
   .forEach(row=>{
    const cell=row.children[index];
    if(!cell)return;

    cell.classList.add(
     "life-global-col",
     cls
    );
   });
 });

 /*
  * Important: make at least one text column flexible.
  * If every column was recognized as fixed, first column absorbs spare width.
  */
 if(
  !headers.some(th=>
   th.classList.contains(
    "life-gcol-flex"
   )
  )
 ){
  const first=headers[0];

  first.classList.add(
   "life-gcol-flex"
  );

  table
   .querySelectorAll("tbody tr,tfoot tr")
   .forEach(row=>{
    const cell=row.children[0];
    if(cell){
     cell.classList.add(
      "life-gcol-flex"
     );
    }
   });
 }

 table.dataset.lifeNormalized="1";
}

function lifeGlobalNormalizeAllTables(){
 document
  .querySelectorAll(
   "#tabv1 table,#tabv2 table,#tabv3 table,#tabv4 table"
  )
  .forEach(table=>
   lifeGlobalNormalizeOneTable(table)
  );
}

(function(){
 let timer=null;

 const schedule=()=>{
  clearTimeout(timer);

  timer=setTimeout(
   lifeGlobalNormalizeAllTables,
   50
  );
 };

 /*
  * Initial page renders.
  */
 if(document.readyState==="loading"){
  document.addEventListener(
   "DOMContentLoaded",
   schedule,
   {once:true}
  );
 }else{
  schedule();
 }

 /*
  * Dynamic tab/filter/report rerenders.
  */
 document.addEventListener(
  "click",
  schedule,
  true
 );

 document.addEventListener(
  "change",
  schedule,
  true
 );

 /*
  * Observe only the four report tabs and debounce heavily.
  * This keeps newly created tables normalized without repeatedly
  * doing expensive work.
  */
 const installObserver=()=>{
  const root=document.querySelector(
   "#tabv1,#tabv2,#tabv3,#tabv4"
  );

  const commonParent=
   document.querySelector(
    ".page_content"
   )||
   document.querySelector(
    "main"
   )||
   document.body;

  if(!commonParent)return;

  const observer=
   new MutationObserver(
    mutations=>{
     if(
      mutations.some(mutation=>
       [...mutation.addedNodes].some(node=>
        node&&
        node.nodeType===1&&
        (
         node.matches?.("table")||
         node.querySelector?.("table")
        )
       )
      )
     ){
      schedule();
     }
    }
   );

  observer.observe(
   commonParent,
   {
    childList:true,
    subtree:true
   }
  );
 };

 setTimeout(installObserver,300);

 /*
  * Extra safety after asynchronous report loads.
  */
 setTimeout(schedule,500);
 setTimeout(schedule,1500);
 setTimeout(schedule,3500);
})();


