function todayISO(){
 try{
  if(
   window.frappe&&
   frappe.datetime&&
   typeof frappe.datetime.get_today==="function"
  ){
   return frappe.datetime.get_today();
  }
 }catch(error){}

 const now=new Date();
 const local=new Date(
  now.getTime()-now.getTimezoneOffset()*60000
 );

 return local.toISOString().slice(0,10);
}

function daysAgoISO(n){
 const parts=todayISO().split("-").map(Number);
 const date=new Date(
  parts[0],
  parts[1]-1,
  parts[2]
 );

 date.setDate(date.getDate()-n);

 const local=new Date(
  date.getTime()-date.getTimezoneOffset()*60000
 );

 return local.toISOString().slice(0,10);
}

const TODAY=todayISO();

/* Same-origin REST call — works when this page is served from portal.lifescc.com
   (e.g. this Web Page route) and the visitor has an active Frappe login session.
   Uses GET only (read-only report), so no CSRF token is strictly required, but we
   send one anyway for consistency with the tested reference page. */
function getCsrf(){
 if(typeof frappe!=="undefined"&&frappe.csrf_token)return frappe.csrf_token;
 const m=document.querySelector('meta[name="csrf-token"]');if(m)return m.content;
 const inp=document.querySelector('input[name="csrf_token"]');if(inp)return inp.value;
 return "";
}
/*
 * =========================================================
 * SAFE GET-LIST
 * ---------------------------------------------------------
 * Prevents transient browser/network failures from immediately
 * breaking edge panels. Retries only network-level failures.
 * HTTP permission/server errors still surface normally.
 * ========================================================= */
const LIFE_API_GETLIST_MAX_CONCURRENT=3;
let LIFE_API_GETLIST_ACTIVE=0;
const LIFE_API_GETLIST_QUEUE=[];

function lifeApiQueueDrain(){
 while(
  LIFE_API_GETLIST_ACTIVE<
   LIFE_API_GETLIST_MAX_CONCURRENT&&
  LIFE_API_GETLIST_QUEUE.length
 ){
  const job=
   LIFE_API_GETLIST_QUEUE.shift();

  LIFE_API_GETLIST_ACTIVE++;

  Promise.resolve()
   .then(job.run)
   .then(job.resolve)
   .catch(job.reject)
   .finally(()=>{
    LIFE_API_GETLIST_ACTIVE--;
    lifeApiQueueDrain();
   });
 }
}

function lifeApiQueued(run){
 return new Promise(
  (resolve,reject)=>{
   LIFE_API_GETLIST_QUEUE.push({
    run,
    resolve,
    reject
   });

   lifeApiQueueDrain();
  }
 );
}

function lifeApiSleep(ms){
 return new Promise(resolve=>
  setTimeout(resolve,ms)
 );
}

async function apiGetList(
 doctype,
 fields,
 filters,
 opts
){
 opts=opts||{};

 const p=
  new URLSearchParams();

 p.set("doctype",doctype);
 p.set(
  "fields",
  JSON.stringify(fields)
 );

 if(filters){
  p.set(
   "filters",
   JSON.stringify(filters)
  );
 }

 if(opts.order_by){
  p.set(
   "order_by",
   opts.order_by
  );
 }

 if(opts.limit_start!=null){
  p.set(
   "limit_start",
   opts.limit_start
  );
 }

 if(opts.limit_page_length!=null){
  p.set(
   "limit_page_length",
   opts.limit_page_length
  );
 }

 const url=
  "/api/method/frappe.client.get_list?"+
  p.toString();

 const maxAttempts=
  Number(
   opts.network_retries!=null
    ?opts.network_retries
    :2
  )+1;

 return lifeApiQueued(
  async()=>{
   let lastError=null;

   for(
    let attempt=1;
    attempt<=maxAttempts;
    attempt++
   ){
    const controller=
     typeof AbortController!=="undefined"
      ?new AbortController()
      :null;

    const timeoutMs=
     Number(
      opts.timeout_ms||
      30000
     );

    const timeout=
     controller
      ?setTimeout(
        ()=>controller.abort(),
        timeoutMs
       )
      :null;

    try{
     const res=
      await fetch(
       url,
       {
        method:"GET",
        credentials:"same-origin",
        headers:{
         "X-Frappe-CSRF-Token":
          getCsrf(),
         "Accept":
          "application/json"
        },
        signal:
         controller
          ?controller.signal
          :undefined
       }
      );

     if(timeout){
      clearTimeout(timeout);
     }

     if(
      res.status===403||
      res.status===401
     ){
      throw new Error(
       "Not logged in — please log into portal.lifescc.com in this browser tab, then refresh this page."
      );
     }

     if(!res.ok){
      throw new Error(
       "API error "+
       res.status
      );
     }

     const data=
      await res.json();

     return data.message||[];

    }catch(error){
     if(timeout){
      clearTimeout(timeout);
     }

     lastError=error;

     const message=
      String(
       error&&error.message||
       error||
       ""
      );

     const networkFailure=
      error&&(
       error.name==="AbortError"||
       message.includes(
        "Failed to fetch"
       )||
       message.includes(
        "NetworkError"
       )||
       message.includes(
        "Load failed"
       )
      );

     /*
      * Do NOT retry permissions / normal HTTP errors.
      */
     if(
      !networkFailure||
      attempt>=maxAttempts
     ){
      throw error;
     }

     console.warn(
      "Temporary API network failure — retrying",
      {
       doctype,
       attempt,
       maxAttempts,
       message
      }
     );

     await lifeApiSleep(
      350*attempt
     );
    }
   }

   throw lastError||
    new Error(
     "API request failed"
    );
  }
 );
}


async function apiCallMethod(method,args){
 const res=await fetch("/api/method/"+method,{
  method:"POST",
  credentials:"same-origin",
  headers:{
   "Content-Type":"application/json",
   "X-Frappe-CSRF-Token":getCsrf(),
   "Accept":"application/json"
  },
  body:JSON.stringify(args||{})
 });

 let data={};
 try{data=await res.json();}catch(e){}

 if(res.status===401||res.status===403){
  throw new Error("You do not have permission to perform this approval action.");
 }

 if(!res.ok||data.exc||data.exception){
  let msg=
   data._server_messages||
   data.exception||
   data.exc_type||
   data.message||
   ("Server method failed. API error "+res.status);

  try{
   const messages=JSON.parse(data._server_messages||"[]");
   if(messages.length){
    const first=JSON.parse(messages[0]);
    msg=first.message||msg;
   }
  }catch(e){}

  throw new Error(String(msg).replace(/<[^>]*>/g," ").trim());
 }

 return data.message;
}

