   activeEmployee&&activeEmployee.branch||""
  ).trim();
 }catch(error){
  console.warn(
   "Walking Report: Employee branch lookup failed",
   error
  );
 }

 /*
  * FALLBACK:
  * Healthcare Practitioner.user_id -> branch
  */
 if(!branch){
  try{
   const practitionerRows=await apiGetList(
    "Healthcare Practitioner",
    [
     "name",
     "practitioner_name",
     "user_id",
     "branch",
     "status"
    ],
