     ["user_id","=",user]
    ],
    {
     limit_page_length:5
    }
   );

   const practitioner=
    (practitionerRows||[]).find(row=>
     String(row&&row.branch||"").trim()
    );

   branch=String(
    practitioner&&practitioner.branch||""
   ).trim();
  }catch(error){
   console.warn(
    "Walking Report: Practitioner branch lookup failed",
