const LIFE_UNASSIGNED_BRANCH="__LIFE_BRANCH_NOT_AVAILABLE__";

function normalizedBranchKey(value){
 const text=String(value||"")
  .trim()
  .toLowerCase()
  .replace(/&/g,"and")
  .replace(/[^a-z0-9]/g,"");

 if(!text)return LIFE_UNASSIGNED_BRANCH;

 /*
  * Normalise known spelling variations.
  */
 const aliases={
  "himayathnagar":"himayatnagar",
  "dilsukhnagar":"dilsukhnagar",
  "srinagar":"srnagar",
  "headoffice":"headoffice"
 };

 return aliases[text]||text;
}

function recordBranchKey(record){
 return normalizedBranchKey(record&&record.br);
}

function sameBranch(left,right){
 return normalizedBranchKey(left)===normalizedBranchKey(right);
}

function branchDisplayLabel(key,rows){
