  recordBranchKey(row)===key&&
  String(row.br||"").trim()
 );

 if(record)return String(record.br).trim();

 const master=BRANCHES.find(branch=>
  normalizedBranchKey(branch)===key
 );

 return master||String(key||"Branch Not Available");
}

function branchKeysForRows(rows,includeEmptyMasters){
 const sourceRows=Array.isArray(rows)?rows:[];
 const present=[
  ...new Set(
   sourceRows.map(recordBranchKey)
  )
 ];

 if(!includeEmptyMasters){
  return present;
 }

 const master=[
  ...new Set(
   BRANCHES.map(normalizedBranchKey)
  )
 ];

 present.forEach(key=>{
  if(!master.includes(key))master.push(key);
 });

 return master;
}

