  frappe.call({
   method:"life_cc_agent_marketing_data",
   args:{
    from_date:from,
    to_date:to,
    agent_owner:
     String(
      agentOwner||""
     ).trim()
   },
   callback:function(response){
    const message=
     response&&response.message!==undefined
      ?response.message
      :response;

    const rows=
     Array.isArray(message)
      ?message
      :(
       message&&Array.isArray(message.rows)
        ?message.rows
        :[]
      );

    resolve({
     ok:true,
     rows:rows,
     rankingRows:
      message&&Array.isArray(message.ranking_rows)
       ?message.ranking_rows
       :[],
     agentNames:
      message&&message.agent_names&&
      typeof message.agent_names==="object"
       ?message.agent_names
       :{},
     financialEvents:
      message&&Array.isArray(message.financial_events)
       ?message.financial_events
       :[],
     branchFinancialEvents:
      message&&Array.isArray(message.branch_financial_events)
       ?message.branch_financial_events
       :[],
     agentReportSummary:
      message&&message.agent_report_summary&&
      typeof message.agent_report_summary==="object"
       ?message.agent_report_summary
       :null,
     ccInvoiceReportSummary:
      message&&message.cc_invoice_report_summary&&
      typeof message.cc_invoice_report_summary==="object"
       ?message.cc_invoice_report_summary
       :null,
     restricted_to_owner:Boolean(
      message&&message.restricted_to_owner
     )
    });
   },
   error:function(error){
    reject(
     error instanceof Error
      ?error
      :new Error(
       "Secure Agent Lead API failed."
      )
    );
   }
  });
 });
}


