/*
 * CC / CALL CENTER FINANCIAL RULE
 * -------------------------------
 * Use ONLY money that can be traced by an exact Lead link:
 *
 * Sales Invoice.patient
 *   -> Patient.custom_lead
 *   -> Lead
 *   -> Lead.lead_owner
 *
 * Do not include overall branch collections or unrelated payments.
 */
function isCcLeadLinkedFinancialEvent(event){
 if(!event)return false;

 /*
  * New secure API explicitly sets this flag.
  */
 if(event.cc_lead_linked===true){
  return true;
 }

 /*
  * Compatibility fallback for already-loaded API payloads.
  */
 const lead=String(
  event.lead||""
 ).trim();

 const owner=String(
  event.lead_owner||""
 ).trim();

 return Boolean(
  lead&&owner
 );
}

function ccLeadLinkedFinancialEventsInRange(
 from,
 to
){
 return financialEventsInRange(
  from,
  to
 ).filter(
  isCcLeadLinkedFinancialEvent
 );
}

function branchFinancialEventsInRange(from,to){
 return BRANCH_FINANCIAL_EVENTS.filter(event=>{
  if(!event)return false;

  const paymentDates=
   Array.isArray(event.payment_dates)
    ?event.payment_dates
    :[];

  if(paymentDates.length){
   return paymentDates.some(date=>{
    const value=String(date||"").slice(0,10);
    return value>=from&&value<=to;
   });
  }

  const date=String(
   event.event_date||
   event.last_payment_date||
   event.first_payment_date||
   ""
  ).slice(0,10);

  return date>=from&&date<=to;
 });
}

