  events=events.filter(event=>{
   const eventBranch=
    event&&(
     event.lead_branch||
     event.branch
    );

   const eventBranchKey=
    normalizedBranchKey(
     eventBranch
    );

   return F.branch===LIFE_UNASSIGNED_BRANCH
    ?eventBranchKey===LIFE_UNASSIGNED_BRANCH
    :sameBranch(
      eventBranch,
      F.branch
     );
  });
 }

 if(F.agent){
  events=events.filter(event=>
   sameAgentOwner(
    event&&event.lead_owner,
    F.agent
   )
  );
 }

 return events;
}

function financialEventTotals(events){
 const source=Array.isArray(events)
  ?events
  :[];

 const totals={
  withoutGst:0,
  withGst:0,
  paid:0,
  balance:0
 };

 /*
  * CORRECT CC FINANCIAL DATE RULE
  * ------------------------------
  *
  * WITH GST / WITHOUT GST
  *   -> Sales Invoice posting_date inside selected range.
  *
  * PAID AMOUNT
  *   -> actual money collected on the selected date:
  *      - POS/direct invoice payment on invoice date
  *      - submitted Payment Entry Reference.allocated_amount on
  *        Payment Entry.posting_date
  *
  * BALANCE
  *   -> current Sales Invoice.outstanding_amount for invoices
  *      created in the selected range.
  *
  * Therefore Paid Amount can include collection against an older
  * invoice. That is intentional because Paid means CASH RECEIVED
  * during the selected period.
  */

 const invoiceSeen=new Set();

 source.forEach(event=>{
  const eventType=String(
   event&&event.event_type||""
  );

  /*
   * Actual collection on this transaction date.
   * The secure API has already grouped Payment Entry Reference
   * allocated_amount by invoice + payment posting date.
   */
  totals.paid+=Math.max(
   Number(event&&event.paid_amount||0),
   0
  );

  const isInvoiceLike=
   eventType==="Invoice"||
   Boolean(
    event&&event.cc_report_qualified
   );

  if(!isInvoiceLike){
   return;
  }

  const invoice=String(
   event&&event.sales_invoice||""
  ).trim();

  if(invoice && invoiceSeen.has(invoice)){
   return;
  }

  if(invoice){
   invoiceSeen.add(invoice);
  }

  const withGst=Math.max(
   Number(event&&event.with_gst||0),
   0
  );

  const withoutGst=Math.max(
   Number(event&&event.without_gst||0),
   0
  );

  let currentOutstanding=Number(
   event&&event.current_outstanding
  );

  if(!Number.isFinite(currentOutstanding)){
   currentOutstanding=Number(
    event&&event.balance_after||0
   );
  }

  currentOutstanding=Math.max(
   currentOutstanding||0,
   0
  );

  if(
   withGst>0 &&
   currentOutstanding>withGst
  ){
   currentOutstanding=withGst;
  }

  totals.withGst+=withGst;
  totals.withoutGst+=withoutGst;
  totals.balance+=currentOutstanding;
 });

 return totals;
}


/*
 * AGENT REPORT FINANCIAL TOTALS
 * -----------------------------
 * Agent report uses exact Lead-linked financial events.
 *
 * With GST / Without GST / Balance:
 *   - Sales Invoice events only
 *   - each Sales Invoice counted once
 *
 * Paid:
 *   - actual paid amount on the transaction/payment date
 *
 * A later Payment event is never counted again as a new invoice sale.
 */
function agentFinancialEventTotals(events){
 const source=Array.isArray(events)
  ?events
  :[];

 const totals={
  withoutGst:0,
  withGst:0,
  paid:0,
  balance:0
 };

 const invoiceSeen=new Set();

 source.forEach(event=>{
  if(!event)return;

  totals.paid+=Math.max(
   Number(event.paid_amount||0),
   0
  );

  if(
   String(event.event_type||"")!=="Invoice"
  ){
   return;
  }

  const invoice=String(
   event.sales_invoice||""
  ).trim();

  if(
   invoice&&
   invoiceSeen.has(invoice)
  ){
   return;
  }

  if(invoice){
   invoiceSeen.add(invoice);
  }

  const withGst=Math.max(
   Number(event.with_gst||0),
   0
  );

  const withoutGst=Math.max(
   Number(event.without_gst||0),
   0
  );

  let outstanding=Number(
   event.current_outstanding
  );

  if(!Number.isFinite(outstanding)){
   outstanding=Number(
    event.balance_after||0
   );
  }

  outstanding=Math.max(
   outstanding||0,
   0
  );

  if(
   withGst>0&&
   outstanding>withGst
  ){
   outstanding=withGst;
  }

  totals.withGst+=withGst;
  totals.withoutGst+=withoutGst;
  totals.balance+=outstanding;
 });

 return totals;
}

/*
 * CC OUTSTANDING COLLECTED AMOUNT
 * -------------------------------
 * Count ONLY later collections against an already-created invoice.
 *
 * Exact source:
 *   Sales Invoice.patient
 *     -> Patient.custom_lead
 *     -> Lead.lead_owner
 *
 * Then:
 *   Payment Entry.posting_date = selected transaction date
 *   Payment Entry Reference.allocated_amount = collected amount
 *
 * Same-day invoice payment is NOT counted as Outstanding Collected.
 */
function ccOutstandingCollectedAmount(events){
 const source=Array.isArray(events)
  ?events
  :[];

 return source.reduce(
  (sum,event)=>{
   if(
    String(
     event&&event.event_type||""
    )!=="Payment"
   ){
    return sum;
   }

   const paymentDate=String(
    event&&event.event_date||""
   ).slice(0,10);

   const invoiceDate=String(
    event&&event.invoice_date||""
   ).slice(0,10);

   /*
    * Only a payment made AFTER the invoice date is an
    * outstanding collection.
    */
   if(
    invoiceDate &&
    paymentDate &&
    paymentDate<=invoiceDate
   ){
    return sum;
   }

   return (
    sum+
    Math.max(
     Number(
      event&&event.paid_amount||0
     ),
     0
    )
   );
  },
  0
 );
}


