async function fetchLeads(
 from,
 to,
 agentOwner
){
 /*
  * First use the secured API Server Script. It returns Branch and
  * appointment-status fields even when the Agent role cannot read
  * those fields through frappe.client.get_list.
  */
 try{
  const secureResult=
   await fetchSecureAgentAppointmentLeads(
    from,
    to,
    agentOwner
   );

  mergeSecureAllAgentRanking(
   secureResult
  );

  mergeSecureFinancialEvents(
   secureResult
  );

  mergeSecureBranchFinancialEvents(
   secureResult
  );

  lifeCcStoreFunnelRows(
   from,
   to,
   secureResult.rows||[],
   agentOwner
  );

  if(
   secureResult.agentReportSummary&&
   agentOwner
  ){
   AGENT_REPORT_SUMMARY_MAP.set(
    agentRangeKey(
     from,
     to,
     agentOwner
    ),
    secureResult.agentReportSummary
   );
  }

  if(
   secureResult.ccInvoiceReportSummary
  ){
   CC_INVOICE_REPORT_SUMMARY_MAP.set(
    String(from||"")+"|"+String(to||""),
    secureResult.ccInvoiceReportSummary
   );
  }

  /*
   * LEAD RECEIVED SUMMARY
   * ---------------------
   * The secure API returns Leads found by appointment date,
   * posting date, or creation date. Before we filter down to
   * appointment rows, calculate how many Leads each Agent actually
   * received in this selected From / To period.
   */
  {
   const receivedByOwner={};
   let receivedTotal=0;

   (secureResult.rows||[]).forEach(row=>{
    if(!row){
     return;
    }

    const receivedDate=
     String(
      row.custom_posting_date||
      row.creation||
      ""
     ).slice(0,10);

    if(
     !receivedDate||
     receivedDate<from||
     receivedDate>to
    ){
     return;
    }

    const owner=
     String(
      row.lead_owner||""
     ).trim();

    if(!owner){
     return;
    }

    const ownerKey=
     owner.toLowerCase();

    receivedByOwner[ownerKey]=
     Number(
      receivedByOwner[ownerKey]||0
     )+1;

    receivedTotal+=1;
   });

   const summaryKey=
    String(from||"")+
    "|"+
    String(to||"");

   const existing=
    LEAD_RECEIVED_SUMMARY_MAP.get(
     summaryKey
    )||{
     byOwner:{},
     total:0
    };

   /*
    * Main CC dashboard load has no agentOwner and therefore contains
    * all permitted Agents. Agent-login loads are also complete for
    * that login because the server restricts them to self.
    *
    * A manager opening one specific Agent Report later must not erase
    * the already-loaded all-agent counts.
    */
   if(
    !agentOwner||
    isLifeCcAgentLogin()
   ){
    LEAD_RECEIVED_SUMMARY_MAP.set(
     summaryKey,
     {
      byOwner:receivedByOwner,
      total:receivedTotal
     }
    );
   }else{
    const mergedOwners=
     Object.assign(
      {},
      existing.byOwner||{}
     );

    Object.keys(
     receivedByOwner
    ).forEach(ownerKey=>{
     mergedOwners[ownerKey]=
      receivedByOwner[ownerKey];
    });

    let mergedTotal=0;

    Object.keys(
     mergedOwners
    ).forEach(ownerKey=>{
     mergedTotal+=Number(
      mergedOwners[ownerKey]||0
     );
    });

    LEAD_RECEIVED_SUMMARY_MAP.set(
     summaryKey,
     {
      byOwner:mergedOwners,
      total:mergedTotal
     }
    );
   }
  }

  const secureRows=secureResult.rows.filter(row=>{
   const appointmentDateTime=String(
    row.custom_appointment_date_and_time||""
   ).trim();

   if(!appointmentDateTime)return false;

   const appointmentDate=
    appointmentDateTime.slice(0,10);

   return (
    appointmentDate>=from&&
    appointmentDate<=to
   );
  });

  console.log(
   "Secure Agent appointment data:",
   {
    login:currentPortalUser(),
    rows:secureRows.length,
    restricted_to_owner:
     secureResult.restricted_to_owner,
    branch_available:secureRows.filter(row=>
     String(
      row.branch||
      row.lead_assign_to_branch||
      ""
     ).trim()
    ).length,
    status_available:secureRows.filter(row=>
     String(
      row.custom_appointment_status||
      row.status||
      ""
     ).trim()
    ).length,

    financial_amounts_available:
     secureRows.filter(row=>
      Number(
       row.financial_with_gst||
       row.financial_without_gst||
       0
      )>0
     ).length,

    financial_transaction_events:
     secureResult.financialEvents.length
   }
  );

  const scopedSecureRows=
   LIFE_WALKING_BRANCH_SCOPE
    ?secureRows.filter(row=>
      normalizedBranchKey(
       row&&(
        row.branch||
        row.lead_assign_to_branch||
        ""
       )
      )===
      normalizedBranchKey(
       LIFE_WALKING_BRANCH_SCOPE
      )
     )
    :secureRows;

  return scopedSecureRows;
 }catch(error){
  console.warn(
   "Secure Agent appointment API failed. "+
   "Falling back to normal Lead list API.",
   error
  );
 }

 const fields=[
