function parseLifeDateTime(value){
 const text=String(value||"").trim();
 if(!text)return null;
 const parsed=new Date(text.replace(" ","T"));
 return Number.isNaN(parsed.getTime())?null:parsed;
}

function hrsBetween(a,b){
 const start=parseLifeDateTime(a);
 const end=parseLifeDateTime(b);
 if(!start||!end)return "—";

 const diffMinutes=Math.floor((end.getTime()-start.getTime())/60000);
 if(diffMinutes<0)return "—";

 // Less than one hour: show minutes.
 if(diffMinutes<60){
  return diffMinutes+" min";
 }

 const totalHours=Math.floor(diffMinutes/60);
 const remainingMinutes=diffMinutes%60;

 // Up to and including 24 hours: keep the value in hours.
 if(totalHours<=24){
  return totalHours+" hr"+(totalHours===1?"":"s")+
   (remainingMinutes?" "+remainingMinutes+" min":"");
 }

 const totalDays=Math.floor(totalHours/24);
 const remainingHours=totalHours%24;

 // More than 24 hours but less than 30 days: show days.
 if(totalDays<30){
  return totalDays+" day"+(totalDays===1?"":"s")+
   (remainingHours?" "+remainingHours+" hr"+(remainingHours===1?"":"s"):"");
 }

 // Thirty days and above: show months, with remaining days.
 const months=Math.floor(totalDays/30);
 const remainingDays=totalDays%30;
 return months+" month"+(months===1?"":"s")+
  (remainingDays?" "+remainingDays+" day"+(remainingDays===1?"":"s"):"");
}

function ageOnDate(dob,referenceDate){
 const birth=parseLifeDateTime(String(dob||"").slice(0,10));
 const ref=parseLifeDateTime(String(referenceDate||"").slice(0,10));
 if(!birth||!ref||birth>ref)return "—";

 let age=ref.getFullYear()-birth.getFullYear();
 const beforeBirthday=
  ref.getMonth()<birth.getMonth()||
  (ref.getMonth()===birth.getMonth()&&ref.getDate()<birth.getDate());
 if(beforeBirthday)age-=1;

 return age>=0&&age<=120?age:"—";
}

