  byId("clk").textContent="⚠ offline";
 }
}

/* ===== State — LIFE business cycle: 6th to 5th ===== */
function getLifeBusinessCycleRange(offset){
 const base=new Date(TODAY+"T00:00:00");
 const start=new Date(base.getFullYear(),base.getMonth(),6);

 if(base.getDate()<6){
  start.setMonth(start.getMonth()-1);
 }

 start.setMonth(start.getMonth()+(offset||0));

 const end=new Date(
  start.getFullYear(),
  start.getMonth()+1,
  5
 );

 const toLocalISO=date=>[
  date.getFullYear(),
  String(date.getMonth()+1).padStart(2,"0"),
  String(date.getDate()).padStart(2,"0")
 ].join("-");

 return {
  from:toLocalISO(start),
  to:toLocalISO(end)
 };
}

function ccDisplayDate(value){
 const iso=String(value||"").slice(0,10);

 if(!/^\d{4}-\d{2}-\d{2}$/.test(iso)){
  return "";
 }

 const parts=iso.split("-");
 const months=[
  "JAN","FEB","MAR","APR","MAY","JUN",
  "JUL","AUG","SEP","OCT","NOV","DEC"
 ];

 return (
  parts[2]+
  "-"+
  months[Number(parts[1])-1]+
  "-"+
  parts[0].slice(-2)
 );
}

