function ccDateFromISO(value){
 const parts=String(value||"")
  .split("-")
  .map(Number);

 return new Date(
  parts[0],
  parts[1]-1,
  parts[2]
 );
}

function ccISOFromDate(date){
 return [
  date.getFullYear(),
  String(date.getMonth()+1).padStart(2,"0"),
  String(date.getDate()).padStart(2,"0")
 ].join("-");
}

function ccMondayOfWeek(value){
 const date=
  typeof value==="string"
   ?ccDateFromISO(value)
   :new Date(
     value.getFullYear(),
     value.getMonth(),
     value.getDate()
    );

 const day=date.getDay();
 const diff=day===0?-6:1-day;

 date.setDate(
  date.getDate()+diff
 );

 return date;
}

function getCcQuickRange(mode){
 const todayDate=
  ccDateFromISO(TODAY);

 if(mode==="today"){
  return {
   from:TODAY,
   to:TODAY
  };
 }

 if(mode==="yesterday"){
  const yesterday=
   new Date(
    todayDate.getFullYear(),
    todayDate.getMonth(),
    todayDate.getDate()-1
   );

  const yesterdayISO=
   ccISOFromDate(
    yesterday
   );

  return {
   from:yesterdayISO,
   to:yesterdayISO
  };
 }

 if(mode==="this_week"){
  const monday=
   ccMondayOfWeek(todayDate);

  return {
   from:ccISOFromDate(monday),
   to:TODAY
  };
 }

 if(mode==="last_week"){
  const thisMonday=
   ccMondayOfWeek(todayDate);

  const lastMonday=
   new Date(
    thisMonday.getFullYear(),
    thisMonday.getMonth(),
    thisMonday.getDate()-7
   );

  const lastSunday=
   new Date(
    thisMonday.getFullYear(),
    thisMonday.getMonth(),
    thisMonday.getDate()-1
   );

  return {
   from:ccISOFromDate(lastMonday),
   to:ccISOFromDate(lastSunday)
  };
 }

 if(mode==="last_month"){
  return getLifeBusinessCycleRange(-1);
 }

 /*
  * LIFE "This Month" = 6th -> TODAY.
  * Do not automatically include future appointments through the 5th
  * of next month.
  */
 const cycle=
  getLifeBusinessCycleRange(0);

 return {
  from:cycle.from,
  to:TODAY
 };
}

