function detectCcQuickRange(
 from,
 to
){
 const modes=[
  "today",
  "yesterday",
  "this_week",
  "last_week",
  "this_month",
  "last_month"
 ];

 for(const mode of modes){
  const range=
   getCcQuickRange(mode);

  if(
   range.from===from&&
   range.to===to
  ){
   return mode;
  }
 }

 return "";
}

