function ccInvoicePackageSplitTotals(rows){
 return (Array.isArray(rows)?rows:[])
  .filter(
   isStrictCallCenterPackageRow
  )
  .reduce(
   (totals,row)=>{
    const invoiceDate=
     String(
      row&&row.invoice_date||""
     ).slice(0,10);

    const withGst=Math.max(
     Number(row&&row.with_gst||0),
     0
    );

    const withoutGst=Math.max(
     Number(row&&row.without_gst||0),
     0
    );

    const paid=Math.max(
     Number(row&&row.paid||0),
     0
    );

    const balance=Math.max(
     Number(row&&row.balance||0),
     0
    );

    const isNewPackage=
     Boolean(
      invoiceDate&&
      invoiceDate>=F.from&&
      invoiceDate<=F.to
     );

    const isOldPackage=
     Boolean(
      invoiceDate&&
      invoiceDate<F.from
     );

    if(isNewPackage){
     totals.withGst+=withGst;
     totals.withoutGst+=withoutGst;
     totals.paid+=paid;
     totals.balance+=balance;
     totals.newPackageCount+=1;
    }else if(isOldPackage){
     /*
      * Old package amount itself is intentionally NOT mixed into
      * New Package With GST / Without GST / Balance.
      *
      * Only the collection received in the selected payment period
      * is shown separately as Old Package Paid Amount.
      */
     totals.oldPackagePaid+=paid;
     totals.oldPackageCount+=1;
    }else{
     /*
      * Safety bucket for a missing/invalid invoice date.
      * Keep the payment visible separately instead of mixing it
      * into new-package sales.
      */
     totals.oldPackagePaid+=paid;
     totals.unknownPackageCount+=1;
    }

    totals.totalPaidReceived+=paid;

    return totals;
   },
   {
    withGst:0,
    withoutGst:0,
    paid:0,
    oldPackagePaid:0,
    balance:0,
    totalPaidReceived:0,
    newPackageCount:0,
    oldPackageCount:0,
    unknownPackageCount:0
   }
  );
}

function ccInvoiceExactTotals(rows){
 return (Array.isArray(rows)?rows:[])
