   (totals,row)=>{
    totals.withGst+=Math.max(
     Number(row&&row.with_gst||0),
     0
    );

    totals.withoutGst+=Math.max(
     Number(row&&row.without_gst||0),
     0
    );

    totals.paid+=Math.max(
     Number(row&&row.paid||0),
     0
    );

    totals.balance+=Math.max(
     Number(row&&row.balance||0),
     0
    );

    totals.outstandingCollected+=Math.max(
     Number(
      row&&row.outstanding_collected||0
     ),
     0
    );

    totals.invoiceCount+=1;

    return totals;
   },
   {
    withGst:0,
    withoutGst:0,
    paid:0,
    balance:0,
    outstandingCollected:0,
    invoiceCount:0
   }
  );
}

