/* ===== Render summary (report 1) — exact appointment-status buckets ===== */
function render(){
 removeBackToCrmControls();
 arrangeCcFilterUi();

 if(!LOADED)return;

 /*
  * Never allow an Agent login to render all-agent CC Agent Summary,
  * even if F.agent was cleared by an older UI state.
  */
 if(
  GRP==="agent"&&
  isLifeCcAgentLogin()
 ){
  enforceLoggedAgentCcScope();
 }

 const rows=filt();
 const tot=rows.length;
 const b=rows.filter(r=>r.cat===CATS[0]).length;
 const nb=rows.filter(r=>r.cat===CATS[1]).length;
 const nv=rows.filter(r=>r.cat===CATS[2]).length;
 const scheduled=rows.filter(r=>r.cat===CATS[3]).length;
 const notBooked=rows.filter(r=>r.cat===CATS[4]).length;
 const cancelled=rows.filter(r=>r.cat===CATS[5]).length;
 const other=rows.filter(r=>r.cat===CATS[6]).length;
 const visited=rows.filter(r=>r.cat===CATS[7]).length;
 const resolvedVisitCount=b+nb;
 const totalVisits=b+nb+visited;
 const currentFinancialEvents=
  FINANCIAL_EVENTS.length
   ?financialEventsForCurrentFilters()
   :[];

 /*
  * EXACT CC INVOICE REPORT SOURCE FOR BRANCH SUMMARY
  * ------------------------------------------------
  * Financial values no longer come from the generic transaction-event
  * timeline. They come from the same invoice/payment qualification as
  * the actual ERPNext "CC Invoice Report".
  */
 const ccInvoiceExactRows=
  ccInvoiceExactRowsForCurrentFilters();

 const ccInvoiceExactFinancials=
  ccInvoiceExactTotals(
   ccInvoiceExactRows
  );

 const ccInvoicePackageSplit=
  ccInvoicePackageSplitTotals(
   ccInvoiceExactRows
  );

 const hasExactCcInvoiceSummary=
  CC_INVOICE_REPORT_SUMMARY_MAP.has(
   String(F.from||"")+
   "|"+
   String(F.to||"")
  );

 const financialTotals=
  hasExactCcInvoiceSummary
   ?{
     withGst:
      ccInvoicePackageSplit.withGst,
     withoutGst:
      ccInvoicePackageSplit.withoutGst,
     paid:
      ccInvoicePackageSplit.paid,
     oldPackagePaid:
      ccInvoicePackageSplit.oldPackagePaid,
     balance:
      ccInvoicePackageSplit.balance
    }
   :zeroPackageFinancialTotals();

 const outstandingCollected=
  hasExactCcInvoiceSummary
   ?ccInvoicePackageSplit.oldPackagePaid
   :0

 const conversion=totalVisits
  ?Math.round(b/totalVisits*100)+"%"
  :"—";

 const branchFinancialCards=[
  [
   "New Package With GST",
   dashboardMoney(
    financialTotals.withGst
   ),
   "gr"
  ],
  [
   "New Package Without GST",
   dashboardMoney(
    financialTotals.withoutGst
   ),
   "gr"
  ],
  [
   "New Package Paid Amount",
   dashboardMoney(
    financialTotals.paid
   ),
   "gr"
  ],
  [
   "Old Package Paid Amount",
   dashboardMoney(
    financialTotals.oldPackagePaid||0
   ),
   "gr"
  ],
  [
   "Old Package Paid + New Package Paid",
   dashboardMoney(
    Number(
     financialTotals.oldPackagePaid||0
    )+
    Number(
     financialTotals.paid||0
    )
   ),
   "gr"
  ],
  [
   "New Package Balance Amount",
   dashboardMoney(
    financialTotals.balance
   ),
   "or"
  ]
 ];

 const branchFunnelMetrics=
  lifeCcFunnelMetrics(
   F.from,
   F.to,
   {
    agent:isLifeCcAgentLogin()
     ?(loggedCcAgentScope()||currentPortalUser())
     :F.agent,
    branch:F.branch
   }
  );

 byId("kpis").insertAdjacentHTML(
  "beforebegin",
  `<div id="lifeCcBranchFunnelHost">${
   lifeCcFunnelCardsHtml(
    branchFunnelMetrics,
    {
     from:F.from,
     to:F.to,
     agent:
      isLifeCcAgentLogin()
       ?(loggedCcAgentScope()||currentPortalUser())
       :F.agent,
     branch:F.branch
    }
   )
  }</div>`
 );

 document.querySelectorAll("#lifeCcBranchFunnelHost").forEach((node,index,nodes)=>{
  if(index<nodes.length-1)node.remove();
 });

 byId("kpis").innerHTML=[
  ["Total Appointments",tot,""],
  ["Visit but Pending in Branch",visited,"gr"],
  ["Total Visit Count",resolvedVisitCount,"gr"],
  [
   "Visited + Total Visit Count",
   totalVisits,
   "gr"
  ],
  ["Booked",b,"gr"],
  ["Not Booked",nb,"or"],
  ["Not Visited",nv,"rd"],
  ["Scheduled / Awaiting Visit",scheduled,"pe"],
  ...branchFinancialCards,
  ["Cancelled",cancelled,"rd"],
  ["Other / Not Set",other,"pe"],
  ["Booking Conversion",conversion,""]
 ].map(k=>{
  const isMoney=
   [
    "With GST",
    "Without GST",
    "Paid Amount",
    "Outstanding Collected Amount",
    "Balance Amount",
    "New Package With GST",
    "New Package Without GST",
    "New Package Paid Amount",
    "Old Package Paid Amount",
    "Old Package Paid + New Package Paid",
    "New Package Balance Amount"
   ].includes(k[0]);

  const cardTitle=
   k[0]==="Outstanding Collected Amount"
    ?"Later CC Lead-linked collections received against invoices created on an earlier date: "+k[1]
    :(
      k[0]==="Old Package Paid Amount"
       ?"Payments received in the selected Payment Entry period against packages/invoices created before the selected From date: "+k[1]
       :(
         k[0]==="Old Package Paid + New Package Paid"
          ?"Old Package Paid Amount + New Package Paid Amount = "+k[1]
          :(
            k[0]==="Visited + Total Visit Count"
             ?"Visited + Total Visit Count = "+k[1]
             :(k[0]+": "+k[1])
           )
        )
     );

  const showCardTitle=
   isMoney||
   k[0]==="Visited + Total Visit Count";

  return `<div class="kpi ${isMoney?"money-kpi":""}" ${showCardTitle?`title="${lifeCcEsc(cardTitle)}"`:""}>
   <b class="num ${k[2]}">${k[1]}</b>
   <span>${k[0]}</span>
  </div>`;
 }).join("");

 byId("kpis").insertAdjacentHTML(
  "beforeend",
  lifeCc3mConversionCardsHtml(
   TODAY,
   {
    agent:isLifeCcAgentLogin()
     ?(loggedCcAgentScope()||currentPortalUser())
     :F.agent,
    branch:F.branch
   },
   "default"
  )
 );

 /*
  * Show only branches that contain records for the selected filters.
  * Previously all empty Branch master rows were rendered first, which
  * pushed the real branch/Branch Not Available row far down the table.
  */
 const keys=GRP==="branch"
  ?[
    ...new Set([
     ...branchKeysForRows(
      rows,
      false
     ),
     ...ccInvoiceExactRows
      .map(row=>
       normalizedBranchKey(
        row&&row.branch
       )
      )
      .filter(Boolean)
    ])
   ].sort((left,right)=>
    branchDisplayLabel(
     left,
     rows
    ).localeCompare(
     branchDisplayLabel(
      right,
      rows
     ),
     "en",
     {
      sensitivity:"base"
     }
    )
   )
  :(
    isLifeCcAgentLogin()
     ?[
       loggedCcAgentScope()||
       currentPortalUser()
      ]
     :(
       String(F.agent||"").trim()
        ?[
          String(F.agent||"").trim()
         ]
        :[
          ...new Set([
           ...rows
            .map(record=>record.agent)
            .filter(Boolean),
           ...ccInvoiceExactRows
            .map(row=>
             String(
              row&&row.lead_owner||""
             ).trim()||
             "__LIFE_UNASSIGNED_AGENT__"
            ),
           ...Object.keys(
            currentLeadReceivedSummary().byOwner||
            {}
           )
          ])
         ].sort((left,right)=>{
       const leftLabel=
        left==="__LIFE_UNASSIGNED_AGENT__"
         ?"Unassigned / No Lead Owner"
         :agName(left);

       const rightLabel=
        right==="__LIFE_UNASSIGNED_AGENT__"
         ?"Unassigned / No Lead Owner"
         :agName(right);

       return leftLabel.localeCompare(
        rightLabel,
        "en",
        {sensitivity:"base"}
       );
      })
      )
   );

 const keyOf=GRP==="branch"
  ?record=>recordBranchKey(record)
  :record=>record.agent;

 if(GRP==="branch"&&hasExactCcInvoiceSummary){
  const branchCheck=
   keys.reduce(
    (sum,key)=>{
     const branchRows=
      ccInvoiceExactRows.filter(row=>
       normalizedBranchKey(
        row&&row.branch
       )===key
      );

     const totals=
      ccInvoiceExactTotals(
       branchRows
      );

     const split=
      ccInvoicePackageSplitTotals(
       branchRows
      );

     sum.withGst+=split.withGst;
     sum.withoutGst+=split.withoutGst;
     sum.paid+=split.paid;
     sum.oldPackagePaid+=
      split.oldPackagePaid;
     sum.balance+=split.balance;

     return sum;
    },
    {
     withGst:0,
     withoutGst:0,
     paid:0,
     oldPackagePaid:0,
     balance:0
    }
   );

  console.log(
   "NEW CALL CENTER PACKAGES ONLY reconciliation:",
   {
    from:F.from,
    to:F.to,
    qualifying_invoices:
     ccInvoiceExactFinancials.invoiceCount,
    total:{
     newPackageWithGst:
      financialTotals.withGst,
     newPackageWithoutGst:
      financialTotals.withoutGst,
     newPackagePaid:
      financialTotals.paid,
     oldPackagePaid:
      financialTotals.oldPackagePaid||0,
     newPackageBalance:
      financialTotals.balance
    },
    sum_of_branch_rows:
     branchCheck
   }
  );
 }

 if(GRP==="agent"){
  const leadReceivedSummary=
   currentLeadReceivedSummary();

  console.log(
   "CC Agent Summary Lead Received:",
   {
    from:F.from,
    to:F.to,
    total_received:
     leadReceivedSummary.total,
    by_owner:
     leadReceivedSummary.byOwner
   }
  );
 }

 if(GRP==="agent"&&hasExactCcInvoiceSummary){
  const agentCheck=
   keys.reduce(
    (sum,key)=>{
     const agentInvoiceRows=
      ccInvoiceExactRows.filter(row=>{
       const owner=
        String(
         row&&row.lead_owner||""
        ).trim();

       if(
        key==="__LIFE_UNASSIGNED_AGENT__"
       ){
        return !owner;
       }

       return sameAgentOwner(
        owner,
        key
       );
      });

     const split=
      ccInvoicePackageSplitTotals(
       agentInvoiceRows
      );

     sum.withGst+=split.withGst;
     sum.withoutGst+=split.withoutGst;
     sum.paid+=split.paid;
     sum.oldPackagePaid+=
      split.oldPackagePaid;
     sum.balance+=split.balance;

     return sum;
    },
    {
     withGst:0,
     withoutGst:0,
     paid:0,
     oldPackagePaid:0,
     balance:0
    }
   );

  console.log(
   "CC AGENT SUMMARY · SELF-ONLY / CALL CENTER PACKAGE reconciliation:",
   {
    logged_in_user:
     currentPortalUser(),
    agent_login:
     isLifeCcAgentLogin(),
    effective_agent:
     (
      isLifeCcAgentLogin()
       ?loggedCcAgentScope()
       :F.agent
     ),
    from:F.from,
    to:F.to,
    total:{
     newPackageWithGst:
      financialTotals.withGst,
     newPackageWithoutGst:
      financialTotals.withoutGst,
     newPackagePaid:
      financialTotals.paid,
     oldPackagePaid:
      financialTotals.oldPackagePaid||0,
     newPackageBalance:
      financialTotals.balance
    },
    sum_of_agent_rows:
     agentCheck
   }
  );
 }

 byId("sumWrap").innerHTML=`
  <h3>
   ${GRP==="branch"?"🏥 Branch Summary":"🎧 CC Agent Summary"}
   ${
    GRP==="agent"
     ?`<span class="pill p-b">
       NEW Call Center packages only · Already Taken = No · grouped by Lead Owner
      </span>`
     :""
   }
   <span class="pill p-gr" style="margin-left:auto">
    ${ccDisplayDate(F.from)} →
    ${ccDisplayDate(F.to)}
   </span>
  </h3>

  <div style="overflow-x:auto">
   <table
    class="tbl exact-status-summary compact-financial-table summary-compact-table"
    style="
     width:${GRP==="agent"?"1100px":"1030px"};
     min-width:${GRP==="agent"?"1100px":"1030px"};
     max-width:${GRP==="agent"?"1100px":"1030px"};
     table-layout:fixed;
    "
   >
    <colgroup>
     <col class="col-branch">
     ${GRP==="agent"?'<col class="col-lead-received">':""}
     <col class="col-total">
     <col class="col-status">
     <col class="col-total-visit">
     <col class="col-status">
     <col class="col-not-booked">
     <col class="col-not-visited">
     <col class="col-money">
     <col class="col-money">
