     <col class="col-percent">
    </colgroup>
    <thead>
     <tr>
      <th class="th-agent">
       <span class="th-label">
        ${GRP==="branch"?"Branch":"CC Agent"}
       </span>
      </th>
      ${
       GRP==="agent"
        ?`<th class="th-lead-received" style="text-align:right">
           <span class="th-label">Lead<br>Received</span>
          </th>`
        :""
      }
      <th class="th-total-appointment" style="text-align:right">
       <span class="th-label">Total<br>Appointment</span>
      </th>
      <th class="th-visit-pending" style="text-align:right">
       <span class="th-label">Visit but Pending<br>in Branch</span>
      </th>
      <th class="th-total-visit" style="text-align:right">
       <span class="th-label">Total Visit<br>Count</span>
      </th>
      <th class="th-booked" style="text-align:right">
       <span class="th-label">Booked</span>
      </th>
      <th class="th-not-booked" style="text-align:right">
       <span class="th-label">Not Booked</span>
      </th>
      <th class="th-not-visited" style="text-align:right">
       <span class="th-label">Not Visited</span>
      </th>
      <th class="fin-col th-money" style="text-align:right">
       <span class="th-label">New Package<br>With GST</span>
      </th>
      <th class="fin-col th-money" style="text-align:right">
       <span class="th-label">New Package<br>W/O GST</span>
      </th>
      <th
       class="fin-col th-money"
       style="text-align:right"
       title="Payment received in selected period against Call Center invoices created inside the selected From/To period"
      >
