      const totalVisitCount=
       visitedBooked+
       visitedNotBooked;

      const groupVisits=
       totalVisitCount+
       visitedRows;

      const rowConversion=
       groupVisits
        ?Math.round(
          visitedBooked/
          groupVisits*
          100
         )+"%"
        :"—";

      return `
       <tr
        class="clk js-life-drill-row"
