        :""
      }
      <td class="num" style="text-align:right">${tot}</td>
      <td class="num cB" style="text-align:right">${visited}</td>
      <td class="num cB total-visit-cell" style="text-align:right;font-weight:800">${b+nb}</td>
      <td class="num cB" style="text-align:right">${b}</td>
      <td class="num cN" style="text-align:right">${nb}</td>
      <td class="num cV" style="text-align:right">${nv}</td>
      <td class="num fin-col" style="text-align:right">${dashboardMoney(financialTotals.withGst)}</td>
      <td class="num fin-col" style="text-align:right">${dashboardMoney(financialTotals.withoutGst)}</td>
      <td class="num fin-col cB" style="text-align:right">${dashboardMoney(financialTotals.paid)}</td>
      <td class="num fin-col" style="text-align:right;font-weight:800">
       ${dashboardMoney(financialTotals.oldPackagePaid||0)}
      </td>
      <td class="num fin-col cN" style="text-align:right">${dashboardMoney(financialTotals.balance)}</td>
      <td class="num" style="text-align:right">${conversion}</td>
     </tr>
    </tbody>
   </table>
  </div>`;

 bindSummaryDrillRows();

 /*
  * PERFORMANCE:
  * Do NOT automatically download 10k+ historical Lead rows every
  * time Branch Summary renders.
  *
  * The 3-month comparison shell is installed below and loads only
  * when the user explicitly opens it.
  */
 life3mInstallLazyComparisonShell(
  GRP
 );
}

/* ===== Drill-down: centered live-data popup ===== */

function popupOpenedDateTime(){
 const now=new Date();

 const dateText=now.toLocaleDateString(
  "en-GB",
  {
   day:"2-digit",
   month:"short",
   year:"numeric"
  }
 );

 const timeText=now.toLocaleTimeString(
  "en-IN",
  {
   hour:"2-digit",
   minute:"2-digit",
   hour12:true
  }
 ).toLowerCase();

 return {
  date:dateText,
  time:timeText
 };
}

function decodeDrillKey(encodedKey){
 try{
  return decodeURIComponent(String(encodedKey||""));
 }catch(error){
  return String(encodedKey||"");
 }
}

function branchPopupDateTime(value){
 const text=String(value||"").trim();

 if(!text||text==="—"){
  return `
   <span class="drill-appt-date">—</span>
   <span class="drill-appt-time">—</span>`;
 }

 const normalized=text.replace(" ","T");
 const date=new Date(normalized);

 if(Number.isNaN(date.getTime())){
  return `
   <span class="drill-appt-date">${lifeCcEsc(text)}</span>
   <span class="drill-appt-time">—</span>`;
 }

 const dateText=date.toLocaleDateString(
  "en-GB",
  {
   day:"2-digit",
   month:"short",
   year:"numeric"
  }
 );

 const timeText=date.toLocaleTimeString(
  "en-IN",
  {
   hour:"2-digit",
   minute:"2-digit",
   hour12:true
  }
 ).toLowerCase();

 return `
  <span class="drill-appt-date">${lifeCcEsc(dateText)}</span>
  <span class="drill-appt-time">${lifeCcEsc(timeText)}</span>`;
}

function lifeCcEscAttr(value){
 return String(value==null?"":value)
  .replace(/&/g,"&amp;")
  .replace(/"/g,"&quot;")
  .replace(/</g,"&lt;")
  .replace(/>/g,"&gt;");
}

function popupFullMobile(value){
 const raw=String(value||"").trim();
 const digits=raw.replace(/\D/g,"");

 if(digits.length>=10)return digits.slice(-10);
 return digits||raw;
}

function maskPopupMobile(value){
 const full=popupFullMobile(value);
 const digits=String(full||"").replace(/\D/g,"");

 if(!digits)return "—";
 if(digits.length<6)return digits;

 return digits.slice(0,3)+"****"+digits.slice(-3);
}

function popupMobileHtml(value){
 const full=popupFullMobile(value);

 if(!full){
