const POPUP_CLIENT_CACHE=new Map();
const POPUP_PLAN_CACHE=new Map();

function normalizePhone10(value){
 return String(value||"")
  .replace(/\D/g,"")
  .slice(-10);
}

function normalizePersonName(value){
 return String(value||"")
  .trim()
  .toLowerCase()
  .replace(/\s+/g," ");
}

function uniqueNonEmpty(values){
 return [...new Set(
  (values||[])
   .map(value=>String(value||"").trim())
   .filter(Boolean)
 )];
}

function splitIntoChunks(values,size){
 const output=[];

 for(let index=0;index<values.length;index+=size){
  output.push(values.slice(index,index+size));
 }

 return output;
}

async function apiGetListChunks(
 doctype,
 fields,
 filterField,
 values,
 options
){
 const uniqueValues=uniqueNonEmpty(values);
 if(!uniqueValues.length)return [];

 const chunks=splitIntoChunks(uniqueValues,80);
 const rows=[];
 const PARALLEL=4;

 for(let i=0;i<chunks.length;i+=PARALLEL){
  const batch=chunks.slice(i,i+PARALLEL);
  const results=await Promise.all(
   batch.map(chunk=>
    apiGetList(
     doctype,
     fields,
     [[filterField,"in",chunk]],
     Object.assign({limit_page_length:0},options||{})
    )
   )
  );

  results.forEach(result=>{
   if(Array.isArray(result))rows.push(...result);
  });
 }

 return rows;
}

function patientMobileVariants(phone){
 const mobile=normalizePhone10(phone);

 if(!mobile)return [];

 return [
  mobile,
  "91"+mobile,
  "+91"+mobile
 ];
}

function choosePatientForRecord(record,patientRows){
 const rows=patientRows||[];

 /*
  * 1. Exact Patient ID already returned by the secure API.
  */
 if(record&&record.patientName){
  const exactPatient=rows.find(patient=>
   String(patient.name||"").trim()===
   String(record.patientName||"").trim()
  );

  if(exactPatient){
   return exactPatient;
  }
 }

 /*
  * 2. Exact Lead -> Patient.custom_lead relation.
  */
 if(record&&record.name){
  const exactLeadPatient=rows.find(patient=>
   String(patient.custom_lead||"").trim()===
   String(record.name||"").trim()
  );

  if(exactLeadPatient){
   return exactLeadPatient;
  }
 }

 /*
  * 3. Exact Customer ID fallback.
  */
 if(record&&record.leadCustomer){
  const exactCustomerRows=rows.filter(patient=>
   String(patient.customer||"").trim()===
   String(record.leadCustomer||"").trim()
  );

  if(exactCustomerRows.length===1){
   return exactCustomerRows[0];
  }
 }

 /*
  * 4. Mobile fallback. If more than one Patient has the same
  * mobile, require exact client-name match.
  */
 const mobile=normalizePhone10(
  record&&record.ph
 );

 if(!mobile)return null;

 const candidates=rows.filter(patient=>
  normalizePhone10(patient.mobile)===mobile
 );

 if(!candidates.length)return null;
 if(candidates.length===1)return candidates[0];

 const recordName=normalizePersonName(
  record&&record.client
 );

 const exactName=candidates.find(patient=>
  normalizePersonName(patient.patient_name)===
  recordName
 );

 return exactName||null;
}

function daysBetweenDates(left,right){
 const leftDate=new Date(String(left||"").slice(0,10)+"T00:00:00");
 const rightDate=new Date(String(right||"").slice(0,10)+"T00:00:00");

 if(
  Number.isNaN(leftDate.getTime())||
  Number.isNaN(rightDate.getTime())
 ){
  return 999999;
 }

 return Math.round(
  (leftDate.getTime()-rightDate.getTime())/86400000
 );
}

function choosePlanForAppointment(record,plans){
 if(!plans||!plans.length)return null;

 /*
  * The Sales Invoice has direct Therapy Plan links in this site.
  * Always use that exact plan when available.
  */
 const linkedPlanId=String(
  record&&record.therapyPlanName||""
 ).trim();

 if(linkedPlanId){
  const exactPlan=plans.find(plan=>
   String(plan.name||"").trim()===
   linkedPlanId
  );

  if(exactPlan){
   return exactPlan;
  }
 }

 const appointmentDate=String(record.dt||"").slice(0,10);

 return [...plans].sort((left,right)=>{
  const leftDiff=daysBetweenDates(
   left.start_date||left.creation,
   appointmentDate
  );

  const rightDiff=daysBetweenDates(
   right.start_date||right.creation,
   appointmentDate
  );

  /*
   * Prefer a Therapy Plan beginning on the appointment date or
   * shortly afterwards. This avoids showing an unrelated old plan.
   */
  const leftPriority=
   leftDiff>=-1&&leftDiff<=45
    ?0
    :1;

  const rightPriority=
   rightDiff>=-1&&rightDiff<=45
    ?0
    :1;

  if(leftPriority!==rightPriority){
   return leftPriority-rightPriority;
  }

  const leftDistance=Math.abs(leftDiff);
  const rightDistance=Math.abs(rightDiff);

  if(leftDistance!==rightDistance){
   return leftDistance-rightDistance;
  }

  return String(right.modified||"").localeCompare(
   String(left.modified||"")
  );
 })[0]||null;
}


function firstPositiveAmount(values){
 for(const value of values){
  const amount=Number(value||0);

  if(
   Number.isFinite(amount)&&
   amount>0
  ){
   return amount;
  }
 }

 return 0;
}

function salesInvoiceAmountWithGst(invoice){
 return firstPositiveAmount([
  invoice&&invoice.rounded_total,
  invoice&&invoice.grand_total,
  invoice&&invoice.base_grand_total
 ]);
}

function salesInvoiceAmountWithoutGst(invoice){
 /*
  * Net Total is the amount after discount and before GST/taxes.
  */
 const directAmount=firstPositiveAmount([
  invoice&&invoice.net_total,
  invoice&&invoice.base_net_total,
  invoice&&invoice.total,
  invoice&&invoice.base_total
 ]);

 if(directAmount>0){
  return directAmount;
 }

 const withGst=
  salesInvoiceAmountWithGst(invoice);

 const taxes=firstPositiveAmount([
  invoice&&invoice.total_taxes_and_charges,
  invoice&&invoice.base_total_taxes_and_charges
 ]);

 const calculated=
  withGst-taxes;

 return (
  Number.isFinite(calculated)&&
  calculated>0
 )
  ?calculated
  :0;
}

function salesInvoiceBalanceAmount(invoice){
 const rawValue=
  invoice&&invoice.outstanding_amount!==undefined
   ?invoice.outstanding_amount
   :invoice&&invoice.base_outstanding_amount;

 const balance=Number(rawValue||0);

 return (
  Number.isFinite(balance)&&
  balance>0
 )
  ?balance
  :0;
}

function salesInvoicePaidAmount(invoice){
 /*
  * IMPORTANT:
  * Do NOT calculate Paid = Grand Total - current outstanding.
  * Current outstanding can become zero after payments made on later
  * dates, which wrongly makes the invoice look fully paid on the
  * invoice/appointment date.
  *
  * For the invoice-created row use only Sales Invoice.paid_amount.
  * Later Payment Entry collections are displayed as separate
  * transaction-date rows.
  */
 const withGst=
  salesInvoiceAmountWithGst(invoice);

 const directPaid=Number(
  invoice&&invoice.paid_amount||0
 );

 if(
  !Number.isFinite(directPaid)||
  directPaid<=0
 ){
  return 0;
 }

 return withGst>0
  ?Math.min(directPaid,withGst)
  :directPaid;
}

function salesInvoiceFinancials(invoice){
 const withGst=
  salesInvoiceAmountWithGst(invoice);

 const paid=
  salesInvoicePaidAmount(invoice);

 /*
  * Balance immediately after invoice creation.
  * Do not use today's outstanding_amount here.
  */
 const invoiceDateBalance=
  Math.max(
   withGst-paid,
   0
  );

 return {
  withoutGst:
   salesInvoiceAmountWithoutGst(invoice),
  withGst:withGst,
  paid:paid,
  balance:invoiceDateBalance
 };
}

function normalizedCustomerKey(value){
 return String(value||"")
  .trim()
  .toLowerCase()
  .replace(/\s+/g," ");
}

function chooseInvoiceForAppointment(
 record,
 invoiceRows
){
 const patientId=String(
  record&&record.patientName||""
 ).trim();

 const appointmentDate=String(
  record&&record.dt||""
 ).slice(0,10);

 if(!patientId||!appointmentDate){
  return null;
 }

 /*
  * STRICT RULE:
  * 1. Exact Patient ID
  * 2. Submitted Sales Invoice
  * 3. Invoice posting date must equal this appointment date
  *
  * We intentionally do NOT select another invoice from a previous
  * or later date. Package sales are reported on invoice posting date.
  */
 let candidates=(invoiceRows||[])
  .filter(invoice=>
   Number(invoice.docstatus)===1&&
   String(invoice.patient||"").trim()===
    patientId&&
   String(invoice.posting_date||"").slice(0,10)===
    appointmentDate&&
   salesInvoiceAmountWithGst(invoice)>0
  );

 if(!candidates.length){
  return null;
 }

 /*
  * When secure API already tells us the exact Therapy Plan,
  * require that plan link if possible.
  */
 const linkedPlanId=String(
  record&&record.therapyPlanName||""
 ).trim();

 if(linkedPlanId){
  const exactPlanCandidates=
   candidates.filter(invoice=>{
    const invoicePlan=String(
     invoice.custom_therapy_plan||
     invoice.therapy_plan_reference_id||
     ""
    ).trim();

    return invoicePlan===linkedPlanId;
   });

  if(exactPlanCandidates.length===1){
   return exactPlanCandidates[0];
  }

  if(exactPlanCandidates.length>1){
   console.warn(
    "Multiple Sales Invoices found for exact Patient + Therapy Plan + date.",
    {
     patient:patientId,
     therapy_plan:linkedPlanId,
     date:appointmentDate,
     invoices:exactPlanCandidates.map(row=>row.name)
    }
   );
   return null;
  }
 }

 /*
  * A unique invoice for the exact Patient on that date is safe.
  * If there are multiple invoices and no exact Therapy Plan match,
  * return null instead of showing the wrong package.
  */
 if(candidates.length===1){
  return candidates[0];
 }

 console.warn(
  "Ambiguous Sales Invoice match. Financial amount suppressed.",
  {
   patient:patientId,
   date:appointmentDate,
   invoices:candidates.map(row=>({
    name:row.name,
    therapy_plan:
     row.custom_therapy_plan||
     row.therapy_plan_reference_id||
     ""
   }))
  }
 );

 return null;
}

