async function applySalesInvoicePackageAmounts(
 records
){
 const source=Array.isArray(records)
  ?records
  :[];

 const invoiceRows=
  await fetchSubmittedSalesInvoicesForRecords(
   source
  );

 source.forEach(record=>{
  if(!isPackageBookedRecord(record)){
   return;
  }

  const invoice=
   chooseInvoiceForAppointment(
    record,
    invoiceRows
   );

  if(!invoice){
   return;
  }

  const financials=
   salesInvoiceFinancials(invoice);

  if(
   financials.withoutGst>0||
   financials.withGst>0
  ){
   record.clientPackageAmount=
    financials.withoutGst;

   record.clientPackageAmountWithoutGst=
    financials.withoutGst;

   record.clientPackageAmountWithGst=
    financials.withGst;

   record.clientPaidAmount=
    financials.paid;

   record.clientBalanceAmount=
    financials.balance;

   record.salesInvoiceName=
    invoice.name||"";

   record.salesInvoiceDate=
    invoice.posting_date||"";

   record.packageAmountSource=
    "Sales Invoice";
  }
 });

 console.log(
  "Booked package amount mapping:",
  {
   booked_records:source.filter(
    isPackageBookedRecord
   ).length,
   submitted_invoices:
    invoiceRows.length,
