   ).length
  }
 );

 return source;
}

async function resolveClientConsultantDisplayNames(records){
 const consultantIds=uniqueNonEmpty(
  (records||[])
   .map(record=>record.clientConsultantId)
 );

 if(!consultantIds.length)return records;

 const consultantNameById=new Map();
 const practitionerEmployeeById=new Map();

 /*
  * Client creation currently stores the Consultant link value in
  * Patient.custom_employee_id. Values such as HLC-PRAC-2026-00145
  * belong to Healthcare Practitioner, so resolve practitioner_name.
  */
 try{
  const practitionerRows=await apiGetListChunks(
   "Healthcare Practitioner",
   [
    "name",
    "practitioner_name",
    "employee"
   ],
   "name",
   consultantIds,
   {
    order_by:"practitioner_name asc"
   }
  );

  practitionerRows.forEach(practitioner=>{
   const practitionerId=String(
    practitioner.name||""
   ).trim();

   if(!practitionerId)return;

   const practitionerName=String(
    practitioner.practitioner_name||""
   ).trim();

   if(practitionerName){
    consultantNameById.set(
     practitionerId,
     practitionerName
    );
   }

   const employeeId=String(
    practitioner.employee||""
   ).trim();

   if(employeeId){
    practitionerEmployeeById.set(
     practitionerId,
     employeeId
    );
   }
  });
 }catch(error){
  console.error(
   "Could not resolve Healthcare Practitioner consultant names:",
   error
  );
 }

 /*
  * Fallback support:
  * - custom_employee_id may contain a real Employee ID on older clients.
  * - a Healthcare Practitioner may have no practitioner_name but have an
  *   Employee link.
  */
 const unresolvedIds=consultantIds.filter(
  consultantId=>!consultantNameById.has(consultantId)
 );

 const employeeIds=uniqueNonEmpty([
  ...unresolvedIds,
  ...practitionerEmployeeById.values()
 ]);

 if(employeeIds.length){
  try{
   const employeeRows=await apiGetListChunks(
    "Employee",
    [
     "name",
     "employee_name"
    ],
    "name",
    employeeIds,
    {
     order_by:"employee_name asc"
    }
   );

   const employeeNameById=new Map();

   employeeRows.forEach(employee=>{
    const employeeId=String(
     employee.name||""
    ).trim();

    if(!employeeId)return;

    employeeNameById.set(
     employeeId,
     employee.employee_name||
     employee.name
    );
   });

   unresolvedIds.forEach(consultantId=>{
    const directEmployeeName=
     employeeNameById.get(consultantId);

    const linkedEmployeeId=
     practitionerEmployeeById.get(consultantId);

    const linkedEmployeeName=
     linkedEmployeeId
      ?employeeNameById.get(linkedEmployeeId)
      :"";

    const resolvedName=
     directEmployeeName||
     linkedEmployeeName||
     "";

    if(resolvedName){
     consultantNameById.set(
      consultantId,
      resolvedName
     );
    }
   });
  }catch(error){
   console.error(
    "Could not resolve fallback Employee consultant names:",
    error
   );
  }
 }

 records.forEach(record=>{
  const consultantId=String(
   record.clientConsultantId||""
  ).trim();

  if(!consultantId)return;

  record.clientConsultant=
   consultantNameById.get(consultantId)||
   record.cons||
   consultantId;
 });

 return records;
}

