 result.forEach(record=>{
  const patientPlans=record&&record.patientName
   ?(plansByPatient.get(record.patientName)||[])
   :[];

  const uniquePlanNames=[...new Set(
   patientPlans.map(plan=>String(plan&&plan.name||"").trim()).filter(Boolean)
  )];

  record.therapyPlansQty=uniquePlanNames.length;
  record.rebookingCountAfterJoining=Math.max(0,uniquePlanNames.length-1);
 });

 result.forEach(record=>{
  if(
   !isPackageBookedRecord(record)||
   !record.patientName
  ){
   return;
  }

  const plan=choosePlanForAppointment(
   record,
   plansByPatient.get(record.patientName)||[]
  );

  if(!plan)return;

  record.clientPackageCategory=
   record.clientPackageCategory!=="—"
    ?record.clientPackageCategory
    :(plan.category||"—");

  /*
   * Correct package value priority:
   * 1. offer_price  = actual package selling/booked price
   * 2. total_amount = plan total when no offer price is saved
   * 3. custom_total_plan_amount = legacy fallback only
   *
   * The old code used custom_total_plan_amount first, which can be a
   * calculated/internal plan value and may not equal the booked package
   * amount shown to the client.
   */
  record.clientPackageAmount=therapyPlanPackageAmount(plan);

  record.therapyPlanName=plan.name||"";

  /*
   * Use Therapy Plan/Lead consultant only when no consultant was
   * selected during Client creation.
   */
  if(
   !record.clientConsultantId&&
   (
    !record.clientConsultant||
    record.clientConsultant==="—"
   )
  ){
   record.clientConsultant=
    record.cons||
    "—";
  }
 });

 /*
  * The submitted Sales Invoice amount without GST is the reliable booked package
  * value. The HAR confirms these standard fields are available:
  * customer, customer_name, contact_mobile, posting_date,
  * grand_total, rounded_total, net_total and docstatus.
  */
 const recordsMissingSecureFinancials=
  result.filter(record=>
   isPackageBookedRecord(record)&&
   Number(
    record.clientPackageAmountWithGst||
    record.clientPackageAmountWithoutGst||
    0
   )<=0
  );

 if(recordsMissingSecureFinancials.length){
  await applySalesInvoicePackageAmounts(
   recordsMissingSecureFinancials
  );
 }

 return result;
}

/*
 * Load Therapy Plan package amounts only for booked Leads and keep
 * the result cached by Lead ID. This makes the package amount card
 * and branch totals available without reloading every popup.
 */
async function enrichBookedPackageAmounts(records){
 const source=Array.isArray(records)?records:[];

 /*
  * Secure API amounts are already present on Agent records.
  * Put them in the cache immediately so no Sales Invoice client query
  * is attempted for those records.
  */
 source.forEach(record=>{
  if(
   !record||
   !record.name||
   !isPackageBookedRecord(record)
  ){
   return;
  }

  const hasSecureFinancials=
   Number(
    record.clientPackageAmountWithGst||
    record.clientPackageAmountWithoutGst||
    0
   )>0;

  if(!hasSecureFinancials){
   return;
  }

  BOOKED_PACKAGE_CACHE.set(
   record.name,
   {
    clientPackageAmount:
     Number(
      record.clientPackageAmountWithoutGst||
      record.clientPackageAmount||
      0
     ),

    clientPackageAmountWithoutGst:
     Number(
      record.clientPackageAmountWithoutGst||
      record.clientPackageAmount||
      0
     ),

    clientPackageAmountWithGst:
     Number(record.clientPackageAmountWithGst||0),

    clientPaidAmount:
     Number(record.clientPaidAmount||0),

    clientBalanceAmount:
     Number(record.clientBalanceAmount||0),

    clientPackageCategory:
     record.clientPackageCategory||"—",

    therapyPlanName:
     record.therapyPlanName||"",

    salesInvoiceName:
     record.salesInvoiceName||"",

    salesInvoiceDate:
     record.salesInvoiceDate||"",

    packageAmountSource:
     record.packageAmountSource||
     "Secure Sales Invoice API",

    patientCustomer:
     record.patientCustomer||"",

    patientName:
     record.patientName||"",

    clientConsultant:
     record.clientConsultant||
     record.cons||
     "—",

    clientConsultantId:
     record.clientConsultantId||""
   }
  );
 });

 const pending=source.filter(record=>
  isPackageBookedRecord(record)&&
  record.name&&
  !BOOKED_PACKAGE_CACHE.has(record.name)
 );

 if(pending.length){
  try{
   const enriched=
    await enrichPopupRecordsWithClientData(
     pending
    );

   enriched.forEach(record=>{
    if(!record||!record.name)return;

    BOOKED_PACKAGE_CACHE.set(
     record.name,
     {
      clientPackageAmount:
       Number(record.clientPackageAmount||0),

      clientPackageAmountWithoutGst:
       Number(
        record.clientPackageAmountWithoutGst||
        record.clientPackageAmount||
        0
       ),

      clientPackageAmountWithGst:
       Number(record.clientPackageAmountWithGst||0),

      clientPaidAmount:
       Number(record.clientPaidAmount||0),

      clientBalanceAmount:
       Number(record.clientBalanceAmount||0),

      clientPackageCategory:
       record.clientPackageCategory||"—",
      therapyPlanName:
       record.therapyPlanName||"",
      salesInvoiceName:
       record.salesInvoiceName||"",
      salesInvoiceDate:
       record.salesInvoiceDate||"",
      packageAmountSource:
       record.packageAmountSource||"",
      patientCustomer:
       record.patientCustomer||"",
      patientName:
       record.patientName||"",
      clientConsultant:
       record.clientConsultant||record.cons||"—",
      clientConsultantId:
       record.clientConsultantId||""
     }
    );
   });
  }catch(error){
   console.error(
    "Could not load booked package amounts:",
    error
   );
  }
 }

 return source.map(record=>{
  if(
   !record||
   !record.name||
   !BOOKED_PACKAGE_CACHE.has(record.name)
  ){
   return record;
  }

  return Object.assign(
   {},
   record,
   BOOKED_PACKAGE_CACHE.get(record.name)
  );
 });
}

function bookedFinancialTotals(records){
 const seen=new Set();

 const totals={
  withoutGst:0,
  withGst:0,
  paid:0,
  balance:0
 };

 (Array.isArray(records)?records:[])
  .filter(record=>
   record&&
   record.cat===CATS[0]
  )
  .forEach(record=>{
   const key=String(
    record.salesInvoiceName||
    record.therapyPlanName||
    record.name||
    ""
   ).trim();

   if(key&&seen.has(key)){
    return;
   }

   if(key){
    seen.add(key);
   }

   const withoutGst=Number(
    record.clientPackageAmountWithoutGst||
    record.clientPackageAmount||
    0
   );

   const withGst=Number(
    record.clientPackageAmountWithGst||0
   );

   const paid=Number(
    record.clientPaidAmount||0
   );

   const balance=Number(
    record.clientBalanceAmount||0
   );

   if(Number.isFinite(withoutGst)&&withoutGst>0){
    totals.withoutGst+=withoutGst;
   }

   if(Number.isFinite(withGst)&&withGst>0){
    totals.withGst+=withGst;
   }

   if(Number.isFinite(paid)&&paid>0){
    totals.paid+=paid;
   }

   if(Number.isFinite(balance)&&balance>0){
    totals.balance+=balance;
   }
  });

 return totals;
}

function bookedPackageAmountTotal(records){
 return bookedFinancialTotals(records).withoutGst;
}

