function therapyPlanPackageAmount(plan){
 const offerPrice=Number(plan&&plan.offer_price||0);
 if(Number.isFinite(offerPrice)&&offerPrice>0){
  return offerPrice;
 }

 const totalAmount=Number(plan&&plan.total_amount||0);
 if(Number.isFinite(totalAmount)&&totalAmount>0){
  return totalAmount;
 }

 const legacyAmount=Number(
  plan&&plan.custom_total_plan_amount||0
 );

 return Number.isFinite(legacyAmount)&&legacyAmount>0
  ?legacyAmount
  :0;
}

