function consultantClean(value){
 const cleaned=String(value||"").trim();
 const normalized=cleaned.toLowerCase();

 if(
  !cleaned||
  cleaned==="—"||
  cleaned==="-"||
  normalized==="not assigned"||
  normalized==="consultant not assigned"||
  normalized==="manager not assigned"||
  normalized==="none"||
  normalized==="null"||
  normalized==="undefined"
 ){
  return "";
 }

 return cleaned;
}

function consultantKeyPart(value){
 return consultantClean(value)
  .toLowerCase()
  .replace(/\s+/g," ");
}

function consultantRangeKey(){
 return [
  CONSULTANT_FILTER.from,
  CONSULTANT_FILTER.to
 ].join("|");
}

function consultantBranchLabel(value){
 const raw=consultantClean(value);
 if(!raw)return "Branch Not Available";

 const key=normalizedBranchKey(raw);
 const master=BRANCHES.find(branch=>
  normalizedBranchKey(branch)===key
 );

 return master||raw;
}

function consultantRecordBranch(record){
 return consultantClean(
  record&&record.consultantReportBranch
 )||consultantClean(record&&record.br)||"";
}


function consultantEmployeeIsActive(employee){
 if(!employee||!employee.name){
  return false;
 }

 const status=
  consultantKeyPart(
   employee.status
  );

 /*
  * Employee master statuses such as Inactive / Left / Suspended
  * must not participate in Consultant / Manager grouping.
  * Missing status is kept for backward compatibility only.
  */
 return (
  !status||
  status==="active"
 );
}

function consultantManagerRank(employee){
 const designation=consultantKeyPart(
  employee&&employee.designation
 );

 if(!designation)return 999;

 if(designation==="senior manager")return 1;
 if(designation==="center manager")return 2;
 if(designation==="centre manager")return 2;
 if(designation==="branch manager")return 3;
 if(designation==="manager")return 4;

 if(designation.includes("senior manager"))return 5;
 if(designation.includes("center manager"))return 6;
 if(designation.includes("centre manager"))return 6;
 if(designation.includes("branch manager"))return 7;
 if(designation.includes("manager"))return 8;

 return 999;
}

function consultantBuildBranchManagerMap(employeeRows){
 const map=new Map();

 (Array.isArray(employeeRows)?employeeRows:[])
  .filter(employee=>{
   if(!employee||!employee.name)return false;

   if(
    !consultantEmployeeIsActive(employee)
   ){
    return false;
   }

   return (
    consultantManagerRank(employee)<999&&
    consultantClean(employee.branch)
   );
  })
  .sort((a,b)=>{
   const rankDiff=
    consultantManagerRank(a)-
    consultantManagerRank(b);

   if(rankDiff)return rankDiff;

   return consultantClean(
    a.employee_name
   ).localeCompare(
    consultantClean(b.employee_name),
    "en",
    {sensitivity:"base"}
   );
  })
  .forEach(employee=>{
   const branchKey=
    normalizedBranchKey(
     employee.branch
    );

   if(
    branchKey&&
    !map.has(branchKey)
   ){
    map.set(branchKey,employee);
   }
  });

 return map;
}

function consultantThreeMonthRange(endIso){
 const end=ccDateFromISO(
  String(endIso||TODAY)
 );

 /*
  * Rolling 3-month window:
  * Example 15-Sep → 16-Jun through 15-Sep.
  */
 const start=new Date(
  end.getFullYear(),
  end.getMonth()-3,
  end.getDate()+1
 );

 return {
  from:ccISOFromDate(start),
  to:ccISOFromDate(end)
 };
}

function consultantManagerThreeMonthKey(){
