 ].join("|");
}

function consultantManagerThreeMonthAverage(groupKey){
 const key=
  consultantManagerThreeMonthKey();

 const cached=
  CONSULTANT_MANAGER_3M_CACHE.get(key);

 if(!cached||!cached.byGroup){
  return null;
 }

 const value=
  Number(
   cached.byGroup[groupKey]||0
  );

 return Number.isFinite(value)
  ?value
  :0;
}

function consultantFormatAverage(value){
 if(
  value==null||
  !Number.isFinite(Number(value))
 ){
  return "—";
 }

 const n=Number(value);

 return Number.isInteger(n)
  ?String(n)
  :n.toFixed(1);
}

async function ensureConsultantManagerThreeMonthAverage(){
 if(
  CONSULTANT_REPORT_VIEW!=="manager"
 ){
  return;
 }

 const range=
  consultantThreeMonthRange(
   CONSULTANT_FILTER.to
  );

 const key=[
  range.from,
  range.to
 ].join("|");

 CONSULTANT_MANAGER_3M_ACTIVE_KEY=key;

 if(
  CONSULTANT_MANAGER_3M_CACHE.has(key)||
  CONSULTANT_MANAGER_3M_PROMISES.has(key)
 ){
  return;
 }

 const promise=(async()=>{
  try{
   let records=[];

   if(
    CONSULTANT_RANGE_CACHE.has(key)
   ){
    records=
     (
      CONSULTANT_RANGE_CACHE.get(key)||
      []
     ).map(row=>Object.assign({},row));
   }else{
    const raw=
     await fetchLeads(
      range.from,
      range.to
     );

    const uniqueRaw=[
     ...new Map(
      (raw||[])
       .filter(row=>row&&row.name)
       .map(row=>[row.name,row])
     ).values()
    ];

    records=
     uniqueRaw.map(
      leadRowToRecord
     );

    records=
     await enrichConsultantReportRecords(
      records
     );

    CONSULTANT_RANGE_CACHE.set(
     key,
     records.map(
      row=>Object.assign({},row)
     )
    );
   }

   const counts=new Map();

   records.forEach(record=>{
    if(!record)return;

    const groupKey=
     consultantManagerGroupKey(
      record
     );

    counts.set(
     groupKey,
     Number(
      counts.get(groupKey)||0
     )+1
    );
   });

   const byGroup={};

   counts.forEach(
    (count,groupKey)=>{
     byGroup[groupKey]=
      Math.round(
       (Number(count||0)/3)*10
      )/10;
    }
   );

   CONSULTANT_MANAGER_3M_CACHE.set(
    key,
    {
     range,
     byGroup,
     totalAppointments:
      records.length
    }
   );

   if(
    CONSULTANT_REPORT_VIEW==="manager"&&
    CONSULTANT_MANAGER_3M_ACTIVE_KEY===key&&
    byId("tb4")&&
    byId("tb4").classList.contains("on")
   ){
    renderConsultantReport();
   }
  }catch(error){
   console.warn(
    "Consultant manager 3-month average failed",
    error
   );

   CONSULTANT_MANAGER_3M_CACHE.set(
    key,
    {
     range,
     byGroup:{},
     totalAppointments:0,
     error:true
    }
   );
  }finally{
   CONSULTANT_MANAGER_3M_PROMISES.delete(
    key
   );
  }
 })();

 CONSULTANT_MANAGER_3M_PROMISES.set(
  key,
  promise
 );

 return promise;
}

function consultantTomorrowRange(){
 const today=ccDateFromISO(TODAY);
 const tomorrow=new Date(
  today.getFullYear(),
  today.getMonth(),
  today.getDate()+1
 );
 const iso=ccISOFromDate(tomorrow);
 return {from:iso,to:iso};
}

function getConsultantQuickRange(mode){
 if(mode==="tomorrow"){
  return consultantTomorrowRange();
 }
 return getCcQuickRange(mode);
}

function detectConsultantQuickRange(){
 const modes=[
  "today","yesterday","tomorrow",
  "this_week","last_week",
  "this_month","last_month"
 ];

 for(const mode of modes){
  const range=getConsultantQuickRange(mode);
  if(
   range&&
   range.from===CONSULTANT_FILTER.from&&
   range.to===CONSULTANT_FILTER.to
  )return mode;
 }
 return "";
}

async function enrichConsultantReportRecords(records){
 const source=Array.isArray(records)?records:[];
 if(!source.length)return source;

 const started=(window.performance&&performance.now)
  ?performance.now()
  :Date.now();

 /*
  * ULTRA FAST CONSULTANT LOAD
  * --------------------------
  * The secured main CC API already gives us:
  * - Patient
  * - Therapy Plan
  * - Sales Invoice
  * - Paid / Balance
  *
  * Do NOT reload Patient for every appointment unless Patient is missing.
  * Do NOT query Employee two or three times. Load the lightweight Employee
  * directory once and resolve consultant + manager locally.
  */

 const missingPatientRows=source.filter(record=>
  !consultantClean(record&&record.patientName)
 );

 if(missingPatientRows.length){
  const missingLeadIds=uniqueNonEmpty(
   missingPatientRows.map(record=>record&&record.name)
  );
  const missingMobiles=uniqueNonEmpty(
   missingPatientRows.flatMap(record=>
    patientMobileVariants(record&&record.ph)
   )
  );

  const patientFields=[
   "name","patient_name","custom_lead",
   "customer","mobile","branch_name",
   "custom_employee_id"
  ];

  let byLead=[];
  let byMobile=[];

  try{
   const results=await Promise.all([
    missingLeadIds.length
     ?apiGetListChunks(
       "Patient",patientFields,"custom_lead",missingLeadIds,
       {order_by:"modified desc"}
      )
     :Promise.resolve([]),
    missingMobiles.length
     ?apiGetListChunks(
       "Patient",patientFields,"mobile",missingMobiles,
       {order_by:"modified desc"}
      )
     :Promise.resolve([])
   ]);
   byLead=results[0]||[];
   byMobile=results[1]||[];
  }catch(error){
   console.warn("Consultant fast Patient fallback failed",error);
  }

  const patientPool=[...new Map(
   [...byLead,...byMobile]
    .filter(row=>row&&row.name)
    .map(row=>[row.name,row])
  ).values()];

  missingPatientRows.forEach(record=>{
   const patient=choosePatientForRecord(record,patientPool);
   if(!patient)return;

   record.patientName=
    consultantClean(patient.name)||"";

   record.patientDisplayName=
    consultantClean(record.patientDisplayName)||
    consultantClean(patient.patient_name)||"";

   /*
    * IMPORTANT FOR NOT VISITED:
    * Client creation stores the assigned consultant in
    * Patient.custom_employee_id. A Not Visited appointment may not have a
    * Therapy Plan yet, so this is the correct fallback consultant source.
    */
   if(!consultantClean(record.clientConsultantId)){
    record.clientConsultantId=
     consultantClean(patient.custom_employee_id);
   }

   if(
    !consultantClean(record.clientConsultant)&&
    consultantClean(record.clientConsultantId)
   ){
    record.clientConsultant=
     consultantClean(record.clientConsultantId);
   }
  });
 }

 const planFields=[
  "name","patient","patient_name","branch",
  "consultant_name","custom_employee_name",
  "start_date","creation","modified","status","docstatus"
 ];

 const exactPlanIds=uniqueNonEmpty(
  source.map(record=>record&&record.therapyPlanName)
 );

 const fallbackPatientIds=uniqueNonEmpty(
  source
   .filter(record=>!consultantClean(record&&record.therapyPlanName))
   .map(record=>record&&record.patientName)
 );

 /*
  * Employee master is independent of Therapy Plan resolution, so fetch it
  * at the SAME TIME as Therapy Plans instead of waiting for plan ->
  * practitioner -> employee -> manager round trips.
  */
 const employeeFields=[
  "name","employee_name","designation",
  "branch","reports_to","status"
 ];

 let exactPlans=[];
 let fallbackPlans=[];
 let employeeRows=[];

 try{
  const firstStage=await Promise.all([
   exactPlanIds.length
    ?apiGetListChunks(
      "Therapy Plan",planFields,"name",exactPlanIds,
      {order_by:"modified desc"}
     )
    :Promise.resolve([]),
   fallbackPatientIds.length
    ?apiGetListChunks(
      "Therapy Plan",planFields,"patient",fallbackPatientIds,
      {order_by:"modified desc"}
     )
    :Promise.resolve([]),
   consultantEmployeeDirectory()
  ]);

  exactPlans=firstStage[0]||[];
  fallbackPlans=firstStage[1]||[];
  employeeRows=firstStage[2]||[];
 }catch(error){
  console.warn("Consultant fast first-stage lookup failed",error);
 }

 const therapyPlanByName=new Map();
 const therapyPlansByPatient=new Map();

 [...exactPlans,...fallbackPlans].forEach(plan=>{
  if(!plan||!plan.name)return;
  const planName=consultantClean(plan.name);
  const patientId=consultantClean(plan.patient);
  therapyPlanByName.set(planName,plan);
  if(patientId){
   if(!therapyPlansByPatient.has(patientId)){
    therapyPlansByPatient.set(patientId,[]);
   }
   therapyPlansByPatient.get(patientId).push(plan);
  }
 });

 function planForRecord(record){
  if(!record)return null;

  const exactId=consultantClean(record.therapyPlanName);
  if(exactId&&therapyPlanByName.has(exactId)){
   const exact=therapyPlanByName.get(exactId);
   if(consultantClean(exact&&exact.consultant_name))return exact;
  }

  const patientId=consultantClean(record.patientName);
  let plans=(therapyPlansByPatient.get(patientId)||[])
   .filter(plan=>consultantClean(plan&&plan.consultant_name));
  if(!plans.length)return null;

  const appointmentDate=String(record.dt||"").slice(0,10);
  const branchKey=normalizedBranchKey(record.br||"");

  const sameBranch=plans.filter(plan=>
   branchKey&&normalizedBranchKey(plan&&plan.branch||"")===branchKey
  );
  if(sameBranch.length)plans=sameBranch;

  plans=plans.map(plan=>{
   const planDate=String(plan.start_date||plan.creation||"").slice(0,10);
   const diff=(appointmentDate&&planDate)
    ?Math.abs(daysBetweenDates(planDate,appointmentDate))
    :999999;
   return {plan,diff};
  }).sort((a,b)=>
   a.diff-b.diff||
   String(b.plan.modified||"").localeCompare(String(a.plan.modified||""))
  );

  return plans.length?plans[0].plan:null;
 }

 source.forEach(record=>{
  const plan=planForRecord(record);
  const consultantId=consultantClean(plan&&plan.consultant_name);
  const employeeName=consultantClean(plan&&plan.custom_employee_name);

  record.consultantTherapyPlanName=
   consultantClean(plan&&plan.name);

  record.consultantTherapyPlanConsultantId=
   consultantId;

  record.consultantTherapyPlanEmployeeName=
   employeeName;

  record.consultantReportBranch=
   consultantClean(plan&&plan.branch)||
   consultantClean(record.br)||"";

  /*
   * Source priority:
   * 1) Therapy Plan consultant
   * 2) Patient.custom_employee_id
   * 3) Lead.custom_consulting_doctor
   *
   * Do NOT erase the Patient/Lead consultant just because a Not Visited
   * appointment does not have a Therapy Plan.
   */
  if(consultantId){
   record.clientConsultantId=
    consultantId;

   record.clientConsultant=
    employeeName||
    consultantId;
  }else{
   const fallbackConsultantId=
    consultantClean(record.clientConsultantId)||
    (
     consultantClean(record.cons)!=="—"
      ?consultantClean(record.cons)
      :""
    );

   record.clientConsultantId=
    fallbackConsultantId;

   if(
    !consultantClean(record.clientConsultant)||
    consultantClean(record.clientConsultant)==="—"
   ){
    record.clientConsultant=
     fallbackConsultantId;
   }
  }

  record.consultantReportEligible=
   Boolean(
    consultantId||
    consultantClean(record.clientConsultantId)||
    (
     consultantClean(record.clientConsultant)&&
     consultantClean(record.clientConsultant)!=="—"
    )
   );
 });

 const allEmployeeById=new Map();
 const allEmployeeByName=new Map();
 const employeeById=new Map();
 const employeeByName=new Map();

 const branchManagerByBranch=
  consultantBuildBranchManagerMap(
   employeeRows
  );

 /*
  * Rebuild shared active indexes for renderer/team-member filtering.
  */
 CONSULTANT_ACTIVE_EMPLOYEE_IDS.clear();
 CONSULTANT_ACTIVE_EMPLOYEE_NAMES.clear();

 employeeRows.forEach(employee=>{
  if(!employee||!employee.name)return;

  const id=
   consultantClean(employee.name);

  const name=
   consultantKeyPart(
    employee.employee_name
   );

  if(id){
   allEmployeeById.set(
    id,
    employee
   );
  }

  if(name){
   allEmployeeByName.set(
    name,
    employee
   );
  }

  /*
   * Only Active employees are allowed to resolve into the report.
   * Inactive / Left / Suspended employees stay excluded.
   */
  if(
   !consultantEmployeeIsActive(employee)
  ){
   return;
  }

  if(id){
   employeeById.set(
    id,
    employee
   );

   CONSULTANT_ACTIVE_EMPLOYEE_IDS.add(
    id
   );
  }

  if(name){
   employeeByName.set(
    name,
    employee
   );

   CONSULTANT_ACTIVE_EMPLOYEE_NAMES.add(
    name
   );
  }
 });

 /*
  * NOT VISITED / VISITED-NOT-BOOKED FALLBACK
  * If no Therapy Plan / Patient / Lead consultant exists, use the employee
  * who updated the appointment status on the Lead.
  */
 const statusFallbackLeadIds=uniqueNonEmpty(
  source
   .filter(record=>{
    if(!record)return false;

    const needsStatusFallback=
     record.cat===CATS[2]||
     record.cat===CATS[1];

    if(!needsStatusFallback)return false;

    const hasTherapyConsultant=
     consultantClean(
      record.consultantTherapyPlanConsultantId
     );

    const hasExistingConsultant=
     consultantClean(record.clientConsultantId)||
     (
      consultantClean(record.clientConsultant)!=="—"
       ?consultantClean(record.clientConsultant)
       :""
     )||
     (
      consultantClean(record.cons)!=="—"
       ?consultantClean(record.cons)
       :""
     );

    return !hasTherapyConsultant&&!hasExistingConsultant;
   })
   .map(record=>record&&record.name)
 );

 const statusUpdaterByLead=new Map();

 if(statusFallbackLeadIds.length){
  try{
   const updaterRows=await apiGetListChunks(
    "Lead",
    [
     "name",
     "custom_status_updated_by_employee",
     "custom_status_updated_by_name",
     "custom_status_updated_by_user"
    ],
    "name",
    statusFallbackLeadIds,
    {order_by:"modified desc"}
   );

   updaterRows.forEach(row=>{
    if(row&&row.name){
     statusUpdaterByLead.set(
      consultantClean(row.name),
      row
     );
    }
   });
  }catch(error){
   console.warn(
    "Consultant status-updater fallback lookup failed",
    error
   );
  }
 }

 source.forEach(record=>{
  if(!record)return;

  const needsStatusFallback=
   record.cat===CATS[2]||
   record.cat===CATS[1];

  if(!needsStatusFallback)return;

  const updater=
   statusUpdaterByLead.get(
    consultantClean(record.name)
   )||null;

  const updaterEmployeeId=
   consultantClean(
    record.statusUpdatedByEmployee||
    updater&&updater.custom_status_updated_by_employee
   );

  const updaterName=
   consultantClean(
    record.statusUpdatedByName||
    updater&&updater.custom_status_updated_by_name
   );

  const hasTherapyConsultant=
   consultantClean(
    record.consultantTherapyPlanConsultantId
   );

  const hasExistingConsultant=
   consultantClean(record.clientConsultantId)||
   (
    consultantClean(record.clientConsultant)!=="—"
     ?consultantClean(record.clientConsultant)
     :""
   )||
   (
    consultantClean(record.cons)!=="—"
     ?consultantClean(record.cons)
     :""
   );

  if(
   !hasTherapyConsultant&&
   !hasExistingConsultant&&
   (updaterEmployeeId||updaterName)
  ){
   record.clientConsultantId=
    updaterEmployeeId;

   record.clientConsultant=
    updaterName||
    updaterEmployeeId;

   record.statusUpdatedByEmployee=
    updaterEmployeeId;

   record.statusUpdatedByName=
    updaterName;

   record.consultantReportEligible=true;
  }
 });

 /*
  * Resolve consultant IDs from all available sources.
  * Not Visited rows commonly use Patient.custom_employee_id and may have no
  * Therapy Plan. If the value is already an Employee ID, employeeById handles
  * it directly; otherwise try Healthcare Practitioner.
  */
 const unresolvedPractitionerIds=uniqueNonEmpty(
  source
   .map(record=>record&&record.clientConsultantId)
   .filter(value=>
    consultantClean(value)&&
    !employeeById.has(consultantClean(value))
   )
 );

 const practitionerById=new Map();

 if(unresolvedPractitionerIds.length){
  try{
   const practitionerRows=await apiGetListChunks(
    "Healthcare Practitioner",
    ["name","practitioner_name","employee"],
    "name",
    unresolvedPractitionerIds,
    {order_by:"practitioner_name asc"}
   );
   practitionerRows.forEach(row=>{
    if(row&&row.name){
     practitionerById.set(consultantClean(row.name),row);
    }
   });
  }catch(error){
   console.warn("Consultant Practitioner fallback failed",error);
  }
 }

 source.forEach(record=>{
  const rawConsultantId=
   consultantClean(record.clientConsultantId);

  const therapyEmployeeName=
   consultantClean(
    record.consultantTherapyPlanEmployeeName
   );

  const byName=
   therapyEmployeeName
    ?employeeByName.get(
      consultantKeyPart(therapyEmployeeName)
     )||null
    :null;

  const practitioner=
   rawConsultantId
    ?practitionerById.get(rawConsultantId)||null
    :null;

  const practitionerEmployeeId=
   consultantClean(
    practitioner&&practitioner.employee
   );

  /*
   * Patient.custom_employee_id can be either:
   * - a Healthcare Practitioner ID, or
   * - a direct Employee ID on older records.
   */
  const directEmployee=
   rawConsultantId
    ?employeeById.get(rawConsultantId)||null
    :null;

  const practitionerEmployee=
   practitionerEmployeeId
    ?employeeById.get(practitionerEmployeeId)||null
    :null;

  const rawEmployeeMaster=
   rawConsultantId
    ?allEmployeeById.get(rawConsultantId)||null
    :null;

  const practitionerEmployeeMaster=
   practitionerEmployeeId
    ?allEmployeeById.get(practitionerEmployeeId)||null
    :null;

  const inactiveConsultantEmployee=
   (
    rawEmployeeMaster&&
    !consultantEmployeeIsActive(rawEmployeeMaster)
   )||
   (
    practitionerEmployeeMaster&&
    !consultantEmployeeIsActive(
     practitionerEmployeeMaster
    )
   );

  const updaterEmployeeId=
   (
    record.cat===CATS[2]||
    record.cat===CATS[1]
   )
    ?consultantClean(record.statusUpdatedByEmployee)
    :"";

  const updaterEmployee=
   updaterEmployeeId
    ?employeeById.get(updaterEmployeeId)||null
    :null;

  const employee=
   byName||
   practitionerEmployee||
   directEmployee||
   updaterEmployee||
   null;

  const existingDisplay=
   (
    consultantClean(record.clientConsultant)!=="—"
     ?consultantClean(record.clientConsultant)
     :""
   );

  const leadConsultant=
   (
    consultantClean(record.cons)!=="—"
     ?consultantClean(record.cons)
     :""
   );

  const statusUpdaterName=
   (
    record.cat===CATS[2]||
    record.cat===CATS[1]
   )
    ?consultantClean(record.statusUpdatedByName)
    :"";

  const resolvedConsultantName=
   inactiveConsultantEmployee
    ?""
    :(
      consultantClean(
       employee&&employee.employee_name
      )||
      therapyEmployeeName||
      consultantClean(
       practitioner&&practitioner.practitioner_name
      )||
      existingDisplay||
      leadConsultant||
      statusUpdaterName||
      rawConsultantId||
      updaterEmployeeId||
      ""
     );

  record.consultantEmployeeId=
   consultantClean(employee&&employee.name)||
   practitionerEmployeeId||
   rawConsultantId||
   updaterEmployeeId||
   "";

  record.consultantEmployeeName=
   resolvedConsultantName||
   "Consultant Unmapped";

  /*
   * Keep popup Consultant / Counsellor synchronized with the resolved name.
   * This fixes Not Visited rows displaying a dash even when Patient has an
   * assigned consultant.
   */
  record.clientConsultant=
   resolvedConsultantName||
   existingDisplay||
   leadConsultant||
   "—";

  record.consultantDesignation=
   consultantClean(employee&&employee.designation)||
   "—";

  record.consultantEmployeeBranch=
   consultantClean(record.consultantReportBranch)||
   consultantClean(employee&&employee.branch)||
   consultantClean(record.br)||
   "";

  record.consultantReportBranch=
   consultantClean(record.consultantReportBranch)||
   consultantClean(record.br)||
   "";

  record.consultantReportEligible=
   Boolean(resolvedConsultantName);

  /*
   * MANAGER RESOLUTION
   * ------------------
   * 1) Employee.reports_to
   * 2) Same-branch Senior Manager / Center Manager /
   *    Branch Manager / Manager
   *
   * This prevents valid branch teams from appearing under
   * "Manager Unmapped" just because reports_to was not maintained.
   */
  const reportsToId=
   consultantClean(
    employee&&employee.reports_to
   );

  const reportsToManager=
   reportsToId
    ?employeeById.get(reportsToId)||null
    :null;

  /*
   * employeeById already contains Active employees only.
   * Therefore an inactive reports_to automatically falls through
   * to the active same-branch manager.
   */

  const managerBranchKey=
   normalizedBranchKey(
    consultantClean(
     record.consultantReportBranch
    )||
    consultantClean(
     employee&&employee.branch
    )||
    consultantClean(record.br)
   );

  const branchManager=
   managerBranchKey
    ?branchManagerByBranch.get(
      managerBranchKey
     )||null
    :null;

  const manager=
   reportsToManager||
   branchManager||
   null;

  record.consultantManagerId=
   consultantClean(
    manager&&manager.name
   )||
   reportsToId||
   "";

  record.consultantManagerName=
   consultantClean(
    manager&&manager.employee_name
   )||
   "Manager Unmapped";

  record.consultantManagerDesignation=
   consultantClean(
    manager&&manager.designation
   )||
   "—";

  record.consultantManagerSource=
   reportsToManager
    ?"Reports To"
    :(
      branchManager
       ?"Branch Manager Fallback"
       :"Unmapped"
     );
 });

 /*
  * BRANCH MANAGER CONSOLIDATION
  * ----------------------------
  * A branch must not split into:
  *   Himayathnagar / Meenakshi...
  *   Himayathnagar / Manager Unmapped
  *
  * If at least one row in the branch has an Active resolved manager,
  * use that manager for every unresolved row in the same branch.
  */
 const learnedManagerByBranch=
  new Map();

 source.forEach(record=>{
  if(!record)return;

  const managerId=
   consultantClean(
    record.consultantManagerId
   );

  const manager=
   managerId
    ?employeeById.get(managerId)||null
    :null;

  if(
   !manager||
   !consultantEmployeeIsActive(manager)
  ){
   return;
  }

  const branchKey=
   normalizedBranchKey(
    consultantRecordBranch(record)
   );

  if(
   !branchKey||
   branchKey===LIFE_UNASSIGNED_BRANCH
  ){
   return;
  }

  const existing=
   learnedManagerByBranch.get(
    branchKey
   );

  /*
   * Prefer the stronger manager designation if multiple valid managers
   * are encountered for the same branch.
   */
  if(
   !existing||
   consultantManagerRank(manager)<
   consultantManagerRank(existing)
  ){
   learnedManagerByBranch.set(
    branchKey,
    manager
   );
  }
 });

 /*
  * Also merge configured active branch managers.
  */
 branchManagerByBranch.forEach(
  (manager,branchKey)=>{
   if(
    !manager||
    !consultantEmployeeIsActive(manager)
   ){
    return;
   }

   const existing=
    learnedManagerByBranch.get(
     branchKey
    );

   if(
    !existing||
    consultantManagerRank(manager)<
    consultantManagerRank(existing)
   ){
    learnedManagerByBranch.set(
     branchKey,
     manager
    );
   }
  }
 );

 source.forEach(record=>{
  if(!record)return;

  const currentManagerId=
   consultantClean(
    record.consultantManagerId
   );

  const currentManager=
   currentManagerId
    ?employeeById.get(
      currentManagerId
     )||null
    :null;

  /*
   * Keep a valid Active manager as-is.
   */
  if(
   currentManager&&
   consultantEmployeeIsActive(
    currentManager
   )
  ){
   return;
  }

  const branchKey=
   normalizedBranchKey(
    consultantRecordBranch(record)
   );

  const learned=
   learnedManagerByBranch.get(
    branchKey
   )||null;

  if(!learned){
   record.consultantManagerId="";
   record.consultantManagerName=
    "Manager Unmapped";
   record.consultantManagerDesignation=
    "—";
   record.consultantManagerSource=
    "Unmapped";
   return;
  }

  record.consultantManagerId=
   consultantClean(
    learned.name
   );

  record.consultantManagerName=
   consultantClean(
    learned.employee_name
   )||
   "Manager Unmapped";

  record.consultantManagerDesignation=
   consultantClean(
    learned.designation
   )||
   "—";

  record.consultantManagerSource=
   "Branch Consolidated Manager";
 });

 /*
  * Export only the final resolved branch keys to renderer scope.
  * This avoids referencing local learnedManagerByBranch later.
  */
 CONSULTANT_RESOLVED_MANAGER_BRANCHES.clear();

 learnedManagerByBranch.forEach(
  (manager,branchKey)=>{
   if(
    manager&&
    consultantEmployeeIsActive(manager)&&
    branchKey
   ){
    CONSULTANT_RESOLVED_MANAGER_BRANCHES.add(
     branchKey
    );
   }
  }
 );

 const ended=(window.performance&&performance.now)
  ?performance.now()
  :Date.now();

 console.log("Consultant ULTRA FAST enrichment",{
  appointments:source.length,
  exact_plan_ids:exactPlanIds.length,
  fallback_patients:fallbackPatientIds.length,
  missing_patient_rows:missingPatientRows.length,
  employee_directory:employeeRows.length,
  practitioner_fallbacks:unresolvedPractitionerIds.length,
  milliseconds:Math.round(ended-started)
 });

 return source;
}

async function loadConsultantReportData(manual,explicitFrom,explicitTo){
 const requestedFrom=String(explicitFrom!=null?explicitFrom:CONSULTANT_FILTER.from||"");
 const requestedTo=String(explicitTo!=null?explicitTo:CONSULTANT_FILTER.to||"");
 const requestedKey=[requestedFrom,requestedTo].join("|");

 if(CONSULTANT_RANGE_CACHE.has(requestedKey)){
  CONSULTANT_RECORDS=(CONSULTANT_RANGE_CACHE.get(requestedKey)||[]).map(row=>Object.assign({},row));
  CONSULTANT_LOADED_KEY=requestedKey;
  CONSULTANT_DISPLAY_KEY=requestedKey;
  CONSULTANT_QUICK_RANGE=detectConsultantQuickRange();
  if(byId("tb4")&&byId("tb4").classList.contains("on"))renderConsultantReport();
  return CONSULTANT_RECORDS;
 }

 if(CONSULTANT_LOADED_KEY===requestedKey&&CONSULTANT_RECORDS.length){
  if(byId("tb4")&&byId("tb4").classList.contains("on"))renderConsultantReport();
  return CONSULTANT_RECORDS;
 }

 if(CONSULTANT_RANGE_PROMISES.has(requestedKey)){
  const existing=CONSULTANT_RANGE_PROMISES.get(requestedKey);
  if(consultantRangeKey()===requestedKey&&CONSULTANT_DISPLAY_KEY!==requestedKey){
   if(consultantSeedFromMainRecords(requestedFrom,requestedTo)){
    if(byId("tb4")&&byId("tb4").classList.contains("on"))renderConsultantReport();
   }
  }
  return existing;
 }

 const host=byId("tabv4");

 /* Never replace the visible Consultant report with a blocking spinner. */
 if(consultantRangeKey()===requestedKey&&CONSULTANT_DISPLAY_KEY!==requestedKey){
  if(consultantSeedFromMainRecords(requestedFrom,requestedTo)){
   if(byId("tb4")&&byId("tb4").classList.contains("on"))renderConsultantReport();
  }
 }

 const promise=(async()=>{
  const totalStarted=(window.performance&&performance.now)?performance.now():Date.now();
  try{
   if(!BRANCHES.length)await fetchBranches();

   let records=[];
   const canReuseMainRecords=
    Array.isArray(RECORDS)&&
    RECORDS.length>0&&
    String(F&&F.from||"")===requestedFrom&&
    String(F&&F.to||"")===requestedTo;

   if(canReuseMainRecords){
    records=RECORDS.map(row=>Object.assign({},row));
   }else{
    const raw=await fetchLeads(requestedFrom,requestedTo);
    const uniqueRaw=[...new Map(
     (raw||[])
      .filter(row=>row&&row.name)
      .map(row=>[row.name,row])
    ).values()];
    records=uniqueRaw.map(leadRowToRecord);

    /*
     * FAST FIRST PAINT:
     * Do not wait for Therapy Plan / Employee enrichment before showing
     * the selected date result. The exact consultant mapping refreshes
     * silently immediately afterwards.
     */
    if(
     consultantRangeKey()===requestedKey&&
     byId("tb4")&&
     byId("tb4").classList.contains("on")
    ){
     CONSULTANT_RECORDS=records.map(row=>Object.assign({},row));
     CONSULTANT_DISPLAY_KEY=requestedKey;
     renderConsultantReport();
    }
   }

   records=await enrichConsultantReportRecords(records);

   /*
    * WALKING REPORT FINANCIALS
    * -------------------------
    * Ensure package / paid / balance values exist before cards/table
    * totals are calculated.
    *
    * Priority:
    * 1) secure Lead API financial fields already mapped by leadRowToRecord
    * 2) exact booked-package Sales Invoice mapping
    * 3) exact CC Invoice Report row by Sales Invoice
    */
   records=
    await enrichBookedPackageAmounts(
     records
    );

   consultantApplyExactCcInvoiceFinancials(
    records
   );

   const totalEnded=(window.performance&&performance.now)?performance.now():Date.now();
   console.log("Consultant range ready",{
    range:requestedKey,
    reused_main_records:canReuseMainRecords,
    appointments:records.length,
    total_ms:Math.round(totalEnded-totalStarted)
   });

   CONSULTANT_RANGE_CACHE.set(
    requestedKey,
    records.map(row=>Object.assign({},row))
   );

   if(consultantRangeKey()===requestedKey){
    CONSULTANT_RECORDS=records;
    CONSULTANT_LOADED_KEY=requestedKey;
    CONSULTANT_DISPLAY_KEY=requestedKey;
    CONSULTANT_QUICK_RANGE=detectConsultantQuickRange();
    if(byId("tb4")&&byId("tb4").classList.contains("on")){
     renderConsultantReport();
    }
    if(manual){
     toast(
      "Consultant report loaded — "+
      records.filter(r=>r.consultantReportEligible).length+
      " mapped appointments"
     );
    }
   }

   return records;
  }catch(error){
   console.error("Consultant report load failed:",error);
   if(host&&consultantRangeKey()===requestedKey&&byId("tb4")&&byId("tb4").classList.contains("on")&&CONSULTANT_DISPLAY_KEY!==requestedKey){
    toast("Consultant refresh failed. Existing report kept on screen.");
   }
   throw error;
  }finally{
   CONSULTANT_RANGE_PROMISES.delete(requestedKey);
   CONSULTANT_LOADING=CONSULTANT_RANGE_PROMISES.size>0;
  }
 })();

 CONSULTANT_RANGE_PROMISES.set(requestedKey,promise);
 CONSULTANT_LOADING=true;
 return promise;
}

function prefetchConsultantRange(from,to,delay){
 const requestedFrom=String(from||"");
 const requestedTo=String(to||"");
 const key=[requestedFrom,requestedTo].join("|");
 if(!requestedFrom||!requestedTo)return;
 if(CONSULTANT_RANGE_CACHE.has(key)||CONSULTANT_RANGE_PROMISES.has(key))return;

 setTimeout(()=>{
  if(CONSULTANT_RANGE_CACHE.has(key)||CONSULTANT_RANGE_PROMISES.has(key))return;
  loadConsultantReportData(false,requestedFrom,requestedTo)
   .catch(error=>console.warn("Consultant background prefetch failed",key,error));
 },Math.max(0,Number(delay||0)));
}

async function openConsultantReportTab(){
 const key=consultantRangeKey();

 if(CONSULTANT_RANGE_CACHE.has(key)){
  CONSULTANT_RECORDS=(CONSULTANT_RANGE_CACHE.get(key)||[]).map(row=>Object.assign({},row));
  CONSULTANT_LOADED_KEY=key;
  CONSULTANT_DISPLAY_KEY=key;
  renderConsultantReport();
  return;
 }

 if(CONSULTANT_DISPLAY_KEY!==key){
  consultantSeedFromMainRecords(CONSULTANT_FILTER.from,CONSULTANT_FILTER.to);
 }

 if(CONSULTANT_DISPLAY_KEY===key){
  renderConsultantReport();
 }

 loadConsultantReportData(false).catch(error=>
  console.warn("Consultant silent refresh failed",error)
 );

 /*
  * Warm the most-used Consultant filters after the current report
  * is already usable. Staggered calls avoid blocking first paint.
  */
 [
  ["yesterday",350],
  ["this_week",850],
  ["this_month",1450]
 ].forEach(item=>{
  const range=getConsultantQuickRange(item[0]);
  if(
   range&&
   !(range.from===CONSULTANT_FILTER.from&&
     range.to===CONSULTANT_FILTER.to)
  ){
   prefetchConsultantRange(
    range.from,
    range.to,
    item[1]
   );
  }
 });
}

function consultantBaseRows(){
 const securityAgent=isLifeCcAgentLogin()
  ?(loggedCcAgentScope()||currentPortalUser())
  :"";
 const query=consultantKeyPart(CONSULTANT_REPORT_QUERY);

 return CONSULTANT_RECORDS.filter(record=>{
  if(!record)return false;

  if(
   securityAgent&&
   !sameAgentOwner(record.agent,securityAgent)
  )return false;

  const reportBranch=consultantRecordBranch(record);

  const enforcedBranch=
   LIFE_WALKING_BRANCH_SCOPE||
   CONSULTANT_FILTER.branch||
   "";

  if(
   enforcedBranch&&
   normalizedBranchKey(reportBranch)!==
   normalizedBranchKey(enforcedBranch)
  )return false;

  if(query){
   const haystack=[
    record.consultantEmployeeName,
    record.consultantDesignation,
    record.consultantManagerName,
    record.consultantManagerDesignation,
    reportBranch,
    record.client
   ].map(consultantKeyPart).join(" ");

   if(!haystack.includes(query))return false;
  }

  return true;
 });
}

