/* =====================================================================
   CONSULTANT POPUP — LIVE SALES INVOICE + PAYMENT ENTRY FINANCIALS
   ---------------------------------------------------------------------
   The Consultant popup must show the actual amount collected against the
   displayed Sales Invoice. The normal report summary is date-attributed,
   so it can legitimately return 0 even when the invoice has payments
   outside that summary bucket. For popup detail, resolve the invoice live:

   1) Sales Invoice.paid_amount = direct / POS amount on the invoice.
   2) Submitted Payment Entry Reference.allocated_amount = later receipts.
   3) Sales Invoice.outstanding_amount = live balance.

   Values are cached by invoice so reopening the popup is instant.
   ===================================================================== */
const CONSULTANT_LIVE_INVOICE_CACHE=new Map();

function consultantChunkValues(values,size){
 const source=[...new Set(
  (Array.isArray(values)?values:[])
   .map(value=>consultantClean(value))
   .filter(Boolean)
 )];
 const out=[];
 const chunkSize=Math.max(1,Number(size||100));
 for(let i=0;i<source.length;i+=chunkSize){
  out.push(source.slice(i,i+chunkSize));
 }
 return out;
}

async function consultantFetchLiveInvoiceFinancials(invoiceIds){
 const ids=[...new Set(
  (Array.isArray(invoiceIds)?invoiceIds:[])
   .map(value=>consultantClean(value))
   .filter(Boolean)
 )];

 const missing=ids.filter(id=>!CONSULTANT_LIVE_INVOICE_CACHE.has(id));
 if(!missing.length){
  return CONSULTANT_LIVE_INVOICE_CACHE;
 }

 const invoiceRows=[];
 const referenceRows=[];

 const chunks=consultantChunkValues(missing,80);

 const invoiceResults=await Promise.all(
  chunks.map(chunk=>
   apiGetList(
    "Sales Invoice",
    [
     "name",
     "docstatus",
     "posting_date",
     "grand_total",
     "rounded_total",
     "net_total",
     "paid_amount",
     "outstanding_amount"
    ],
    [
     ["name","in",chunk],
     ["docstatus","=",1]
    ],
    {limit_page_length:0}
   ).catch(error=>{
    console.warn(
     "Consultant popup: Sales Invoice live lookup failed",
     error
    );
    return [];
   })
  )
 );

 invoiceResults.forEach(rows=>{
  if(Array.isArray(rows))invoiceRows.push(...rows);
 });

 const referenceResults=await Promise.all(
  chunks.map(chunk=>
   apiGetList(
    "Payment Entry Reference",
    [
     "parent",
     "reference_doctype",
     "reference_name",
     "allocated_amount"
    ],
    [
     ["reference_doctype","=","Sales Invoice"],
     ["reference_name","in",chunk]
    ],
    {limit_page_length:0}
   ).catch(error=>{
    console.warn(
     "Consultant popup: Payment Entry Reference lookup failed",
     error
    );
    return [];
   })
  )
 );

 referenceResults.forEach(rows=>{
  if(Array.isArray(rows))referenceRows.push(...rows);
 });

 const paymentEntryIds=[...new Set(
  referenceRows
   .map(row=>consultantClean(row&&row.parent))
   .filter(Boolean)
 )];

 const paymentEntryByName=new Map();

 if(paymentEntryIds.length){
  const peChunks=consultantChunkValues(paymentEntryIds,80);
  const peResults=await Promise.all(
   peChunks.map(chunk=>
    apiGetList(
     "Payment Entry",
     [
      "name",
      "docstatus",
      "payment_type",
      "posting_date",
      "paid_amount",
      "received_amount"
     ],
     [
      ["name","in",chunk],
      ["docstatus","=",1]
     ],
     {limit_page_length:0}
    ).catch(error=>{
     console.warn(
      "Consultant popup: Payment Entry lookup failed",
      error
     );
     return [];
    })
   )
  );

  peResults.forEach(rows=>{
   (Array.isArray(rows)?rows:[]).forEach(row=>{
    if(row&&row.name){
     paymentEntryByName.set(
      consultantClean(row.name),
      row
     );
    }
   });
  });
 }

 const invoiceByName=new Map();
 invoiceRows.forEach(row=>{
  if(row&&row.name){
   invoiceByName.set(
    consultantClean(row.name),
    row
   );
  }
 });

 const allocatedByInvoice=new Map();

 referenceRows.forEach(ref=>{
  const invoice=consultantClean(ref&&ref.reference_name);
  const parent=consultantClean(ref&&ref.parent);
  if(!invoice||!parent)return;

  const pe=paymentEntryByName.get(parent);
  if(!pe||Number(pe.docstatus)!==1)return;

  /*
   * Customer invoice collection must be a Receive entry.
   * Ignore Pay/Internal Transfer rows so refunds/transfers are not
   * incorrectly shown as client collections.
   */
  if(
   consultantClean(pe.payment_type)&&
   consultantClean(pe.payment_type)!=="Receive"
  ){
   return;
  }

  const allocated=Math.max(
   Number(ref&&ref.allocated_amount||0),
   0
  );

  allocatedByInvoice.set(
   invoice,
   Number(allocatedByInvoice.get(invoice)||0)+allocated
  );
 });

 missing.forEach(invoiceId=>{
  const invoice=invoiceByName.get(invoiceId)||null;

  const directPaid=Math.max(
   Number(invoice&&invoice.paid_amount||0),
   0
  );

  const allocatedPaid=Math.max(
   Number(allocatedByInvoice.get(invoiceId)||0),
   0
  );

  const grandTotal=Math.max(
   Number(
    invoice&&(
     invoice.rounded_total||
     invoice.grand_total
    )||0
   ),
   0
  );

  const withoutGst=Math.max(
   Number(invoice&&invoice.net_total||0),
   0
  );

  const balance=Math.max(
   Number(invoice&&invoice.outstanding_amount||0),
   0
  );

  CONSULTANT_LIVE_INVOICE_CACHE.set(
   invoiceId,
   {
    invoice:invoiceId,
    directPaid,
    allocatedPaid,
    paid:directPaid+allocatedPaid,
    withGst:grandTotal,
    withoutGst,
    balance,
    postingDate:consultantClean(
     invoice&&invoice.posting_date
    )
   }
  );
 });

 return CONSULTANT_LIVE_INVOICE_CACHE;
}

async function consultantApplyLiveInvoiceFinancials(records){
 const rows=Array.isArray(records)?records:[];

 const invoiceIds=[...new Set(
  rows.map(record=>
   consultantClean(
    record&&(
     record.salesInvoiceName||
     record.financial_sales_invoice||
     record.sales_invoice
    )
   )
  ).filter(Boolean)
 )];

 if(!invoiceIds.length)return rows;

 await consultantFetchLiveInvoiceFinancials(invoiceIds);

 rows.forEach(record=>{
  if(!record)return;

  const invoice=consultantClean(
   record.salesInvoiceName||
   record.financial_sales_invoice||
   record.sales_invoice
  );

  if(!invoice)return;

  const financial=CONSULTANT_LIVE_INVOICE_CACHE.get(invoice);
  if(!financial)return;

  /*
   * Live popup values intentionally override date-summary values.
   * The summary report can still keep its selected-period attribution.
   */
  record.clientPaidAmount=
   Number(financial.paid||0);

  record.clientBalanceAmount=
   Number(financial.balance||0);

  if(Number(financial.withGst||0)>0){
   record.clientPackageAmountWithGst=
    Number(financial.withGst||0);
  }

  if(Number(financial.withoutGst||0)>0){
   record.clientPackageAmountWithoutGst=
    Number(financial.withoutGst||0);
   record.clientPackageAmount=
    Number(financial.withoutGst||0);
  }

  record.consultantLiveFinancialLoaded=true;
  record.consultantLiveDirectPaid=
   Number(financial.directPaid||0);
  record.consultantLiveAllocatedPaid=
   Number(financial.allocatedPaid||0);
 });

 return rows;
}

/*
 * POPUP FINANCIAL SOURCE OF TRUTH
 * -------------------------------
 * Use the exact CC Invoice Report row by Sales Invoice.
 * This gives the same Paid Amount and Balance shown by CC Invoice Report.
 */
function consultantApplyExactCcInvoiceFinancials(records){
 const rows=Array.isArray(records)?records:[];
 const exactRows=consultantExactCcRows();

 if(!rows.length||!exactRows.length)return rows;

 const byInvoice=new Map();

 exactRows.forEach(row=>{
  const invoice=consultantClean(
   row&&(row.invoice||row.sales_invoice||row.name)
  );

  if(!invoice)return;

  if(!byInvoice.has(invoice)){
   byInvoice.set(invoice,[]);
  }
  byInvoice.get(invoice).push(row);
 });

 rows.forEach(record=>{
  if(!record)return;

  const invoice=consultantClean(
   record.salesInvoiceName||
   record.financial_sales_invoice||
   record.sales_invoice
  );

  if(!invoice)return;

  const matched=byInvoice.get(invoice)||[];
  if(!matched.length)return;

  const exact=ccInvoiceExactTotals(matched);

  record.clientPackageAmountWithGst=
   Number(exact.withGst||0);

  record.clientPackageAmountWithoutGst=
   Number(exact.withoutGst||0);

  record.clientPackageAmount=
   Number(exact.withoutGst||0);

  record.clientPaidAmount=
   Number(exact.paid||0);

  record.clientBalanceAmount=
   Number(exact.balance||0);

  record.consultantExactFinancialLoaded=true;
  record.consultantPopupFinancialLoaded=true;
 });

 return rows;
}

function consultantFinancialsForRows(groupRows){
 const rows=Array.isArray(groupRows)?groupRows:[];

 /*
  * Popup/detail rows can carry live invoice + Payment Entry values.
  * When present, never overwrite them with the selected-period summary.
  */
 if(
  rows.length&&
  rows.every(record=>
   record&&(
    record.consultantExactFinancialLoaded||
    record.consultantLiveFinancialLoaded||
    record.consultantPopupFinancialLoaded
   )
  )
 ){
  const totals={
   withGst:0,
   withoutGst:0,
   paid:0,
   oldPackagePaid:0,
   balance:0
  };
  const seenInvoices=new Set();

  rows.forEach(record=>{
   const invoice=consultantClean(
    record.salesInvoiceName||
    record.financial_sales_invoice||
    record.sales_invoice
   );

   if(invoice){
    if(seenInvoices.has(invoice))return;
    seenInvoices.add(invoice);
   }

   totals.withGst+=Math.max(
    Number(record.clientPackageAmountWithGst||0),
    0
   );
   totals.withoutGst+=Math.max(
    Number(
     record.clientPackageAmountWithoutGst||
     record.clientPackageAmount||
     0
    ),
    0
   );
   totals.paid+=Math.max(
    Number(record.clientPaidAmount||0),
    0
   );
   totals.balance+=Math.max(
    Number(record.clientBalanceAmount||0),
    0
   );
  });

  return totals;
 }

 const invoiceIds=new Set();
 const therapyPlans=new Set();

 rows.forEach(record=>{
  [record&&record.salesInvoiceName,record&&record.financial_sales_invoice,record&&record.sales_invoice].forEach(value=>{
   const clean=consultantClean(value);
   if(clean)invoiceIds.add(clean);
  });
  [record&&record.consultantTherapyPlanName,record&&record.therapyPlanName,record&&record.therapy_plan,record&&record.financial_therapy_plan].forEach(value=>{
   const clean=consultantClean(value);
   if(clean)therapyPlans.add(clean);
  });
 });

 /*
  * NEW PACKAGE rows:
  * Match by the current appointment Sales Invoice / Therapy Plan.
  *
  * OLD PACKAGE collections:
  * The payment belongs to an older invoice, so it will not match today's
  * appointment invoice/plan. Match those rows by the consultant / CC Agent
  * identity as well.
  */
 const consultantIdentityKeys=new Set();

 rows.forEach(record=>{
  [
   record&&record.consultantEmployeeName,
   record&&record.clientConsultant,
   record&&record.cons,
   record&&record.consultantEmployeeId
  ].forEach(value=>{
   const clean=consultantClean(value);

   if(
    clean&&
    clean!=="—"&&
    clean!=="Consultant Unmapped"
   ){
    consultantIdentityKeys.add(
     consultantKeyPart(clean)
    );
   }
  });
 });

 const exactCcRows=consultantExactCcRows();

 const matchedCurrent=exactCcRows.filter(row=>{
  const invoice=consultantClean(
   row&&(
    row.invoice||
    row.sales_invoice||
    row.name
   )
  );

  const therapyPlan=consultantClean(
   row&&(
    row.therapy_plan||
    row.therapy_plan_reference_id||
    row.custom_therapy_plan
   )
  );

  return (
   (invoice&&invoiceIds.has(invoice))||
   (therapyPlan&&therapyPlans.has(therapyPlan))
  );
 });

 const matchedKeys=new Set(
  matchedCurrent.map(row=>{
   const invoice=consultantClean(
    row&&(
     row.invoice||
     row.sales_invoice||
     row.name
    )
   );

   const paymentRef=consultantClean(
    row&&(
     row.payment_entry||
     row.payment_reference||
     row.reference_name
    )
   );

   return invoice+"|"+paymentRef;
  })
 );

 const matchedOldByConsultant=exactCcRows.filter(row=>{
  const invoiceDate=String(
   row&&row.invoice_date||""
  ).slice(0,10);

  const paid=Math.max(
   Number(row&&row.paid||0),
   0
  );

  if(
   !invoiceDate||
   invoiceDate>=F.from||
   !paid
  ){
   return false;
  }

  const candidateValues=[
   row&&row.cc_agent,
   row&&row.agent_name,
   row&&row.consultant,
   row&&row.consultant_name,
   row&&row.consultant_employee,
   row&&row.employee_name,
   row&&row.lead_owner
     ?(
       AGENT_NAME[row.lead_owner]||
       agName(row.lead_owner)
      )
     :""
  ];

  const hasConsultantMatch=
   candidateValues.some(value=>{
    const clean=consultantClean(value);

    return (
     clean&&
     consultantIdentityKeys.has(
      consultantKeyPart(clean)
     )
    );
   });

  if(!hasConsultantMatch){
   return false;
  }

  const invoice=consultantClean(
   row&&(
    row.invoice||
    row.sales_invoice||
    row.name
   )
  );

  const paymentRef=consultantClean(
   row&&(
    row.payment_entry||
    row.payment_reference||
    row.reference_name
   )
  );

  const rowKey=invoice+"|"+paymentRef;

  return !matchedKeys.has(rowKey);
 });

 const matched=
  matchedCurrent.concat(
   matchedOldByConsultant
  );

 const totals=
  ccInvoicePackageSplitTotals(
   matched
  );

 /*
  * RECORD-LEVEL FINANCIAL FALLBACK
  * -------------------------------
  * Even when some CC Invoice Report rows matched, individual secure
  * records may carry the only valid package/payment values.
  *
  * Build de-duplicated record totals and take the larger valid amount
  * per metric. This prevents a valid invoice from rendering as ₹0 just
  * because the summary join missed its invoice/therapy-plan key.
  */
 const recordTotals={
  withGst:0,
  withoutGst:0,
  paid:0,
  balance:0
 };

 const seenRecordInvoices=new Set();

 rows.forEach(record=>{
  if(!record)return;

  const invoice=
   consultantClean(
    record.salesInvoiceName||
    record.financial_sales_invoice||
    record.sales_invoice
   );

  const uniqueKey=
   invoice||
   consultantClean(
    record.therapyPlanName||
    record.consultantTherapyPlanName||
    record.financial_therapy_plan
   )||
   consultantClean(record.name);

  if(
   uniqueKey&&
   seenRecordInvoices.has(uniqueKey)
  ){
   return;
  }

  if(uniqueKey){
   seenRecordInvoices.add(uniqueKey);
  }

  recordTotals.withGst+=Math.max(
   Number(
    record.clientPackageAmountWithGst||
    record.financial_with_gst||
    0
   ),
   0
  );

  recordTotals.withoutGst+=Math.max(
   Number(
    record.clientPackageAmountWithoutGst||
    record.clientPackageAmount||
    record.financial_without_gst||
    0
   ),
   0
  );

  recordTotals.paid+=Math.max(
   Number(
    record.clientPaidAmount||
    record.financial_paid_amount||
    record.paid_amount||
    0
   ),
   0
  );

  recordTotals.balance+=Math.max(
   Number(
    record.clientBalanceAmount||
    record.financial_balance_amount||
    record.outstanding_amount||
    0
   ),
   0
  );
 });

 totals.withGst=Math.max(
  Number(totals.withGst||0),
  recordTotals.withGst
 );

 totals.withoutGst=Math.max(
  Number(totals.withoutGst||0),
  recordTotals.withoutGst
 );

 totals.paid=Math.max(
  Number(totals.paid||0),
  recordTotals.paid
 );

 totals.balance=Math.max(
  Number(totals.balance||0),
  recordTotals.balance
 );

 if(matchedOldByConsultant.length){
  console.log(
   "Consultant old-package collections matched:",
   {
    consultants:
     Array.from(consultantIdentityKeys),
    rows:
     matchedOldByConsultant.map(row=>({
      invoice:
       row&&(
        row.invoice||
        row.sales_invoice||
        row.name
       ),
      invoice_date:
       row&&row.invoice_date,
      paid:
       Number(row&&row.paid||0),
      cc_agent:
       row&&(
        row.cc_agent||
        row.agent_name||
        row.consultant||
        row.consultant_name||
        row.employee_name||
        ""
       )
     }))
   }
  );
 }

 totals.withGst=Number(totals.withGst||0);
 totals.withoutGst=Number(totals.withoutGst||0);
 totals.paid=Number(totals.paid||0);
 totals.oldPackagePaid=Number(totals.oldPackagePaid||0);
 totals.balance=Number(totals.balance||0);
 return totals;
}

function consultantBookPercent(rows){
 const booked=(rows||[]).filter(r=>r.cat===CATS[0]).length;
 const notBooked=(rows||[]).filter(r=>r.cat===CATS[1]).length;
 const visited=(rows||[]).filter(r=>r.cat===CATS[7]).length;
 const denominator=booked+notBooked+visited;
 return denominator?Math.round(booked/denominator*100):0;
}


function consultantSeedFromSharedSecureCache(from,to){
 const key=String(from||"")+"|"+String(to||"");
 const cached=LIFE_CC_FUNNEL_ROWS_MAP.get(key);

 if(!Array.isArray(cached)||!cached.length){
  return false;
 }

 const unique=[
  ...new Map(
   cached
    .filter(row=>row&&row.name)
    .map(row=>[row.name,row])
  ).values()
 ];

 if(!unique.length)return false;

 CONSULTANT_RECORDS=
  unique.map(leadRowToRecord);

 CONSULTANT_DISPLAY_KEY=key;

 /*
  * Do not mark as fully enriched yet.
  * Exact Therapy Plan / Employee resolution refreshes silently.
  */
 return true;
}

function consultantShowRangeImmediately(from,to){
 const key=String(from||"")+"|"+String(to||"");

 if(CONSULTANT_RANGE_CACHE.has(key)){
  CONSULTANT_RECORDS=
   (CONSULTANT_RANGE_CACHE.get(key)||[])
    .map(row=>Object.assign({},row));

  CONSULTANT_LOADED_KEY=key;
  CONSULTANT_DISPLAY_KEY=key;
  renderConsultantReport();
  return true;
 }

 if(consultantSeedFromMainRecords(from,to)){
  renderConsultantReport();
  return true;
 }

 if(consultantSeedFromSharedSecureCache(from,to)){
  renderConsultantReport();
  return true;
 }

 /*
  * Apply the selected dates immediately even if that range has never
  * been fetched. Do not keep showing the previous date range as though
  * the click did nothing.
  */
 CONSULTANT_RECORDS=[];
 CONSULTANT_DISPLAY_KEY=key;
 renderConsultantReport();
 return false;
}

async function setConsultantQuickRange(mode){
 const range=getConsultantQuickRange(mode);
 if(!range)return;

 CONSULTANT_QUICK_RANGE=mode;
 CONSULTANT_FILTER.from=range.from;
 CONSULTANT_FILTER.to=range.to;

 const key=consultantRangeKey();

 /*
  * FIRST PAINT IS SYNCHRONOUS.
  * Cache/main/shared-secure rows are used immediately.
  */
 const alreadyExact=
  consultantShowRangeImmediately(
   range.from,
   range.to
  );

 if(
  alreadyExact&&
  CONSULTANT_RANGE_CACHE.has(key)
 ){
  return;
 }

 /*
  * Exact consultant mapping refreshes silently.
  * The button click never waits for this promise.
  */
 loadConsultantReportData(
  false,
  range.from,
  range.to
 ).catch(error=>
  console.warn(
   "Consultant range refresh failed",
   key,
   error
  )
 );
}

