async function openConsultantGroupStatusDetails(encodedKey,statusKey){
 const key=decodeURIComponent(String(encodedKey||""));
 const cat=
  statusKey==="notVisited"
   ?CATS[2]
   :statusKey==="notBooked"
    ?CATS[1]
    :"";

 if(!cat)return;

 const allGroupRows=consultantReportRows()
  .filter(record=>consultantGroupKey(record)===key);

 const rows=allGroupRows
  .filter(record=>record.cat===cat)
  .sort((left,right)=>
   String(right.aptDts||"")
    .localeCompare(String(left.aptDts||""))
  );

 const popup=ensureLifeCcPopupShell();
 if(!popup||!popup.body||!popup.title)return;

 const label=consultantGroupLabel(key,allGroupRows);
 const branch=consultantBranchLabel(
  allGroupRows[0]&&consultantRecordBranch(allGroupRows[0])
 );

 const statusLabel=
  statusKey==="notVisited"
   ?"Not Visited"
   :"Visited - Not Booked";

 popup.title.textContent=(
  CONSULTANT_REPORT_VIEW==="manager"
   ?"Manager — "
   :"Consultant Employee — "
 )+label+" · "+branch+" · "+statusLabel+
 " · "+rows.length+" client"+(rows.length===1?"":"s");

 consultantApplyExactCcInvoiceFinancials(rows);
 let popupRows=rows;
 try{popupRows=await enrichPopupRecordsWithClientData(rows);}catch(error){console.warn("Consultant status popup related-doctype enrichment failed:",error);}
 popup.body.innerHTML=leadTable(popupRows);
 popup.overlay.classList.add("on");
}

