async function openConsultantGroupDetails(encodedKey){
 const key=decodeURIComponent(String(encodedKey||""));
 const rows=consultantReportRows()
  .filter(record=>consultantGroupKey(record)===key)
  .sort((left,right)=>
   String(right.aptDts||"")
    .localeCompare(String(left.aptDts||""))
  );

 const popup=ensureLifeCcPopupShell();
 if(!popup||!popup.body||!popup.title)return;

 const label=consultantGroupLabel(key,rows);
 const branch=consultantBranchLabel(
  rows[0]&&consultantRecordBranch(rows[0])
 );

 popup.title.textContent=(
  CONSULTANT_REPORT_VIEW==="manager"
   ?"Manager — "
   :"Consultant Employee — "
 )+label+" · "+branch+" · "+rows.length+" appointments";

 /*
  * Use exact CC Invoice Report values first.
  * Do not overwrite correct PE Paid / Outstanding values with a second
  * Payment Entry lookup that can return zero because of permissions/mapping.
  */
 consultantApplyExactCcInvoiceFinancials(rows);

 let popupRows=rows;
 try{popupRows=await enrichPopupRecordsWithClientData(rows);}catch(error){console.warn("Consultant popup related-doctype enrichment failed:",error);}
 popup.body.innerHTML=leadTable(popupRows);
 popup.overlay.classList.add("on");

 /*
  * Only invoices missing from the CC Invoice Report summary use the old
  * live lookup as a fallback.
  */
 const fallbackRows=rows.filter(
  record=>!record.consultantExactFinancialLoaded
 );

 if(fallbackRows.length){
  try{
   await consultantApplyLiveInvoiceFinancials(fallbackRows);

   if(
    popup.overlay.classList.contains("on")
   ){
    popup.body.innerHTML=leadTable(popupRows);
   }
  }catch(error){
   console.warn(
    "Consultant popup fallback live financial refresh failed",
    error
   );
  }
 }
}

function renderConsultantReport(){
 if(
  LIFE_WALKING_BRANCH_USER&&
  LIFE_WALKING_BRANCH_SCOPE
 ){
  CONSULTANT_FILTER.branch=
   LIFE_WALKING_BRANCH_SCOPE;
 }

 const host=byId("tabv4");
 if(!host)return;

 const currentKey=consultantRangeKey();
 const currentRangeLoading=
  CONSULTANT_RANGE_PROMISES.has(currentKey)&&
  !CONSULTANT_RANGE_CACHE.has(currentKey)&&
  CONSULTANT_LOADED_KEY!==currentKey;

 /* NO BLOCKING LOADER: keep usable rows visible while exact data syncs. */
 if(CONSULTANT_DISPLAY_KEY!==currentKey&&!CONSULTANT_RECORDS.length){
  consultantSeedFromMainRecords(CONSULTANT_FILTER.from,CONSULTANT_FILTER.to);
 }

 CONSULTANT_QUICK_RANGE=detectConsultantQuickRange();

 const baseRows=consultantBaseRows();
 const rows=baseRows;
 const unassignedCount=rows.filter(
  r=>!r.consultantReportEligible
 ).length;
 const groups=new Map();

 rows.forEach(record=>{
  const key=consultantGroupKey(record);
  if(!groups.has(key))groups.set(key,[]);
  groups.get(key).push(record);
 });

 const groupRows=Array.from(groups.entries())
  .map(([key,records])=>{
   const booked=records.filter(r=>r.cat===CATS[0]).length;
   const notBooked=records.filter(r=>r.cat===CATS[1]).length;
   const notVisited=records.filter(r=>r.cat===CATS[2]).length;
   const visited=records.filter(r=>r.cat===CATS[7]).length;
   const financial=consultantFinancialsForRows(records);
   const managerNameKey=
    CONSULTANT_REPORT_VIEW==="manager"
     ?consultantKeyPart(
       records[0]&&
       records[0].consultantManagerName
      )
     :"";

   const memberNames=[
    ...new Set(
     records
      .map(record=>{
       const employeeId=
        consultantClean(
         record&&
         record.consultantEmployeeId
        );

       const name=
        consultantClean(
         record&&
         record.consultantEmployeeName
        );

       /*
        * Active-only filtering uses the shared index built during enrichment.
        * Do NOT reference employeeById here: that Map is local to
        * enrichConsultantReportRecords() and caused:
        *   ReferenceError: employeeById is not defined
        */
       if(
        employeeId&&
        !CONSULTANT_ACTIVE_EMPLOYEE_IDS.has(
         employeeId
        )
       ){
        return "";
       }

       /*
        * For name-only records, reject the name only when it is known in the
        * Employee directory but not present in the active-name index.
        */
       const nameKey=
        consultantKeyPart(name);

       if(
        !employeeId&&
        nameKey&&
        CONSULTANT_EMPLOYEE_DIRECTORY_ROWS&&
        CONSULTANT_EMPLOYEE_DIRECTORY_ROWS.some(row=>
         consultantKeyPart(
          row&&row.employee_name
         )===nameKey
        )&&
        !CONSULTANT_ACTIVE_EMPLOYEE_NAMES.has(
         nameKey
        )
       ){
        return "";
       }

       if(
        !name||
        name==="Consultant Unmapped"||
        consultantKeyPart(name)===
         managerNameKey
       ){
        return "";
       }

       return name;
      })
      .filter(Boolean)
    )
   ];

   return {
    key,
    records,
    label:consultantGroupLabel(key,records),
    branch:consultantBranchLabel(
     consultantRecordBranch(records[0])
    ),
    appointments:records.length,
    visited,
    totalVisitCount:booked+notBooked,
    booked,
    notBooked,
    notVisited,
    financial,
    bookPercent:consultantBookPercent(records),
