function lifeCcCurrentVisibleTab(){
 const tabs=[
  {
   id:"tabv1",
   title:"CC — Branch Visits Report"
  },
  {
   id:"tabv2",
   title:"Agent Report"
  },
  {
   id:"tabv3",
   title:"Lead & Digital Marketing Report"
  },
  {
   id:"tabv4",
   title:"Walking Report"
  }
 ];

 return (
  tabs.find(item=>{
   const node=byId(item.id);

   if(!node){
    return false;
   }

   const style=
    window.getComputedStyle(node);

   return (
    style.display!=="none"&&
    style.visibility!=="hidden"
   );
  })||
  tabs[0]
 );
}

function lifeCcPrintCurrentReport(){
 const current=
  lifeCcCurrentVisibleTab();

 const source=
  byId(current.id);

 if(!source){
  alert("Report is not ready to print.");
  return;
 }

 /*
  * DIRECT PRINT MODE
  * -----------------
  * Do not open a separate preview/report tab first.
  * Build the printable report inside a hidden iframe and open the
  * browser Print / Save PDF dialog directly from the current page.
  */
 const printFrame=document.createElement("iframe");
 printFrame.setAttribute("aria-hidden","true");
 printFrame.tabIndex=-1;
 printFrame.style.position="fixed";
 printFrame.style.right="0";
 printFrame.style.bottom="0";
 printFrame.style.width="1px";
 printFrame.style.height="1px";
 printFrame.style.border="0";
 printFrame.style.opacity="0";
 printFrame.style.pointerEvents="none";
 document.body.appendChild(printFrame);

 const printWindow=printFrame.contentWindow;

 if(!printWindow){
  printFrame.remove();
  alert("Unable to prepare the report for printing.");
  return;
 }

 const clone=
  source.cloneNode(true);

 const isMarketing=
  current.id==="tabv3";

 const isAgent=
  current.id==="tabv2";

 const isBranch=
  current.id==="tabv1";

 const isConsultant=
  current.id==="tabv4";

 /*
  * Remove all interactive controls.
  */
 clone
  .querySelectorAll(
   [
    ".fbar",
    ".cc-filter-action-row",
    ".life-mkt-filter-wrap",
    ".life-cc-print-btn",
    ".life-mkt-actions",
    ".drill-actions",
    "button",
    "input",
    "select",
    "textarea",
    ".life-mkt-multi-menu",
    "#lifeMktAgencyPortal"
   ].join(",")
  )
  .forEach(node=>node.remove());

 /*
  * PRINT-SPECIFIC CLEANUP — MARKETING REPORT
  * Avoid duplicate headings and long screen-only explanations.
  */
 if(isMarketing){
  clone
   .querySelectorAll(
    [
     ".life-mkt-hero",
     ".life-mkt-note",
     ".life-mkt-category-rules",
     ".life-mkt-live",
     ".life-mkt-sub"
    ].join(",")
   )
   .forEach(node=>node.remove());

  clone
   .querySelectorAll(
    ".life-mkt-section-body"
   )
   .forEach(node=>{
    node.style.display="block";
   });

  clone
   .querySelectorAll(
    ".life-mkt-section-head .arrow"
   )
   .forEach(node=>node.remove());

  /*
   * Remove screen-only click hints from KPI cards.
   */
  clone
   .querySelectorAll(
    ".life-mkt-kpi small"
   )
   .forEach(node=>node.remove());

  /*
   * Remove inline min-width values that force tables off the page.
   */
  clone
   .querySelectorAll(
    ".life-mkt-table"
   )
   .forEach(table=>{
    table.style.minWidth="0";
    table.style.width="100%";
   });
 }

 /*
  * Agent report: remove controls but keep the report header/data.
  */
 if(isAgent){
  clone
   .querySelectorAll(
    ".agent-report-toolbar-actions"
   )
   .forEach(node=>node.remove());
 }

 /*
  * Branch report: expand horizontally scrollable result areas.
  */
 if(isBranch){
  clone
   .querySelectorAll(
    "#sumWrap,.table-wrap"
   )
   .forEach(node=>{
    node.style.overflow="visible";
    node.style.maxHeight="none";
   });
 }

 /*
  * Consultant report print cleanup.
  * Remove screen-only controls/notes so KPI cards + summary table can fit
  * together on the first landscape page.
  */
 if(isConsultant){
  clone
   .querySelectorAll(
    [
     ".consultant-report-toolbar",
     ".consultant-quick-range-bar",
     ".consultant-report-note"
    ].join(",")
   )
   .forEach(node=>node.remove());

  clone
   .querySelectorAll(
    ".consultant-report-table-wrap"
   )
   .forEach(node=>{
    node.style.overflow="visible";
    node.style.maxHeight="none";
    node.style.width="100%";
   });

  clone
   .querySelectorAll(
    ".consultant-report-table"
   )
   .forEach(table=>{
    table.style.minWidth="0";
    table.style.width="100%";
   });
 }

 /*
  * Build selected-filter summary from the live Marketing screen.
  */
 let reportSubtitle="";
 let filterSummary="";

 if(isMarketing){
  const liveHero=
   source.querySelector(
    ".life-mkt-hero-copy p"
   );

  reportSubtitle=
   liveHero
    ?String(liveHero.textContent||"").trim()
    :"Lead Source-wise · Ad Set-wise · Enquired For-wise · Branch conversion";

  const selectedAgency=
   source.querySelector(
    ".life-mkt-agency-current"
   );

  const category=
   source.querySelector(
    "#lifeMktCategory"
   );

  const branch=
   source.querySelector(
    "#lifeMktBranch"
   );

  const from=
   source.querySelector(
    "#lifeMktFrom"
   );

  const to=
   source.querySelector(
    "#lifeMktTo"
   );

  const parts=[];

  if(from&&to){
   parts.push(
    "Period: "+
    String(from.value||"")+" → "+
    String(to.value||"")
   );
  }

  if(selectedAgency){
   parts.push(
    "Agency: "+
    String(
     selectedAgency.textContent||
     "All Agencies"
    ).trim()
   );
  }

  if(category){
   parts.push(
    "Category: "+
    String(
     category.options[
      category.selectedIndex
     ]?.text||
     "All Categories"
    )
   );
  }

  if(branch){
   parts.push(
    "Branch: "+
    String(
     branch.options[
      branch.selectedIndex
     ]?.text||
     "All Branches"
    )
   );
  }

  filterSummary=
   parts.join("  ·  ");
 }

