 const escapeHtml=value=>
  String(value||"")
   .replace(
    /[<>&"]/g,
    char=>({
     "<":"&lt;",
     ">":"&gt;",
     "&":"&amp;",
     '"':"&quot;"
    }[char])
   );

 const safeTitle=
  escapeHtml(
