    if(!fields.length){
      try{
        const response=await call(
          "frappe.desk.form.load.getdoctype",
          {doctype:"Lead"}
        );

        const docs=
          response&&Array.isArray(response.docs)
            ?response.docs
            :Array.isArray(response)
              ?response
              :[];

        const docType=docs.find(doc=>
          doc&&
          doc.doctype==="DocType"&&
          doc.name==="Lead"
