  function dynamicMarketingValue(
    lead,
    includePatterns,
    excludePatterns
  ){
    if(!lead)return "";

    const excludes=Array.isArray(excludePatterns)
      ?excludePatterns
      :[];

    const candidates=[];

    /*
     * First scan Lead metadata so custom field labels such as
     * "Marketing Source", "Ad Set Name", or "Assigned Branch"
     * are supported even when their fieldnames are different.
     */
    (M.leadMetaFields||[]).forEach(field=>{
      const searchable=(
        field.fieldname+" "+field.label
      ).toLowerCase();

      const included=includePatterns.some(pattern=>
        pattern.test(searchable)
      );

      const excluded=excludes.some(pattern=>
        pattern.test(searchable)
      );

      if(!included||excluded)return;

      const value=usableMarketingValue(
        lead[field.fieldname]
      );

      if(!value)return;

      candidates.push({
        value:value,
        fieldname:field.fieldname,
        score:
          field.permlevel===0?10:0
      });
    });

    /*
     * Full Lead documents can contain fields absent from cached metadata.
     * Scan their property names as a second fallback.
     */
    Object.keys(lead).forEach(fieldname=>{
      const searchable=fieldname.toLowerCase();

      const included=includePatterns.some(pattern=>
        pattern.test(searchable)
      );

      const excluded=excludes.some(pattern=>
        pattern.test(searchable)
      );

      if(!included||excluded)return;

      const value=usableMarketingValue(
        lead[fieldname]
      );

      if(!value)return;

      candidates.push({
        value:value,
        fieldname:fieldname,
        score:5
      });
    });

    if(!candidates.length)return "";

    candidates.sort((left,right)=>
      right.score-left.score||
      left.fieldname.localeCompare(right.fieldname)
    );

    return candidates[0].value;
  }

