  function mergeSecureMarketingRows(leads,secureRows){
    const secureMap=new Map(
      (Array.isArray(secureRows)?secureRows:[])
        .filter(row=>row&&row.name)
        .map(row=>[row.name,row])
    );

    return (Array.isArray(leads)?leads:[]).map(lead=>{
      const secure=secureMap.get(lead.name);

      if(!secure)return lead;

      const merged={...lead};

      [
        "source",
        "ad_set",
        "enquired_for",
        "lead_assign_to_branch",
        "branch",
        "campaign_name",
        "custom_campaignaudience",
        "category",
        "custom_treatment_interests",
        "custom_specific_interests",
        "custom_client_category",
        "custom_media"
      ].forEach(fieldname=>{
        const value=secure[fieldname];

        if(
          value!==undefined &&
          value!==null &&
          String(value).trim()!==""
        ){
          merged[fieldname]=value;
        }
      });

      return merged;
    });
  }

