  async function enrichMarketingLeadFields(leads){
    const rows=Array.isArray(leads)?leads:[];
    const missing=rows.filter(marketingLeadNeedsEnrichment);

    if(!missing.length)return rows;

    const fullDocs=new Map();
    const concurrency=6;
    let cursor=0;

    async function worker(){
      while(cursor<missing.length){
        const index=cursor++;
        const row=missing[index];
        const full=await fetchFullLeadForMarketing(row.name);

        if(full){
          fullDocs.set(row.name,full);
        }
      }
    }

    await Promise.all(
      Array.from(
        {length:Math.min(concurrency,missing.length)},
        ()=>worker()
      )
    );

    const enriched=rows.map(row=>{
      const full=fullDocs.get(row.name);

      if(!full)return row;

      /*
       * Full document is placed first and the existing row second only
       * for values already present in the list result. Blank list values
       * must not overwrite real full-document values.
       */
      const merged={...full};

      Object.keys(row).forEach(key=>{
        const value=row[key];

        if(
          value!==undefined &&
          value!==null &&
          String(value).trim()!==""
        ){
          merged[key]=value;
        }
      });

      return merged;
    });

    const check={
      requested:missing.length,
      enriched:fullDocs.size,
      source:enriched.filter(
        row=>String(row.source||"").trim()
      ).length,
      adSet:enriched.filter(
        row=>String(row.ad_set||"").trim()
      ).length,
      enquiredFor:enriched.filter(
        row=>String(row.enquired_for||"").trim()
      ).length,
      branch:enriched.filter(
        row=>String(
          row.branch||
          row.lead_assign_to_branch||
          ""
        ).trim()
      ).length
    };

    console.log(
      "LIFE Marketing Lead enrichment:",
      check
    );

    if(
      check.enriched>0 &&
      check.source===0 &&
      check.adSet===0 &&
      check.enquiredFor===0
    ){
      console.warn(
        "Lead source, ad_set and enquired_for are blank or not readable "+
        "for this ERPNext login."
      );
    }

    return enriched;
  }

  async function campaignMeta(){
    let fields=[];
    try{
      if(frappe.get_meta){
        const m=frappe.get_meta("Campaign");
        if(m && Array.isArray(m.fields) && m.fields.length) fields=m.fields;
      }
    }catch(e){}
    if(!fields.length){
      try{
        const r=await call("frappe.desk.form.load.getdoctype",{doctype:"Campaign"});
        const docs=(r&&r.docs)||r||[];
        const dt=Array.isArray(docs)?docs.find(d=>d && d.doctype==="DocType" && d.name==="Campaign"):null;
        if(dt && Array.isArray(dt.fields)) fields=dt.fields;
      }catch(e){}
    }
    const exists=fn=>fields.some(f=>f.fieldname===fn);
    const pick=(regex,types)=>{
      const found=fields.find(f=>regex.test((f.fieldname||"")+" "+(f.label||"")) && (!types || types.includes(f.fieldtype)));
      return found?found.fieldname:"";
    };
    return {
      available:new Set(fields.map(f=>f.fieldname)),
      displayField:exists("campaign_name")?"campaign_name":pick(/title|campaign name/i),
      startField:exists("start_date")?"start_date":pick(/start.*date/i),
      endField:exists("end_date")?"end_date":pick(/end.*date/i),
      statusField:exists("status")?"status":pick(/status/i),
      agencyField:pick(/agency|vendor|marketing partner/i),
      spendField:pick(/ad.*spend|spent.*amount|spend.*amount|media.*cost|campaign.*cost/i,["Currency","Float","Int"]),
      categoryField:pick(/category|treatment/i),
      platformField:pick(/platform|media channel|ad channel/i)
    };
  }

