    if(!names.length) return;
    const f=new Set(["name"]);
    ["campaign_name","start_date","end_date","status",M.campaignMeta.displayField,M.campaignMeta.startField,M.campaignMeta.endField,M.campaignMeta.statusField,M.campaignMeta.agencyField,M.campaignMeta.spendField,M.campaignMeta.categoryField,M.campaignMeta.platformField].filter(Boolean).forEach(x=>f.add(x));
    const fields=Array.from(f).filter(x=>x==="name" || !M.campaignMeta.available.size || M.campaignMeta.available.has(x));
    for(let i=0;i<names.length;i+=100){
      try{
        const rows=await getAll("Campaign",fields,[["Campaign","name","in",names.slice(i,i+100)]],"modified desc",500);
        rows.forEach(r=>M.campaignMap.set(r.name,r));
