      ],
      "posting_date asc",
      500
    );

    const patientNames=Array.from(new Set(invoices.map(x=>x.patient).filter(Boolean)));
    const customerNames=Array.from(new Set(invoices.map(x=>x.customer).filter(Boolean)));
    const patientFields=["name","patient_name","customer","custom_lead","branch_name"];

    const [patientsByName,patientsByCustomer]=await Promise.all([
      fetchByValues("Patient",patientFields,"name",patientNames,"modified desc"),
