      fetchByValues("Lead",LEAD_FIELDS,"customer",customerNames,"modified desc")
    ]);

    M.invoices=uniqueByName(invoices);
    M.patientLinks=patients;
    return uniqueByName(leadsByName.concat(leadsByCustomer));
