  function invoiceAllocation(leads){
    const leadMap=new Map((leads||[]).map(l=>[l.name,l]));
    const patientToLead=new Map();
    const customerToLead=new Map();
    const patientBranch=new Map();
    const customerBranch=new Map();

    M.patientLinks.forEach(patient=>{
      if(patient.name&&patient.branch_name){
        patientBranch.set(patient.name,patient.branch_name);
      }

      if(patient.customer&&patient.branch_name){
        customerBranch.set(patient.customer,patient.branch_name);
      }

      if(
        patient.name&&
        patient.custom_lead&&
        leadMap.has(patient.custom_lead)
      ){
        patientToLead.set(patient.name,patient.custom_lead);

        if(patient.customer){
          customerToLead.set(patient.customer,patient.custom_lead);
        }
      }
    });

    /*
     * Customer fallback is used only when exactly one loaded Lead owns
     * that customer, avoiding invoice allocation to an unrelated Lead.
     */
    const customerCandidates=new Map();

    (leads||[]).forEach(lead=>{
      if(!lead.customer)return;

      if(!customerCandidates.has(lead.customer)){
        customerCandidates.set(lead.customer,new Set());
      }

      customerCandidates.get(lead.customer).add(lead.name);
    });

    customerCandidates.forEach((names,customer)=>{
      if(names.size===1&&!customerToLead.has(customer)){
        customerToLead.set(customer,Array.from(names)[0]);
      }
    });

    const alloc=new Map();

    M.invoices.forEach(invoice=>{
      const leadName=
        (invoice.patient&&patientToLead.get(invoice.patient))||
        (invoice.customer&&customerToLead.get(invoice.customer));

      if(!leadName)return;

      const value=number(invoice.grand_total||invoice.net_total);
      const branch=firstMarketingValue([
        invoice.branch,
        invoice.patient&&patientBranch.get(invoice.patient),
        invoice.customer&&customerBranch.get(invoice.customer)
      ],"");

      const current=alloc.get(leadName)||{
        revenue:0,
        rebooking:0,
        branch:""
      };

      if(value>0){
        current.revenue+=value;
      }

      if(!current.branch&&branch){
        current.branch=branch;
      }

      alloc.set(leadName,current);
    });

    return alloc;
  }

  function campaignSpendForLead(lead){
    /* Lead has no Ad Set spend field in the supplied DocType.
       Do not assign whole Campaign spend to individual Ad Sets. */
    return 0;
