  function decorate(leads){
    const allocation=invoiceAllocation(leads);

    const resolvedBranch=lead=>{
      const context=allocation.get(lead.name)||{};
      return branchName(lead,context);
    };

    const agencyLabels=buildLabelMap(
      leads,
      lead=>agencyName(lead),
      "Unspecified"
    );

    const categoryLabels=buildLabelMap(
      leads,
      lead=>categoryName(lead),
      "Unspecified"
    );

    const branchLabels=buildLabelMap(
      leads,
      lead=>resolvedBranch(lead),
      "Unassigned"
    );

    return leads.map(l=>{
      const money=allocation.get(l.name)||{
        revenue:0,
        rebooking:0,
        branch:""
      };

      const agency=canonicalLabel(
        agencyName(l),
        "Unspecified",
        agencyLabels
      );

      const category=canonicalLabel(
        categoryName(l),
        "Unspecified",
        categoryLabels
      );

      const campaignItem=adSetIdentity(campaignKey(l));
      const campaign=campaignItem.label;

      const branch=canonicalLabel(
        branchName(l,money),
        "Unassigned",
        branchLabels
      );
      return Object.assign({},l,{
        _agency:agency,_category:category,_branch:branch,_campaign:campaign,
        _campaignKey:campaignItem.key,_source:agency,
        _junk:isJunk(l),_quality:isQuality(l),_connected:isConnected(l),_appointment:hasAppointment(l),
        _visited:isVisited(l),_booked:isVisitedBooked(l),_unbooked:isVisitedUnbooked(l),
        _revenue:money.revenue,_rebooking:0,_spend:campaignSpendForLead(l)
      });
    });
  }


  function paymentFinancialRows(decoratedLeads){
    const leadMap=new Map(
      (decoratedLeads||[])
        .filter(row=>row&&row.name)
        .map(row=>[
          String(row.name),
          row
        ])
    );

    const useExact=
      Array.isArray(
        M.ccInvoicePaymentRows
      )&&
      M.ccInvoicePaymentRows.length>0;

    const sourceRows=
      useExact
        ?M.ccInvoicePaymentRows.filter(event=>
          Boolean(
           event&&
           String(
            event.therapy_plan||""
           ).trim()
          )&&
          String(
           event&&event.therapy_plan_media||""
          ).trim().toLowerCase()==="call center"&&
          Number(
           event&&event.therapy_plan_already_taken||0
          )!==1
         )
        :[];

    return sourceRows
      .filter(event=>{
        const eventDate=cleanDate(
          useExact
            ?event&&event.payment_date
            :event&&event.event_date
        );

        const paidAmount=number(
          useExact
            ?event&&event.paid
            :event&&event.paid_amount
        );

        return (
          eventDate>=M.from&&
          eventDate<=M.to&&
          paidAmount>0
        );
      })
      .map((event,index)=>{
        const leadId=String(
          event&&event.lead||""
        ).trim();

        const existing=
          leadId&&leadMap.has(leadId)
            ?leadMap.get(leadId)
            :null;

        const source=String(
          event&&event.source||""
        ).trim()||"Unspecified";

        const category=String(
          event&&event.enquired_for||""
        ).trim()||"Unspecified";

        const campaignItem=
          adSetIdentity(
            event&&event.ad_set||""
          );

        const branch=String(
          event&&(
            event.lead_branch||
            event.branch
          )||
          ""
        ).trim()||"Unassigned";

        const paidDate=cleanDate(
          useExact
            ?event&&event.payment_date
            :event&&event.event_date
        );

        const invoiceDate=cleanDate(
          event&&event.invoice_date
        );

        const paidAmount=number(
          useExact
            ?event&&event.paid
            :event&&event.paid_amount
        );

        const laterCollection=
          useExact
            ?Boolean(
              event&&event.is_later_collection
             )
            :(
              String(
                event&&event.event_type||""
              ).trim().toLowerCase()==="payment"
            );

        const base=existing
          ?Object.assign({},existing)
          :{
            name:
              leadId||
              (
                "PAYMENT-"+
                String(
                  (
                    event&&(
                      event.payment_entry||
                      event.event_key||
                      event.invoice
                    )
                  )||
                  index
                )
              ),
            lead_name:
              event&&event.lead_name||
              event&&event.customer||
              "Client",
            mobile_no:"",
            lead_owner:
              event&&event.lead_owner||"",
            source:source,
            ad_set:
              event&&event.ad_set||"",
            enquired_for:category,
            lead_assign_to_branch:branch,
            branch:branch,
            campaign_name:
              event&&event.campaign_name||""
          };

        return Object.assign(
          {},
          base,
          {
            name:
              "PAYEVENT::"+
              String(
                (
                  event&&(
                    event.payment_entry||
                    event.event_key
                  )
                )||
                (
                  (
                    event&&(
                      event.invoice||
                      event.sales_invoice
                    )
                  )+
                  "|"+
                  paidDate+
                  "|"+
                  index
                )
              ),
            _leadName:
              leadId||
              String(
                existing&&existing.name||""
              ),
            _financialEvent:true,
            _eventKey:String(
              (
                event&&(
                  event.payment_entry||
                  event.event_key
                )
              )||
              (
                (
                  event&&(
                    event.invoice||
                    event.sales_invoice
                  )
                )+
                "|"+
                paidDate+
                "|"+
                index
              )
            ),
            _paidDate:paidDate,
            _invoiceDate:invoiceDate,
            _paymentType:
              laterCollection
                ?"Payment"
                :"Invoice",
            _salesInvoice:String(
              event&&(
                event.invoice||
                event.sales_invoice
              )||
              ""
            ),
            _paymentEntries:
              event&&event.payment_entry
                ?[String(event.payment_entry)]
                :(
                  Array.isArray(
                    event&&event.payment_entries
                  )
                    ?event.payment_entries.slice()
                    :[]
                ),
            _therapyPlan:String(
              event&&event.therapy_plan||""
            ),
            _agency:
              existing
                ?existing._agency
                :source,
            _category:
              existing
                ?existing._category
                :category,
            _campaign:
              existing
                ?existing._campaign
                :campaignItem.label,
            _campaignKey:
              existing
                ?existing._campaignKey
                :campaignItem.key,
            _source:
              existing
                ?existing._source
                :source,
            _branch:
              existing
                ?existing._branch
                :branch,
            _revenue:paidAmount,
            _outstandingAfterPayment:0,
            _currentOutstanding:number(
              event&&event.current_outstanding
            ),
            _rebooking:0,
            _spend:
              existing
                ?number(existing._spend)
                :0
          }
        );
      });
  }

  function filtersMatch(l){
    if(!l){
      return false;
    }

    if(
      Array.isArray(M.agencies)&&
      M.agencies.length&&
      !M.agencies.some(agency=>
        selectedAgencyMatchesRow(
          agency,
          l._agency
        )
      )
    ){
      return false;
    }

    if(
      M.category&&
      l._category!==M.category
    ){
      return false;
    }

    if(
      M.branch&&
      l._branch!==M.branch
    ){
      return false;
    }

    if(M.query){
      const text=[
        displayName(l),
        l.name,
        l.mobile_no,
        l._agency,
        l._campaign,
        l._source,
        l._category,
        l._branch,
        l.lead_owner
      ]
        .join(" ")
        .toLowerCase();

      if(
        !text.includes(
          M.query.toLowerCase()
        )
      ){
        return false;
      }
    }

    return true;
  }

  function filteredReceived(){ return M.received.filter(filtersMatch); }
  function filteredVisits(){ return M.visits.filter(filtersMatch); }
  function filteredFinancial(){ return M.financial.filter(filtersMatch); }

  function outstandingCollectedAmount(financialRows){
    const rows=Array.isArray(financialRows)
      ?financialRows
      :[];

    /*
     * OUTSTANDING COLLECTED AMOUNT
     *
     * Invoice event = payment made on the invoice posting date.
     * Payment event = payment made on a later date against an
     * already-outstanding Sales Invoice.
     *
     * Therefore only event_type === "Payment" is counted here.
     */
    return rows.reduce(
      (sum,row)=>{
        const eventType=String(
          row&&row._paymentType||""
        ).trim().toLowerCase();

        if(eventType!=="payment"){
          return sum;
        }

        return sum+number(
          row&&row._revenue
        );
      },
      0
    );
  }

  function aggregate(received,visits,financial){
    const a={raw:received.length,quality:0,junk:0,connected:0,appointments:0,remaining:0,visits:visits.length,booked:0,unbooked:0,revenue:0,rebooking:0,spend:0};
    received.forEach(l=>{
      if(l._quality)a.quality++;
      if(l._junk)a.junk++;
      if(l._connected)a.connected++;
      if(l._appointment)a.appointments++;
    });
    visits.forEach(l=>{
      if(l._booked)a.booked++;
      if(l._unbooked)a.unbooked++;
    });
    (financial||[]).forEach(l=>{
      /*
       * One row = one actual invoice/payment-date collection event.
       * The same client can therefore contribute again on a later date.
       */
      a.revenue+=number(l._revenue);
      a.rebooking+=number(l._rebooking);
    });
    a.remaining=Math.max(0,a.quality-a.appointments);
    const spendCampaigns=new Map();
    received.concat(visits,financial||[]).forEach(l=>{
      if(l._spend>0) spendCampaigns.set(l._campaignKey,l._spend);
    });
    a.spend=Array.from(spendCampaigns.values()).reduce((x,y)=>x+y,0);
    return a;
  }

  /*
   * Exact funnel metrics for the other tabs.
   * Uses the SAME decorated rows and SAME classification as this
   * Lead & Digital Marketing report.
   */
  window.LIFE_CC_MARKETING_FUNNEL_METRICS=
   function(from,to,opts){
    opts=opts||{};

    if(
     !M.loaded||
     String(from||"")!==String(M.from||"")||
     String(to||"")!==String(M.to||"")
    ){
     return null;
    }

    const agent=
     String(opts.agent||"").trim();

    const branch=
     String(opts.branch||"").trim();

    const matchScope=row=>{
     if(!row)return false;

     if(
      agent&&
      !sameAgentOwner(
       row.lead_owner,
       agent
      )
     ){
      return false;
     }

     if(
      branch&&
      normalizedBranchKey(
       row._branch||
       row.branch||
       row.lead_assign_to_branch||
       ""
      )!==normalizedBranchKey(branch)
     ){
      return false;
     }

     return true;
    };

    const received=
     M.received.filter(matchScope);

    const visits=
     M.visits.filter(matchScope);

    const exact=
     aggregate(
      received,
      visits,
      []
     );

    return {
     raw:exact.raw,
     quality:exact.quality,
     junk:exact.junk,
     connected:exact.connected,
     appointments:exact.appointments,
     visits:exact.visits,
     booked:exact.booked,
     unbooked:exact.unbooked
    };
   };

  globalThis.LIFE_CC_MARKETING_FUNNEL_METRICS=
   window.LIFE_CC_MARKETING_FUNNEL_METRICS;

  function groups(received,visits,financial,keyFn){
    const keys=new Set(received.map(keyFn).concat(visits.map(keyFn), (financial||[]).map(keyFn)));
    return Array.from(keys).filter(Boolean).sort((a,b)=>String(a).localeCompare(String(b))).map(key=>{
      const r=received.filter(x=>keyFn(x)===key);
      const v=visits.filter(x=>keyFn(x)===key);
      const f=(financial||[]).filter(x=>keyFn(x)===key);
      return {key,received:r,visits:v,financial:f,agg:aggregate(r,v,f)};
    });
  }

