        ){
          map.set(
            key,
            {
              value:String(value),
              label:String(value)
            }
          );
        }
      });

    return Array.from(
      map.values()
    ).sort((a,b)=>
      String(a.label||a.value)
        .localeCompare(
          String(b.label||b.value),
          "en",
          {sensitivity:"base"}
        )
    );
