        Math.max(
          12,
          rect.left
        ),
        Math.max(
          12,
          window.innerWidth-width-12
        )
      );

    let top=
      rect.bottom+6;

    const maxHeight=390;

    if(
      top+maxHeight>
      window.innerHeight-10&&
      rect.top>maxHeight
    ){
      top=
        Math.max(
          10,
          rect.top-maxHeight-6
        );
    }

    portal.style.left=
      left+"px";

    portal.style.top=
      top+"px";

    portal.style.width=
      width+"px";
  }

