  function filterAgencyOptions(value){
    M.agencySearch=
      String(value||"");

    const query=
      marketingAgencyKey(
        M.agencySearch
      );

    let visibleCount=0;

    document
      .querySelectorAll(
        "#lifeMktAgencyOptions .life-mkt-agency-option"
      )
      .forEach(option=>{
        const text=
          String(
            option.getAttribute(
              "data-agency-search"
            )||""
          );

        const matches=
          !query||
          text.includes(query);

        option.classList.toggle(
          "life-mkt-agency-hidden",
          !matches
        );

        if(matches){
          visibleCount+=1;
        }
      });

    const optionsWrap=
      document.getElementById(
        "lifeMktAgencyOptions"
      );

    if(optionsWrap){
      let empty=
        optionsWrap.querySelector(
          ".life-mkt-agency-search-empty"
        );

      if(
        query&&
        visibleCount===0
      ){
        if(!empty){
          empty=
            document.createElement(
              "div"
            );

          empty.className=
            "life-mkt-agency-search-empty";

          empty.textContent=
            "No matching Marketing Agency";

          optionsWrap.appendChild(
            empty
          );
        }
      }else if(empty){
        empty.remove();
      }
    }

    const topSearch=
      document.getElementById(
        "lifeMktAgencySearch"
      );

    const portalSearch=
      document.getElementById(
        "lifeMktAgencyPortalSearch"
      );

    if(
      topSearch&&
      document.activeElement===topSearch&&
      portalSearch
    ){
      portalSearch.value=
        M.agencySearch;
    }
  }

  function toggleAgency(value,checked){
    const clean=
      String(value||"").trim();

    if(!clean){
      return;
    }

    let selected=
      Array.isArray(M.agencies)
        ?M.agencies.slice()
        :[];

    selected=
      selected.filter(item=>
        marketingAgencyKey(item)!==
        marketingAgencyKey(clean)
      );

    if(checked){
      selected.push(clean);
    }

    M.agencies=selected;

    /*
     * Apply immediately.
     * Multiple selections use OR logic in filtersMatch().
     */
    const activeSearch=
      String(
        M.agencySearch||""
      );

    render();

    M.agencyDropdownOpen=true;
    M.agencySearch=activeSearch;

    setTimeout(()=>{
      renderAgencyPortal();

      const portalSearch=
        document.getElementById(
          "lifeMktAgencyPortalSearch"
        );

      if(portalSearch){
        portalSearch.value=
          activeSearch;

        filterAgencyOptions(
          activeSearch
        );
      }
    },0);
  }

  function removeAgency(value){
    const clean=
      String(value||"").trim();

    M.agencies=
      (M.agencies||[])
        .filter(item=>
          marketingAgencyKey(item)!==
          marketingAgencyKey(clean)
        );

    render();
  }

  function selectAllAgencies(){
    M.agencies=[];
    M.agencySearch="";

    render();

    M.agencyDropdownOpen=true;

    setTimeout(()=>{
      renderAgencyPortal();
    },0);
  }

