  async function load(force){
    if(M.loading) return;

    const key=M.from+'|'+M.to;

    if(
      !force &&
      M.loaded &&
      M.lastLoadedKey===key
    ){
      render();
      return;
    }

    M.loading=true;
    renderLoading();

    const startedAt=performance.now();

    try{
      const dateTimeFrom=
        M.from+' 00:00:00';

      const dateTimeTo=
        M.to+' 23:59:59';

      /*
       * FAST LOAD:
       * Only the three Lead date queries are loaded in the browser.
       *
       * Removed from every date change:
       * Sales Invoice -> Patient -> Lead browser lookup.
       *
       * Paid Date / Paid Amount / Outstanding already come from the
       * secure API as financial_events, so that old invoice context
       * request was duplicate work.
       */
      const [
        byPosting,
        byCreation,
        byVisit
      ]=await Promise.all([
        getAll(
          'Lead',
          LEAD_FIELDS,
          [
            [
              "Lead",
              "custom_posting_date",
              "between",
              [M.from,M.to]
            ]
          ],
          "custom_posting_date desc",
          500
        ),
        getAll(
          'Lead',
          LEAD_FIELDS,
          [
            [
              "Lead",
              "creation",
              "between",
              [dateTimeFrom,dateTimeTo]
            ]
          ],
          "creation desc",
          500
        ),
        getAll(
          'Lead',
          LEAD_FIELDS,
          [
            [
              "Lead",
              "custom_appointment_date_and_time",
              "between",
              [dateTimeFrom,dateTimeTo]
            ]
          ],
          "custom_appointment_date_and_time desc",
          500
        )
      ]);

      const merged=uniqueByName(
        byPosting.concat(
          byCreation,
          byVisit
        )
      );

      /*
       * IMPORTANT SPEED CHANGE:
       * Do not open every missing Lead document one-by-one before calling
       * the secure API. The secure API already supplies Source, Ad Set,
       * Enquired For, Branch and payment events.
       */
      const enrichedMerged=
        await enrichMarketingFromSecureApi(
          merged
        );

      /*
       * Campaign meta is retained, but it runs only after the main secure
       * data is available. Lead meta is cached by the existing function.
       */
      await Promise.all([
        loadLeadMarketingMeta(),
        loadCampaigns(enrichedMerged)
      ]);

      const decorated=decorate(enrichedMerged);

      const mappingCheck={
        total:decorated.length,
        sourceAvailable:decorated.filter(
          row=>norm(row._agency)!=="unspecified"
        ).length,
        adSetAvailable:decorated.filter(
          row=>norm(row._campaign)!=="unspecified"
        ).length,
        categoryAvailable:decorated.filter(
          row=>norm(row._category)!=="unspecified"
        ).length,
        branchAvailable:decorated.filter(
          row=>norm(row._branch)!=="unassigned"
        ).length
      };

      console.log(
        "LIFE Marketing field mapping:",
        mappingCheck
      );

      if(
        mappingCheck.total>0&&
        mappingCheck.sourceAvailable===0&&
        mappingCheck.adSetAvailable===0&&
        mappingCheck.categoryAvailable===0
      ){
        console.error(
          "The current ERPNext login returned no readable Source, "+
          "Ad Set, or Enquired For values for these Lead records. "+
          "Check the fields' Perm Level and the user's Lead field permissions."
        );
      }
      M.received=decorated.filter(l=>{
        const d=receivedDate(l);
        return d>=M.from&&d<=M.to;
      });

      M.visits=decorated.filter(l=>{
        const d=visitDate(l);
        return l._visited&&d>=M.from&&d<=M.to;
      });

      /*
       * Marketing money is now CASH COLLECTION based:
       * - invoice-day payment -> that invoice/payment date
       * - later Payment Entry -> later Payment Entry posting date
       * - same client may appear multiple times on different dates
       */
      M.financial=
        paymentFinancialRows(decorated);

      M.allLeads=
        decorated.concat(
          M.financial
        );

      const paidTotal=
        M.financial.reduce(
          (sum,row)=>
            sum+number(row._revenue),
          0
        );

      console.log(
        "Marketing date/payment load:",
        {
          from:M.from,
          to:M.to,
          leads:decorated.length,
          payment_events:M.financial.length,
          exact_cc_invoice_source:
            M.ccInvoicePaymentRows.length>0,
          paid_amount:paidTotal,
          load_ms:Math.round(
            performance.now()-startedAt
          )
        }
      );

      M.loaded=true;
      M.lastLoadedKey=key;
      render();

      setTimeout(()=>{
       if(
        typeof window.LIFE_CC_REFRESH_EXACT_FUNNELS==="function"
       ){
        window.LIFE_CC_REFRESH_EXACT_FUNNELS();
       }
      },0);
    }catch(e){ console.error('Live marketing report error',e); renderError(e); }
    finally{ M.loading=false; }
  }

  function syncInputs(){
    const from=el('lifeMktFrom'),to=el('lifeMktTo'),category=el('lifeMktCategory'),branch=el('lifeMktBranch'),query=el('lifeMktQuery');
    if(from)M.from=from.value||M.from;
    if(to)M.to=to.value||M.to;
    if(category)M.category=category.value;
    if(branch)M.branch=branch.value;
    if(query)M.query=query.value.trim();
  }

  function setPeriod(mode){
    const t=today(); M.mode=mode;
    if(mode==='Today'){M.from=t;M.to=t;}
    else if(mode==='Yesterday'){M.from=addDays(t,-1);M.to=addDays(t,-1);}
    else if(mode==='This Month'){
      const r=lifeBusinessCycle(t,0);
      M.from=r[0];
      M.to=t;
    }
    else if(mode==='Last Month'){const r=lifeBusinessCycle(t,-1);M.from=r[0];M.to=r[1];}
    else { syncInputs(); render(); return; }
    load(false);
  }

  function search(){
    syncInputs(); M.mode='Date Range';
    if(!M.from||!M.to||M.from>M.to){ renderError(new Error('Please select a valid From Date and To Date.')); return; }
    load(false);
  }
