  function detail(scope,key,metric){
    const popup=ensureLifeCcPopupShell();
    const selectedMetric=metric||'all';
    const received=filteredReceived();
    const visits=filteredVisits();
    const financial=filteredFinancial();
    let rows=[];

    if(selectedMetric==='raw') rows=received.slice();
    else if(selectedMetric==='quality') rows=received.filter(x=>x._quality);
    else if(selectedMetric==='junk') rows=received.filter(x=>x._junk);
    else if(selectedMetric==='connected') rows=received.filter(x=>x._connected);
    else if(selectedMetric==='appointments') rows=received.filter(x=>x._appointment);
    else if(selectedMetric==='visits') rows=visits.slice();
    else if(selectedMetric==='booked') rows=visits.filter(x=>x._booked);
    else if(selectedMetric==='unbooked') rows=visits.filter(x=>x._unbooked);
    else if(selectedMetric==='revenue') rows=financial.slice();
    else rows=received.concat(visits,financial);

    const map=new Map();

    rows.forEach(x=>{
      const rowKey=x._financialEvent
        ?String(x._eventKey||x.name)
        :String(x.name||"");

      map.set(rowKey,x);
    });

    rows=Array.from(map.values());

    if(scope==='agency'){
      rows=rows.filter(x=>x._agency===key);
    }

    if(scope==='campaign'){
      rows=rows.filter(x=>x._campaign===key);
    }

    if(scope==='category'){
      rows=rows.filter(x=>x._category===key);
    }

    rows.sort((a,b)=>
      String(
        b._paidDate||
        b.custom_appointment_date_and_time||
        receivedDate(b)
