    const scopeLabel=
      scope==='agency'
        ?'Lead Source'
        :scope==='campaign'
          ?'Ad Set'
          :scope==='category'
            ?'Enquired For'
            :scope;

    const metricLabels={
      all:'All matching records',
      raw:'Raw Leads',
      quality:'Quality Leads',
      junk:'Junk Leads',
      connected:'Connected',
      appointments:'Appointments',
      visits:'Visits',
      booked:'Booked Visits',
      unbooked:'Unbooked Visits',
