  function exportCategoryCsv(){
    const r=filteredReceived(),v=filteredVisits(),f=filteredFinancial();
    const categoryGroups=groups(r,v,f,x=>x._category)
      .sort((a,b)=>(b.agg.raw-a.agg.raw)||String(a.key).localeCompare(String(b.key)));

    const rows=[[
      "Enquired For","Ad Sets","Raw Leads","Quality Leads","Junk Leads","Connected",
      "Appointments","Pending Appointment","Visits","Booked","Unbooked",
      "Lead to Visit %","Visit to Booked %","Paid Amount","Average Paid / Booked"
    ]];

    categoryGroups.forEach(g=>{
      const a=g.agg;
      const allRows=g.received.concat(g.visits,g.financial||[]);
      const adSets=new Set(allRows.map(x=>x._campaign).filter(x=>x&&norm(x)!=="unspecified")).size;

      rows.push([
        g.key,adSets,a.raw,a.quality,a.junk,a.connected,a.appointments,a.remaining,
        a.visits,a.booked,a.unbooked,pct(a.visits,a.raw),pct(a.booked,a.visits),
        a.revenue,a.booked&&a.revenue?Math.round(a.revenue/a.booked):0
      ]);
    });

    const a=aggregate(r,v,f);
    const allRows=r.concat(v,f||[]);
    const totalAdSets=new Set(allRows.map(x=>x._campaign).filter(x=>x&&norm(x)!=="unspecified")).size;
    rows.push([
      "TOTAL",totalAdSets,a.raw,a.quality,a.junk,a.connected,a.appointments,a.remaining,
      a.visits,a.booked,a.unbooked,pct(a.visits,a.raw),pct(a.booked,a.visits),
      a.revenue,a.booked&&a.revenue?Math.round(a.revenue/a.booked):0
    ]);

    const csv=rows.map(row=>row.map(value=>'"'+String(value==null?'':value).replace(/"/g,'""')+'"').join(',')).join('\n');
    const blob=new Blob(["\ufeff"+csv],{type:'text/csv;charset=utf-8;'});
    const url=URL.createObjectURL(blob);
    const anchor=document.createElement('a');
    anchor.href=url;
    anchor.download='LIFE_Category_Summary_'+M.from+'_to_'+M.to+'.csv';
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
  }

  function exportCsv(){
    const r=filteredReceived(),v=filteredVisits(),f=filteredFinancial(),gs=groups(r,v,f,x=>x._campaign);
    const rows=[["Ad Set","Lead Source","Enquired For","Raw Leads","Quality Leads","Junk Leads","Connected","Appointments","Visits","Booked","Unbooked","Revenue","Ad Spend","Conversion %"]];
    gs.forEach(g=>{const a=g.agg,s=g.received[0]||g.visits[0]||(g.financial&&g.financial[0])||{};rows.push([g.key,s._agency||'',s._category||'',a.raw,a.quality,a.junk,a.connected,a.appointments,a.visits,a.booked,a.unbooked,a.revenue,a.spend,pct(a.booked,a.visits)]);});
    const csv=rows.map(row=>row.map(v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"').join(',')).join('\n');
    const blob=new Blob(["\ufeff"+csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download='LIFE_Lead_Digital_Marketing_'+M.from+'_to_'+M.to+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
  }

