function lifeCycleDateLabel(iso){
 const d=new Date(iso+"T00:00:00");
 return d.toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"});
}

function last6LifeCycles(){
 const out=[];

 for(let offset=-5;offset<=0;offset++){
  const cycle=
   getLifeBusinessCycleRange(offset);

  /*
   * Historical LIFE cycles are full 6th -> 5th.
   * Current cycle must never include future dates.
   */
  const effectiveTo=
   offset===0&&TODAY<cycle.to
    ?TODAY
    :cycle.to;

  out.push({
   from:cycle.from,
   to:effectiveTo,
   label:
    lifeCycleDateLabel(cycle.from)+
    " – "+
    lifeCycleDateLabel(effectiveTo),
   short:
    lifeCycleDateLabel(
     cycle.from
    ).replace(/\s\d{4}$/,'')
  });
 }

 return out;
}

