async function ensureAgentHistory(){
 const first=
  AGENT_LIFE_CYCLES[0];

 const last=
  AGENT_LIFE_CYCLES[
   AGENT_LIFE_CYCLES.length-1
  ];

 /*
  * Include the complete Last 180 Days option.
  * Also stop at Today so future appointments are not silently
  * mixed into normal Agent period calculations.
  */
 const last180From=
  daysAgoISO(179);

 const historyFrom=
  last180From<first.from
   ?last180From
   :first.from;

 const historyTo=
  TODAY<last.to
   ?TODAY
   :last.to;

 const historyAgent=
  String(
   AG||""
  ).trim();

 const key=
  normalizedAgentUser(
   historyAgent
  )+
  "|"+
  historyFrom+
  "|"+
  historyTo;

 if(AGENT_HISTORY_CACHE_KEY===key&&AGENT_HISTORY_CACHE.length){
  mergeAgentHistoryIntoRecords();

  if(!isLifeCcAgentLogin()){
   await refreshAgentMaster();
  }

  AGENT_HISTORY_READY=true;
  return;
 }
 if(AGENT_HISTORY_PROMISE)return AGENT_HISTORY_PROMISE;

 AGENT_HISTORY_PROMISE=(async()=>{
  const raw=
   await fetchLeads(
    historyFrom,
    historyTo,
    historyAgent
   );
  const unique=[...new Map(raw.filter(row=>row&&row.name).map(row=>[row.name,row])).values()];
  AGENT_HISTORY_CACHE=
   unique.map(
    leadRowToRecord
   );

  /*
   * IMPORTANT PERFORMANCE FIX:
   * Do NOT run enrichBookedPackageAmounts() across six months.
   *
   * Agent financial cards use secure financial_events, so this
   * per-record package lookup is unnecessary for history and was
   * one of the biggest causes of slow Agent Report loading.
   */
  AGENT_HISTORY_CACHE_KEY=key;
  mergeAgentHistoryIntoRecords();

  if(!isLifeCcAgentLogin()){
   await refreshAgentMaster();
  }

  AGENT_HISTORY_READY=true;
 })();

 try{
  await AGENT_HISTORY_PROMISE;
 }finally{
  AGENT_HISTORY_PROMISE=null;
 }
}


