     record&&
     record.name
    ){
     merged.set(
      record.name,
      record
     );
    }
   });

   AGENT_FAST_PERIOD_CACHE=
    Array.from(
     merged.values()
    );

   AGENT_FAST_PERIOD_KEYS.add(
    key
   );

   mergeAgentHistoryIntoRecords();

   if(!isLifeCcAgentLogin()){
    await refreshAgentMaster();
   }

   console.log(
    "Agent period fast load:",
    {
     from:from,
     to:to,
     rows:converted.length,
     load_ms:
      Math.round(
       performance.now()-
       startedAt
      )
    }
   );
  })();

 AGENT_FAST_PERIOD_PROMISES.set(
  key,
  promise
 );

 try{
  await promise;
 }finally{
  AGENT_FAST_PERIOD_PROMISES.delete(
   key
  );
 }
}

