  }

  const leadId=
   String(
    record.name||""
   ).trim();

  if(leadId){
   leadIds.add(leadId);
  }
 });

 return leadIds;
}

function agentFinancialEventsForRange(
 from,
 to,
 branchKey
){
 const owner=
  String(
   AG||""
  ).trim();

 if(!owner){
  return [];
 }

 /*
  * STRICT SELECTED AGENT RULE:
  *
  *   selected Agent
  *   + appointment Lead inside From/To
  *   + exact same Lead-linked financial event
  *
  * No unrelated/older Lead financial activity is allowed into
  * this Agent report period.
  */
 const selectedLeadIds=
  agentLeadIdsForRange(
   from,
   to,
   branchKey
  );

 if(!selectedLeadIds.size){
  return [];
 }

 let events=
  ccLeadLinkedFinancialEventsInRange(
   from,
   to
  ).filter(event=>{
   if(
    !isQualifiedCcNewPackageFinancialEvent(
     event
    )
   ){
    return false;
   }

   if(
    !sameAgentOwner(
     event&&event.lead_owner,
     owner
    )
   ){
    return false;
   }

   const eventLead=
    String(
     event&&event.lead||""
    ).trim();

   return (
    eventLead&&
    selectedLeadIds.has(
     eventLead
    )
   );
  });

 if(branchKey){
  events=
   events.filter(event=>{
    const eventBranch=
     event&&(
      event.lead_branch||
      event.branch
     );

    return (
     normalizedBranchKey(
      eventBranch
     )===branchKey
    );
   });
 }

 return events;
}

