function agentFinancialMetric(
 totals,
 key
){
 if(key==="amount_without_gst"){
  return totals.withoutGst;
 }

 if(key==="amount_with_gst"){
  return totals.withGst;
 }

 if(key==="paid_amount"){
  return totals.paid;
 }

 if(key==="balance_amount"){
  return totals.balance;
 }

 return 0;
}

const M=(rs,k)=>
 k==="raw"
  ?rs.length
  :k==="qual"
   ?rs.filter(r=>r.qual).length
   :k==="conv"
    ?convPct(rs)
    :k==="amount_without_gst"
     ?bookedFinancialTotals(rs).withoutGst
    :k==="amount_with_gst"
     ?bookedFinancialTotals(rs).withGst
    :k==="paid_amount"
     ?bookedFinancialTotals(rs).paid
    :k==="balance_amount"
     ?bookedFinancialTotals(rs).balance
    :k==="visited_total"
     ?rs.filter(r=>
       r.cat===CATS[0]||
       r.cat===CATS[1]||
       r.cat===CATS[7]
      ).length
     :rs.filter(r=>r.cat===k).length;
function growth(k){
 const financialKeys=[
  "amount_without_gst",
  "amount_with_gst",
  "paid_amount",
  "outstanding_collected_amount",
  "balance_amount"
 ];

 if(financialKeys.includes(k)){
  const currentRange=
   agentPeriodRange(PERIOD);

  const previousRange=
   prevP(PERIOD);

  const currentTotals=
   agentFinancialTotalsForRange(
    currentRange[0],
    currentRange[1]
   );

  const previousTotals=
   agentFinancialTotalsForRange(
    previousRange[0],
    previousRange[1]
   );

  const c=
   k==="outstanding_collected_amount"
    ?agentOutstandingCollectedForRange(
      currentRange[0],
      currentRange[1]
     )
    :agentFinancialMetric(
      currentTotals,
      k
     );

  const p=
   k==="outstanding_collected_amount"
    ?agentOutstandingCollectedForRange(
      previousRange[0],
      previousRange[1]
     )
    :agentFinancialMetric(
      previousTotals,
      k
     );

  return {
   c,
   p,
   d:p
    ?Math.round(
      (c-p)/p*100
     )
    :null
  };
 }

 const cur=inP(arec(),PERIOD);
 const [pf,pt]=prevP(PERIOD);
 const prv=arec().filter(r=>r.dt>=pf&&r.dt<=pt);
 const c=M(cur,k),p=M(prv,k);
 return {c,p,d:p?Math.round((c-p)/p*100):null};
}
function gArrow(g,inv){
 if(!AGENT_HISTORY_READY){
  return '<span class="gr8">history loading…</span>';
 }

 if(!g.p){
  if(!g.c)return '<span class="gr8">— no records in either period</span>';
  const cls=inv?"dn":"up";
  return '<span class="gr8 '+cls+'">NEW · previous period was 0</span>';
 }
 const d=g.d||0;
 const good=inv?d<=0:d>=0;
 return '<span class="gr8 '+(good?"up":"dn")+'">'+(d>=0?"▲ ":"▼ ")+Math.abs(d)+'% vs prev period</span>';
}

