function srt(k){
 if(SORTK===k){
  SORTD*=-1;
 }else{
  SORTK=k;

  /*
   * Branch defaults to alphabetical A -> Z.
   * Numeric columns retain the existing descending-first behaviour.
   */
  SORTD=
   k==="br"
    ?-1
    :1;
 }

 renderAgent();
}

async function tilePop(key,label){
 const financialKeys=[
  "amount_without_gst",
  "amount_with_gst",
  "paid_amount",
  "outstanding_collected_amount",
  "balance_amount"
 ];

 if(financialKeys.includes(key)){
  const range=
   agentPeriodRange(PERIOD);

  let financialRows=
   agentFinancialEventsForRange(
    range[0],
    range[1]
   );

  if(key==="paid_amount"){
   financialRows=
    financialRows.filter(event=>
     Number(
      event&&event.paid_amount||0
     )>0
    );
  }else if(
   key==="outstanding_collected_amount"
  ){
   financialRows=
    financialRows.filter(event=>{
     if(
      String(
       event&&event.event_type||""
      )!=="Payment"
     ){
      return false;
     }

     const paymentDate=
      String(
       event&&event.event_date||""
      ).slice(0,10);

     const invoiceDate=
      String(
       event&&event.invoice_date||""
      ).slice(0,10);

     return (
      Number(
       event&&event.paid_amount||0
      )>0&&
      paymentDate&&
      invoiceDate&&
      paymentDate>invoiceDate
     );
    });
  }else{
   /*
    * GST / Balance cards show the invoice cohort.
    */
   financialRows=
    financialRows.filter(event=>
     String(
      event&&event.event_type||""
     )==="Invoice"
    );
  }

  const popup=
   ensureLifeCcPopupShell();

  if(
   !popup||
   !popup.overlay||
   !popup.title||
   !popup.body
  ){
   return;
  }

  popup.title.textContent=
   agName(AG)+
   " — "+
   label+
   " · "+
   agentPeriodLabel(PERIOD);

  popup.body.innerHTML=
   financialActivityTable(
    financialRows
   );

  popup.overlay.classList.add("on");
  return;
 }

 let rows=inP(
