function bmShift(n){
 BMON=Math.max(0,Math.min(AGENT_LIFE_CYCLES.length-1,BMON+n));
 renderAgent();
}

function splitBookedTreatments(record){
 const raw=String(record.treatment||record.category||record.treat||"").trim();
 if(!raw||raw==="—"||raw.toLowerCase()==="unspecified")return [];
 return [...new Set(raw.split(";").map(v=>v.trim()).filter(Boolean))];
}

function validAgeGroup(value){
 const age=Number(value);
 if(!Number.isFinite(age)||age<=0||age>120)return "";
 if(age<20)return "Below 20";
 if(age<30)return "20-29";
 if(age<40)return "30-39";
 if(age<50)return "40-49";
 if(age<60)return "50-59";
 return "60+";
}

function perfBoard(all){
 const cycle=AGENT_LIFE_CYCLES[BMON]||AGENT_LIFE_CYCLES[AGENT_LIFE_CYCLES.length-1];
 const prevCycle=BMON>0?AGENT_LIFE_CYCLES[BMON-1]:null;
 const scope=all.filter(r=>r.dt>=cycle.from&&r.dt<=cycle.to);
 const prevScope=prevCycle?all.filter(r=>r.dt>=prevCycle.from&&r.dt<=prevCycle.to):[];
 const booked=scope.filter(r=>r.cat===CATS[0]);
 const unbooked=scope.filter(r=>r.cat===CATS[1]);
 const resolved=booked.length+unbooked.length;
 const pBooked=prevScope.filter(r=>r.cat===CATS[0]);
 const activeDays=new Set(scope.map(r=>r.dt).filter(Boolean)).size;
 const avgPerDay=activeDays?(booked.length/activeDays).toFixed(1):"0.0";

 const mC=booked.filter(r=>r.g==="M").length;
 const fC=booked.filter(r=>r.g==="F").length;
 const oC=booked.filter(r=>r.g==="O").length;
 const totG=mC+fC+oC;

 const treatmentCounts={};
 booked.forEach(record=>{
  splitBookedTreatments(record).forEach(name=>{
   treatmentCounts[name]=(treatmentCounts[name]||0)+1;
  });
 });
 const trTop=Object.entries(treatmentCounts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,11);

 const categoryCounts={};
 booked.forEach(record=>{
  const key=String(record.category||"Unspecified").trim()||"Unspecified";
  categoryCounts[key]=(categoryCounts[key]||0)+1;
 });
 const bestCat=Object.entries(categoryCounts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0]||["—",0];

 const ageCounts={};
 booked.forEach(record=>{
  const group=validAgeGroup(record.age);
  if(group)ageCounts[group]=(ageCounts[group]||0)+1;
 });
 const bestAge=Object.entries(ageCounts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0]||["—",0];

 const dayC=Array(32).fill(0);
 booked.forEach(r=>{if(r.day>=1&&r.day<=31)dayC[r.day]++;});
 const maxDay=Math.max(...dayC);
 const hotDays=maxDay>0?dayC.map((v,i)=>[i,v]).filter(x=>x[0]>0&&x[1]===maxDay).map(x=>x[0]):[];

 const cycleRanking=
  agentCycleRank(
   AG,
   cycle
  );

 const ranking=
  cycleRanking.list.map(row=>({
   agent:row.agent,
   booked:row.booked,
   visits:row.visits,
   total:row.total,
   pct:row.pct,score:row.score,rank:row.rank,leads:row.leads,bookingAchievement:row.bookingAchievement,visitAchievement:row.visitAchievement
  }));

 const rkPos=
  cycleRanking.pos;

 const selectedRank=
  rkPos>0
   ?ranking[rkPos-1]
   :null;

 const brRows=branchKeysForRows(scope,false).map(key=>{
  const visitRows=scope.filter(r=>
   recordBranchKey(r)===key&&
   (
    r.cat===CATS[0]||
    r.cat===CATS[1]||
