   )
  );

  const bk=visitRows.filter(r=>r.cat===CATS[0]).length;

  const previousBooked=prevCycle
   ?prevScope.filter(r=>
     recordBranchKey(r)===key&&
     r.cat===CATS[0]
    ).length
   :null;

  return {
   br:branchDisplayLabel(key,visitRows),
   v:visitRows.length,
   b:bk,
   previousBooked
  };
 }).filter(row=>row.v>0)
