/* --- typing guard: never auto-open while user types --- */
let TYPING=false,TYPT=null;
document.addEventListener("focusin",e=>{const t=(e.target.tagName||"").toLowerCase();if(t==="input"||t==="textarea"||t==="select"){TYPING=true;clearTimeout(TYPT);}});
document.addEventListener("focusout",()=>{clearTimeout(TYPT);TYPT=setTimeout(()=>TYPING=false,2500);});
document.addEventListener("keydown",()=>{const t=(document.activeElement&&document.activeElement.tagName||"").toLowerCase();
 if(t==="input"||t==="textarea"||t==="select"){TYPING=true;clearTimeout(TYPT);TYPT=setTimeout(()=>TYPING=false,2500);}});
function later(fn,ms){setTimeout(function tick(){if(TYPING){setTimeout(tick,4000);return;}fn();},ms);}

