function bindEdgeCloseButton(
 panel,
 key
){
 if(!panel)return;

 const closeButton=
  panel.querySelector(
   ".ep-x,[data-edge-close]"
  );

 if(!closeButton)return;

 closeButton.removeAttribute(
  "onclick"
 );
 closeButton.onclick=null;

 if(
  closeButton.dataset
   .lifeEdgeCloseBound==="1"
 ){
  return;
 }

 closeButton.dataset
  .lifeEdgeCloseBound="1";

 closeButton.addEventListener(
  "click",
  function(event){
   event.preventDefault();
   event.stopPropagation();
   togEp(key,false);
  }
 );
}

function ensureEdgePanelShell(key){
 let panel=byId("ep"+key);
 const definition=
  edgePanelDefinition(key);

 if(!definition){
  return null;
 }

 if(!panel){
  panel=document.createElement(
   "aside"
  );

  panel.className="ep";
  panel.id="ep"+key;
  panel.setAttribute(
   "role",
   "dialog"
  );
  panel.setAttribute(
   "aria-modal",
   "false"
  );
  panel.setAttribute(
   "aria-labelledby",
   "ep"+key+"Title"
  );

  panel.innerHTML=`
   <div class="ep-hd">
    <h4 id="ep${key}Title">
     ${definition.title}
     <small id="${definition.subtitleId}">
      ${definition.subtitle}
     </small>
    </h4>

    <button
     type="button"
     class="ep-x"
     data-edge-close="${key}"
     aria-label="Close ${definition.title}"
    >✕</button>
   </div>

   <div
    class="ep-bd"
    id="${definition.bodyId}"
   ></div>`;

  (
   document.body||
   document.documentElement
  ).appendChild(panel);
 }

 bindEdgeCloseButton(
  panel,
  key
 );

 return panel;
}

function setEdgePanelState(
 panel,
 isOpen
){
 if(!panel)return;

 panel.classList.toggle(
  "on",
  isOpen
 );

 /*
  * Inline styles guarantee that old or conflicting ERPNext CSS
  * cannot keep the panel outside the visible screen.
  */
 panel.style.setProperty(
  "right",
  isOpen?"20px":"-520px",
  "important"
 );

 panel.style.setProperty(
  "visibility",
  isOpen?"visible":"hidden",
  "important"
 );

 panel.style.setProperty(
  "pointer-events",
  isOpen?"auto":"none",
  "important"
 );

 panel.setAttribute(
  "aria-hidden",
  isOpen?"false":"true"
 );
}

function togEp(keyValue,forceOpen){
 const key=String(
  keyValue||""
 ).trim().toUpperCase();

 if(
  !["A","B","C","D","E"]
   .includes(key)
 ){
  return;
 }

 const selectedPanel=
  ensureEdgePanelShell(key);

 if(!selectedPanel){
  console.error(
   "Edge panel could not be created:",
   key
  );
  return;
 }

 const currentlyOpen=
  selectedPanel.classList
   .contains("on");

 const shouldOpen=
  forceOpen===true
   ?true
   :forceOpen===false
    ?false
    :!currentlyOpen;

 ["A","B","C","D","E"]
  .forEach(otherKey=>{
   const panel=
    ensureEdgePanelShell(
     otherKey
    );

   const button=
    byId("et"+otherKey);

   const open=
    otherKey===key&&
    shouldOpen;

   setEdgePanelState(
    panel,
    open
   );

   if(button){
    button.setAttribute(
     "aria-expanded",
     open?"true":"false"
    );
   }
  });

 if(!shouldOpen){
  return;
 }

 if(key==="A"){
  epA();
 }else if(key==="B"){
  epB();
 }else if(key==="C"){
  epC();
 }else if(key==="D"){
  epD();
 }else if(key==="E"){
  epE();
 }
}

function bindOneEdgeButton(key){
 const button=byId(
  "et"+key
 );

 if(!button){
  return;
 }

 /*
  * Remove old inline onclick handlers. Otherwise one click may
  * open and immediately close the panel by toggling twice.
  */
 button.removeAttribute(
  "onclick"
 );
 button.onclick=null;
 button.style.setProperty(
  "pointer-events",
  "auto",
  "important"
 );
 button.style.setProperty(
  "cursor",
  "pointer",
  "important"
 );

 if(
  button.dataset
   .lifeDirectEdgeBound==="1"
 ){
  return;
 }

 button.dataset
  .lifeDirectEdgeBound="1";

 button.addEventListener(
  "click",
  function(event){
   event.preventDefault();
   event.stopPropagation();
   togEp(key);
  }
 );
}

function bindEdgePanelControls(){
 ["A","B","C","D","E"]
  .forEach(key=>{
   bindOneEdgeButton(key);

   const panel=
    ensureEdgePanelShell(key);

   if(
    panel&&
    !panel.classList.contains("on")
   ){
    setEdgePanelState(
     panel,
     false
    );
   }
  });
}

