/* ===== Live: Support On-Floor Staff (Employee + Employee Checkin) ===== */
let SUPPORT_EMPS=[];

function cleanSupportDepartmentName(value){
 return String(value||"")
  .replace(/\s*-\s*(LSACPL|LASPL)\s*$/i,"")
  .trim();
}

function isSupportDepartment(value){
 return cleanSupportDepartmentName(value).toLowerCase().includes("support");
}

async function fetchSupportEmployees(){
 const fields=[
  "name",
  "employee_name",
  "designation",
  "department",
  "branch",
  "user_id"
 ];

 let rows=await apiGetList(
  "Employee",
  fields,
  [["status","=","Active"],["department","like","Support%"]],
  {order_by:"employee_name asc",limit_page_length:1000}
 );

 rows=(rows||[]).filter(employee=>isSupportDepartment(employee.department));

 /* Fallback protects sites where the company suffix/prefix makes LIKE too strict. */
 if(!rows.length){
  const activeEmployees=await apiGetList(
   "Employee",
   fields,
   [["status","=","Active"]],
   {order_by:"employee_name asc",limit_page_length:1000}
  );

  rows=(activeEmployees||[]).filter(employee=>isSupportDepartment(employee.department));
 }

 SUPPORT_EMPS=rows.sort((a,b)=>
  String(a.employee_name||a.name||"").localeCompare(
   String(b.employee_name||b.name||"")
  )
 );
}

function fmtT(hm){
 if(!hm)return "—";
 const parts=String(hm).split(":").map(Number);
 const h=parts[0];
 const m=parts[1];
 if(!Number.isFinite(h)||!Number.isFinite(m))return String(hm);
 const hh=h%12||12;
 return hh+":"+String(m).padStart(2,"0")+" "+(h<12?"am":"pm");
}

async function fetchTodayCheckins(){
 if(!SUPPORT_EMPS.length)await fetchSupportEmployees();
 if(!SUPPORT_EMPS.length)return [];

 const employeeNames=SUPPORT_EMPS.map(employee=>employee.name).filter(Boolean);
 const today=attendanceTodayISO();

 const [attendanceRows,checkinRows]=await Promise.all([
  fetchTodayAttendanceRows(today),
  employeeNames.length
   ?fetchTodayEmployeeCheckins(employeeNames,today)
   :Promise.resolve([])
 ]);

 const attendanceByEmployee={};
 (attendanceRows||[]).forEach(row=>{
  if(row.employee)attendanceByEmployee[row.employee]=row;
 });

 const checkinByEmployee=buildCheckinMap(checkinRows);

 return SUPPORT_EMPS.map(employee=>{
  const attendanceRow=attendanceByEmployee[employee.name]||null;
  const checkin=checkinByEmployee[employee.name]||null;

  const directIn=attendanceTimePart(attendanceRow&&attendanceRow.in_time);
  const directOut=attendanceTimePart(attendanceRow&&attendanceRow.out_time);
  const firstIn=directIn||(checkin&&checkin.firstIn)||null;
  const latestOut=directOut||(checkin&&checkin.latestOut)||null;

  let state="not-checked-in";
  if(latestOut)state="checked-out";
  else if(firstIn)state="on-floor";

  return {
   id:employee.name||"",
   name:employee.employee_name||employee.name||"—",
   designation:employee.designation||"—",
   department:cleanSupportDepartmentName(employee.department)||"Support",
   branch:employee.branch||"—",
   attendanceStatus:attendanceRow&&attendanceRow.status||"",
   checkIn:firstIn?attendanceDisplayTime(firstIn):"—",
   checkOut:latestOut?attendanceDisplayTime(latestOut):"—",
   state
  };
 }).sort((a,b)=>{
  const order={"on-floor":0,"checked-out":1,"not-checked-in":2};
  return (order[a.state]-order[b.state])||a.name.localeCompare(b.name);
 });
}

