  );
 }

 return doc;
}

async function aprCheckAuthorization(a){
 const me=currentPortalUser();

 if(!me){
  throw new Error(
   "The logged-in ERPNext user could not be detected."
  );
 }

 if(
  me!=="Administrator"&&
  String(a.selected_approver||"").trim()!==me
 ){
  throw new Error(
   "This request is assigned to "+
   (agName(a.selected_approver)||a.selected_approver||"another approver")+
   "."
  );
 }

 if(aprIsL3(a)){
  const hasL3=await aprHasL3Permission();

  if(!hasL3){
   throw new Error(
    "Only an L3 Discount Approver or Administrator can approve this L3 request."
   );
  }
 }

 return me;
}

