async function aprApprove(i){
 if(APR_ACTION_BUSY)return;

 const a=APR[i];
 if(!a)return;

 const remarks=String(
  byId("aprRemarks")&&byId("aprRemarks").value||""
 ).trim();

 let approvedAmount=0;

 if(aprIsL3(a)){
  approvedAmount=Number(
   byId("aprApprovedAmount")&&
   byId("aprApprovedAmount").value||0
  );

  const billTotal=Number(a.bill_total||0);

  if(!approvedAmount||approvedAmount<=0){
   setAprBusy(
    false,
    "Enter the approved final amount.",
    true
   );
   if(byId("aprApprovedAmount"))byId("aprApprovedAmount").focus();
   return;
  }

  if(billTotal>0&&approvedAmount>=billTotal){
   setAprBusy(
    false,
    "Approved final amount must be lower than the original bill total.",
    true
   );
   if(byId("aprApprovedAmount"))byId("aprApprovedAmount").focus();
   return;
  }
 }

 const confirmed=window.confirm(
  "Approve this discount request?\n\n"+
  (a.branch||"—")+" · "+aprRequestLabel(a)
 );

 if(!confirmed)return;

 setAprBusy(
  true,
  "Applying the approved discount to the Sales Invoice…",
  false
 );

 try{
  await aprFreshPendingRequest(a);
  await aprCheckAuthorization(a);

  if(!a.linked_invoice){
   throw new Error(
    "This approval request has no linked Sales Invoice."
   );
  }

  const args={
   invoice_name:a.linked_invoice
  };

  if(aprIsL3(a)){
   args.approved_amount=approvedAmount;
  }

  /*
   * This is the same backend method already used by the
   * Sales Invoice discount approval workflow. It applies the
   * discount and updates the approval request/invoice backend.
   */
  const result=await apiCallMethod(
   "apply_invoice_discount",
   args
  );

  await aprSaveComment(
   a,
   "Approved",
   remarks
  );

  byId("ovl").classList.remove("on");

  const finalAmount=Number(
   result&&result.final_amount||0
  );

  toast(
   finalAmount>0
    ?(a.branch||"—")+
      " — APPROVED · Customer pays ₹"+
      moneyIN(finalAmount)
    :(a.branch||"—")+" — APPROVED ✓"
  );

  await epD();
 }catch(error){
  console.error("Discount approval failed:",error);

  setAprBusy(
   false,
   error&&error.message
    ?error.message
    :"Could not approve this discount request.",
   true
  );
 }
}

async function aprReject(i){
 if(APR_ACTION_BUSY)return;

 const a=APR[i];
 if(!a)return;

 const remarks=String(
  byId("aprRemarks")&&byId("aprRemarks").value||""
 ).trim();

 if(!remarks){
  setAprBusy(
   false,
   "Remarks are mandatory when rejecting.",
   true
  );

  if(byId("aprRemarks"))byId("aprRemarks").focus();
  return;
 }

 const confirmed=window.confirm(
  "Reject this discount request?\n\n"+
  (a.branch||"—")+" · "+aprRequestLabel(a)
 );

 if(!confirmed)return;

 setAprBusy(
  true,
  "Rejecting request and unlocking the Sales Invoice…",
  false
 );

 try{
  await aprFreshPendingRequest(a);
  const me=await aprCheckAuthorization(a);

  /*
   * Match the existing Sales Invoice rejection workflow:
   * 1. Reject the Discount Approval Request.
   * 2. Save rejection reason, acting user and action time.
   * 3. Unlock the linked Sales Invoice.
   * 4. Keep invoice status Approved when an earlier approval exists;
   *    otherwise mark it Rejected.
   */
  await apiSetValue(
   "Discount Approval Request",
   a.name,
   {
    status:"Rejected",
    rejection_reason:remarks,
    approved_by:me,
    approved_at:portalNowDateTime()
   }
  );

  if(a.linked_invoice){
   const previousApprovals=await apiGetList(
    "Discount Approval Request",
    ["name"],
    [
     ["linked_invoice","=",a.linked_invoice],
     ["status","=","Approved"]
    ],
    {
     limit_page_length:1
    }
   );

   await apiSetValue(
    "Sales Invoice",
    a.linked_invoice,
    {
     discount_locked:0,
     approval_workflow_status:
      previousApprovals.length>0
       ?"Approved"
       :"Rejected"
    }
   );
  }

  await aprSaveComment(
   a,
   "Rejected",
   remarks
  );

  byId("ovl").classList.remove("on");

  toast(
   (a.branch||"—")+
   " — REJECTED · Invoice unlocked"
  );

  await epD();
 }catch(error){
  console.error("Discount rejection failed:",error);

  setAprBusy(
   false,
   error&&error.message
    ?error.message
    :"Could not reject this discount request.",
   true
  );
 }
}

