let TODAY_APPOINTMENTS=[];
let TODAY_APPOINTMENTS_LOADING=false;

function todayAppointmentDateLabel(dateText){
 const value=String(dateText||"").trim();

 if(!value)return "—";

 const parts=value.split("-").map(Number);
 const date=new Date(
  parts[0],
  parts[1]-1,
  parts[2]
 );

 if(Number.isNaN(date.getTime()))return value;

 return date.toLocaleDateString(
  "en-GB",
  {
   day:"2-digit",
   month:"short",
   year:"numeric"
  }
 );
}

function todayAppointmentTime(value){
 const text=String(value||"").trim();

 if(!text)return "—";

 const timePart=(
  text.includes(" ")
   ?text.split(" ")[1]
   :text.includes("T")
    ?text.split("T")[1]
    :text
 ).slice(0,8);

 const match=timePart.match(/^(\d{1,2}):(\d{2})/);

 if(!match)return timePart||"—";

 let hour=Number(match[1]);
 const minute=match[2];
 const suffix=hour>=12?"pm":"am";

 hour=hour%12||12;

 return (
  String(hour).padStart(2,"0")+
  ":"+
  minute+
  " "+
  suffix
 );
}

function todayAppointmentStatusInfo(status){
 const value=String(status||"").trim();
 const normalized=value.toLowerCase();

 if(normalized==="visited booked"){
  return {
   label:"VISITED – BOOKED",
   pill:"p-g",
   border:"#2E7D32"
  };
 }

 if(normalized==="visited not booked"){
  return {
   label:"VISITED – NOT BOOKED",
   pill:"p-a",
   border:"#E65100"
  };
 }

 if(normalized==="not visited"){
  return {
   label:"NOT VISITED",
   pill:"p-r",
   border:"#C62828"
  };
 }

 if(normalized==="booked"){
  return {
   label:"SCHEDULED / AWAITING VISIT",
   pill:"p-b",
   border:"#1565C0"
  };
 }

 if(normalized==="not booked"){
  return {
   label:"NOT BOOKED",
   pill:"p-p",
   border:"#8D6E00"
  };
 }

 if(normalized==="cancelled"){
  return {
   label:"CANCELLED",
   pill:"p-r",
   border:"#C62828"
  };
 }

 return {
  label:value?value.toUpperCase():"STATUS NOT SET",
  pill:"p-gr",
  border:"#78909C"
 };
}

async function fetchTodayAppointments(){
 const today=todayISO();

 const fields=[
  "name",
  "lead_name",
  "branch",
  "lead_owner",
  "status",
  "custom_cc_stage",
  "gender",
  "age",
  "mobile_no",
  "custom_appointment_date_and_time",
  "custom_appointment_status",
  "custom_consulting_doctor",
  "custom_treatment_interests",
  "custom_remarks"
 ];

 const filters=[
  [
   "custom_appointment_date_and_time",
   ">=",
   today+" 00:00:00"
  ],
  [
   "custom_appointment_date_and_time",
   "<=",
   today+" 23:59:59"
  ]
 ];

 if(isLifeCcAgentLogin()){
  filters.push([
   "lead_owner",
   "=",
   currentPortalUser()
  ]);
 }

 let rows=[];
 let start=0;
 const pageLength=500;

 while(true){
  const page=await apiGetList(
   "Lead",
   fields,
   filters,
   {
    order_by:"custom_appointment_date_and_time asc",
    limit_start:start,
    limit_page_length:pageLength
   }
  );

  rows.push(...page);

  if(page.length<pageLength)break;

  start+=pageLength;

  if(rows.length>=10000)break;
 }

 const uniqueRows=[
  ...new Map(
   rows
    .filter(row=>row&&row.name)
    .map(row=>[row.name,row])
  ).values()
 ];

 /*
  * Appointment Booked / Booked / Scheduled / Confirmed /
  * Awaiting Visit are all the same Scheduled/Awaiting category.
  */
 return uniqueRows.filter(row=>{
  const status=
   String(row.custom_appointment_status||"").trim()||
   String(row.status||"").trim()||
   String(row.custom_cc_stage||"").trim();

  return mapCat(status)===CATS[3];
 });
}

