function attendanceTodayISO(){
 if(typeof frappe!=="undefined"&&frappe.datetime&&frappe.datetime.get_today){
  return frappe.datetime.get_today();
 }
 if(typeof todayISO==="function")return todayISO();
 const d=new Date();
 return [
  d.getFullYear(),
  String(d.getMonth()+1).padStart(2,"0"),
  String(d.getDate()).padStart(2,"0")
 ].join("-");
}

function attendanceTimePart(value){
 if(value===null||value===undefined||value==="")return null;

 const text=String(value).trim();
 const match=text.match(/(?:^|\s|T)(\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?/);
 if(!match)return null;

 const hour=Number(match[1]);
 const minute=Number(match[2]);
 if(!Number.isFinite(hour)||!Number.isFinite(minute))return null;

 return String(hour).padStart(2,"0")+":"+String(minute).padStart(2,"0");
}

function attendanceDisplayTime(value){
 const hm=attendanceTimePart(value);
 return hm?fmtT(hm):"—";
}

async function fetchTodayAttendanceRows(today){
 const commonFilters=[
  ["attendance_date","=",today],
  ["docstatus","<",2]
