   return [];
  }
 }
}

async function fetchTodayEmployeeCheckins(employeeNames,today){
 const output=[];
 const seen=new Set();

 for(const employeeChunk of splitIntoChunks(employeeNames,60)){
  let rows=[];

  try{
   rows=await attendanceGetAll(
    "Employee Checkin",
    ["name","employee","employee_name","log_type","time","shift"],
    [
     ["employee","in",employeeChunk],
     ["time","between",[today+" 00:00:00",today+" 23:59:59"]]
    ],
    "time asc"
   );
  }catch(error){
   console.warn("Employee Checkin could not be loaded for an employee batch.",error);
   continue;
  }

  rows.forEach(row=>{
   const key=row.name||[
    row.employee||"",
    row.log_type||"",
    row.time||""
   ].join("|");

   if(seen.has(key))return;
   seen.add(key);
   output.push(row);
  });
 }

 return output;
}

function buildCheckinMap(rows){
 const grouped={};

 (rows||[]).forEach(row=>{
  if(!row.employee||!row.time)return;
  (grouped[row.employee]=grouped[row.employee]||[]).push(row);
 });

 const result={};

 Object.keys(grouped).forEach(employee=>{
  const employeeRows=grouped[employee].slice().sort((a,b)=>
   String(a.time||"").localeCompare(String(b.time||""))
  );

  let firstIn=null;
  let latestOut=null;
  let lastLog=null;
  let inferredNext="IN";

  employeeRows.forEach(row=>{
   let logType=String(row.log_type||"").trim().toUpperCase();
   const time=attendanceTimePart(row.time);
   if(!time)return;

   /* Some biometric imports leave log_type empty. In that case alternate IN/OUT. */
   if(logType!=="IN"&&logType!=="OUT"){
    logType=inferredNext;
    inferredNext=logType==="IN"?"OUT":"IN";
   }else{
    inferredNext=logType==="IN"?"OUT":"IN";
   }

   if(logType==="IN"&&!firstIn)firstIn=time;
   if(logType==="OUT")latestOut=time;
   lastLog=logType;
  });

  result[employee]={firstIn,latestOut,lastLog};
 });

 return result;
}

function attendanceState(attendanceRow,checkin){
 const status=String(attendanceRow&&attendanceRow.status||"").trim().toLowerCase();

 if(status==="absent")return "absent";
 if(status==="on leave")return "on-leave";
 if(status==="half day")return "half-day";
 if(status==="work from home")return "work-from-home";

 const directOut=attendanceTimePart(attendanceRow&&attendanceRow.out_time);
 const directIn=attendanceTimePart(attendanceRow&&attendanceRow.in_time);

 if(directOut)return "checked-out";
 if(checkin&&checkin.lastLog==="OUT")return "checked-out";
 if(directIn||checkin&&checkin.lastLog==="IN")return "on-floor";
 if(status==="present")return "present";
 return "not-checked-in";
}

async function epC(){
 if(ATTENDANCE_LOADING)return;
 ATTENDANCE_LOADING=true;

 const body=byId("epCb");
 const count=byId("cC");

 if(!body){
  ATTENDANCE_LOADING=false;
  return;
 }

 body.innerHTML='<div class="loadwrap"><span class="spin"></span>Loading today\'s Check-in and Check-out times…</div>';

 try{
  await fetchAllEmployees(true);

  const today=attendanceTodayISO();
  const employeeNames=ALL_EMPS.map(employee=>employee.name).filter(Boolean);

  const [attendanceRows,checkinRows]=await Promise.all([
   fetchTodayAttendanceRows(today),
   employeeNames.length?fetchTodayEmployeeCheckins(employeeNames,today):Promise.resolve([])
  ]);

  const attendanceByEmployee={};
  attendanceRows.forEach(row=>{
   if(row.employee)attendanceByEmployee[row.employee]=row;
  });

  const checkinByEmployee=buildCheckinMap(checkinRows);
  const employeesByBranch={};

  ALL_EMPS.forEach(employee=>{
   const attendanceRow=attendanceByEmployee[employee.name]||null;
   const checkin=checkinByEmployee[employee.name]||null;

   const directIn=attendanceTimePart(attendanceRow&&attendanceRow.in_time);
   const directOut=attendanceTimePart(attendanceRow&&attendanceRow.out_time);

   const firstIn=directIn||(checkin&&checkin.firstIn)||null;
   const latestOut=directOut||(checkin&&checkin.latestOut)||null;
   const state=attendanceState(attendanceRow,checkin);
   const branch=employee.branch||"Unassigned";

   const record={
    name:employee.employee_name||employee.name||"—",
    designation:employee.designation||employee.department||"—",
    status:attendanceRow&&attendanceRow.status||"",
    checkIn:firstIn?attendanceDisplayTime(firstIn):"—",
    checkOut:latestOut?attendanceDisplayTime(latestOut):"—",
    state
   };

   if(!employeesByBranch[branch])employeesByBranch[branch]=[];
   employeesByBranch[branch].push(record);
  });

  const branches=Object.keys(employeesByBranch).sort((a,b)=>a.localeCompare(b));
  if(count)count.textContent=ALL_EMPS.length;

  body.innerHTML=branches.map((branch,branchIndex)=>{
   const employees=employeesByBranch[branch];
   const stateOrder={
    "on-floor":0,
    "present":1,
    "half-day":2,
    "work-from-home":3,
    "checked-out":4,
    "on-leave":5,
    "absent":6,
    "not-checked-in":7
   };

   employees.sort((a,b)=>
    ((stateOrder[a.state]??99)-(stateOrder[b.state]??99))||a.name.localeCompare(b.name)
   );

   const checkedIn=employees.filter(employee=>employee.checkIn!=="—").length;
   const checkedOut=employees.filter(employee=>employee.checkOut!=="—").length;
   const missing=employees.filter(employee=>employee.checkIn==="—"&&employee.checkOut==="—").length;
   const onFloor=employees.filter(employee=>employee.state==="on-floor").length;

   const employeeRows=employees.map(employee=>{
    const colorMap={
     "on-floor":"#2E7D32",
     "present":"#43A047",
     "checked-out":"#757575",
     "half-day":"#E65100",
     "work-from-home":"#1565C0",
     "on-leave":"#8D6E00",
     "absent":"#C62828",
     "not-checked-in":"#C62828"
    };

    const labelMap={
     "on-floor":"ON FLOOR",
     "present":"PRESENT",
     "checked-out":"CHECKED OUT",
     "half-day":"HALF DAY",
     "work-from-home":"WORK FROM HOME",
     "on-leave":"ON LEAVE",
     "absent":"ABSENT",
     "not-checked-in":"NOT CHECKED IN"
    };

    return `<div class="erow attendance-row">
     <span class="ed" style="background:${colorMap[employee.state]||"#9E9E9E"}"></span>
     <div class="en">
      <b>${lifeCcEsc(employee.name)}</b>
      <span>${lifeCcEsc(employee.designation)}</span>
      <span class="attendance-status ${lifeCcEsc(employee.state)}">${lifeCcEsc(labelMap[employee.state]||employee.status||"—")}</span>
     </div>
     <div class="et num attendance-times">
      <div><span>Check-in</span><b>${lifeCcEsc(employee.checkIn)}</b></div>
      <div><span>Check-out</span><b>${lifeCcEsc(employee.checkOut)}</b></div>
     </div>
    </div>`;
   }).join("");

   return `<div class="bacc" id="bacc${branchIndex}">
    <div class="bacc-h" onclick="byId('bacc${branchIndex}').classList.toggle('open')">
     <b>🏥 ${lifeCcEsc(branch)} <small style="font-weight:700;color:var(--mut)">(${employees.length})</small></b>
     <span class="bstat" style="color:var(--g700)" title="Currently on floor">ON ${onFloor}</span>
     <span class="bstat" style="color:#616161" title="Checked out today">OUT ${checkedOut}</span>
     <span class="bstat" style="color:var(--red)" title="No Check-in time found">NO-IN ${missing}</span>
     <button type="button" class="tog" onclick="event.stopPropagation();byId('bacc${branchIndex}').classList.toggle('open')">▾</button>
    </div>
    <div class="bacc-b">${employeeRows}</div>
   </div>`;
  }).join("")||'<div style="font-size:11px;color:var(--mut);padding:10px 4px">No active employees found.</div>';

  console.log("Today's Attendance rows:",attendanceRows);
  console.log("Today's Employee Checkin rows:",checkinRows);
 }catch(error){
  console.error("Could not load today attendance:",error);
  if(count)count.textContent="—";
  body.innerHTML='<div class="errbox">Could not load today\'s Attendance / Employee Checkin data ('+lifeCcEsc(error&&error.message||"error")+'). Open browser Console for the exact API error.</div>';
 }finally{
  ATTENDANCE_LOADING=false;
 }
}

