/* --- notifications: live --- */
function notif(cls,html,onclick){
 const notificationHtml=
  String(html||"");

 /*
  * Defense-in-depth:
  * even if some older code directly calls notif() for Discount
  * Approval Request, normal / branch users must not see it.
  */
 if(
  notificationHtml.includes(
   "New Discount Approval Request"
  )&&
  !lifeCanSeeDiscountApprovalPopups()
 ){
  return;
 }

 const stack=byId("nstack");

 if(!stack){
  return;
 }

 const notification=
  document.createElement("div");

 notification.className=
  "notif "+String(cls||"");

 notification.innerHTML=`
  <button
   type="button"
   class="nx"
   aria-label="Close notification"
  >✕</button>
  ${html}
  <div class="nt">
   live · just now · auto-hides in 15s
  </div>`;

 const closeButton=
  notification.querySelector(".nx");

 if(closeButton){
  closeButton.addEventListener(
   "click",
   function(event){
    event.stopPropagation();
    notification.remove();
   }
  );
 }

 if(onclick){
  notification.addEventListener(
   "click",
   function(){
    notification.remove();
    onclick();
   }
  );
 }

 stack.prepend(notification);

 setTimeout(function(){
  if(notification.parentNode){
   notification.remove();
  }
 },15000);
}

