let LEAD_POLL_SINCE=null;

function removeLeadVisitUpdatePopups(){
 const stack=byId("nstack");
 const scope=stack||document;
 scope.querySelectorAll(".notif").forEach(notification=>{
  const text=String(notification.textContent||"");
  if(text.includes("Lead Visit Update"))notification.remove();
 });
}

/*
 * Safety guard: even if another old code block attempts to create a
 * Lead Visit Update notification, remove only that card immediately.
 * COO approval and other notification cards remain untouched.
 */
(function blockLeadVisitUpdatePopups(){
 removeLeadVisitUpdatePopups();
 const stack=byId("nstack");
 if(!stack)return;
 const observer=new MutationObserver(()=>removeLeadVisitUpdatePopups());
 observer.observe(stack,{childList:true,subtree:true});
})();

async function pollLeadUpdates(){
 try{
  const since=LEAD_POLL_SINCE||new Date(Date.now()-10*60000)
   .toISOString().slice(0,19).replace("T"," ");
  const nowStamp=new Date().toISOString().slice(0,19).replace("T"," ");

  const rows=await apiGetList(
   "Lead",
   ["name","modified"],
   [["modified",">",since],["custom_appointment_status","!=",""]],
   {order_by:"modified desc",limit_page_length:50}
  );

  LEAD_POLL_SINCE=nowStamp;
  removeLeadVisitUpdatePopups();

  /*
   * IMPORTANT:
   * Do NOT auto-refresh / re-render the dashboard when a Lead changes.
   *
   * Previously this called loadData(), which rebuilt the whole report
   * automatically and looked like the page was refreshing by itself.
   *
   * Report data now changes only when the user clicks Refresh / Apply
   * or changes a report filter.
   */
  if(rows.length){
   console.log(
    "Lead changes detected — dashboard auto-refresh is disabled:",
    rows.length
   );
  }
 }catch(error){
  console.error("Silent Lead update polling failed:",error);
 }
}

