/* New pending Discount Approval Request notifications — reuses the epD fetch */
let APR_SEEN=null;
async function pollApprovalNotifs(){
 /*
  * Branch / normal portal users:
  * - no Discount Approval popup
  * - no approval fetch/poll
  */
 if(
  !lifeCanSeeDiscountApprovalPopups()
 ){
  lifeRemoveDiscountApprovalPopups();

  const approvalCount=byId("cD");

  if(approvalCount){
   approvalCount.textContent="0";
  }

  return;
 }

 try{
  const rows=await fetchApprovals();
  if(APR_SEEN===null){APR_SEEN=new Set(rows.map(a=>a.name));} // first run: don't notify for pre-existing backlog
  else{
   rows.forEach(a=>{
    if(!APR_SEEN.has(a.name)){
     APR_SEEN.add(a.name);
     const idx=rows.findIndex(x=>x.name===a.name);
     notif("","<b>🛎 New Discount Approval Request</b>"+lifeCcEsc(a.branch||"—")+" · "+(a.requested_discount_pct||"—")+"% on ₹"+(a.bill_total||0).toLocaleString("en-IN")+" · Req by "+lifeCcEsc(agName(a.requested_by))+" — tap to open",()=>{APR=rows;aprOpen(idx);});
    }
   });
  }
  APR=rows;

  const approvalCount=byId("cD");

  if(approvalCount){
   approvalCount.textContent=
    String(rows.length);
  }
 }catch(error){
  console.error(
   "approval poll",
   error
  );
 }
}

