function lifePdAbsoluteUrl(value){
 const url=String(value||"").trim();

 if(!url){
  return "";
 }

 if(
  url.startsWith("http://")||
  url.startsWith("https://")||
  url.startsWith("data:")
 ){
  return url;
 }

 return url.startsWith("/")
  ?url
  :"/"+url;
}

