/* =========================================================
 * SINGLE CARD-LAYOUT RUNTIME GUARD
 * No competing old runtime patches exist in this rebuilt file.
 * ========================================================= */
(function(){
 let timer=null;

 function applyCleanCardLayout(){
  const branchFunnel =
   document.querySelector("#tabv1 .life-cc-funnel-grid");

  const branchKpis =
   document.querySelector("#tabv1 #kpis");

  const agentKpis =
   document.querySelector("#tabv2 .agent-kpi-grid");

  const consultantKpis =
   document.querySelector("#tabv4 .consultant-report-kpis");

  const applyGrid = (grid, columns)=>{
   if(!grid) return;

   grid.style.setProperty(
    "display",
    "grid",
    "important"
   );

   grid.style.setProperty(
    "grid-template-columns",
    `repeat(${columns},minmax(0,1fr))`,
    "important"
   );

   grid.style.setProperty(
    "width",
    "100%",
    "important"
   );

   grid.style.setProperty(
    "min-width",
    "0",
    "important"
   );

   grid.style.setProperty(
    "max-width",
    "100%",
    "important"
   );

   grid.style.setProperty(
    "overflow-x",
    "visible",
    "important"
   );
  };

  applyGrid(branchFunnel,10);
  applyGrid(branchKpis,10);
  applyGrid(agentKpis,10);
  applyGrid(consultantKpis,7);

  /*
   * Reset accidental horizontal card offsets created by old CSS.
   */
  [
   branchFunnel,
   branchKpis,
   agentKpis,
   consultantKpis
  ].filter(Boolean).forEach(grid=>{
   let parent=grid.parentElement;
   let depth=0;

   while(parent && depth<2){
    parent.style.setProperty(
     "min-width",
     "0",
     "important"
    );

    parent.style.setProperty(
     "max-width",
     "100%",
     "important"
    );

    if(parent.scrollLeft){
     parent.scrollLeft=0;
    }

    parent=parent.parentElement;
    depth++;
   }
  });
 }

 function schedule(){
  clearTimeout(timer);
  timer=setTimeout(
   applyCleanCardLayout,
   40
  );
 }

 if(document.readyState==="loading"){
  document.addEventListener(
   "DOMContentLoaded",
   schedule,
   {once:true}
  );
 }else{
  schedule();
 }

 document.addEventListener(
  "click",
  schedule,
  true
 );

 document.addEventListener(
  "change",
  schedule,
  true
 );

 setTimeout(schedule,300);
 setTimeout(schedule,1000);
 setTimeout(schedule,2200);
})();

/* =====================================================================
   LIFE CC REPORTS — UI ADD-ON v2 (design only, no data/API logic)
   Replaces the v1 add-on. Paste at the VERY END of the Scripting tab.
   - Home + Back buttons (top-left of tab bar)
