   - Dual-tone card structure, auto-fit numbers, +/− colour tone
   - Open/close for section titles
   - Auto column widths for every report table
   ===================================================================== */
(function () {
  if (window.__lccUiAddonV2) return;
  window.__lccUiAddonV2 = true;

  var HOME_URL = '/life-home';          /* change if your home page is different */
  var TABS = '#tabv1,#tabv2,#tabv3,#tabv4';
  var GRID_SEL = '.life-cc-funnel-grid,#kpis,.tdrow,.agent-kpi-grid,.life-mkt-kpis,.mkt-kpis,.consultant-report-kpis';
  var NUM_RE = /^[▲▼+\-−]?\s*₹?\s*\d[\d,]*(\.\d+)?\s*%?$|^[—–-]$/;
  var TREND_RE = /vs\.?\s*prev|previous period|prev\.?\s*period|no records|^\s*new\b/i;
  var NEG_RE = /junk|not booked|not visited|cancel|lost|reject|drop/i;
  var WARN_RE = /unbooked|balance|pending|awaiting|scheduled/i;
  var GOLD_RE = /other|not set/i;
  var state = {};                        /* open/close state for this session */
  var each = function (list, fn) { Array.prototype.forEach.call(list, fn); };

  /* ---------------- text size ---------------- */
  var scale = 1;
  try { scale = parseFloat(localStorage.getItem('lccUiScale')) || 1; } catch (e) {}
  function applyScale() {
    scale = Math.min(1.4, Math.max(0.85, Math.round(scale * 100) / 100));
    document.documentElement.style.setProperty('--lcc-zoom', scale);
    var v = document.getElementById('lccZoomVal');
    if (v) v.textContent = Math.round(scale * 100) + '%';
    try { localStorage.setItem('lccUiScale', scale); } catch (e) {}
  }
  function buildZoom() {
    if (document.getElementById('lccZoom')) return;
    var d = document.createElement('div');
    d.id = 'lccZoom';
    d.innerHTML = '<button type="button" data-z="-1" title="Smaller text">A−</button><span id="lccZoomVal">100%</span>' +
      '<button type="button" data-z="1" title="Larger text">A+</button><button type="button" data-z="0" title="Reset size">⟲</button>';
    d.addEventListener('click', function (e) {
      var b = e.target.closest('button'); if (!b) return;
      var z = +b.getAttribute('data-z'); scale = z === 0 ? 1 : scale + z * 0.05; applyScale();
    });
    document.body.appendChild(d); applyScale();
  }

  /* ---------------- home + back ---------------- */
  function buildNav() {
    var bar = document.querySelector('.tabbar');
    if (!bar || document.getElementById('lccNav')) return;
    var n = document.createElement('div');
    n.id = 'lccNav';
    n.innerHTML =
      '<a class="lcc-nav-btn" href="' + HOME_URL + '" title="Home" aria-label="Home"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M3 11 12 3l9 8"/><path d="M5 10v10h14V10"/></svg></a>' +
      '<button type="button" class="lcc-nav-btn" title="Back" aria-label="Back"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5l-7 7 7 7"/></svg></button>';
    n.querySelector('button').addEventListener('click', function () {
      if (history.length > 1) history.back(); else location.href = HOME_URL;
    });
    bar.insertBefore(n, bar.firstChild);
  }

  var CHEV = '<svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M2.5 4.5 6 8l3.5-3.5"/></svg>';
  function secBtn() {
    var b = document.createElement('button');
    b.type = 'button'; b.className = 'lcc-sec-btn'; b.title = 'Open / close'; b.setAttribute('aria-label', 'Open or close section');
    b.innerHTML = CHEV; return b;
  }

  /* ---------------- cards ---------------- */
  function wrapText(node, cls) {
    var s = document.createElement('span'); s.className = cls;
    node.parentNode.insertBefore(s, node); s.appendChild(node); return s;
  }
  function findNumber(card) {
    var w = document.createTreeWalker(card, NodeFilter.SHOW_TEXT, null), node, best = null, bestSize = -1;
    while ((node = w.nextNode())) {
      var t = node.nodeValue.trim(), p = node.parentElement;
      if (!t || !NUM_RE.test(t) || !p) continue;
      if (TREND_RE.test(p.textContent) && p.textContent.trim() !== t) continue;
      if (p.closest('.lcc-t,.gr8')) continue;
      var size = parseFloat(getComputedStyle(p).fontSize) || 0;
      if (size > bestSize) { best = node; bestSize = size; }
    }
    return best;
  }
  function classifyInside(el, numEl) {
    each(Array.prototype.slice.call(el.childNodes), function (ch) {
      if (ch === numEl) return;
      if (ch.nodeType === 3) { if (ch.nodeValue.trim()) wrapText(ch, 'lcc-t'); return; }
      if (ch.nodeType !== 1) return;
      if (ch.contains(numEl)) { ch.classList.add('lcc-nwrap'); classifyInside(ch, numEl); }
      else ch.classList.add('lcc-t');
    });
  }
  function toneOf(card, numEl, labelText) {
    var cls = card.className + ' ', sty = (card.getAttribute('style') || '');
    for (var e = numEl; e && e !== card; e = e.parentElement) { cls += ' ' + (e.className || ''); sty += (e.getAttribute('style') || ''); }
    if (/\b(rd|red|dn|cV|is-danger|neg)\b/.test(cls) || /c62828|b71c1c|d32f2f|e53935|:\s*red/i.test(sty)) return 'neg';
    if (/\b(or|orange|cN|is-warning|warn)\b/.test(cls) || /e65100|d84a00|ef6c00|f57c00|orange/i.test(sty)) return 'warn';
    if (/\b(pe|gold|cP)\b/.test(cls) || /8d6e00|8a6a00|b8860b/i.test(sty)) return 'gold';
    if (/\bblue\b/.test(cls)) return 'blue';
    if (NEG_RE.test(labelText)) return 'neg';
    if (WARN_RE.test(labelText)) return 'warn';
    if (GOLD_RE.test(labelText)) return 'gold';
    return 'pos';
  }
  function normCard(card) {
    if (card.nodeType !== 1 || card.classList.contains('loadwrap') || card.classList.contains('lcc-grid-toggle')) return;
    var numEl = card.querySelector('.lcc-n');
    if (!numEl) {
      var node = findNumber(card);
      if (!node) return;
      numEl = node.parentElement;
      if (numEl === card || numEl.textContent.trim() !== node.nodeValue.trim()) numEl = wrapText(node, 'lcc-n');
      else numEl.classList.add('lcc-n');
      each(Array.prototype.slice.call(card.childNodes), function (ch) {
        if (ch === numEl) return;
        if (ch.nodeType === 3) { if (ch.nodeValue.trim()) wrapText(ch, TREND_RE.test(ch.nodeValue) ? 'lcc-t' : 'lcc-l'); return; }
        if (ch.nodeType !== 1) return;
        if (ch.contains(numEl)) { ch.classList.add('lcc-nwrap'); classifyInside(ch, numEl); return; }
        var tx = ch.textContent.trim();
        ch.classList.add(!tx || TREND_RE.test(tx) || /\b(gr8|trend|delta)\b/.test(ch.className) ? 'lcc-t' : 'lcc-l');
      });
      card.classList.add('lcc-card');
    }
    var label = '';
    each(card.querySelectorAll('.lcc-l'), function (l) { label += ' ' + l.textContent; });
    card.setAttribute('data-tone', toneOf(card, numEl, label));
    card.style.setProperty('--lcc-len', Math.max(2, numEl.textContent.trim().length));
    each(card.querySelectorAll('.lcc-t'), function (t) {
      var x = t.textContent;
