    var key = tab.id + '|cards';
    var toggles = tab.querySelectorAll('.lcc-grid-toggle');
    var t = null;
    each(toggles, function (x) { if (!t && x.getAttribute('data-key') === key) t = x; else x.remove(); });
    if (!grids.length) { if (t) t.remove(); return; }

    var count = 0;
    grids.forEach(function (g) {
      g.classList.add('lcc-grid');
      each(g.children, function (c) { if (!c.classList.contains('loadwrap')) { count++; normCard(c); } });
    });

    if (!t) {
      t = document.createElement('div');
      t.className = 'lcc-grid-toggle lcc-sec-head';
      t.setAttribute('data-key', key);
      t.innerHTML = '<span>Summary Cards</span><span class="lcc-count"></span>';
      t.appendChild(secBtn());
      t.addEventListener('click', function () { state[key] = !state[key]; scan(); });
    }
    var first = grids[0];
    if (t.nextElementSibling !== first || t.parentNode !== first.parentNode) first.parentNode.insertBefore(t, first);
    var c = t.querySelector('.lcc-count'); var txt = count ? count + ' cards' : '';
    if (c && c.textContent !== txt) c.textContent = txt;
    var on = !!state[key];
    t.classList.toggle('lcc-collapsed', on);
    grids.forEach(function (g) { g.classList.toggle('lcc-hide', on); });
  }

  /* ---------------- section titles ---------------- */
  var SKIP_HEAD = '.life-controlled-panel,.life-premium-section,.lcc-grid-toggle,.agent-report-toolbar,.consultant-report-toolbar,.ovl,.ep,.life-mkt-section-head,.aghd,.aghd2,.agent-compact-head,.pbx';
  var STOP = 'h3,.lcc-grid,.lcc-grid-toggle,.fbar,.tabbar,.life-mkt-filter-wrap,.agent-period-bar,.cc-filter-action-row';
  var CONTROLS = '.fbar,.lcc-grid,.life-mkt-filter-wrap,.agent-period-bar,.cc-filter-action-row,.persel';

  function sectionItems(h, tab) {
    var box = h.closest('.card,.card2');
    if (box && tab.contains(box) && box !== tab && box.querySelectorAll('h3').length === 1 && !box.querySelector(CONTROLS)) {
      var headChild = h;
      while (headChild.parentElement && headChild.parentElement !== box) headChild = headChild.parentElement;
      return { box: box, items: Array.prototype.filter.call(box.children, function (c) { return c !== headChild; }) };
    }
    var a = h;
    for (var k = 0; k < 4; k++) {
      var p = a.parentElement;
      if (!p || p === tab || p.matches('.card,.card2,.wrap')) break;
      if (!a.nextElementSibling || /head|title/i.test(p.className || '')) a = p; else break;
    }
    var list = [];
    for (var n = a.nextElementSibling; n; n = n.nextElementSibling) {
      if (n.matches(STOP) || n.querySelector(STOP)) break;
      list.push(n);
    }
    return { box: null, items: list };
  }

  function sections(tab) {
    each(tab.querySelectorAll('h3'), function (h) {
      if (h.closest(SKIP_HEAD)) return;
      if (h.querySelector('.colbtns') || (h.parentElement && h.parentElement.querySelector(':scope > .colbtns'))) return;
      var key = tab.id + '|' + (h.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 50);
      var sec = sectionItems(h, tab);
      if (!sec.items.length) return;
      var btn = h.querySelector(':scope > .lcc-sec-btn');
      if (!btn) {
        btn = secBtn(); h.appendChild(btn);
        h.classList.add('lcc-sec-head');
        h.addEventListener('click', function (e) {
          if (e.target.closest('select,input,a,label,.colbtns') || (e.target.closest('button') && !e.target.closest('.lcc-sec-btn'))) return;
          state[key] = !state[key];
          scan();
        });
      }
      var on = !!state[key];
      h.classList.toggle('lcc-collapsed', on);
      if (sec.box) { sec.box.classList.add('lcc-sec-card'); sec.box.classList.toggle('lcc-sec-card-closed', on); }
      sec.items.forEach(function (el) { el.classList.toggle('lcc-hide', on); });
    });
  }

  /* ---------------- auto column widths ---------------- */
  var TNUM_RE = /^[▲▼+\-−]?\s*₹?\s*[\d][\d,]*(\.\d+)?\s*%?$|^[—–-]$/;
  function sizeTable(t) {
    var head = t.tHead && t.tHead.rows.length ? t.tHead.rows[t.tHead.rows.length - 1] : null;
    if (!head || !t.tBodies.length) return;
    var rows = [];
    each(t.tBodies, function (b) { each(b.rows, function (r) { rows.push(r); }); });
    if (t.tFoot) each(t.tFoot.rows, function (r) { rows.push(r); });
    var n = head.cells.length;
    var colspan = false; each(head.cells, function (c) { if (c.colSpan > 1) colspan = true; });
    if (!rows.length || !n || colspan) return;
    var sig = n + '|' + rows.length + '|' + rows[0].textContent.length + '|' + rows[rows.length - 1].textContent.length;
    if (t.getAttribute('data-lcc-sig') === sig) return;

    var maxLen = [], num = [], filled = [];
    for (var i = 0; i < n; i++) { maxLen[i] = 0; num[i] = 0; filled[i] = 0; }
    rows.slice(0, 120).forEach(function (r) {
      if (r.cells.length !== n) return;
      for (var i = 0; i < n; i++) {
        var txt = r.cells[i].textContent.replace(/\s+/g, ' ').trim();
        if (!txt) continue;
        filled[i]++; if (TNUM_RE.test(txt)) num[i]++;
        if (txt.length > maxLen[i]) maxLen[i] = txt.length;
      }
    });
    var total = 0, kinds = [];
    for (var j = 0; j < n; j++) {
      var th = head.cells[j];
      var words = (th.textContent || '').trim().split(/\s+/);
      var hw = words.reduce(function (m, w) { return Math.max(m, w.length); }, 0);
      var isNum = filled[j] > 0 && num[j] / filled[j] >= 0.7;
      var w, kind;
      if (isNum) { w = Math.max(hw * 8.2, maxLen[j] * 8.6) + 24; kind = 'lcc-num'; }
      else {
        var cap = j === 0 ? 40 : 30, eff = Math.min(maxLen[j], cap);
        w = Math.max(hw * 8.2, eff * 7.3) + 24;
        kind = maxLen[j] > cap ? 'lcc-wrap' : 'lcc-txt';
      }
      w = Math.round(Math.max(w, 56));
      th.style.setProperty('min-width', w + 'px', 'important');
      th.style.setProperty('width', w + 'px', 'important');
      th.classList.remove('lcc-num', 'lcc-txt', 'lcc-wrap'); th.classList.add('lcc-col', kind);
      kinds[j] = kind; total += w;
    }
    rows.forEach(function (r) {
      if (r.cells.length !== n) return;
      for (var i = 0; i < n; i++) {
        var c = r.cells[i];
        c.classList.remove('lcc-num', 'lcc-txt', 'lcc-wrap');
        c.classList.add(kinds[i]);
        if (i === 0) c.classList.add('lcc-first');
      }
    });
    t.classList.add('lcc-sized');
    t.style.setProperty('min-width', total + 'px', 'important');
    t.style.setProperty('width', '100%', 'important');
    t.setAttribute('data-lcc-sig', sig);
  }

  /* ---------------- A4 landscape print ---------------- */
  var printScope = null, printSaved = null;
  function activeTabId() {
    var id = 'tabv1';
    each(document.querySelectorAll(TABS), function (t) { if (getComputedStyle(t).display !== 'none') id = t.id; });
    return id;
  }
  function preparePrint() {
    if (printSaved) return;
    var root = document.documentElement;
    var modalOpen = document.querySelector('.ovl.on');
    var scope = printScope || (modalOpen ? 'modal' : activeTabId());
    printSaved = { hidden: [], tables: [], head: null };
    each(document.querySelectorAll('.lcc-hide'), function (el) { printSaved.hidden.push(el); el.classList.remove('lcc-hide'); });
    each(document.querySelectorAll('table.lcc-sized'), function (t) {
      var ths = [];
      if (t.tHead) each(t.tHead.querySelectorAll('th'), function (th) { ths.push([th, th.style.minWidth, th.style.width]); th.style.removeProperty('min-width'); th.style.removeProperty('width'); });
      printSaved.tables.push([t, ths]);
      t.style.removeProperty('min-width');
    });
    var title = '';
    if (scope === 'modal') { var mt = document.querySelector('.ovl.on .m-hd'); title = mt ? mt.textContent.replace(/\s+/g, ' ').trim() : 'Report'; }
    else { var on = document.querySelector('.tabbar .tbtn.on'); title = on ? on.textContent.replace(/\s+/g, ' ').trim() : 'Report'; }
    var head = document.createElement('div');
    head.id = 'lccPrintHead';
    var now = new Date();
    head.innerHTML = '<b></b><span></span>';
    head.querySelector('b').textContent = title.slice(0, 140);
    head.querySelector('span').textContent = 'LIFE Clinics · Printed ' + now.toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    document.body.insertBefore(head, document.body.firstChild);
    printSaved.head = head;
    root.classList.add('lcc-print');
    root.setAttribute('data-lcc-scope', scope);
  }
  function restorePrint() {
    if (!printSaved) return;
    var root = document.documentElement;
    root.classList.remove('lcc-print'); root.removeAttribute('data-lcc-scope');
    printSaved.hidden.forEach(function (el) { el.classList.add('lcc-hide'); });
    printSaved.tables.forEach(function (x) { x[0].removeAttribute('data-lcc-sig'); });
    if (printSaved.head) printSaved.head.remove();
    printSaved = null; printScope = null;
    scan();
  }
  window.addEventListener('beforeprint', preparePrint);
  window.addEventListener('afterprint', function () { setTimeout(restorePrint, 50); });
  window.addEventListener('click', function (e) {
    var btn = e.target.closest && e.target.closest('button,a,.life-cc-print-btn');
    if (!btn || btn.closest('#lccZoom,#lccNav')) return;

    /*
     * IMPORTANT: Cluster Report has its own isolated iframe printer.
     * Do not let this old global capture-phase handler call window.print()
     * for the Cluster Print / PDF button. Window capture runs before
     * document capture, so this exclusion must be here.
     */
    if (btn.classList.contains('life-cluster-print') || btn.closest('#tabv5')) return;

    var txt = (btn.textContent || '').replace(/\s+/g, ' ').trim();
    if (!btn.classList.contains('life-cc-print-btn') && !/^(🖨\uFE0F?\s*)?print(\s*\/\s*pdf)?$/i.test(txt)) return;
    e.preventDefault(); e.stopImmediatePropagation();
    printScope = btn.closest('.ovl') ? 'modal' : activeTabId();
    preparePrint();
    setTimeout(function () {
      window.print();
      setTimeout(function () { if (!window.matchMedia || !window.matchMedia('print').matches) restorePrint(); }, 800);
    }, 60);
  }, true);

  /* ---------------- scan loop ---------------- */
  function scan() {
    if (printSaved) return;
    buildNav();
    each(document.querySelectorAll(TABS), function (tab) {
      groupCards(tab);
      sections(tab);
    });
    each(document.querySelectorAll('#tabv1 table,#tabv2 table,#tabv3 table,#tabv4 table,.ovl table'), sizeTable);
  }
  var timer = null;
  function schedule() { clearTimeout(timer); timer = setTimeout(scan, 140); }
  function init() {
    buildZoom();
    scan();
    new MutationObserver(schedule).observe(document.body, { childList: true, subtree: true });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();

/* =====================================================================
   TODAY'S CC - WALK-IN APMTS PANEL ONLY  (append at END of Scripting)
   Title · full-body gender icons · serial no. + colour · visit number
   ===================================================================== */
(function () {
  if (window.__lccApPanel) return;
  window.__lccApPanel = true;

  var NEW_TITLE = "\uD83D\uDEB6 Today's CC - Walk-in Apmts";
  var COLORS = ['#1E7F3C', '#1257A8', '#C2410C', '#7B1FA2', '#00796B', '#B8860B', '#AD1457', '#3949AB', '#2E7D32', '#6D4C41'];
  var MALE = /👨|🧑|👦|🧔|👱‍♂️|👱|👴|🙎‍♂️|👨‍🦱|👨‍🦰/g;
  var FEMALE = /👩|👧|👱‍♀️|👵|🙎‍♀️|👩‍🦱|👩‍🦰/g;
  var visitCache = {};          // key: name|branch -> visit number
  var loading = false, loadedDay = '';

  function pad(n) { return n < 10 ? '0' + n : '' + n; }
  function today() { var d = new Date(); return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
  function ord(n) { var s = ['th', 'st', 'nd', 'rd'], v = n % 100; return n + (s[(v - 20) % 10] || s[v] || s[0]); }
  function norm(t) { return (t || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }

  function findPanel() {
    var found = null;
    Array.prototype.forEach.call(document.querySelectorAll('.ep'), function (ep) {
      var h = ep.querySelector('.ep-hd h4');
      if (h && (/today'?s appointments/i.test(h.textContent) || /walk-in apmts/i.test(h.textContent))) found = ep;
    });
    return found;
  }

  function setTitle(ep) {
    var h = ep.querySelector('.ep-hd h4');
    if (!h || h.textContent.indexOf("Walk-in Apmts") >= 0) return;
    var small = h.querySelector('small');
    Array.prototype.slice.call(h.childNodes).forEach(function (n) { if (n !== small) h.removeChild(n); });
    h.insertBefore(document.createTextNode(NEW_TITLE), small || null);
  }

  function swapGender(card) {
    var line = card.querySelector('.today-appt-client');
    if (!line) return;
    var w = document.createTreeWalker(line, NodeFilter.SHOW_TEXT, null), n;
    while ((n = w.nextNode())) {
      var v = n.nodeValue, nv = v.replace(FEMALE, '\uD83E\uDDCD\u200D\u2640\uFE0F').replace(MALE, '\uD83E\uDDCD\u200D\u2642\uFE0F');
      if (nv !== v) n.nodeValue = nv;
    }
  }

  function cardKey(card) {
    var line = card.querySelector('.today-appt-client');
    var name = line ? (line.firstChild && line.firstChild.nodeType === 3 ? line.firstChild.nodeValue : line.textContent.split('·')[0]) : '';
    var branch = '';
    Array.prototype.forEach.call(card.querySelectorAll('.today-appt-meta'), function (m) { if (!branch && /🏥|🏢/.test(m.textContent)) branch = m.textContent; });
    if (!branch) { var m0 = card.querySelector('.today-appt-meta'); branch = m0 ? m0.textContent : ''; }
    return norm(name.split('·')[0]) + '|' + norm(branch);
  }

  function decorate(ep) {
    var cards = ep.querySelectorAll('.today-appt-card');
    Array.prototype.forEach.call(cards, function (card, i) {
      var color = COLORS[i % COLORS.length];
      card.style.setProperty('--ap', color);
      var top = card.querySelector('.today-appt-topline');
      if (!top) return;
      var sn = top.querySelector('.lcc-ap-sn');
      if (!sn) { sn = document.createElement('span'); sn.className = 'lcc-ap-sn'; top.insertBefore(sn, top.firstChild); }
      if (sn.textContent !== String(i + 1)) sn.textContent = i + 1;
      swapGender(card);

      var key = cardKey(card), vb = top.querySelector('.lcc-ap-visit');
      if (!vb) { vb = document.createElement('span'); vb.className = 'lcc-ap-visit loading'; vb.textContent = '…'; top.appendChild(vb); }
      if (visitCache[key]) {
        var n = visitCache[key], label = ord(n) + ' Visit';
        if (vb.textContent !== label) { vb.textContent = label; vb.className = 'lcc-ap-visit'; vb.setAttribute('data-n', Math.min(n, 4)); }
      } else if (loadedDay === today()) {
        vb.remove();
      }
    });
    if (cards.length && loadedDay !== today()) loadVisits();
  }

  function api(doctype, fields, filters, limit) {
    var url = '/api/resource/' + encodeURIComponent(doctype) +
      '?fields=' + encodeURIComponent(JSON.stringify(fields)) +
      '&filters=' + encodeURIComponent(JSON.stringify(filters)) +
      '&limit_page_length=' + (limit || 1000);
    return fetch(url, { credentials: 'same-origin', headers: { Accept: 'application/json' } })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then(function (j) { return j.data || []; });
  }

  /* Visit no. = earlier walk-ins of the same mobile number (before today) + 1 */
  function loadVisits() {
    if (loading) return;
    loading = true;
    var d = today();
    api('Lead', ['name', 'lead_name', 'first_name', 'branch', 'lead_assign_to_branch', 'mobile_no'],
      [['custom_appointment_date_and_time', 'between', [d + ' 00:00:00', d + ' 23:59:59']]], 1000)
      .then(function (todays) {
        var mobiles = [];
        todays.forEach(function (l) { if (l.mobile_no && mobiles.indexOf(l.mobile_no) < 0) mobiles.push(l.mobile_no); });
        if (!mobiles.length) return [todays, []];
        return api('Lead', ['mobile_no'], [
          ['mobile_no', 'in', mobiles],
          ['custom_appointment_date_and_time', '<', d + ' 00:00:00'],
          ['custom_visit_status', 'not in', ['', 'Not Visited', 'No Show', 'Cancelled']]
        ], 5000).then(function (prev) { return [todays, prev]; });
      })
      .then(function (res) {
        var prevCount = {};
        res[1].forEach(function (p) { prevCount[p.mobile_no] = (prevCount[p.mobile_no] || 0) + 1; });
        res[0].forEach(function (l) {
          var n = (prevCount[l.mobile_no] || 0) + 1, nm = norm(l.lead_name || l.first_name);
          [l.branch, l.lead_assign_to_branch].forEach(function (b) { if (b) visitCache[nm + '|' + norm(b)] = n; });
        });
        loadedDay = d;
      })
      .catch(function () { loadedDay = d; })
      .then(function () { loading = false; run(); });
  }

  /* branch keys: card text may include emoji/extra words, so match loosely */
  var baseDecorate = decorate;
  decorate = function (ep) {
    Array.prototype.forEach.call(ep.querySelectorAll('.today-appt-card'), function (card) {
      var k = cardKey(card);
      if (visitCache[k]) return;
      var parts = k.split('|');
      Object.keys(visitCache).forEach(function (ck) {
        var c = ck.split('|');
        if (c[0] === parts[0] && c[1] && parts[1].indexOf(c[1]) >= 0) visitCache[k] = visitCache[ck];
      });
    });
    baseDecorate(ep);
  };

  var busy = false;
  function run() {
    if (busy) return;
    var ep = findPanel();
    if (!ep) return;
    busy = true;
    ep.classList.add('lcc-apx');
    setTitle(ep);
    decorate(ep);
    busy = false;
  }

  var t = null;
  new MutationObserver(function () { clearTimeout(t); t = setTimeout(run, 150); })
    .observe(document.body, { childList: true, subtree: true });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run); else run();
})();

/* ================================================================
   LIFE TODAY APMTS — CC AGENT MULTI SELECT FILTER V2
   Multiple Selection + All Agents + Clear + Apply
   ================================================================ */

(function () {

  if (window.__lccCCMultiFilterV2) return;
  window.__lccCCMultiFilterV2 = true;

  var appliedAgents = [];
  var pendingAgents = [];
  var filterOpen = false;


  function clean(v) {
    return (v || '').replace(/\s+/g, ' ').trim();
  }


  /* ================================================================
     FIND PANEL
     ================================================================ */

  function getPanel() {

    var panels = document.querySelectorAll('.ep');

    for (var i = 0; i < panels.length; i++) {

      var h = panels[i].querySelector('.ep-hd h4');

      if (
        h &&
        (
          /walk-in apmts/i.test(h.textContent) ||
          /today'?s appointments/i.test(h.textContent)
        )
      ) {
        return panels[i];
      }
    }

    return null;
  }


  /* ================================================================
     GET CC AGENT NAME FROM CARD
     ================================================================ */

  function getCCName(card) {

    var meta =
      card.querySelectorAll('.today-appt-meta');

    for (var i = 0; i < meta.length; i++) {

      var txt = clean(meta[i].textContent);

      if (/\bCC\s*:/i.test(txt)) {

        return clean(
          txt
            .replace(/^.*?CC\s*:\s*/i, '')
            .replace(/^[🎧\s]+/, '')
        );
      }
    }

    return '';
  }


  /* ================================================================
     GET ALL UNIQUE AGENTS
     ================================================================ */

  function getAgents(panel) {

    var cards =
      panel.querySelectorAll('.today-appt-card');

    var agents = [];

    Array.prototype.forEach.call(
      cards,
      function (card) {

        var name = getCCName(card);

        if (
          name &&
          name !== '—' &&
          name !== '-' &&
          agents.indexOf(name) === -1
        ) {
          agents.push(name);
        }
      }
    );

    agents.sort(function (a, b) {
      return a.localeCompare(b);
    });

    return agents;
  }


  /* ================================================================
     APPLY FILTER TO CARDS
     ================================================================ */

  function applyFilter(panel) {

    var cards =
      panel.querySelectorAll('.today-appt-card');

    Array.prototype.forEach.call(
      cards,
      function (card) {

        var cc = getCCName(card);

        var show =
          appliedAgents.length === 0 ||
          appliedAgents.indexOf(cc) !== -1;

        card.style.display =
          show ? '' : 'none';
      }
    );

    updateButton(panel);
  }


  /* ================================================================
     UPDATE MAIN BUTTON
     ================================================================ */

  function updateButton(panel) {

    var btn =
      panel.querySelector('.lcc-cc-filter-btn');

    if (!btn) return;

    var text =
      btn.querySelector('.lcc-filter-text');

    if (!text) return;


    if (appliedAgents.length === 0) {

      text.textContent = 'All Agents';

      btn.classList.remove('active');

    } else if (appliedAgents.length === 1) {

      text.textContent =
        appliedAgents[0];

      btn.classList.add('active');

    } else {

      text.textContent =
        appliedAgents.length +
        ' Agents Selected';

      btn.classList.add('active');
    }
  }


  /* ================================================================
     BUILD AGENT CHECKBOX LIST
     ================================================================ */

  function buildOptions(panel) {

    var list =
      panel.querySelector(
        '.lcc-cc-filter-options'
      );

    if (!list) return;

    var agents =
      getAgents(panel);

    list.innerHTML = '';


    /* ============================================================
       ALL AGENTS OPTION
       ============================================================ */

    var allRow =
      document.createElement('label');

    allRow.className =
      'lcc-filter-option lcc-filter-all-row';


    var allCheck =
      document.createElement('input');

    allCheck.type = 'checkbox';


    /*
       All Agents is checked when
       no individual filter is selected
    */

    allCheck.checked =
      pendingAgents.length === 0;


    var allTick =
      document.createElement('span');

    allTick.className =
      'lcc-filter-check';


    var allLabel =
      document.createElement('span');

    allLabel.className =
      'lcc-filter-name';

    allLabel.textContent =
      'All Agents';


    allCheck.addEventListener(
      'change',
      function () {

        /*
           ALL AGENTS = empty filter
           Empty means show everybody
        */

        pendingAgents = [];

        buildOptions(panel);
      }
    );


    allRow.appendChild(allCheck);
    allRow.appendChild(allTick);
    allRow.appendChild(allLabel);

    list.appendChild(allRow);


    /* DIVIDER */

    var divider =
      document.createElement('div');

    divider.className =
      'lcc-agent-divider';

    list.appendChild(divider);


    /* ============================================================
       INDIVIDUAL AGENTS
       ============================================================ */

    agents.forEach(function (name) {

      var row =
        document.createElement('label');

      row.className =
        'lcc-filter-option';


      var check =
        document.createElement('input');

      check.type = 'checkbox';
      check.value = name;

      check.checked =
        pendingAgents.indexOf(name) !== -1;


      var tick =
        document.createElement('span');

      tick.className =
        'lcc-filter-check';


      var label =
        document.createElement('span');

      label.className =
        'lcc-filter-name';

      label.textContent = name;


      check.addEventListener(
        'change',
        function () {

          if (this.checked) {

            if (
              pendingAgents.indexOf(name) === -1
            ) {
              pendingAgents.push(name);
            }

          } else {

            pendingAgents =
              pendingAgents.filter(
                function (v) {
                  return v !== name;
                }
              );
          }

          /*
             IMPORTANT:
             DO NOT FILTER YET.
             Wait for APPLY button.
          */

          buildOptions(panel);
        }
      );


      row.appendChild(check);
      row.appendChild(tick);
      row.appendChild(label);

      list.appendChild(row);
    });
  }


  /* ================================================================
     CREATE FILTER
     ================================================================ */

  function createFilter(panel) {

    /*
       Remove OLD filter if it exists
       but is not V2.
    */

    var old =
      panel.querySelector(
        '.lcc-cc-filter-wrap'
      );

    if (old) {

      if (
        old.getAttribute('data-filter-version') === '2'
      ) {
        return;
      }

      old.remove();
    }


    var body =
      panel.querySelector('.ep-bd');

    if (!body) return;


    var wrap =
      document.createElement('div');

    wrap.className =
      'lcc-cc-filter-wrap';

    wrap.setAttribute(
      'data-filter-version',
      '2'
    );


    wrap.innerHTML =

      '<div class="lcc-filter-label">' +

        '🎧 FILTER BY CC EMPLOYEE' +

      '</div>' +


      '<div class="lcc-filter-control">' +


        '<button type="button" ' +
        'class="lcc-cc-filter-btn">' +

          '<span class="lcc-filter-text">' +
            'All Agents' +
          '</span>' +

          '<span class="lcc-filter-arrow">' +
            '⌄' +
          '</span>' +

        '</button>' +


        '<div class="lcc-cc-filter-dropdown">' +


          '<div class="lcc-cc-filter-options">' +
          '</div>' +


          '<div class="lcc-filter-footer">' +

            '<button type="button" ' +
            'class="lcc-filter-clear-v2">' +
              'Clear' +
            '</button>' +

            '<button type="button" ' +
            'class="lcc-filter-apply">' +
              'Apply' +
            '</button>' +

          '</div>' +


        '</div>' +

      '</div>';


    var summary =
      body.querySelector(
        '.today-appt-summary'
      );


    if (summary) {

      body.insertBefore(
        wrap,
        summary
      );

    } else {

      body.insertBefore(
        wrap,
        body.firstChild
      );
    }


    var button =
      wrap.querySelector(
        '.lcc-cc-filter-btn'
      );

    var dropdown =
      wrap.querySelector(
        '.lcc-cc-filter-dropdown'
      );


    /* ============================================================
       OPEN DROPDOWN
       ============================================================ */

    button.addEventListener(
      'click',
      function (e) {

        e.stopPropagation();

        filterOpen =
          !filterOpen;


        if (filterOpen) {

          /*
             Start with currently
             applied selection.
          */

          pendingAgents =
            appliedAgents.slice();

          buildOptions(panel);

          dropdown.classList.add('show');

          button.classList.add('open');

        } else {

          dropdown.classList.remove('show');

          button.classList.remove('open');
        }
      }
    );


    /* ============================================================
       CLEAR
       ============================================================ */

    wrap
      .querySelector(
        '.lcc-filter-clear-v2'
      )
      .addEventListener(
        'click',
        function (e) {

          e.stopPropagation();

          /*
             Clear means ALL AGENTS
          */

          pendingAgents = [];

          buildOptions(panel);
        }
      );


    /* ============================================================
       APPLY
       ============================================================ */

    wrap
      .querySelector(
        '.lcc-filter-apply'
      )
      .addEventListener(
        'click',
        function (e) {

          e.stopPropagation();


          /*
             COPY PENDING SELECTION
             INTO ACTIVE FILTER
          */

          appliedAgents =
            pendingAgents.slice();


          /*
             NOW FILTER
          */

          applyFilter(panel);


          /*
             CLOSE DROPDOWN
          */

          dropdown.classList.remove(
            'show'
          );

          button.classList.remove(
            'open'
          );

          filterOpen = false;
        }
      );


    /*
       Don't close when clicking
       inside dropdown
    */

    dropdown.addEventListener(
      'click',
      function (e) {
        e.stopPropagation();
      }
    );


    buildOptions(panel);
    applyFilter(panel);
  }


  /* ================================================================
     CLICK OUTSIDE = CLOSE WITHOUT APPLYING
     ================================================================ */

  document.addEventListener(
    'click',
    function () {

      var panel = getPanel();

      if (!panel) return;

      var dropdown =
        panel.querySelector(
          '.lcc-cc-filter-dropdown'
        );

      var button =
        panel.querySelector(
          '.lcc-cc-filter-btn'
        );

      if (dropdown) {
        dropdown.classList.remove('show');
      }

      if (button) {
        button.classList.remove('open');
      }

      filterOpen = false;
    }
  );


  /* ================================================================
     RUN
     ================================================================ */

  function runFilter() {

    var panel = getPanel();

    if (!panel) return;

    createFilter(panel);

    /*
       Maintain applied selection
       when appointment cards refresh.
    */

    applyFilter(panel);
  }


  var timer = null;

  new MutationObserver(function () {

    clearTimeout(timer);

    timer =
      setTimeout(
        runFilter,
        300
      );

  }).observe(
    document.body,
    {
      childList: true,
      subtree: true
    }
  );


  if (
    document.readyState === 'loading'
  ) {

    document.addEventListener(
      'DOMContentLoaded',
      runFilter
    );

  } else {

    runFilter();
  }

})();

function getRole(designation) {

  var d =
    clean(designation).toLowerCase();


  /* ============================================================
     ACM — CHECK BEFORE CM
     ============================================================ */

  if (
    d === 'acm' ||
    /assistant centre manager/.test(d) ||
    /assistant center manager/.test(d) ||
    /asst centre manager/.test(d) ||
    /asst center manager/.test(d)
  ) {
    return 'ACM';
  }


  /* ============================================================
     TCM — CHECK BEFORE CM
     ============================================================ */

  if (
    d === 'tcm' ||
    /trainee centre manager/.test(d) ||
    /trainee center manager/.test(d) ||
    /training centre manager/.test(d) ||
    /training center manager/.test(d)
  ) {
    return 'TCM';
  }


  /* ============================================================
     CM
     ============================================================ */

  if (
    d === 'cm' ||
    d === 'centre manager' ||
    d === 'center manager' ||
    d === 'clinic manager' ||
    d === 'branch manager'
  ) {
    return 'CM';
  }


  /* ============================================================
     DOCTOR
     ============================================================ */

  if (
    d === 'doctor' ||
    d === 'dr' ||
    /^dr\b/.test(d) ||
    /doctor/.test(d) ||
    /medical officer/.test(d) ||
    /physician/.test(d) ||
    /dermatologist/.test(d) ||
    /consultant doctor/.test(d) ||
    /medical consultant/.test(d)
  ) {
    return 'DR';
  }


  return '';
}

/* =====================================================================
   LIFE TODAY APMTS — BRANCH LIVE STAFF FINAL V4
   CM + ACM + TCM + DOCTOR
   SAME BRANCH + TODAY'S EMPLOYEE CHECKIN

   IMPORTANT:
   PASTE THIS COMPLETE BLOCK AT THE VERY BOTTOM OF SCRIPTING.
   DO NOT CHANGE THE WORKING "ALL AGENTS" FILTER.
   ===================================================================== */

(function () {

  if (window.__lifeTodayBranchStaffV4) return;
  window.__lifeTodayBranchStaffV4 = true;

  var TEAM_CACHE = {};
  var CHECKIN_CACHE = {};
  var loading = false;

  var DATA_REFRESH_MS = 60000;


  /* =========================================================
     BASIC HELPERS
     ========================================================= */

  function clean(value) {
    return String(value || '')
      .replace(/\s+/g, ' ')
      .trim();
  }


  function norm(value) {
    return clean(value)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '');
  }


  function pad(value) {
    return Number(value) < 10
      ? '0' + Number(value)
      : String(value);
  }


  function todayISO() {

    var d = new Date();

    return (
      d.getFullYear() +
      '-' +
      pad(d.getMonth() + 1) +
      '-' +
      pad(d.getDate())
    );
  }


  /* =========================================================
     FIND TODAY'S APPOINTMENT PANEL
     ========================================================= */

  function findPanel() {

    var panels =
      document.querySelectorAll('.ep');

    for (var i = 0; i < panels.length; i++) {

      var heading =
        panels[i].querySelector('.ep-hd h4');

      if (
        heading &&
        (
          /walk-in apmts/i.test(
            heading.textContent
          ) ||
          /today'?s appointments/i.test(
            heading.textContent
          )
        )
      ) {
        return panels[i];
      }
    }

    return null;
  }


  /* =========================================================
     API
     ========================================================= */

  function api(doctype, fields, filters, limit) {

    var url =
      '/api/resource/' +
      encodeURIComponent(doctype) +
      '?fields=' +
      encodeURIComponent(
        JSON.stringify(fields)
      ) +
      '&filters=' +
      encodeURIComponent(
        JSON.stringify(filters || [])
      ) +
      '&limit_page_length=' +
      String(limit || 1000);


    return fetch(
      url,
      {
        credentials: 'same-origin',
        headers: {
          Accept: 'application/json'
        }
      }
    )
    .then(function (response) {

      if (!response.ok) {

        throw new Error(
          doctype +
          ' API Error ' +
          response.status
        );
      }

      return response.json();
    })
    .then(function (result) {

      return result.data || [];

    });
  }


  /* =========================================================
     GET BRANCH FROM APPOINTMENT CARD
     ========================================================= */

  function getCardBranch(card) {

    var meta =
      card.querySelectorAll(
        '.today-appt-meta'
      );


    for (var i = 0; i < meta.length; i++) {

      var text =
        clean(meta[i].textContent);


      /*
         Your cards use hospital/office
         icon for Branch.
      */

      if (
        text.indexOf('🏥') !== -1 ||
        text.indexOf('🏢') !== -1
      ) {

        return clean(
          text
            .replace(/🏥/g, '')
            .replace(/🏢/g, '')
        );
      }
    }


    /*
       FALLBACK:
       Look for Branch:
    */

    for (var x = 0; x < meta.length; x++) {

      var fallback =
        clean(meta[x].textContent);

      if (/branch\s*:/i.test(fallback)) {

        return clean(
          fallback.replace(
            /^.*?branch\s*:\s*/i,
            ''
          )
        );
      }
    }


    return '';
  }


  /* =========================================================
     DESIGNATION → ROLE

     IMPORTANT:
     ACM + TCM checked BEFORE CM.
     This prevents "Assistant Centre Manager"
     being detected as CM.
     ========================================================= */

  function getRole(designation) {

    var d =
      clean(designation)
        .toLowerCase();


    /* ---------------- ACM ---------------- */

    if (
      d === 'acm' ||
      /assistant centre manager/.test(d) ||
      /assistant center manager/.test(d) ||
      /asst centre manager/.test(d) ||
      /asst center manager/.test(d) ||
      /assistant clinic manager/.test(d)
    ) {
      return 'ACM';
    }


    /* ---------------- TCM ---------------- */

    if (
      d === 'tcm' ||
      /trainee centre manager/.test(d) ||
      /trainee center manager/.test(d) ||
      /training centre manager/.test(d) ||
      /training center manager/.test(d)
    ) {
      return 'TCM';
    }


    /* ---------------- CM ---------------- */

    if (
      d === 'cm' ||
      d === 'centre manager' ||
      d === 'center manager' ||
      d === 'clinic manager' ||
      d === 'branch manager'
    ) {
      return 'CM';
    }


    /* ---------------- DOCTOR ---------------- */

    if (
      d === 'doctor' ||
      d === 'dr' ||
      /^dr\b/.test(d) ||
      /doctor/.test(d) ||
      /medical officer/.test(d) ||
      /physician/.test(d) ||
      /dermatologist/.test(d) ||
      /consultant doctor/.test(d) ||
      /medical consultant/.test(d)
    ) {
      return 'DR';
    }


    return '';
  }


  /* =========================================================
     LOAD ACTIVE EMPLOYEES
     ========================================================= */

  function loadEmployees() {

    return api(
      'Employee',

      [
        'name',
        'employee_name',
        'designation',
        'department',
        'branch',
        'status'
      ],

      [
        ['status', '=', 'Active']
      ],

      3000
    );
  }


  /* =========================================================
     LOAD TODAY'S EMPLOYEE CHECKINS
     ========================================================= */

  function loadCheckins() {

    var day =
      todayISO();


    return api(
      'Employee Checkin',

      [
        'name',
        'employee',
        'employee_name',
        'time',
        'log_type'
      ],

      [
        [
          'time',
          'between',
          [
            day + ' 00:00:00',
            day + ' 23:59:59'
          ]
        ]
      ],

      5000
    );
  }


  /* =========================================================
     BUILD LATEST CHECKIN STATUS
     ========================================================= */

  function buildCheckinCache(rows) {

    CHECKIN_CACHE = {};


    (rows || []).forEach(
      function (row) {

        if (!row.employee) return;


        var current =
          CHECKIN_CACHE[row.employee];


        if (
          !current ||
          String(row.time) >
          String(current.time)
        ) {

          CHECKIN_CACHE[row.employee] = {

            time:
              row.time || '',

            type:
              clean(row.log_type)
                .toUpperCase()
          };
        }
      }
    );
  }


  /* =========================================================
     EMPLOYEE AVAILABLE?
     ========================================================= */

  function employeeAvailable(employeeId) {

    var punch =
      CHECKIN_CACHE[employeeId];


    if (!punch) {
      return false;
    }


    /*
       Latest punch IN  = GREEN
       Latest punch OUT = RED
    */

    return punch.type === 'IN';
  }


  /* =========================================================
     BUILD BRANCH TEAM CACHE
     ========================================================= */

  function buildTeamCache(employees) {

    TEAM_CACHE = {};


    (employees || []).forEach(
      function (employee) {

        var designation =
          clean(
            employee.designation ||
            employee.department
          );


        var role =
          getRole(designation);


        /*
           We only need:
           CM / ACM / TCM / Doctor
        */

        if (!role) return;


        var branch =
          clean(employee.branch);


        if (!branch) return;


        var key =
          norm(branch);


        if (!TEAM_CACHE[key]) {

          TEAM_CACHE[key] = {

            branch: branch,

            CM: [],
            ACM: [],
            TCM: [],
            DR: []
          };
        }


        TEAM_CACHE[key][role].push({

          employee:
            employee.name,

          name:
            clean(
              employee.employee_name ||
              employee.name
            ),

          designation:
            designation,

          available:
            employeeAvailable(
              employee.name
            )
        });
      }
    );
  }


  /* =========================================================
     FIND TEAM FOR CARD BRANCH
     ========================================================= */

  function findBranchTeam(branch) {

    var key =
      norm(branch);


    if (!key) return null;


    /*
       EXACT MATCH
    */

    if (TEAM_CACHE[key]) {
      return TEAM_CACHE[key];
    }


    /*
       LOOSE MATCH
       Example:
       "Kukatpally Branch"
       vs
       "Kukatpally"
    */

    var keys =
      Object.keys(TEAM_CACHE);


    for (var i = 0; i < keys.length; i++) {

      if (
        key.indexOf(keys[i]) !== -1 ||
        keys[i].indexOf(key) !== -1
      ) {

        return TEAM_CACHE[keys[i]];
      }
    }


    return null;
  }


  /* =========================================================
     CREATE ONE PERSON DISPLAY
     ========================================================= */

  function createPerson(role, person) {

    var item =
      document.createElement('span');


    item.className =
      'life-v4-staff-person ' +
      (
        person.available
          ? 'life-v4-present'
          : 'life-v4-absent'
      );


    /* DOT */

    var dot =
      document.createElement('span');

    dot.className =
      'life-v4-staff-dot';


    /* ROLE */

    var roleText =
      document.createElement('b');

    roleText.textContent =
      role === 'DR'
        ? 'Dr'
        : role;


    /* NAME */

    var name =
      document.createElement('span');

    name.textContent =
      ': ' + person.name;


    item.appendChild(dot);
    item.appendChild(roleText);
    item.appendChild(name);


    /*
       MOUSE HOVER INFORMATION
    */

    var punch =
      CHECKIN_CACHE[
        person.employee
      ];


    if (punch) {

      item.title =
        (
          person.available
            ? 'Available'
            : 'Not Available'
        ) +
        ' | Last Punch: ' +
        punch.type +
        ' | ' +
        punch.time;

    } else {

      item.title =
        'No biometric/check-in found today';
    }


    return item;
  }


  /* =========================================================
     ADD ROLE PEOPLE
     ========================================================= */

  function addRole(
    row,
    role,
    people
  ) {

    if (
      !people ||
      !people.length
    ) {
      return;
    }


    /*
       GREEN first,
       then RED.
    */

    people.sort(
      function (a, b) {

        if (
          a.available ===
          b.available
        ) {

          return a.name.localeCompare(
            b.name
          );
        }


        return a.available
          ? -1
          : 1;
      }
    );


    people.forEach(
      function (person) {

        row.appendChild(
          createPerson(
            role,
            person
          )
        );
      }
    );
  }


  /* =========================================================
     DECORATE ONE APPOINTMENT CARD
     ========================================================= */

  function decorateCard(card) {

    if (!card) return;


    var branch =
      getCardBranch(card);


    if (!branch) return;


    var team =
      findBranchTeam(branch);


    /*
       Remove previous staff row first.
    */

    var existing =
      card.querySelector(
        '.life-v4-branch-staff'
      );


    if (existing) {
      existing.remove();
    }


    /*
       If no matching employees,
       don't create blank row.
    */

    if (!team) {
      return;
    }


    var row =
      document.createElement('div');


    row.className =
      'life-v4-branch-staff';


    /*
       DISPLAY ORDER
       CM → ACM → TCM → DOCTOR
    */

    addRole(
      row,
      'CM',
      team.CM
    );


    addRole(
      row,
      'ACM',
      team.ACM
    );


    addRole(
      row,
      'TCM',
      team.TCM
    );


    addRole(
      row,
      'DR',
      team.DR
    );


    /*
       No matching role?
    */

    if (!row.children.length) {
      return;
    }


    /*
       Add under Treatment / Interest.
    */

    var interest =
      card.querySelector(
        '.today-appt-interest'
      );


    if (interest) {

      interest.insertAdjacentElement(
        'afterend',
        row
      );

    } else {

      card.appendChild(row);
    }
  }


  /* =========================================================
     DECORATE ALL CARDS
     ========================================================= */

  function decorateAllCards() {

    var panel =
      findPanel();


    if (!panel) return;


    var cards =
      panel.querySelectorAll(
        '.today-appt-card'
      );


    Array.prototype.forEach.call(
      cards,
      function (card) {

        decorateCard(card);

      }
    );
  }


  /* =========================================================
     LOAD TEAM DATA
     ========================================================= */

  function loadTeamData() {

    if (loading) return;


    loading = true;


    Promise.all([
      loadEmployees(),
      loadCheckins()
    ])

    .then(
      function (results) {

        var employees =
          results[0] || [];

        var checkins =
          results[1] || [];


        buildCheckinCache(
          checkins
        );


        buildTeamCache(
          employees
        );


        decorateAllCards();
      }
    )

    .catch(
      function (error) {

        console.error(
          'LIFE Branch Staff V4 Error:',
          error
        );
      }
    )

    .then(
      function () {

        loading = false;

      }
    );
  }


  /* =========================================================
     REPAIR STAFF ROWS AFTER APPOINTMENT CARDS RE-RENDER
     ========================================================= */

  function repairStaffRows() {

    var panel =
      findPanel();


    if (!panel) return;


    /*
       Data not loaded yet.
    */

    if (
      !Object.keys(
        TEAM_CACHE
      ).length
    ) {

      loadTeamData();
      return;
    }


    var cards =
      panel.querySelectorAll(
        '.today-appt-card'
      );


    Array.prototype.forEach.call(
      cards,
      function (card) {

        if (
          !card.querySelector(
            '.life-v4-branch-staff'
          )
        ) {

          decorateCard(card);
        }
      }
    );
  }


  /* =========================================================
     WATCH APPOINTMENT PANEL RE-RENDER
     ========================================================= */

  var observerTimer = null;


  var observer =
    new MutationObserver(
      function (mutations) {

        var relevant = false;


        for (
          var i = 0;
          i < mutations.length;
          i++
        ) {

          var added =
            mutations[i].addedNodes;


          for (
            var x = 0;
            x < added.length;
            x++
          ) {

            var node =
              added[x];


            if (
              !node ||
              node.nodeType !== 1
            ) {
              continue;
            }


            /*
               Ignore our own staff rows.
               Prevent observer loop.
            */

            if (
              node.classList &&
              node.classList.contains(
                'life-v4-branch-staff'
              )
            ) {
              continue;
            }


            if (
              node.classList &&
              node.classList.contains(
                'today-appt-card'
              )
            ) {

              relevant = true;
              break;
            }


            if (
              node.querySelector &&
              node.querySelector(
                '.today-appt-card'
              )
            ) {

              relevant = true;
              break;
            }
          }


          if (relevant) break;
        }


        if (!relevant) return;


        clearTimeout(
          observerTimer
        );


        observerTimer =
          setTimeout(
            repairStaffRows,
            400
          );
      }
    );


  observer.observe(
    document.body,
    {
      childList: true,
      subtree: true
    }
  );


  /* =========================================================
     SAFETY CHECK EVERY 3 SECONDS

     This does NOT call API every 3 sec.
     It only restores staff rows if cards were rebuilt.
     ========================================================= */

  setInterval(
    function () {

      repairStaffRows();

    },
    3000
  );


  /* =========================================================
     REFRESH BIOMETRIC DATA EVERY 60 SECONDS
     ========================================================= */

  setInterval(
    function () {

      if (findPanel()) {

        loadTeamData();

      }

    },
    DATA_REFRESH_MS
  );


