 const source=ALL_AGENT_RANKING_RECORDS.length?ALL_AGENT_RANKING_RECORDS:RECORDS;
 const scoped=[...new Map(source.filter(r=>r.dt>=from&&r.dt<=to&&r.agent).map(r=>[r.name||r.agent+'|'+r.dt+'|'+r.cat,r])).values()];
