  const booked=rows.filter(r=>r.cat===CATS[0]).length;
  const visits=rows.filter(r=>[CATS[0],CATS[1],CATS[7]].includes(r.cat)).length;
  const leads=received?Number(received.byOwner[String(agent).toLowerCase()]||0):null;
  const input=lifePremiumKpiInput(from,to,agent);
