  const bookingAchievement=valid?Math.min(100,booked/Number(input.bookingTarget)*100):null;
  const visitAchievement=valid?Math.min(100,visits/Number(input.visitTarget)*100):null;
  const pct=visits?booked/visits*100:null;
  const conversionWeight=visits<5?0:visits<10?.5:1;
  const score=valid?bookingAchievement*.35+visitAchievement*.25+(pct||0)*.20*conversionWeight+Number(input.handling)*.10+Number(input.followup)*.10:null;
