/* =========================================================
 * ALL 4 REPORT TABS — QUALITY → APPOINTMENT BOOKED %
 *
 * Formula:
 *     Appointments / Quality Leads × 100
 *
 * IMPORTANT:
 * - Clones the NORMAL Appointments card in each tab, so the
 *   new card has exactly the same theme/height/padding/borders.
 * - Recalculates after every date/branch/agent/search filter.
 * - Recreates itself safely if a report render replaces cards.
 * ========================================================= */
(function () {
  if (window.LIFE_QUALITY_APPT_CARD_V2) return;
  window.LIFE_QUALITY_APPT_CARD_V2 = true;

  const TAB_IDS = ["tabv1", "tabv2", "tabv3", "tabv4"];
  const CARD_CLASS = "life-quality-appointment-percent-card";
  const LABEL = "Quality → Appointment Booked %";

  let busy = false;
  let refreshTimer = null;

  function txt(v) {
    return String(v == null ? "" : v)
      .replace(/\s+/g, " ")
      .trim();
  }

  function numberFrom(v) {
    const n = Number(
      txt(v)
        .replace(/₹/g, "")
        .replace(/,/g, "")
        .replace(/%/g, "")
        .replace(/[^\d.-]/g, "")
    );
    return Number.isFinite(n) ? n : 0;
  }

  function cardLabel(card) {
    if (!card) return "";

    const candidates = [
      card.querySelector(".life-agent-card-label"),
      card.querySelector(".life-walking-card-label"),
      card.querySelector(".lcc-l"),
      card.querySelector(".kpi-label"),
      card.querySelector(".life-mkt-kpi-label"),
      card.querySelector(":scope > span")
    ].filter(Boolean);

    for (const el of candidates) {
      const value = txt(el.textContent);
      if (value) return value;
    }

    return "";
  }

  function cardValue(card) {
    if (!card) return 0;

    const candidates = [
      card.querySelector(".life-agent-card-value"),
      card.querySelector(".life-walking-card-value"),
      card.querySelector(".lcc-n"),
      card.querySelector(":scope > b"),
      card.querySelector(".num")
    ].filter(Boolean);

    for (const el of candidates) {
      const value = txt(el.textContent);
      if (value) return numberFrom(value);
    }

    return 0;
  }

  function cardsIn(tab) {
    if (!tab) return [];

    return [
      ...tab.querySelectorAll(
        ".life-agent-3line-card," +
        ".life-walking-3line-card," +
        ".life-cc-funnel-card," +
        ".life-mkt-kpi," +
        ".mkt-kpi," +
        ".kpi"
      )
    ].filter(card =>
      !card.classList.contains(CARD_CLASS)
    );
  }

  function findByLabels(tab, labels) {
    const wanted = new Set(
      labels.map(x => txt(x).toLowerCase())
    );

    return cardsIn(tab).find(card =>
      wanted.has(
        cardLabel(card).toLowerCase()
      )
    ) || null;
  }

  function findValueEl(card) {
    return (
      card.querySelector(".life-agent-card-value") ||
      card.querySelector(".life-walking-card-value") ||
      card.querySelector(".lcc-n") ||
      card.querySelector(":scope > b") ||
      card.querySelector(".num")
    );
  }

  function findLabelEls(card) {
    const preferred = [
      card.querySelector(".life-agent-card-label"),
      card.querySelector(".life-walking-card-label"),
      card.querySelector(".lcc-l"),
      card.querySelector(".kpi-label"),
      card.querySelector(".life-mkt-kpi-label")
    ].filter(Boolean);

    if (preferred.length) return preferred;

    const direct = card.querySelector(":scope > span");
    return direct ? [direct] : [];
  }

  function sanitizeClone(card) {
    if (!card) return;

    card.classList.add(CARD_CLASS);

    // New percentage card must not inherit click actions from Appointments.
    card.removeAttribute("onclick");
    card.removeAttribute("id");
    card.style.cursor = "";

    card.querySelectorAll("[id]").forEach(el =>
      el.removeAttribute("id")
    );

    card.querySelectorAll("[onclick]").forEach(el =>
      el.removeAttribute("onclick")
    );

    // Prevent the cloned card from carrying stale selected states.
    card.classList.remove(
      "selected",
      "active",
      "on"
    );
  }

  function makeNormalCard(appointmentCard) {
    const card = appointmentCard.cloneNode(true);
    sanitizeClone(card);

    const valueEl = findValueEl(card);
    if (valueEl) {
      valueEl.textContent = "0%";
    }

    const labelEls = findLabelEls(card);
    labelEls.forEach(el => {
      el.textContent = LABEL;
    });

    /*
     * If the cloned card did not expose a recognizable label node,
     * add one using the same common structure.
     */
    if (!labelEls.length) {
      const label = document.createElement("span");
      label.textContent = LABEL;
      label.className = "lcc-l";
      card.appendChild(label);
    }

    return card;
  }

  function setPercent(card, percent) {
    const valueEl = findValueEl(card);
    if (valueEl) {
      valueEl.textContent = `${percent}%`;
    }

    findLabelEls(card).forEach(el => {
      el.textContent = LABEL;
    });
  }

  function ensureCardForTab(tab) {
    if (!tab) return;

    const qualityCard = findByLabels(tab, [
      "Quality Leads"
    ]);

    const appointmentCard = findByLabels(tab, [
      "Appointments",
      "Appointment Leads",
      "Total Appointments",
      "Consultant Appointments"
    ]);

    /*
     * If the tab is not ready yet, don't leave a stale percentage.
     */
    if (!qualityCard || !appointmentCard) {
      return;
    }

    const quality = cardValue(qualityCard);
    const appointments = cardValue(appointmentCard);

    const percent =
      quality > 0
        ? Math.round((appointments / quality) * 100)
        : 0;

    let card = tab.querySelector("." + CARD_CLASS);

    /*
     * If a report rerender moved/rebuilt the source card grid,
     * rebuild our percentage card next to the CURRENT appointment card.
     */
    const correctParent = appointmentCard.parentElement;

    if (
      !card ||
      !card.isConnected ||
      card.parentElement !== correctParent
    ) {
      if (card && card.isConnected) card.remove();

      card = makeNormalCard(appointmentCard);

      appointmentCard.insertAdjacentElement(
        "afterend",
        card
      );
    }

    setPercent(card, percent);
  }

  function refreshAll() {
    if (busy) return;
    busy = true;

    try {
      TAB_IDS.forEach(id => {
        const tab = document.getElementById(id);
        if (tab) ensureCardForTab(tab);
      });
    } finally {
      busy = false;
    }
  }

  function queueRefresh(delay = 120) {
    clearTimeout(refreshTimer);
    refreshTimer = setTimeout(
      refreshAll,
      delay
    );
  }

  function installTabObserver(tab) {
    if (!tab || tab.dataset.lifeQualityApptObserver === "1") return;

    tab.dataset.lifeQualityApptObserver = "1";

    const observer = new MutationObserver(() => {
      if (busy) return;
      queueRefresh(100);
    });

    observer.observe(tab, {
      childList: true,
      subtree: true,
      characterData: true
    });
  }

  function installFilterHooks() {
    /*
     * Capture filter actions globally.
     * This does NOT replace existing filter handlers.
     * It only refreshes this percentage card after the normal
     * report/filter code finishes rendering.
     */
    document.addEventListener(
      "change",
      function (event) {
        const target = event.target;
        if (!target) return;

        if (
          target.matches(
            "input,select"
          )
        ) {
          queueRefresh(350);
          setTimeout(refreshAll, 900);
        }
      },
      true
    );

    document.addEventListener(
      "input",
      function (event) {
        const target = event.target;
        if (!target) return;

        if (
          target.matches(
            "input[type='search']," +
            "input[placeholder*='Search']," +
            "input[placeholder*='search']"
          )
        ) {
          queueRefresh(450);
        }
      },
      true
    );

    document.addEventListener(
      "click",
      function (event) {
        const button = event.target &&
          event.target.closest("button");

        if (!button) return;

        const label = txt(button.textContent).toLowerCase();

        if (
          /apply|today|yesterday|tomorrow|week|month|reset|refresh|search/.test(label)
        ) {
          queueRefresh(250);
          setTimeout(refreshAll, 850);
          setTimeout(refreshAll, 1600);
        }
      },
      true
    );
  }

  function start() {
    TAB_IDS.forEach(id => {
      installTabObserver(
        document.getElementById(id)
      );
    });

    installFilterHooks();

    refreshAll();

    /*
     * Safety for async report loads and slower secure API responses.
     */
    setTimeout(refreshAll, 500);
    setTimeout(refreshAll, 1200);
    /* PERFORMANCE: periodic 2.5s DOM scan removed; observers/filter hooks refresh this card. */

    window.LIFE_REFRESH_QUALITY_APPT_PERCENT =
      refreshAll;
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      start,
      { once: true }
    );
  } else {
    start();
  }
})();



