/* =========================================================
 * LAST 3 BUSINESS MONTHS COMPARISON
 * ---------------------------------------------------------
 * Appears directly below Branch Summary / CC Agent Summary.
 *
 * Modes:
 *   - Branch-wise
 *   - CC Agent-wise
 *
 * Each month:
 *   Lead Count
 *   Walk-ins
 *   Joined
 *   J/W Conv %
 *   Revenue
 *
 * Deficit:
 *   Latest business month - previous business month
 *   Lead Count / Walk-ins / Joined / Revenue
 *
 * Revenue source:
 *   exact Call Center package "With GST" amount for each period.
 * ========================================================= */

const LIFE_3M_COMPARE_CACHE = new Map();
const LIFE_3M_COMPARE_PROMISES = new Map();
let LIFE_3M_COMPARE_MODE = "branch";
let LIFE_3M_COMPARE_RENDER_TOKEN = 0;

/*
 * Optional custom comparison range.
 * Default = full last 3 business months (6th → 5th),
 * with current business month ending today.
 */
let LIFE_3M_FILTER_FROM = "";
let LIFE_3M_FILTER_TO = "";

function life3mIsoDate(year,month,day){
 const maxDay=
  new Date(
   year,
   month,
   0
  ).getDate();

 const safeDay=
  Math.max(
   1,
   Math.min(
    Number(day||1),
    maxDay
   )
  );

 return [
  year,
  String(month).padStart(2,"0"),
  String(safeDay).padStart(2,"0")
 ].join("-");
}

function life3mAnchorMonthForCycle(cycle){
 /*
  * The comparison label/month is based on the business-cycle
  * start month. Example:
  *   06-Jul -> 05-Aug  => JUL'26
  */
 const parts=
  String(cycle.from||"")
   .split("-")
   .map(Number);

 return {
  year:parts[0],
  month:parts[1]
 };
}

function life3mBusinessCycles(){
 const rows=[];

 const customMode=
  Boolean(
   LIFE_3M_FILTER_FROM&&
   LIFE_3M_FILTER_TO
  );

 let customStartDay=0;
 let customEndDay=0;

 if(customMode){
  const fp=
   String(
    LIFE_3M_FILTER_FROM
   ).split("-");

  const tp=
   String(
    LIFE_3M_FILTER_TO
   ).split("-");

  customStartDay=
   Number(fp[2]||0);

  customEndDay=
   Number(tp[2]||0);
 }

 for(let offset=-2;offset<=0;offset++){
  const cycle=
   getLifeBusinessCycleRange(
    offset
   );

  const anchor=
   life3mAnchorMonthForCycle(
    cycle
   );

  let effectiveFrom="";
  let effectiveTo="";

  if(customMode){
   /*
    * CUSTOM RANGE MODE
    * -----------------
    * Apply the selected day numbers to EACH comparison month.
    *
    * Example:
    * From Date = any 5th
    * To Date   = any 10th
    *
    * JUL'26 = 05-Jul -> 10-Jul
    * AUG'26 = 05-Aug -> 10-Aug
    * SEP'26 = 05-Sep -> 10-Sep
    *
    * If start day > end day, treat it as a cross-month pattern:
    * 25th -> 5th means 25-Jul -> 05-Aug, then
    * 25-Aug -> 05-Sep, etc.
    */
   effectiveFrom=
    life3mIsoDate(
     anchor.year,
     anchor.month,
     customStartDay
    );

   if(
    customStartDay<=
    customEndDay
   ){
    effectiveTo=
     life3mIsoDate(
      anchor.year,
      anchor.month,
      customEndDay
     );
   }else{
    let nextMonth=
     anchor.month+1;

    let nextYear=
     anchor.year;

    if(nextMonth>12){
     nextMonth=1;
     nextYear++;
    }

    effectiveTo=
     life3mIsoDate(
      nextYear,
      nextMonth,
      customEndDay
     );
   }

   /*
    * Current/future safety:
    * never request beyond TODAY for the latest bucket.
    */
   if(
    offset===0&&
    effectiveTo>TODAY
   ){
    effectiveTo=TODAY;
   }

  }else{
   /*
    * DEFAULT MODE:
    * normal business month 6th -> 5th.
    */
   effectiveFrom=
    String(cycle.from||"");

   effectiveTo=
    String(cycle.to||"");

   if(
    offset===0&&
    TODAY<effectiveTo
   ){
    effectiveTo=TODAY;
   }
  }

  const startDate=
   new Date(
    cycle.from+"T00:00:00"
   );

  const monthLabel=
   startDate
    .toLocaleDateString(
     "en-US",
     {
      month:"short",
      year:"2-digit"
     }
    )
    .replace(" ","'")
    .toUpperCase();

  rows.push({
   offset,

   business_from:
    String(cycle.from||""),

   business_to:
    String(cycle.to||""),

   from:
    effectiveFrom,

   to:
    effectiveTo,

   valid:
    Boolean(
     effectiveFrom&&
     effectiveTo&&
     effectiveFrom<=effectiveTo
    ),

   label:
    monthLabel,

   fullLabel:
    ccDisplayDate(
     effectiveFrom
    )+
    " → "+
    ccDisplayDate(
     effectiveTo
    )
  });
 }

 return rows;
}

