/*
 * =========================================================
 * FAST 3-MONTH LOADER
 * ---------------------------------------------------------
 * OLD:
 *   3 separate secure API calls
 *   one call for each business month
 *
 * NEW:
 *   1 secure API call covering the entire three-month window
 *   then split/filter locally in browser memory
 * =========================================================
 */

const LIFE_3M_SESSION_CACHE_PREFIX=
 "life-3m-cache-v1:";

function life3mSessionCacheKey(
 from,
 to
){
 return (
  LIFE_3M_SESSION_CACHE_PREFIX+
  String(from||"")+
  "|"+
  String(to||"")
 );
}

function life3mReadSessionCache(
 from,
 to
){
 try{
  const raw=
   sessionStorage.getItem(
    life3mSessionCacheKey(
     from,
     to
    )
   );

  if(!raw)return null;

  const parsed=
   JSON.parse(raw);

  if(
   !parsed||
   !Array.isArray(parsed.rows)||
   !Array.isArray(parsed.financialEvents)
  ){
   return null;
  }

  /*
   * Cache only for 20 minutes.
   */
  if(
   !parsed.savedAt||
   Date.now()-parsed.savedAt>
   20*60*1000
  ){
   sessionStorage.removeItem(
    life3mSessionCacheKey(
     from,
     to
    )
   );

   return null;
  }

  return parsed;
 }catch(error){
  return null;
 }
}

function life3mWriteSessionCache(
 from,
 to,
 secureResult
){
 try{
  /*
   * Avoid browser storage failure on exceptionally large payloads.
   */
  const payload={
   savedAt:Date.now(),
   rows:
    Array.isArray(
     secureResult.rows
    )
     ?secureResult.rows
     :[],
   financialEvents:
    Array.isArray(
     secureResult.financialEvents
    )
     ?secureResult.financialEvents
     :[],
   ccInvoiceReportSummary:
    secureResult.ccInvoiceReportSummary||
    {}
  };

  sessionStorage.setItem(
   life3mSessionCacheKey(
    from,
    to
   ),
   JSON.stringify(payload)
  );
 }catch(error){
  /*
   * Storage quota can be exceeded for large datasets.
   * In-memory cache still works, so silently continue.
   */
 }
}

let LIFE_3M_FAST_CACHE=null;
let LIFE_3M_FAST_PROMISE=null;
let LIFE_3M_FAST_CACHE_KEY="";

async function life3mLoadAllFast(cycles){
 const validCycles=
  (cycles||[]).filter(
   cycle=>cycle&&cycle.valid!==false
  );

 const first=
  validCycles&&validCycles[0];

 const last=
  validCycles&&validCycles[
   validCycles.length-1
  ];

 if(!first||!last){
  return [];
 }

 const from=
  String(first.from||"");

 const to=
  String(last.to||"");

 const cacheKey=
  from+"|"+to;

 if(
  LIFE_3M_FAST_CACHE&&
  LIFE_3M_FAST_CACHE_KEY===cacheKey
 ){
  return LIFE_3M_FAST_CACHE;
 }

 if(
  LIFE_3M_FAST_PROMISE&&
  LIFE_3M_FAST_CACHE_KEY===cacheKey
 ){
  return LIFE_3M_FAST_PROMISE;
 }

 LIFE_3M_FAST_CACHE_KEY=
  cacheKey;

 LIFE_3M_FAST_PROMISE=
  (async()=>{
   const life3mStartedAt=
    performance.now();

   let secureResult=
    life3mReadSessionCache(
     from,
     to
    );

   if(secureResult){
    console.log(
     "3-month comparison loaded from session cache"
    );
   }else{
    secureResult=
     await fetchSecureAgentAppointmentLeads(
      from,
      to
     );

    life3mWriteSessionCache(
     from,
     to,
     secureResult
    );
   }

   /*
    * Keep normal shared caches/data in sync with the rest
    * of the dashboard without running fetchLeads three times.
    */
   mergeSecureAllAgentRanking(
    secureResult
   );

   mergeSecureFinancialEvents(
    secureResult
   );

   mergeSecureBranchFinancialEvents(
    secureResult
   );

   const allRows=[
    ...new Map(
     (secureResult.rows||[])
      .filter(row=>row&&row.name)
      .map(row=>[
       row.name,
       row
      ])
    ).values()
   ];

   const invoiceSummary=
    secureResult.ccInvoiceReportSummary||
    {};

   const allInvoiceRows=
    Array.isArray(
     invoiceSummary.rows
    )
     ?invoiceSummary.rows
     :[];

   /*
    * Store the combined summary too, in case another section
    * needs this exact full window later.
    */
   CC_INVOICE_REPORT_SUMMARY_MAP.set(
    cacheKey,
    invoiceSummary
   );

   const records=
    allRows.map(
     leadRowToRecord
    );

   const datasets=
    cycles.map(cycle=>{
     /*
      * Invalid clamped bucket = no rows.
      */
     if(cycle.valid===false){
      return {
       cycle,
       raw:[],
       records:[],
       invoiceRows:[],
       financialEvents:[]
      };
     }

     /*
      * One combined secure response is reused by all 3 buckets.
      */
     return {
      cycle,
      raw:allRows,
      records,
      invoiceRows:allInvoiceRows,
      financialEvents:
       Array.isArray(
        secureResult.financialEvents
       )
        ?secureResult.financialEvents
        :[]
     };
    });

   LIFE_3M_FAST_CACHE=
    datasets;

   const life3mElapsed=
    performance.now()-
    life3mStartedAt;

   if(life3mElapsed>2000){
    console.warn(
     "3-month secure data load:",
     Math.round(life3mElapsed)+"ms",
     {
      rows:allRows.length,
      financial_events:
       Array.isArray(
        secureResult.financialEvents
       )
        ?secureResult.financialEvents.length
        :0
     }
    );
   }

   return datasets;
  })();

 try{
  return await LIFE_3M_FAST_PROMISE;
 }finally{
  LIFE_3M_FAST_PROMISE=null;
 }
}

/*
 * Compatibility wrapper.
 * Existing references can still ask for one cycle,
 * but no new API request is made.
 */
async function life3mLoadCycle(cycle){
 const cycles=
  life3mBusinessCycles();

 const datasets=
  await life3mLoadAllFast(
   cycles
  );

 const key=
  life3mCompareKey(
   cycle
  );

 return (
  datasets.find(data=>
   life3mCompareKey(
    data.cycle
   )===key
  )||
  null
 );
}

