function life3mRevenueForGroup(
 cycleData,
 mode,
 key
){
 const cycle=
  cycleData&&cycleData.cycle||{};

 const from=
  String(cycle.from||"");

 const to=
  String(cycle.to||"");

 /*
  * 3-MONTH COMPARISON REVENUE RULE
  * -------------------------------
  *
  * Revenue = New Package Paid + Old Package Paid
  *
  * Use ACTUAL money received in the selected business month:
  *
  *   event.event_date  -> payment / transaction date
  *   event.paid_amount -> amount actually collected
  *
  * New Package Paid:
  *   invoice_date is inside this business month.
  *
  * Old Package Paid:
  *   invoice_date is before this business month,
  *   but payment/event_date is inside this business month.
  *
  * This intentionally does NOT use With GST / Without GST
  * package value because the user wants actual collections.
  */
 const source=
  Array.isArray(
   cycleData&&cycleData.financialEvents
  )
   ?cycleData.financialEvents
   :[];

 let newPackagePaid=0;
 let oldPackagePaid=0;

 source.forEach(event=>{
  if(!event)return;

  /*
   * Keep only exact CC Lead-linked financial activity.
   */
  if(
   typeof isCcLeadLinkedFinancialEvent==="function"&&
   !isCcLeadLinkedFinancialEvent(event)
  ){
   return;
  }

  /*
   * Keep Call Center package only when qualification fields exist.
   * Compatibility: older secure payloads may not carry those fields
   * on every payment event, so exact Lead-link remains sufficient.
   */
  const media=
   String(
    event.therapy_plan_media||""
   ).trim().toLowerCase();

  if(
   media&&
   media!=="call center"
  ){
   return;
  }

  if(
   Number(
    event.therapy_plan_already_taken||0
   )===1
  ){
   return;
  }

  const eventDate=
   String(
    event.event_date||
    event.payment_date||
    ""
   ).slice(0,10);

  /*
   * Revenue is based on CASH RECEIVED during THIS month.
   */
  if(
   !eventDate||
   eventDate<from||
   eventDate>to
  ){
   return;
  }

  /*
   * Group by Branch / CC Agent.
   */
  if(mode==="branch"){
   const eventBranch=
    normalizedBranchKey(
     event.branch||
     event.lead_branch||
     event.patient_branch||
     ""
    );

   if(eventBranch!==key){
    return;
   }
  }else{
   const owner=
    String(
     event.lead_owner||
     event.agent||
     event.owner||
     ""
    ).trim();

   if(
    key==="__LIFE_UNASSIGNED_AGENT__"
   ){
    if(owner)return;
   }else if(
    !sameAgentOwner(
     owner,
     key
    )
   ){
    return;
   }
  }

  const paid=
   Math.max(
    Number(
     event.paid_amount||
     event.paid||
     0
    ),
    0
   );

  if(!paid){
   return;
  }

  const invoiceDate=
   String(
    event.invoice_date||
    event.posting_date||
    ""
   ).slice(0,10);

  /*
   * Older invoice + current-month collection = Old Package Paid.
   * Current-month invoice/payment = New Package Paid.
   */
  if(
   invoiceDate&&
   invoiceDate<from
  ){
   oldPackagePaid+=paid;
  }else{
   newPackagePaid+=paid;
  }
 });

 const total=
  newPackagePaid+
  oldPackagePaid;

 return {
  total:Number(total||0),
  newPackagePaid:
   Number(newPackagePaid||0),
  oldPackagePaid:
   Number(oldPackagePaid||0)
 };
}


/* =========================================================
 * 3-MONTH COMPARISON — ONE-PASS METRIC INDEX
 * ---------------------------------------------------------
 * Instead of filtering all Leads + financial events once for
 * every Branch/Agent, build the full month index ONE TIME.
 * ========================================================= */
const LIFE_3M_METRIC_INDEX_CACHE =
 new WeakMap();

function life3mEmptyMetric(){
 return {
  leads:0,
  walkins:0,
  joined:0,
  conversion:0,
  revenue:0,
  revenueNewPaid:0,
  revenueOldPaid:0,
  _leadNames:new Set(),
  _visitNames:new Set()
 };
}

function life3mIndexMetric(
 map,
 key
){
 if(!map.has(key)){
  map.set(
   key,
   life3mEmptyMetric()
  );
 }

 return map.get(key);
}

function life3mFinancialEventAllowed(
 event
){
 if(!event)return false;

 if(
  typeof isCcLeadLinkedFinancialEvent==="function"&&
  !isCcLeadLinkedFinancialEvent(event)
 ){
  return false;
 }

 const media=
  String(
   event.therapy_plan_media||""
  ).trim().toLowerCase();

 if(
  media&&
  media!=="call center"
 ){
  return false;
 }

 if(
  Number(
   event.therapy_plan_already_taken||0
  )===1
 ){
  return false;
 }

 return true;
}

function life3mFinalizeMetricMap(
 map
){
 map.forEach(metric=>{
  metric.leads=
   metric._leadNames.size;

  metric.walkins=
   metric._visitNames.size;

  metric.conversion=
   metric.walkins
    ?Math.round(
      metric.joined/
      metric.walkins*
      100
     )
    :0;

  metric.revenue=
   Number(
    metric.revenueNewPaid||0
   )+
   Number(
    metric.revenueOldPaid||0
   );

  delete metric._leadNames;
  delete metric._visitNames;
 });
}

function life3mBuildMetricIndex(
 cycleData
){
 if(
  !cycleData||
  !cycleData.cycle
 ){
  return {
   branch:new Map(),
   agent:new Map()
  };
 }

 if(
  LIFE_3M_METRIC_INDEX_CACHE.has(
   cycleData
  )
 ){
  return LIFE_3M_METRIC_INDEX_CACHE.get(
   cycleData
  );
 }

 const branchMap=
  new Map();

 const agentMap=
  new Map();

 const from=
  String(
   cycleData.cycle.from||""
  );

 const to=
  String(
   cycleData.cycle.to||""
  );

 /*
  * ONE pass through Leads.
  */
 (cycleData.raw||[])
  .forEach(row=>{
   if(!row||!row.name)return;

   const branchKey=
    life3mBranchKeyFromRaw(
     row
    );

   const agentKey=
    life3mAgentKeyFromRaw(
     row
    );

   const branchMetric=
    branchKey
     ?life3mIndexMetric(
       branchMap,
       branchKey
      )
     :null;

   const agentMetric=
    agentKey
     ?life3mIndexMetric(
       agentMap,
       agentKey
      )
     :null;

   const receivedDate=
    lifeCcFunnelReceivedDate(
     row
    );

   if(
    receivedDate&&
    receivedDate>=from&&
    receivedDate<=to
   ){
    if(branchMetric){
     branchMetric._leadNames.add(
      row.name
     );
    }

    if(agentMetric){
     agentMetric._leadNames.add(
      row.name
     );
    }
   }

   const visitDate=
    lifeCcFunnelVisitDate(
     row
    );

   const outcome=
    lifeCcFunnelVisitOutcome(
     row
    );

   if(
    visitDate&&
    visitDate>=from&&
    visitDate<=to&&
    outcome
   ){
    if(branchMetric){
     if(
      !branchMetric._visitNames.has(
       row.name
      )
     ){
      branchMetric._visitNames.add(
       row.name
      );

      if(outcome==="booked"){
       branchMetric.joined++;
      }
     }
    }

    if(agentMetric){
     if(
      !agentMetric._visitNames.has(
       row.name
      )
     ){
      agentMetric._visitNames.add(
       row.name
      );

      if(outcome==="booked"){
       agentMetric.joined++;
      }
     }
    }
   }
  });

 /*
  * ONE pass through financial events.
  * Revenue = New Package Paid + Old Package Paid.
  */
 (cycleData.financialEvents||[])
  .forEach(event=>{
   if(
    !life3mFinancialEventAllowed(
     event
    )
   ){
    return;
   }

   const eventDate=
    String(
     event.event_date||
     event.payment_date||
     ""
    ).slice(0,10);

   if(
    !eventDate||
    eventDate<from||
    eventDate>to
   ){
    return;
   }

   const paid=
    Math.max(
     Number(
      event.paid_amount||
      event.paid||
      0
     ),
     0
    );

   if(!paid)return;

   const invoiceDate=
    String(
     event.invoice_date||
     event.posting_date||
     ""
    ).slice(0,10);

   const isOld=
    Boolean(
     invoiceDate&&
     invoiceDate<from
    );

   const branchKey=
    normalizedBranchKey(
     event.branch||
     event.lead_branch||
     event.patient_branch||
     ""
    );

   const owner=
    String(
     event.lead_owner||
     event.agent||
     event.owner||
     ""
    ).trim();

   const agentKey=
    owner||
    "__LIFE_UNASSIGNED_AGENT__";

   if(branchKey){
    const metric=
     life3mIndexMetric(
      branchMap,
      branchKey
     );

    if(isOld){
     metric.revenueOldPaid+=paid;
    }else{
     metric.revenueNewPaid+=paid;
    }
   }

   if(agentKey){
    const metric=
     life3mIndexMetric(
      agentMap,
      agentKey
     );

    if(isOld){
     metric.revenueOldPaid+=paid;
    }else{
     metric.revenueNewPaid+=paid;
    }
   }
  });

 life3mFinalizeMetricMap(
  branchMap
 );

 life3mFinalizeMetricMap(
  agentMap
 );

 const index={
  branch:branchMap,
  agent:agentMap
 };

 LIFE_3M_METRIC_INDEX_CACHE.set(
  cycleData,
  index
 );

 return index;
}

function life3mMetricsForGroup(
 cycleData,
 mode,
 key
){
 const index=
  life3mBuildMetricIndex(
   cycleData
  );

 const map=
  mode==="agent"
   ?index.agent
   :index.branch;

 const metric=
  map.get(key);

 if(!metric){
  return {
   leads:0,
   walkins:0,
   joined:0,
   conversion:0,
   revenue:0,
   revenueNewPaid:0,
   revenueOldPaid:0
  };
 }

 return metric;
}

function life3mGroupKeys(
 datasets,
 mode
){
 const set=
  new Set();

 (datasets||[])
  .forEach(data=>{
   const index=
    life3mBuildMetricIndex(
     data
    );

   const map=
    mode==="agent"
     ?index.agent
     :index.branch;

   map.forEach(
    (metric,key)=>{
     if(
      mode==="branch"&&
      key==="testingbranch"
     ){
      return;
     }

     /*
      * Keep only groups with real activity in this cycle.
      */
     if(
      Number(metric.leads||0)||
      Number(metric.walkins||0)||
      Number(metric.joined||0)||
      Number(metric.revenue||0)
     ){
      set.add(key);
     }
    }
   );
  });

 return [...set];
}

function life3mMoney(value){
 return dashboardMoney(
  Number(value||0)
 );
}

function life3mSignedNumber(value){
 const n=Number(value||0);

 if(n>0)return "+"+n;
 return String(n);
}

function life3mSignedMoney(value){
 const n=Number(value||0);

 if(n>0){
  return "+"+dashboardMoney(n);
 }

 if(n<0){
  return "-"+dashboardMoney(
   Math.abs(n)
  );
 }

 return dashboardMoney(0);
}

function life3mDeficitClass(value){
 const n=Number(value||0);

 if(n>0)return "life3m-positive";
 if(n<0)return "life3m-negative";
 return "life3m-neutral";
}

