function life3mBindToggle(){
 /*
  * No duplicate Branch-wise / Agent-wise controls here.
  * Main report buttons continue to control mode.
  */

 const from=
  byId("life3mFromDate");

 const to=
  byId("life3mToDate");

 const apply=
  byId("life3mApplyDate");

 const reset=
  byId("life3mResetDate");

 if(apply){
  apply.onclick=()=>{
   const nextFrom=
    String(
     from&&from.value||""
    );

   const nextTo=
    String(
     to&&to.value||""
    );

   if(
    !nextFrom||
    !nextTo
   ){
    toast(
     "Select From Date and To Date"
    );
    return;
   }

   /*
    * These dates act as DAY-OF-MONTH selectors for all 3 months.
    * Their absolute month/year values are not used for comparison.
    * Example: From day 5, To day 10 => each month uses 5th -> 10th.
    */
   LIFE_3M_FILTER_FROM=
    nextFrom;

   LIFE_3M_FILTER_TO=
    nextTo;

   /*
    * Date range changed, so clear fast cache and rerender.
    */
   LIFE_3M_FAST_CACHE=null;
   LIFE_3M_FAST_CACHE_KEY="";
   LIFE_3M_FAST_PROMISE=null;
   LIFE_3M_LAST_RENDER_KEY="";

   lifeCcStartThreeMonthComparison(
    LIFE_3M_COMPARE_MODE
   );
  };
 }

 if(reset){
  reset.onclick=()=>{
   LIFE_3M_FILTER_FROM="";
   LIFE_3M_FILTER_TO="";

   LIFE_3M_FAST_CACHE=null;
   LIFE_3M_FAST_CACHE_KEY="";
   LIFE_3M_FAST_PROMISE=null;
   LIFE_3M_LAST_RENDER_KEY="";

   lifeCcStartThreeMonthComparison(
    LIFE_3M_COMPARE_MODE
   );
  };
 }
}

function life3mComparisonTable(
 datasets,
 mode
){
 const cycles=
  datasets.map(
   x=>x.cycle
  );

 const keys=
  life3mGroupKeys(
   datasets,
   mode
  );

 const rows=
  keys.map(key=>{
   const metrics=
    datasets.map(data=>
     life3mMetricsForGroup(
      data,
      mode,
      key
     )
    );

   const latest=
    metrics[
     metrics.length-1
    ];

   const previous=
    metrics[
     metrics.length-2
    ];

   const label=
    mode==="branch"
     ?life3mBranchLabel(
       key,
       datasets
      )
     :life3mAgentLabel(
       key
      );

   return {
    key,
    label,
    metrics,
    deficit:{
     leads:
      latest.leads-
      previous.leads,
     walkins:
      latest.walkins-
      previous.walkins,
     joined:
      latest.joined-
      previous.joined,
     revenue:
      latest.revenue-
      previous.revenue
    }
   };
  });

 rows.sort((a,b)=>
  String(a.label)
   .localeCompare(
    String(b.label)
   )
 );

 const totals=
  datasets.map((data,index)=>{
   return rows.reduce(
    (sum,row)=>{
     const m=
      row.metrics[index];

     sum.leads+=m.leads;
     sum.walkins+=m.walkins;
     sum.joined+=m.joined;
     sum.revenue+=m.revenue;
     sum.revenueNewPaid+=
      Number(
       m.revenueNewPaid||0
      );
     sum.revenueOldPaid+=
      Number(
       m.revenueOldPaid||0
      );

     return sum;
    },
    {
     leads:0,
     walkins:0,
     joined:0,
     revenue:0,
     revenueNewPaid:0,
     revenueOldPaid:0
    }
   );
  });

 totals.forEach(total=>{
  total.conversion=
   total.walkins
    ?Math.round(
      total.joined/
      total.walkins*
      100
     )
    :0;
 });

 const latestTotal=
  totals[totals.length-1];

 const previousTotal=
  totals[totals.length-2];

 const totalDeficit={
  leads:
   latestTotal.leads-
   previousTotal.leads,
  walkins:
   latestTotal.walkins-
   previousTotal.walkins,
  joined:
   latestTotal.joined-
   previousTotal.joined,
  revenue:
   latestTotal.revenue-
   previousTotal.revenue
 };

 const monthHeader=
  cycles.map(
   (cycle,index)=>`
    <th
     colspan="5"
     class="
      life3m-group-head
      life3m-month-${index+1}
     "
     title="${lifeCcEsc(cycle.fullLabel)}"
    >
     ${lifeCcEsc(cycle.label)}
    </th>`
  ).join("");

 const subHeaders=
  cycles.map(
   (cycle,index)=>`
    <th class="life3m-sub-head life3m-month-${index+1}">
     LEADS
    </th>
    <th class="life3m-sub-head life3m-month-${index+1}">
     WALK-INS
    </th>
    <th class="life3m-sub-head life3m-month-${index+1}">
     JOINED
    </th>
    <th class="life3m-sub-head life3m-month-${index+1}">
     J/W CONV %
    </th>
    <th class="life3m-sub-head life3m-revenue life3m-month-${index+1}">
     REVENUE
     <small>New + Old Paid</small>
    </th>`
  ).join("");

 const bodyRows=
  rows.map(row=>`
   <tr>
    <td class="life3m-name">
     ${lifeCcEsc(row.label)}
    </td>

    ${row.metrics.map(
     (m,index)=>`
      <td class="life3m-month-${index+1}">
       ${m.leads}
      </td>
      <td class="life3m-month-${index+1}">
       ${m.walkins}
      </td>
      <td class="life3m-month-${index+1}">
       ${m.joined}
      </td>
      <td class="life3m-month-${index+1}">
       ${m.conversion}%
      </td>
      <td
       class="life3m-month-${index+1} life3m-revenue-cell"
       title="New Package Paid: ${life3mMoney(m.revenueNewPaid||0)} | Old Package Paid: ${life3mMoney(m.revenueOldPaid||0)}"
      >
       ${life3mMoney(m.revenue)}
      </td>`
    ).join("")}

    <td class="life3m-deficit ${life3mDeficitClass(row.deficit.leads)}">
     ${life3mSignedNumber(row.deficit.leads)}
    </td>
    <td class="life3m-deficit ${life3mDeficitClass(row.deficit.walkins)}">
     ${life3mSignedNumber(row.deficit.walkins)}
    </td>
    <td class="life3m-deficit ${life3mDeficitClass(row.deficit.joined)}">
     ${life3mSignedNumber(row.deficit.joined)}
    </td>
    <td class="life3m-deficit life3m-revenue-cell ${life3mDeficitClass(row.deficit.revenue)}">
     ${life3mSignedMoney(row.deficit.revenue)}
    </td>
   </tr>`
  ).join("");

 const patternNote=
  (
   LIFE_3M_FILTER_FROM&&
   LIFE_3M_FILTER_TO
  )
   ?(
     " · Same day-range applied to every month"
    )
   :" · Default business month 6th → 5th";

 return `
  <div class="life3m-compare-range-note">
   ${
    cycles.map(c=>
     `<b>${lifeCcEsc(c.label)}</b>: ${lifeCcEsc(c.fullLabel)}`
    ).join(" · ")
   }
   ${patternNote}
   · Revenue = New Package Paid + Old Package Paid
   · Deficit = latest month − previous month
  </div>

  <div class="life3m-compare-scroll">
   <table class="life3m-compare-table">
    <thead>
     <tr>
      <th
       rowspan="2"
       class="life3m-name"
      >
       ${mode==="branch"?"BRANCH":"CC AGENT"}
      </th>

      ${monthHeader}

      <th
       colspan="4"
       class="life3m-group-head life3m-deficit"
      >
       DEFICIT
      </th>
     </tr>

     <tr>
      ${subHeaders}

      <th class="life3m-sub-head life3m-deficit">
       LEADS
      </th>
      <th class="life3m-sub-head life3m-deficit">
       WALK-INS
      </th>
      <th class="life3m-sub-head life3m-deficit">
       JOINED
      </th>
      <th class="life3m-sub-head life3m-revenue life3m-deficit">
       REVENUE
       <small>New + Old Paid</small>
      </th>
     </tr>
    </thead>

    <tbody>
     ${bodyRows}

     <tr class="life3m-total-row">
      <td class="life3m-name">
       TOTAL
      </td>

      ${totals.map(
       (m,index)=>`
        <td>${m.leads}</td>
        <td>${m.walkins}</td>
        <td>${m.joined}</td>
        <td>${m.conversion}%</td>
        <td
         class="life3m-revenue-cell"
         title="New Package Paid: ${life3mMoney(m.revenueNewPaid||0)} | Old Package Paid: ${life3mMoney(m.revenueOldPaid||0)}"
        >${life3mMoney(m.revenue)}</td>`
      ).join("")}

      <td class="${life3mDeficitClass(totalDeficit.leads)}">
       ${life3mSignedNumber(totalDeficit.leads)}
      </td>
      <td class="${life3mDeficitClass(totalDeficit.walkins)}">
       ${life3mSignedNumber(totalDeficit.walkins)}
      </td>
      <td class="${life3mDeficitClass(totalDeficit.joined)}">
       ${life3mSignedNumber(totalDeficit.joined)}
      </td>
      <td class="life3m-revenue-cell ${life3mDeficitClass(totalDeficit.revenue)}">
       ${life3mSignedMoney(totalDeficit.revenue)}
      </td>
     </tr>
    </tbody>
   </table>
  </div>`;
}

let LIFE_3M_LAST_RENDER_KEY="";


/* =========================================================
 * 3-MONTH COMPARISON — LAZY LOAD
 * ---------------------------------------------------------
 * The secure API can return 10k+ Lead rows and ~2k payment events.
 * Do not pay that cost on every Branch Summary render.
 * ========================================================= */
let LIFE_3M_LAZY_OPENED=false;

function life3mInstallLazyComparisonShell(
 preferredMode
){
 const sumWrap=
  byId("sumWrap");

 if(!sumWrap)return;

 if(
  preferredMode==="branch"||
  preferredMode==="agent"
 ){
  LIFE_3M_COMPARE_MODE=
   preferredMode;
 }

 life3mComparisonCss();

 let host=
  byId("life3mComparisonHost");

 if(!host){
  host=
   document.createElement(
    "div"
   );

  host.id=
   "life3mComparisonHost";

  sumWrap.appendChild(
   host
  );
 }

 /*
  * If already loaded, keep current rendered comparison.
  */
 if(
  LIFE_3M_LAZY_OPENED&&
  LIFE_3M_FAST_CACHE&&
  host.querySelector(
   ".life3m-compare-table"
  )
 ){
  return;
 }

 host.innerHTML=`
  <div class="life3m-compare-card">
   <div class="life3m-compare-head">
    <h3>
     📊 Last 3 Business Months Comparison
     <span
      style="
       margin-left:8px;
