    </h3>

    <button
     type="button"
     id="life3mLoadButton"
     class="btn btn-o"
     style="
      min-height:34px;
      height:34px;
      padding:0 14px;
      font-size:10px;
     "
    >
     Load 3-Month Comparison
    </button>
   </div>

   <div
    class="life3m-compare-range-note"
   >
    Historical comparison is loaded only when requested to keep the dashboard fast.
    Once loaded, it stays cached for repeat viewing.
   </div>
  </div>`;

 const button=
  byId("life3mLoadButton");

 if(button){
  button.onclick=async()=>{
   button.disabled=true;
   button.textContent=
    "Loading comparison…";

   LIFE_3M_LAZY_OPENED=true;

   try{
    await lifeCcStartThreeMonthComparison(
     LIFE_3M_COMPARE_MODE
    );
   }catch(error){
    console.error(
     "3-month lazy load failed",
     error
    );

    button.disabled=false;
    button.textContent=
     "Retry 3-Month Comparison";
   }
  };
 }
}

async function lifeCcStartThreeMonthComparison(
 preferredMode
){
 const sumWrap=
  byId("sumWrap");

 if(!sumWrap)return;

 life3mComparisonCss();

 if(
  preferredMode==="branch"||
  preferredMode==="agent"
 ){
  LIFE_3M_COMPARE_MODE=
   preferredMode;
 }

 const cyclesForKey=
  life3mBusinessCycles();

 const renderKey=
  LIFE_3M_COMPARE_MODE+
  "|"+
  String(LIFE_3M_FILTER_FROM||"DEFAULT")+
  "|"+
  String(LIFE_3M_FILTER_TO||"DEFAULT")+
  "|"+
  cyclesForKey.map(c=>
   c.from+"|"+c.to
  ).join("||");

 /*
  * If same comparison is already rendered and data is cached,
  * do not repaint/reload it.
  */
 const existingHost=
  byId("life3mComparisonHost");

 if(
  existingHost&&
  LIFE_3M_LAST_RENDER_KEY===renderKey&&
  LIFE_3M_FAST_CACHE
 ){
  return;
 }

 LIFE_3M_LAST_RENDER_KEY=
  renderKey;

 let host=
  byId(
   "life3mComparisonHost"
  );

 if(!host){
  host=
   document.createElement(
    "div"
   );

  host.id=
   "life3mComparisonHost";

  sumWrap.appendChild(
   host
  );
 }

 host.innerHTML=
  life3mComparisonSkeleton();

 life3mBindToggle();

 const token=
  ++LIFE_3M_COMPARE_RENDER_TOKEN;

 try{
  const cycles=
   life3mBusinessCycles();

  /*
   * FAST:
   * One server request for the whole 3-business-month window.
   * Local JavaScript then splits/calculates each month.
   */
  const datasets=
   await life3mLoadAllFast(
    cycles
   );

  if(
   token!==
   LIFE_3M_COMPARE_RENDER_TOKEN
  ){
   return;
  }

  const body=
   byId(
    "life3mComparisonBody"
   );

  if(!body)return;

  body.outerHTML=`
   <div id="life3mComparisonBody">
    ${life3mComparisonTable(
      datasets,
      LIFE_3M_COMPARE_MODE
     )}
   </div>`;

  life3mBindToggle();

 }catch(error){
  console.error(
   "Last 3 month comparison failed:",
   error
  );

  const body=
   byId(
    "life3mComparisonBody"
   );

  if(body){
   body.innerHTML=`
    <div
     style="
      padding:14px;
      color:#a12626;
      font-size:11px;
     "
    >
     Could not load Last 3 Business Months comparison:
     ${lifeCcEsc(
       error&&error.message||
       "connection error"
      )}
    </div>`;
  }
 }
}



