  D:null,
  E:null
 };

 function wrap(key,fn){
  if(typeof fn!=="function"){
   return fn;
  }

  return async function(){
   if(running[key]){
    return running[key];
   }

   running[key]=
    Promise.resolve()
     .then(()=>
      fn.apply(
       this,
       arguments
      )
     )
     .finally(()=>{
      running[key]=null;
     });

   return running[key];
  };
 }

 if(original.A){
  epA=wrap("A",original.A);
  window.epA=epA;
 }

 if(original.B){
  epB=wrap("B",original.B);
  window.epB=epB;
 }

 if(original.C){
  epC=wrap("C",original.C);
  window.epC=epC;
 }

 if(original.D){
  epD=wrap("D",original.D);
  window.epD=epD;
 }

 if(original.E){
  epE=wrap("E",original.E);
  window.epE=epE;
 }
})();



