/* =====================================================================
 * TAB 5 — CLUSTER / AREA MANAGER REPORT
 * ---------------------------------------------------------------------
 * Columns:
 * - Area Manager Name
 * - Total Walk-ins
 * - Booked
 * - Package Amount (W/O GST)
 * - Paid Amount
 * - Balance Amount
 * - Ticket (Package Amount ÷ Booked)
 *
 * Mapping priority:
 * Only Active Employees whose designation contains Cluster Manager or Area Manager.
 * Resolution uses Employee.reports_to chain.
 * Center Manager / Assistant Centre Manager / Senior Manager are excluded.
 * ===================================================================== */

let LIFE_CLUSTER_MANAGER_MAP = new Map();
let LIFE_CLUSTER_MANAGER_MAP_READY = false;
let LIFE_CLUSTER_MANAGER_MAP_PROMISE = null;

function lifeClusterClean(v){
 return String(v||"").trim();
}

function lifeClusterDesignation(v){
 return lifeClusterClean(v).toLowerCase();
}

function lifeClusterEmployeeActive(employee){
 if(!employee)return false;

 const status=
  lifeClusterClean(
   employee.status
  ).toLowerCase();

 return (
  !status||
  status==="active"
 );
}

function lifeClusterIsClusterManager(employee){
 const d=
  lifeClusterDesignation(
   employee&&employee.designation
  );

 return (
  d==="cluster manager"||
  d.includes("cluster manager")
 );
}

function lifeClusterIsAreaManager(employee){
 const d=
  lifeClusterDesignation(
   employee&&employee.designation
  );

 return (
  d==="area manager"||
  d.includes("area manager")
 );
}

function lifeClusterManagerLabel(employee){
 if(!employee)return "Area Manager Unmapped";

 return (
  lifeClusterClean(employee.employee_name)||
  lifeClusterClean(employee.name)||
  "Area Manager Unmapped"
 );
}

async function lifeClusterBuildManagerMap(){
 if(LIFE_CLUSTER_MANAGER_MAP_READY){
  return LIFE_CLUSTER_MANAGER_MAP;
 }

 if(LIFE_CLUSTER_MANAGER_MAP_PROMISE){
  return LIFE_CLUSTER_MANAGER_MAP_PROMISE;
 }

 LIFE_CLUSTER_MANAGER_MAP_PROMISE=
  (async()=>{
   /*
    * AREA MANAGER SOURCE OF TRUTH
    * ----------------------------
    * Employee fields:
    * - designation
    * - branch
    * - custom_branch_list
    *
    * Only Area Manager designations are included.
    * No Center Manager / Senior Manager / Cluster Manager /
    * Unmapped fallback rows.
    */
   let employees=[];

   try{
    employees=
     await apiGetList(
      "Employee",
      [
       "name",
       "employee_name",
       "designation",
       "branch",
       "custom_branch_list",
       "status"
      ],
      [
       ["status","=","Active"],
       ["designation","like","%Area Manager%"]
      ],
      {
       limit_page_length:200,
       order_by:"employee_name asc",
       network_retries:1,
       timeout_ms:12000
      }
     );
   }catch(error){
    console.warn(
     "Area Manager employee load failed",
     error
    );

    employees=[];
   }

   const resolved=
    new Map();

   function addBranch(
    branchValue,
    employee
   ){
    const key=
     normalizedBranchKey(
      branchValue||""
     );

    if(
     !key||
     key==="testingbranch"||
     key==="headoffice"
    ){
     return;
    }

    /*
     * First active Area Manager wins deterministically
     * because employee query is ordered by name.
     */
    if(!resolved.has(key)){
     resolved.set(
      key,
      employee
     );
    }
   }

   (employees||[])
    .filter(employee=>{
     if(!lifeClusterEmployeeActive(employee)){
      return false;
     }

     const designation=
      lifeClusterDesignation(
       employee.designation
      );

     return designation.includes(
      "area manager"
     );
    })
    .forEach(employee=>{
     /*
      * custom_branch_list may contain comma/newline/semicolon/
      * pipe separated branch names.
      */
     const branchList=
      String(
       employee.custom_branch_list||""
      )
       .split(/[\n,;|]+/)
       .map(value=>
        value.trim()
       )
       .filter(Boolean);

     branchList.forEach(branch=>
      addBranch(
       branch,
       employee
      )
     );

     /*
      * Employee.branch is fallback when Branch List is empty
      * or for the employee's primary branch.
      */
     addBranch(
      employee.branch,
      employee
     );
    });

   LIFE_CLUSTER_MANAGER_MAP=
    resolved;

   LIFE_CLUSTER_MANAGER_MAP_READY=
    true;

   console.log(
    "Area Manager branch mapping ready",
    {
     area_managers:
      (employees||[]).length,
     mapped_branches:
      resolved.size,
     mappings:
      [...resolved.entries()]
       .map(([branchKey,employee])=>({
        branch:branchKey,
        area_manager:
         lifeClusterManagerLabel(
          employee
         )
       }))
    }
   );

   return LIFE_CLUSTER_MANAGER_MAP;
  })()
  .catch(error=>{
   console.warn(
    "Area Manager mapping failed",
    error
   );

   LIFE_CLUSTER_MANAGER_MAP=
    new Map();

   LIFE_CLUSTER_MANAGER_MAP_READY=
    true;

   return LIFE_CLUSTER_MANAGER_MAP;
  })
  .finally(()=>{
   LIFE_CLUSTER_MANAGER_MAP_PROMISE=null;
  });

 return LIFE_CLUSTER_MANAGER_MAP_PROMISE;
}

function lifeClusterIsWalkin(record){
 return Boolean(
  record&&(
   record.cat===CATS[0]||
   record.cat===CATS[1]||
   record.cat===CATS[7]
  )
 );
}

function lifeClusterIsBooked(record){
 return Boolean(
  record&&
  record.cat===CATS[0]
 );
}

function lifeClusterMoney(value){
 return dashboardMoney(
  Number(value||0)
 );
}


/* =========================================================
 * CLUSTER / AREA MANAGER FINANCIALS
 * ---------------------------------------------------------
 * Package Amount = NEW package WITH GST
 * Paid Amount    = NEW Package Paid + OLD Package Paid
 * Balance Amount = current NEW package invoice balance
 *
 * Uses the exact CC Invoice Report rows for the selected period.
 * ========================================================= */
function lifeClusterFinancialsForBranches(branchKeys){
 const wanted=
  new Set(
   (branchKeys||[])
    .map(normalizedBranchKey)
    .filter(Boolean)
  );

 const summary=
  CC_INVOICE_REPORT_SUMMARY_MAP.get(
   String(F.from||"")+
   "|"+
   String(F.to||"")
  );

 const rows=
  summary&&Array.isArray(summary.rows)
   ?summary.rows
    .filter(isStrictCallCenterPackageRow)
    .filter(row=>
     wanted.has(
      normalizedBranchKey(
       row&&row.branch
      )
     )
    )
   :[];

 const split=
  ccInvoicePackageSplitTotals(
   rows
  );

 return {
  packageAmountWithGst:
   Number(split.withGst||0),

  newPackagePaid:
   Number(split.paid||0),

  oldPackagePaid:
   Number(split.oldPackagePaid||0),

  paidAmount:
   Number(split.paid||0)+
   Number(split.oldPackagePaid||0),

  balanceAmount:
   Number(split.balance||0)
 };
}

function lifeClusterReportRows(records,managerMap){
 const groups=
  new Map();

 (records||[])
  .forEach(record=>{
   const branchKey=
    normalizedBranchKey(
     record&&record.br||""
    );

   if(
    !branchKey||
    branchKey==="testingbranch"
   ){
    return;
   }

   const manager=
    managerMap.get(branchKey)||null;

   /*
    * AREA MANAGER REPORT:
    * do not show overall / unassigned branches.
    */
   if(!manager){
    return;
   }

   const managerName=
    lifeClusterManagerLabel(
     manager
    );

   const managerId=
    String(
     manager.name
    );

   if(!groups.has(managerId)){
    groups.set(
     managerId,
     {
      managerId,
      managerName,
      designation:
       lifeClusterClean(
        manager.designation
       ),
      branches:new Set(),
      branchKeys:new Set(),
      walkins:new Set(),
      booked:new Set(),
      invoices:new Map()
     }
    );
   }

   const group=
    groups.get(managerId);

   group.branches.add(
    consultantBranchLabel(
     record.br
    )
   );

   group.branchKeys.add(
    branchKey
   );

   const leadKey=
    String(
     record.patientLead||
     record.client||
     record.ph||
     Math.random()
    );

   if(lifeClusterIsWalkin(record)){
    group.walkins.add(
     leadKey
    );
   }

   if(lifeClusterIsBooked(record)){
    group.booked.add(
     leadKey
    );
   }

   /*
    * Deduplicate financials by Sales Invoice when possible.
    * If there is no invoice, fall back to Lead key.
    */
   const invoiceKey=
    lifeClusterClean(
     record.salesInvoiceName
    )||
    ("LEAD:"+leadKey);

   if(!group.invoices.has(invoiceKey)){
    group.invoices.set(
     invoiceKey,
     {
      packageAmount:
       Math.max(
        Number(
         record.clientPackageAmountWithoutGst||
         record.clientPackageAmount||
         0
        ),
        0
       ),

      paidAmount:
       Math.max(
        Number(
         record.clientPaidAmount||
         0
        ),
        0
       ),

      balanceAmount:
       Math.max(
        Number(
         record.clientBalanceAmount||
         0
        ),
        0
       )
     }
    );
   }
  });

 const rows=
  [...groups.values()]
   .map(group=>{
    /*
     * Exact financial source:
     * CC Invoice Report rows for all branches owned by this manager.
     */
    const financials=
     lifeClusterFinancialsForBranches(
      [...group.branchKeys]
     );

    const packageAmount=
     Number(
      financials.packageAmountWithGst||0
     );

    const paidAmount=
     Number(
      financials.paidAmount||0
     );

    const balanceAmount=
     Number(
      financials.balanceAmount||0
     );

    const newPackagePaid=
     Number(
      financials.newPackagePaid||0
     );

    const oldPackagePaid=
     Number(
      financials.oldPackagePaid||0
     );

    const booked=
     group.booked.size;

    return {
     managerId:
      group.managerId,

     managerName:
      group.managerName,

     designation:
      group.designation,

     branches:
      [...group.branches]
       .sort(
        (a,b)=>
         a.localeCompare(
          b,
          "en",
          {sensitivity:"base"}
         )
       ),

     branchKeys:
      [...group.branchKeys],

     walkins:
      group.walkins.size,

     booked,

     packageAmount,

     paidAmount,

     newPackagePaid,

     oldPackagePaid,

     balanceAmount,

     ticket:
      booked>0
       ?packageAmount/booked
       :0
    };
   })
   .sort((a,b)=>{
    if(
     b.packageAmount!==
     a.packageAmount
    ){
     return (
      b.packageAmount-
      a.packageAmount
     );
    }

    return a.managerName.localeCompare(
     b.managerName,
     "en",
     {sensitivity:"base"}
    );
   });

 return rows;
}

