/* =========================================================
 * CLUSTER / AREA MANAGER POPUP
 * Reuses the existing LIFE CC popup + leadTable().
 * ========================================================= */
function lifeClusterRowsForBranches(
 branchKeys,
 type
){
 const wanted=
  new Set(
   (branchKeys||[])
    .map(normalizedBranchKey)
    .filter(Boolean)
  );

 let rows=
  (RECORDS||[])
   .filter(record=>{
    const branchKey=
     normalizedBranchKey(
      record&&record.br||""
     );

    return (
     wanted.size===0||
     wanted.has(branchKey)
    );
   });

 if(type==="walkins"){
  rows=
   rows.filter(
    lifeClusterIsWalkin
   );
 }else if(type==="booked"){
  rows=
   rows.filter(
    lifeClusterIsBooked
   );
 }else{
  /*
   * Manager-row click shows all actual walk-in outcomes for that manager.
   */
  rows=
   rows.filter(
    lifeClusterIsWalkin
   );
 }

 return rows.sort(
  (left,right)=>
   String(
    right.aptDts||""
   ).localeCompare(
    String(
     left.aptDts||""
    )
   )
 );
}

async function lifeClusterOpenPopup(
 branchKeys,
