 if(
  !popup||
  !popup.body||
  !popup.title
 ){
  return;
 }

 const label=
  type==="booked"
   ?"Booked"
   :type==="walkins"
    ?"Walk-ins"
    :"Client Details";

 popup.title.textContent=
  String(title||"Area Manager")+
  " · "+
  label+
  " · "+
  rows.length+
  " client"+
  (rows.length===1?"":"s");

 /*
  * Apply exact financials to the client rows before rendering popup.
  */
