/* AREA MANAGER REPORT RULE
 * Only mapped active Area Manager employees are displayed.
 * Branch ownership uses Employee.custom_branch_list first,
 * then Employee.branch.
 * Unmapped branches are intentionally excluded.
 */




/* =====================================================================
 * CLEAN FINAL IMPLEMENTATION
 * ONE Cluster renderer / filter engine / print handler / 3M fast loader.
 * ===================================================================== */

/* ---------- Cluster state ---------- */
let LIFE_CLUSTER_FILTER = {
 from: String(F.from || TODAY),
 to: String(F.to || TODAY)
};
let LIFE_CLUSTER_QUICK = "";
let LIFE_CLUSTER_RECORDS = [];
let LIFE_CLUSTER_RECORDS_KEY = "";
const LIFE_CLUSTER_CACHE = new Map();
const LIFE_CLUSTER_ENRICHING = new Map();
let LIFE_CLUSTER_REQUEST_ID = 0;

function lifeClusterRangeKey(from, to){
 return String(from || "") + "|" + String(to || "");
}

function lifeClusterQuickRange(mode){
 return getCcQuickRange(mode);
}

function lifeClusterParseBranches(employee){
 const values = [];
 String(employee && employee.custom_branch_list || "")
  .split(/[\n,;|]+/)
  .map(v => v.trim())
  .filter(Boolean)
  .forEach(v => values.push(v));

 const primary = String(employee && employee.branch || "").trim();
 if(primary) values.push(primary);

 const seen = new Set();
 return values.filter(branch => {
  const key = normalizedBranchKey(branch);
  if(!key || key === "testingbranch" || key === "headoffice" || seen.has(key)){
   return false;
  }
  seen.add(key);
  return true;
 });
}

function lifeClusterAreaManagersFromMap(){
 const employees = [];
 const seen = new Set();

 if(LIFE_CLUSTER_MANAGER_MAP instanceof Map){
  LIFE_CLUSTER_MANAGER_MAP.forEach(employee => {
   if(!employee || !employee.name || seen.has(employee.name)) return;
   const d = String(employee.designation || "").toLowerCase();
   if(!d.includes("area manager")) return;
   seen.add(employee.name);
   employees.push(employee);
  });
 }
 return employees;
}

async function lifeClusterEnsureAreaManagers(){
 if(LIFE_CLUSTER_MANAGER_MAP_READY && LIFE_CLUSTER_MANAGER_MAP.size){
  return LIFE_CLUSTER_MANAGER_MAP;
 }

 try{
  return await Promise.race([
   lifeClusterBuildManagerMap(),
   new Promise(resolve => setTimeout(
    () => resolve(LIFE_CLUSTER_MANAGER_MAP || new Map()),
    4500
   ))
  ]);
 }catch(error){
  console.warn("Area Manager mapping fallback", error);
  return LIFE_CLUSTER_MANAGER_MAP || new Map();
 }
}

function lifeClusterConsultantKey(record){
 const id = consultantClean(record && record.consultantEmployeeId);
 if(id) return "EMP:" + id;

 const name = consultantClean(
  record && (
   record.consultantEmployeeName ||
   record.clientConsultant ||
   record.cons ||
   record.patientAppointmentPractitioner ||
   ""
  )
 );

 if(!name || name === "Consultant Not Assigned" || name === "Consultant Unmapped"){
  return "";
 }

 return "NAME:" + consultantKeyPart(name);
}

function lifeClusterConsultantName(record){
 return consultantClean(
  record && (
   record.consultantEmployeeName ||
   record.clientConsultant ||
   record.cons ||
   record.patientAppointmentPractitioner ||
   ""
  )
 ) || "Consultant Unmapped";
}

function lifeClusterFinancials(rows){
 /*
  * Use the existing Walking Report financial engine.
  * This preserves exact package/paid/balance enrichment already used elsewhere.
  */
 try{
  return consultantFinancialsForRows(rows || []);
 }catch(error){
  let withGst = 0, withoutGst = 0, paid = 0, balance = 0;
  const seen = new Set();

  (rows || []).forEach(record => {
   const key = consultantClean(
    record && (
     record.salesInvoiceName ||
     record.financial_sales_invoice ||
     record.therapyPlanName ||
     record.name
    )
   );
   if(key && seen.has(key)) return;
   if(key) seen.add(key);

   withGst += Number(record && (
    record.clientPackageAmountWithGst ||
    record.financial_with_gst ||
    0
   ) || 0);

   withoutGst += Number(record && (
    record.clientPackageAmountWithoutGst ||
    record.financial_without_gst ||
    0
   ) || 0);

   paid += Number(record && (
    record.clientPaidAmount ||
    record.financial_paid_amount ||
    0
   ) || 0);

   balance += Number(record && (
    record.clientBalanceAmount ||
    record.financial_balance_amount ||
    0
   ) || 0);
  });

  return {withGst, withoutGst, paid, balance};
 }
}

function lifeClusterRows(records, managerMap){
 const groups = new Map();

 (records || []).forEach(record => {
  const branchKey = normalizedBranchKey(record && record.br || "");
  const areaManager = managerMap && managerMap.get(branchKey);
  if(!areaManager) return;

  const consultantKey = lifeClusterConsultantKey(record);
  if(!consultantKey) return;

  const managerId = String(areaManager.name || areaManager.employee_name || "");
  const groupKey = managerId + "|" + consultantKey;

  if(!groups.has(groupKey)){
   groups.set(groupKey, {
    key: groupKey,
    managerId,
    managerName: lifeClusterManagerLabel(areaManager),
    managerDesignation: String(areaManager.designation || "Area Manager").trim(),
    employeeName: lifeClusterConsultantName(record),
    designation: consultantClean(record.consultantDesignation) || "—",
    branches: new Set(),
    records: []
   });
  }

  const group = groups.get(groupKey);
  group.records.push(record);
  group.branches.add(consultantBranchLabel(record.br));
 });

 return [...groups.values()].map(group => {
  const rows = group.records;
  const booked = rows.filter(r => r.cat === CATS[0]).length;
  const notBooked = rows.filter(r => r.cat === CATS[1]).length;
  const notVisited = rows.filter(r => r.cat === CATS[2]).length;
  const pending = rows.filter(r => r.cat === CATS[7]).length;
  const totalVisits = booked + notBooked;
  const walkins = rows.filter(lifeClusterIsWalkin).length;
  const financial = lifeClusterFinancials(rows);
  const ticket = booked > 0 ? Number(financial.withGst || 0) / booked : 0;

  return {
   ...group,
   branches: [...group.branches].filter(Boolean).sort((a,b)=>a.localeCompare(b)),
   appointments: rows.length,
   pending,
   totalVisits,
   booked,
   notBooked,
   notVisited,
   financial,
   joiningRatio: walkins > 0 ? Math.round(booked / walkins * 100) : 0,
   ticket
  };
 }).sort((a,b) =>
  a.managerName.localeCompare(b.managerName, "en", {sensitivity:"base"}) ||
  b.appointments - a.appointments ||
  a.employeeName.localeCompare(b.employeeName, "en", {sensitivity:"base"})
 );
}

function lifeClusterTotals(rows){
 const all = [];
 (rows || []).forEach(row => all.push(...(row.records || [])));

 const booked = all.filter(r => r.cat === CATS[0]).length;
 const notBooked = all.filter(r => r.cat === CATS[1]).length;
 const notVisited = all.filter(r => r.cat === CATS[2]).length;
 const pending = all.filter(r => r.cat === CATS[7]).length;
 const walkins = all.filter(lifeClusterIsWalkin).length;
 const financial = lifeClusterFinancials(all);

 return {
  appointments: all.length,
  pending,
  totalVisits: booked + notBooked,
  booked,
  notBooked,
  notVisited,
  financial,
  joiningRatio: walkins > 0 ? Math.round(booked / walkins * 100) : 0,
  ticket: booked > 0 ? Number(financial.withGst || 0) / booked : 0
 };
}

