let LIFE_3M_BACKGROUND_RUNNING = false;

life3mLoadAllFast = async function(cycles){
 const valid = (cycles || []).filter(c=>c&&c.valid!==false);
 if(!valid.length) return [];

 const key = valid.map(c=>c.from+"|"+c.to).join("||");
 if(LIFE_3M_FAST_CACHE && LIFE_3M_FAST_CACHE_KEY === key) return LIFE_3M_FAST_CACHE;
 if(LIFE_3M_FAST_PROMISE && LIFE_3M_FAST_CACHE_KEY === key) return LIFE_3M_FAST_PROMISE;

 LIFE_3M_FAST_CACHE_KEY = key;

 LIFE_3M_FAST_PROMISE = Promise.all(
  (cycles || []).map(async cycle => {
   if(!cycle || cycle.valid===false){
    return {cycle,raw:[],records:[],invoiceRows:[],financialEvents:[]};
   }

   let raw = [];
   try{ raw = await fetchLeads(cycle.from,cycle.to); }
   catch(error){ console.warn("3M Lead load",cycle.from,cycle.to,error); }

   raw = [...new Map((raw||[]).filter(r=>r&&r.name).map(r=>[r.name,r])).values()];
   return {
    cycle,
    raw,
    records: raw.map(leadRowToRecord),
    invoiceRows: [],
    financialEvents: []
   };
  })
 ).then(datasets=>{
  LIFE_3M_FAST_CACHE = datasets;
  life3mRevenueBackground(cycles,key);
  return datasets;
 });

 try{return await LIFE_3M_FAST_PROMISE;}
 finally{LIFE_3M_FAST_PROMISE=null;}
};

function life3mRevenueBackground(cycles,key){
 if(LIFE_3M_BACKGROUND_RUNNING) return;
 LIFE_3M_BACKGROUND_RUNNING = true;

 Promise.all(
  (cycles || []).map(async cycle=>{
   if(!cycle || cycle.valid===false){
    return {cycle,raw:[],records:[],invoiceRows:[],financialEvents:[]};
   }

   let secure = life3mReadSessionCache(cycle.from,cycle.to);
   if(!secure){
    try{
     secure = await fetchSecureAgentAppointmentLeads(cycle.from,cycle.to);
     life3mWriteSessionCache(cycle.from,cycle.to,secure);
    }catch(error){
     console.warn("3M revenue background",cycle.from,cycle.to,error);
     secure={rows:[],financialEvents:[],ccInvoiceReportSummary:{}};
    }
   }

   const raw=[...new Map((secure.rows||[]).filter(r=>r&&r.name).map(r=>[r.name,r])).values()];
   const summary=secure.ccInvoiceReportSummary||{};
   CC_INVOICE_REPORT_SUMMARY_MAP.set(cycle.from+"|"+cycle.to,summary);

   return {
    cycle,
    raw,
    records:raw.map(leadRowToRecord),
    invoiceRows:Array.isArray(summary.rows)?summary.rows:[],
    financialEvents:Array.isArray(secure.financialEvents)?secure.financialEvents:[]
   };
  })
 ).then(full=>{
  LIFE_3M_BACKGROUND_RUNNING=false;
  if(LIFE_3M_FAST_CACHE_KEY!==key)return;
  LIFE_3M_FAST_CACHE=full;

  const body=byId("life3mComparisonBody");
  if(body){
   body.outerHTML=`<div id="life3mComparisonBody">${life3mComparisonTable(full,LIFE_3M_COMPARE_MODE)}</div>`;
   life3mBindToggle();
  }
 }).catch(error=>{
  LIFE_3M_BACKGROUND_RUNNING=false;
  console.warn("3M revenue refresh",error);
 });
}

