/* =====================================================================
 * FINAL 3-MONTH SEPARATION
 *
 * TAB 1 — CC / Branch Visits:
 *   📊 Last 3 Business Months — Branch-wise Comparison
 *
 * TAB 2 — Agent Report:
 *   📊 Last 3 Business Months — CC Agent-wise Comparison
 *
 * One shared secure request/cache.
 * No Branch table inside Agent tab.
 * No Agent table inside Branch tab.
 * ===================================================================== */

let LIFE_3M_SEP_DATA = null;
let LIFE_3M_SEP_KEY = "";
let LIFE_3M_SEP_PROMISE = null;

function life3mSepTimeout(ms){
 return new Promise((_, reject)=>{
  setTimeout(()=>{
   reject(
    new Error(
     "3-month comparison timed out after " +
     Math.round(ms / 1000) +
     " seconds"
    )
   );
  }, ms);
 });
}

function life3mSepCycles(){
 return (life3mBusinessCycles() || [])
  .filter(cycle => cycle && cycle.valid !== false);
}

async function life3mSepGetData(force){
 const cycles = life3mSepCycles();

 if(cycles.length < 3){
  throw new Error(
   "Unable to resolve the last 3 business-month ranges."
  );
 }

 const from = String(cycles[0].from || "");
 const to = String(
  cycles[cycles.length - 1].to || ""
 );
 const key = from + "|" + to;

 if(
  !force &&
  LIFE_3M_SEP_DATA &&
  LIFE_3M_SEP_KEY === key
 ){
  return LIFE_3M_SEP_DATA;
 }

 if(
  !force &&
  LIFE_3M_SEP_PROMISE &&
  LIFE_3M_SEP_KEY === key
 ){
  return LIFE_3M_SEP_PROMISE;
 }

 LIFE_3M_SEP_KEY = key;

 LIFE_3M_SEP_PROMISE = (async()=>{
  let secure = null;

  try{
   secure = life3mReadSessionCache(
    from,
    to
   );
  }catch(error){
   secure = null;
  }

  if(!secure || force){
   secure = await Promise.race([
    fetchSecureAgentAppointmentLeads(
     from,
     to
    ),
    life3mSepTimeout(45000)
   ]);

   try{
    life3mWriteSessionCache(
     from,
     to,
     secure
    );
   }catch(error){}
  }

  try{
   mergeSecureAllAgentRanking(secure);
  }catch(error){}

  try{
   mergeSecureFinancialEvents(secure);
  }catch(error){}

  try{
   mergeSecureBranchFinancialEvents(secure);
  }catch(error){}

  const raw = [
   ...new Map(
    (
     secure &&
     Array.isArray(secure.rows)
      ? secure.rows
      : []
    )
     .filter(row => row && row.name)
     .map(row => [row.name, row])
   ).values()
  ];

  const mapped = raw.map(
   leadRowToRecord
  );

  const invoiceSummary =
   secure &&
   secure.ccInvoiceReportSummary &&
   typeof secure.ccInvoiceReportSummary === "object"
    ? secure.ccInvoiceReportSummary
    : {};

  const invoiceRows =
   Array.isArray(invoiceSummary.rows)
    ? invoiceSummary.rows
    : [];

  const financialEvents =
   secure &&
   Array.isArray(secure.financialEvents)
    ? secure.financialEvents
    : [];

  CC_INVOICE_REPORT_SUMMARY_MAP.set(
   key,
   invoiceSummary
  );

  const datasets = cycles.map(cycle => ({
   cycle,
   raw,
   records:mapped,
   invoiceRows,
   financialEvents
  }));

  LIFE_3M_SEP_DATA = datasets;

  console.log(
   "3M SEPARATED shared data ready",
   {
    from,
    to,
    leads:raw.length,
    financial_events:financialEvents.length
   }
  );

  return datasets;
 })();

 try{
  return await LIFE_3M_SEP_PROMISE;
 }finally{
  LIFE_3M_SEP_PROMISE = null;
 }
}


