/* =====================================================================
 * 3M FINAL DATA FIX — REMOVE FALSE 45-SECOND TIMEOUT
 * ---------------------------------------------------------------------
 * Console proved:
 * - fetchSecureAgentAppointmentLeads() DOES finish
 * - previous Promise.race timeout rejects before ERP responds
 * - ERP response arrives later and gets discarded
 *
 * This override:
 * - removes timeout completely
 * - uses ONE shared request for Branch + Agent
 * - keeps loading text visible until ERP really finishes
 * - both reports render from the same resolved dataset
 * ===================================================================== */

LIFE_3M_SEP_PROMISE = null;

async function life3mSepGetData(force){
 const cycles = life3mSepCycles();

 if(cycles.length < 3){
  throw new Error(
   "Unable to resolve the last 3 business-month ranges."
  );
 }

 const from = String(
  cycles[0].from || ""
 );

 const to = String(
  cycles[cycles.length - 1].to || ""
 );

 const key = from + "|" + to;

 /*
  * Reuse finished data.
  */
 if(
  !force &&
  LIFE_3M_SEP_DATA &&
  LIFE_3M_SEP_KEY === key
 ){
  return LIFE_3M_SEP_DATA;
 }

 /*
  * Reuse the SAME running request for Branch + Agent.
  */
 if(
  !force &&
  LIFE_3M_SEP_PROMISE &&
  LIFE_3M_SEP_KEY === key
 ){
  console.log(
   "3M shared request already running — reusing it"
  );

  return LIFE_3M_SEP_PROMISE;
 }

 LIFE_3M_SEP_KEY = key;

 LIFE_3M_SEP_PROMISE =
  (async()=>{
   let secure = null;

   /*
    * First reuse browser/session cache if already available.
    */
   try{
    secure =
     life3mReadSessionCache(
      from,
      to
     );
   }catch(error){
    secure = null;
   }

   if(
    !secure ||
    force
   ){
    console.log(
     "3M shared secure request started",
     {
      from,
      to
     }
    );

    /*
     * IMPORTANT:
     * NO Promise.race.
     * NO 45-second timeout.
     * Wait for the real ERP response.
     */
    secure =
     await fetchSecureAgentAppointmentLeads(
      from,
      to
     );

    console.log(
     "3M shared secure request finished",
     {
      from,
      to,
      rows:
       secure &&
       Array.isArray(secure.rows)
        ?secure.rows.length
        :0
     }
    );

    try{
     life3mWriteSessionCache(
      from,
      to,
      secure
     );
    }catch(error){}
   }else{
    console.log(
     "3M using cached secure response",
     {
      from,
      to,
      rows:
       secure &&
       Array.isArray(secure.rows)
        ?secure.rows.length
        :0
     }
    );
   }

   try{
    mergeSecureAllAgentRanking(
     secure
    );
   }catch(error){}

   try{
    mergeSecureFinancialEvents(
     secure
    );
   }catch(error){}

   try{
    mergeSecureBranchFinancialEvents(
     secure
    );
   }catch(error){}

   const raw = [
    ...new Map(
     (
      secure &&
      Array.isArray(secure.rows)
       ?secure.rows
       :[]
     )
      .filter(
       row=>
        row &&
        row.name
      )
      .map(
       row=>[
        row.name,
        row
       ]
      )
    ).values()
   ];

   /*
    * Convert once for both tables.
    */
   const mapped =
    raw.map(
     leadRowToRecord
    );

   const invoiceSummary =
    secure &&
    secure.ccInvoiceReportSummary &&
    typeof secure.ccInvoiceReportSummary ===
     "object"
     ?secure.ccInvoiceReportSummary
     :{};

   const invoiceRows =
    Array.isArray(
     invoiceSummary.rows
    )
     ?invoiceSummary.rows
     :[];

   const financialEvents =
    secure &&
    Array.isArray(
     secure.financialEvents
    )
     ?secure.financialEvents
     :[];

   CC_INVOICE_REPORT_SUMMARY_MAP.set(
    key,
    invoiceSummary
   );

   const datasets =
    cycles.map(cycle=>({
     cycle,
     raw,
     records:mapped,
     invoiceRows,
     financialEvents
    }));

   LIFE_3M_SEP_DATA =
    datasets;

   console.log(
    "3M shared dataset ready",
    {
     from,
     to,
     leads:raw.length,
     financial_events:
      financialEvents.length,
     months:
      cycles.map(c=>c.label)
    }
   );

   return datasets;
  })();

 try{
  return await LIFE_3M_SEP_PROMISE;
 }catch(error){
  /*
   * Real ERP/network error only.
   */
  LIFE_3M_SEP_DATA = null;

  console.error(
   "3M real request failed",
