/* =====================================================================
 * 3M PROGRESSIVE FINAL FIX
 * ---------------------------------------------------------------------
 * - 3 smaller secure month requests run in parallel
 * - comparison table appears immediately
 * - each month replaces its placeholder as soon as it finishes
 * - Branch-wise stays in Branch tab
 * - Agent-wise stays in Agent tab
 * - zoom is normal-flow BELOW comparison, never overlaying table
 * ===================================================================== */

const LIFE_3M_PROGRESS = new Map();
let LIFE_3M_PROGRESS_RUN = 0;

function life3mProgressEmptyDataset(cycle){
 return {
  cycle:cycle,
  raw:[],
  records:[],
  invoiceRows:[],
  financialEvents:[],
  _loading:true
 };
}

function life3mProgressStatusHtml(cycles){
 const states = (cycles||[]).map(cycle=>{
  const key = life3mCompareKey(cycle);
  const state = LIFE_3M_PROGRESS.get(key);

  if(state && state.done){
   return `<span class="life3m-progress-done">✓ ${lifeCcEsc(cycle.label)}</span>`;
  }

  if(state && state.error){
   return `<span class="life3m-progress-error">! ${lifeCcEsc(cycle.label)}</span>`;
  }

  return `<span class="life3m-progress-loading">… ${lifeCcEsc(cycle.label)}</span>`;
 }).join("");

 return `
  <div class="life3m-progress-status">
   ${states}
  </div>`;
}

function life3mProgressCurrentDatasets(cycles){
 return (cycles||[]).map(cycle=>{
  const key = life3mCompareKey(cycle);
  const state = LIFE_3M_PROGRESS.get(key);

  if(state && state.dataset){
   return state.dataset;
  }

  return life3mProgressEmptyDataset(cycle);
 });
}

function life3mProgressRenderBranch(cycles){
 const body = byId("life3mSepBranchBody");
 if(!body) return;

 const datasets =
  life3mProgressCurrentDatasets(cycles);

 body.innerHTML =
  life3mProgressStatusHtml(cycles) +
  life3mComparisonTable(
   datasets,
   "branch"
  );
}

function life3mProgressRenderAgent(cycles){
 const body = byId("life3mSepAgentBody");
 if(!body) return;

 const datasets =
  life3mProgressCurrentDatasets(cycles);

 body.innerHTML =
  life3mProgressStatusHtml(cycles) +
  life3mComparisonTable(
   datasets,
   "agent"
  );
}

function life3mProgressRenderBoth(cycles){
 life3mProgressRenderBranch(cycles);
 life3mProgressRenderAgent(cycles);
 life3mMoveZoomBelowComparisons();
}

async function life3mProgressLoadCycle(cycle,runId,force){
 const key = life3mCompareKey(cycle);

 if(
  !force &&
  LIFE_3M_PROGRESS.has(key) &&
  LIFE_3M_PROGRESS.get(key).done
 ){
  return LIFE_3M_PROGRESS.get(key).dataset;
 }

 const existing =
  LIFE_3M_PROGRESS.get(key);

 if(
  !force &&
  existing &&
  existing.promise
 ){
  return existing.promise;
 }

 const state = {
  done:false,
  error:false,
  dataset:null,
  promise:null
 };

 LIFE_3M_PROGRESS.set(
  key,
  state
 );

 const promise = (async()=>{
  try{
   let secure = null;

   try{
    secure =
     life3mReadSessionCache(
      cycle.from,
      cycle.to
     );
   }catch(error){
    secure = null;
   }

   if(!secure || force){
    console.log(
     "3M progressive month request started",
     {
      label:cycle.label,
      from:cycle.from,
      to:cycle.to
     }
    );

    /*
     * Direct month-sized secure request.
     * NO artificial timeout.
     */
    secure =
     await fetchSecureAgentAppointmentLeads(
      cycle.from,
      cycle.to
     );

    try{
     life3mWriteSessionCache(
      cycle.from,
      cycle.to,
      secure
     );
    }catch(error){}
   }

   if(runId !== LIFE_3M_PROGRESS_RUN){
    return null;
   }

   try{
    mergeSecureAllAgentRanking(
     secure
    );
   }catch(error){}

   try{
    mergeSecureFinancialEvents(
     secure
    );
   }catch(error){}

   try{
    mergeSecureBranchFinancialEvents(
     secure
    );
   }catch(error){}

   const raw = [
    ...new Map(
     (
      secure &&
      Array.isArray(secure.rows)
       ?secure.rows
       :[]
     )
      .filter(row=>row&&row.name)
      .map(row=>[
       row.name,
       row
      ])
    ).values()
   ];

   const invoiceSummary =
    secure &&
    secure.ccInvoiceReportSummary &&
    typeof secure.ccInvoiceReportSummary === "object"
     ?secure.ccInvoiceReportSummary
     :{};

   const invoiceRows =
    Array.isArray(invoiceSummary.rows)
     ?invoiceSummary.rows
     :[];

   const financialEvents =
    secure &&
    Array.isArray(secure.financialEvents)
     ?secure.financialEvents
     :[];

   CC_INVOICE_REPORT_SUMMARY_MAP.set(
    key,
    invoiceSummary
   );

   const dataset = {
    cycle:cycle,
    raw:raw,
    records:raw.map(leadRowToRecord),
    invoiceRows:invoiceRows,
    financialEvents:financialEvents,
    _loading:false
   };

   state.dataset = dataset;
   state.done = true;
   state.error = false;

   console.log(
    "3M progressive month ready",
    {
     label:cycle.label,
     rows:raw.length,
     financial_events:
      financialEvents.length
    }
   );

   return dataset;

  }catch(error){
   state.error = true;
   state.done = false;

   console.error(
    "3M progressive month failed",
    cycle && cycle.label,
    error
   );

   return null;

  }finally{
   state.promise = null;

   if(runId === LIFE_3M_PROGRESS_RUN){
    life3mProgressRenderBoth(
     life3mSepCycles()
    );
   }
  }
 })();

 state.promise = promise;

 return promise;
}

async function life3mProgressStart(force){
 const cycles =
  life3mSepCycles();

 if(cycles.length < 3){
  return;
 }

 const runId =
  ++LIFE_3M_PROGRESS_RUN;

 if(force){
  cycles.forEach(cycle=>{
   LIFE_3M_PROGRESS.delete(
    life3mCompareKey(cycle)
   );
  });
 }

 /*
  * FIRST PAINT IMMEDIATELY.
  * Users see table structure, month headers and progress badges now.
  */
 life3mProgressRenderBoth(
  cycles
 );

 /*
  * Start the three smaller month calls simultaneously.
  * Do not wait sequentially.
  */
 await Promise.allSettled(
  cycles.map(cycle=>
   life3mProgressLoadCycle(
    cycle,
    runId,
    !!force
   )
  )
 );

 if(runId === LIFE_3M_PROGRESS_RUN){
  life3mProgressRenderBoth(
   cycles
  );

  console.log(
   "3M progressive comparison complete"
  );
 }
}


