/* =====================================================================
 * 3M MEMORY-CACHE FINAL FIX
 * ---------------------------------------------------------------------
 * Do NOT launch 3 new historical API requests.
 *
 * 1) Build Branch/Agent comparison immediately from raw Lead rows that
 *    the dashboard has ALREADY loaded into LIFE_CC_FUNNEL_ROWS_MAP.
 * 2) Reuse global FINANCIAL_EVENTS already loaded by secure API.
 * 3) Reuse the existing rolling-3-month loader
 *    lifeCcEnsure3mAppointments(TODAY) for ONE background refresh only.
 * 4) Repaint when that existing request finishes.
 * 5) Ensure zoom exists and place it below Branch 3M comparison.
 * ===================================================================== */

let LIFE_3M_MEMORY_REFRESH_RUNNING=false;

function life3mMemoryAllRawRows(){
 const byName=new Map();

 try{
  LIFE_CC_FUNNEL_ROWS_MAP.forEach(rows=>{
   (Array.isArray(rows)?rows:[])
    .forEach(row=>{
     if(
      row&&
      row.name
     ){
      byName.set(
       row.name,
       row
      );
     }
    });
  });
 }catch(error){}

 return [
  ...byName.values()
 ];
}

function life3mMemoryDatasets(){
 const cycles=
  life3mSepCycles();

 const raw=
  life3mMemoryAllRawRows();

 /*
  * Financial events are already merged globally whenever fetchLeads()
  * / secure Agent data runs.
  */
 const financialEvents=
  Array.isArray(FINANCIAL_EVENTS)
   ?FINANCIAL_EVENTS.slice()
   :[];

 const records=
  raw.map(
   leadRowToRecord
  );

 return cycles.map(cycle=>({
  cycle,
  raw,
  records,
  invoiceRows:[],
  financialEvents,
  _memory:true
 }));
}

function life3mMemoryHasUsefulData(
 datasets
){
 if(
  !Array.isArray(datasets)||
  !datasets.length
 ){
  return false;
 }

 return datasets.some(data=>{
  const branchIndex=
   life3mBuildMetricIndex(
    data
   ).branch;

  let found=false;

  branchIndex.forEach(metric=>{
   if(
    Number(metric.leads||0)||
    Number(metric.walkins||0)||
    Number(metric.joined||0)||
    Number(metric.revenue||0)
   ){
    found=true;
   }
  });

  return found;
 });
}

function life3mMemoryRender(){
 const datasets=
  life3mMemoryDatasets();

 const branchBody=
  byId("life3mSepBranchBody");

 const agentBody=
  byId("life3mSepAgentBody");

 if(branchBody){
  if(
   life3mMemoryHasUsefulData(
    datasets
   )
  ){
   branchBody.innerHTML=`
    <div class="life3m-memory-note">
     Showing data already loaded by the dashboard. Historical cache refresh continues in background.
    </div>
    ${
     life3mComparisonTable(
      datasets,
      "branch"
     )
    }`;
  }else{
   branchBody.innerHTML=`
    <div class="life3m-memory-note">
     Preparing historical 3-month data from the dashboard cache…
    </div>
    ${
     life3mComparisonTable(
      datasets,
      "branch"
     )
    }`;
  }
 }

 if(agentBody){
