     life3mMemoryHasUsefulData(datasets)
      ?"Showing data already loaded by the dashboard."
      :"Preparing historical 3-month data from the dashboard cache…"
    }
   </div>
   ${
    life3mComparisonTable(
     datasets,
     "agent"
    )
   }`;
 }

 lifeEnsureZoomBelow3m();
}

async function life3mMemoryRefreshOnce(
 force
){
 if(
  LIFE_3M_MEMORY_REFRESH_RUNNING
 ){
  return;
 }

 LIFE_3M_MEMORY_REFRESH_RUNNING=true;

 try{
  /*
   * Reuse the dashboard's EXISTING rolling 3-month loader.
   * It has its own promise/cache and therefore cannot create
   * duplicate rolling requests.
   */
  if(force){
   const rolling=
    lifeCc3mRange(TODAY);

   const key=
    rolling.from+
    "|"+
    rolling.to;

   LIFE_CC_3M_APPOINTMENT_CACHE.delete(
    key
   );
  }

  await lifeCcEnsure3mAppointments(
   TODAY
  );

  /*
   * fetchLeads() inside the existing rolling loader stores raw rows
   * into LIFE_CC_FUNNEL_ROWS_MAP and merges financial events.
   */
  /*
   * LIFE_3M_METRIC_INDEX_CACHE is a const WeakMap.
   * Do not reassign it. New dataset objects naturally get fresh WeakMap keys.
   */

  life3mMemoryRender();

  console.log(
   "3M memory-cache comparison refreshed",
   {
    raw_rows:
     life3mMemoryAllRawRows().length,
    financial_events:
     Array.isArray(FINANCIAL_EVENTS)
      ?FINANCIAL_EVENTS.length
      :0
   }
  );

 }catch(error){
  console.warn(
   "3M rolling cache refresh failed",
   error
  );

  /*
   * Keep already-rendered memory data on screen.
   */
 }finally{
  LIFE_3M_MEMORY_REFRESH_RUNNING=false;
 }
}


