function lifeEnsureZoomControl(){
 let zoom=
  byId("lccZoom");

 if(zoom){
  return zoom;
 }

 /*
  * The original buildZoom() is scoped inside an IIFE.
  * Recreate the exact same control when an older patch removed it.
  */
 zoom=
  document.createElement(
   "div"
  );

 zoom.id=
  "lccZoom";

 zoom.innerHTML=`
  <button
   type="button"
   data-z="-1"
   title="Smaller text"
  >A−</button>

  <span id="lccZoomVal">
   100%
  </span>

  <button
   type="button"
   data-z="1"
   title="Larger text"
  >A+</button>

  <button
   type="button"
   data-z="0"
   title="Reset size"
  >⟲</button>`;

 let scale=1;

 try{
  scale=
   parseFloat(
    localStorage.getItem(
     "lccUiScale"
    )
   )||1;
 }catch(error){}

 const apply=()=>{
  scale=
   Math.min(
    1.4,
    Math.max(
     0.85,
     Math.round(
      scale*100
     )/100
    )
   );

  document.documentElement
   .style.setProperty(
    "--lcc-zoom",
    scale
   );

  const value=
   byId("lccZoomVal");

  if(value){
   value.textContent=
    Math.round(
     scale*100
    )+
    "%";
  }

  try{
   localStorage.setItem(
    "lccUiScale",
    scale
   );
  }catch(error){}
 };

 zoom.addEventListener(
  "click",
  event=>{
   const button=
    event.target.closest(
     "button"
    );

   if(!button)return;

   const delta=
    Number(
     button.getAttribute(
      "data-z"
     )
    );

   scale=
    delta===0
     ?1
     :scale+
      delta*0.05;

   apply();
  }
 );

 document.body.appendChild(
  zoom
 );

 apply();

 return zoom;
}

