/* =====================================================================
 * 3M FULL DEFAULT DATA — AUTHORITATIVE FIX
 * ---------------------------------------------------------------------
 * Problem with previous version:
 * LIFE_CC_FUNNEL_ROWS_MAP may contain only current/partial ranges,
 * therefore JUL/AUG can show 0 even though historical ERP data exists.
 *
 * Correct behavior:
 * - Start ONE rolling 3-month secure load automatically.
 * - Cache the FULL secure response BEFORE fetchLeads() filters it.
 * - Use that complete raw secure dataset for JUL/AUG/SEP business months.
 * - Branch tab shows Branch-wise.
 * - Agent tab shows CC Agent-wise.
 * - No partial-memory table is presented as final data.
 * - Zoom is always visible below the comparison.
 * ===================================================================== */

const LIFE_3M_FULL_SECURE_CACHE = new Map();
let LIFE_3M_FULL_DATA_PROMISE = null;
let LIFE_3M_FULL_DATA = null;
let LIFE_3M_FULL_DATA_KEY = "";


/* ---------------------------------------------------------------------
 * Capture the complete secure payload for any non-agent range.
 * --------------------------------------------------------------------- */
const LIFE_3M_SECURE_FETCH_BASE =
 fetchSecureAgentAppointmentLeads;

fetchSecureAgentAppointmentLeads =
 async function(
  from,
  to,
  agentOwner
 ){
  const result =
   await LIFE_3M_SECURE_FETCH_BASE(
    from,
    to,
    agentOwner
   );

  if(
   !String(agentOwner||"").trim()
  ){
   LIFE_3M_FULL_SECURE_CACHE.set(
    String(from||"")+
    "|"+
    String(to||""),
    result
   );
  }

  return result;
 };


