function life3mFullBuildDatasets(
 secure
){
 const cycles =
  life3mSepCycles();

 const raw = [
  ...new Map(
   (
    secure &&
    Array.isArray(secure.rows)
     ?secure.rows
     :[]
   )
    .filter(
     row=>
      row &&
      row.name
    )
    .map(
     row=>[
      row.name,
      row
     ]
    )
  ).values()
 ];

 const records =
  raw.map(
   leadRowToRecord
  );

 const invoiceSummary =
  secure &&
  secure.ccInvoiceReportSummary &&
  typeof secure.ccInvoiceReportSummary ===
   "object"
   ?secure.ccInvoiceReportSummary
   :{};

 const invoiceRows =
  Array.isArray(
   invoiceSummary.rows
  )
   ?invoiceSummary.rows
   :[];

 const financialEvents =
  secure &&
  Array.isArray(
   secure.financialEvents
  )
   ?secure.financialEvents
   :[];

 /*
  * Keep all normal dashboard financial caches synchronized.
  */
 try{
  mergeSecureAllAgentRanking(
   secure
  );
 }catch(error){}

 try{
  mergeSecureFinancialEvents(
   secure
  );
 }catch(error){}

 try{
  mergeSecureBranchFinancialEvents(
   secure
  );
 }catch(error){}

 return cycles.map(
  cycle=>({
   cycle,
   raw,
   records,
   invoiceRows,
   financialEvents
  })
 );
}


async function life3mFullGetData(
 force
){
 const range =
  life3mFullRollingRange();

 const key =
  String(range.from||"")+
  "|"+
  String(range.to||"");

 if(
  !force &&
  LIFE_3M_FULL_DATA &&
  LIFE_3M_FULL_DATA_KEY === key
 ){
  return LIFE_3M_FULL_DATA;
 }

 if(
  !force &&
  LIFE_3M_FULL_DATA_PROMISE &&
  LIFE_3M_FULL_DATA_KEY === key
 ){
  return LIFE_3M_FULL_DATA_PROMISE;
 }

 LIFE_3M_FULL_DATA_KEY =
  key;

 LIFE_3M_FULL_DATA_PROMISE =
  (async()=>{
   let secure =
    !force
     ?LIFE_3M_FULL_SECURE_CACHE.get(
       key
      )
     :null;

   if(!secure){
    /*
     * First reuse the dashboard's own rolling 3-month loader.
     * fetchLeads() inside that loader calls our wrapped secure fetch,
     * which stores the COMPLETE secure payload above.
     */
    if(force){
     LIFE_CC_3M_APPOINTMENT_CACHE.delete(
      key
     );

     LIFE_CC_3M_APPOINTMENT_PROMISES.delete(
      key
     );
    }

    console.log(
     "3M FULL rolling load started",
     range
    );

    await lifeCcEnsure3mAppointments(
     TODAY
    );

    secure =
     LIFE_3M_FULL_SECURE_CACHE.get(
      key
     );
   }

   /*
    * Defensive fallback:
    * if another earlier code path bypassed the wrapper,
    * perform ONE direct full secure request.
    */
   if(!secure){
    console.log(
     "3M FULL direct secure fallback started",
     range
    );

    secure =
     await fetchSecureAgentAppointmentLeads(
      range.from,
      range.to
     );
   }

   const datasets =
    life3mFullBuildDatasets(
     secure
    );

   LIFE_3M_FULL_DATA =
    datasets;

   /*
    * LIFE_3M_METRIC_INDEX_CACHE is declared const.
    * No reset is required because these are new dataset objects.
    */

   console.log(
    "3M FULL default dataset ready",
    {
     range,
     raw_rows:
      secure &&
      Array.isArray(secure.rows)
       ?secure.rows.length
       :0,
     financial_events:
      secure &&
      Array.isArray(
       secure.financialEvents
      )
       ?secure.financialEvents.length
       :0,
     months:
      datasets.map(
       data=>data.cycle.label
      )
    }
   );

   return datasets;
  })();

 try{
  return await LIFE_3M_FULL_DATA_PROMISE;
 }finally{
  LIFE_3M_FULL_DATA_PROMISE =
   null;
 }
}


