/* =====================================================================
 * 3M COMPARISON — FOLLOW THE ACTUAL BRANCH / CC AGENT MODE
 * ---------------------------------------------------------------------
 * setGrp("branch") -> GRP = "branch" -> render()
 * setGrp("agent")  -> GRP = "agent"  -> render()
 *
 * renderSummary() already calls:
 *     life3mInstallLazyComparisonShell(GRP)
 *
 * Therefore use ONE comparison host inside #sumWrap and render exactly
 * the same mode as the current summary.
 * ===================================================================== */

let LIFE_3M_MODE_RENDER_TOKEN = 0;

function life3mModeRemoveOldHosts(){
 [
  "life3mComparisonHost",
  "life3mSafeHost",
  "life3mV2Host",
  "life3mFinalHost",
  "life3mForceHost",
  "life3mCorrectHost",
  "life3mSepBranchHost",
  "life3mSepAgentHost",
  "life3mModeHost"
 ].forEach(id=>{
  const node = byId(id);
  if(node){
   node.remove();
  }
 });
}

function life3mModeNormalize(mode){
 return String(mode || GRP || "branch")
  .toLowerCase() === "agent"
   ? "agent"
   : "branch";
}

function life3mModeLabel(mode){
 return mode === "agent"
  ? "CC Agent-wise"
  : "Branch-wise";
}

function life3mModeHost(mode){
 const sumWrap = byId("sumWrap");
 if(!sumWrap) return null;

 /*
  * renderSummary() recreates #sumWrap contents first, so removing
  * old 3M hosts here is safe and guarantees no stale Branch table.
  */
 life3mModeRemoveOldHosts();

 const host = document.createElement("div");
 host.id = "life3mModeHost";
 host.dataset.mode = mode;

 sumWrap.appendChild(host);

 return host;
}

function life3mModeShell(mode){
 const host = life3mModeHost(mode);
 if(!host) return null;

 const label = life3mModeLabel(mode);

 host.innerHTML = `
  <div class="life3m-mode-card">
   <div class="life3m-mode-head">
    <div>
     <h3>📊 Last 3 Business Months Comparison</h3>
     <small>${lifeCcEsc(label)}</small>
    </div>

    <button
     type="button"
     id="life3mModeRefresh"
     class="btn btn-o"
    >
     Refresh
    </button>
   </div>

   <div
    id="life3mModeBody"
    class="life3m-mode-body"
   >
    <div class="life3m-mode-loading">
     <b>Loading ${lifeCcEsc(label)} 3-month comparison…</b>
     <span>
      Using the complete rolling 3-month ERP dataset.
     </span>
    </div>
   </div>
  </div>`;

 const refresh = byId("life3mModeRefresh");

 if(refresh){
  refresh.onclick = ()=>{
   life3mModeLoad(
    life3mModeNormalize(GRP),
    true
   );
  };
 }

 return host;
}

async function life3mModeLoad(mode, force){
 mode = life3mModeNormalize(mode);

 const token = ++LIFE_3M_MODE_RENDER_TOKEN;

 const host = byId("life3mModeHost");
 const body = byId("life3mModeBody");

 /*
  * If renderSummary() already switched mode, abandon this request's UI.
  */
 if(
  !host ||
  host.dataset.mode !== mode ||
  !body
 ){
  return;
 }

 body.innerHTML = `
  <div class="life3m-mode-loading">
   <b>Loading ${lifeCcEsc(life3mModeLabel(mode))} 3-month comparison…</b>
   <span>
    Using the complete rolling 3-month ERP dataset.
   </span>
  </div>`;

 try{
  /*
   * Use the corrected full-data loader already present in this file.
   * Branch and Agent views share this same complete dataset.
   */
  const datasets =
   await life3mFullGetData(
    !!force
   );

  if(
   token !== LIFE_3M_MODE_RENDER_TOKEN
  ){
   return;
  }

  const currentHost =
   byId("life3mModeHost");

  const currentBody =
   byId("life3mModeBody");

  /*
   * Critical stale-render protection:
   * if user changed Branch-wise <-> CC Agent-wise while the API
   * request was running, never paint the old mode.
   */
  if(
   !currentHost ||
   !currentBody ||
   currentHost.dataset.mode !== mode ||
   life3mModeNormalize(GRP) !== mode
  ){
   return;
  }

  currentBody.innerHTML =
   life3mComparisonTable(
    datasets,
    mode
   );

  console.log(
   "3M MODE rendered",
   {
    grp:GRP,
    mode:mode,
    label:life3mModeLabel(mode)
   }
  );

 }catch(error){
  console.error(
   "3M MODE failed",
   {
    mode,
    error
   }
  );

  const currentBody =
   byId("life3mModeBody");

  const currentHost =
   byId("life3mModeHost");

  if(
   currentBody &&
   currentHost &&
   currentHost.dataset.mode === mode
  ){
   currentBody.innerHTML = `
    <div class="life3m-mode-error">
     <b>
      Could not load ${lifeCcEsc(life3mModeLabel(mode))} 3-month comparison.
     </b>
     <span>
      ${lifeCcEsc(
       error &&
       error.message
        ? error.message
        : "ERP request failed"
      )}
     </span>
    </div>`;
  }
 }
}


