/* =====================================================================
 * AREA MANAGER LOGIN — BRANCH SCOPE
 * ---------------------------------------------------------------------
 * If the logged-in ERP user maps to an active Employee whose designation
 * contains "Area Manager":
 *
 * - allowed branches = custom_branch_list + primary branch
 * - Testing Branch excluded
 * - Head Office excluded unless explicitly mapped and desired by backend
 * - all dashboard record filtering is restricted to those branches
 * - Branch dropdown shows only those branches
 * - "All Branches" means all branches assigned to that Area Manager
 *
 * Other users keep existing behavior.
 * ===================================================================== */

let LIFE_AREA_MANAGER_SCOPE_READY = false;
let LIFE_AREA_MANAGER_SCOPE_LOADING = false;
let LIFE_AREA_MANAGER_SCOPE = null;

function lifeAreaManagerNormalizeBranch(value){
 return String(value || "")
  .trim()
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "");
}

function lifeAreaManagerSplitBranches(employee){
 const result = [];
 const seen = new Set();

 function add(value){
  const label = String(value || "").trim();
  if(!label) return;

  const key = lifeAreaManagerNormalizeBranch(label);
  if(!key) return;

  if(
   key === "testingbranch" ||
   key === "testing"
  ){
   return;
  }

  if(seen.has(key)) return;

  seen.add(key);
  result.push(label);
 }

 String(
  employee &&
  employee.custom_branch_list ||
  ""
 )
  .split(/[\n,;|]+/)
  .forEach(add);

 add(
  employee &&
  employee.branch
 );

 return result;
}

function lifeAreaManagerIsDesignation(value){
 return String(value || "")
  .trim()
  .toLowerCase()
  .includes("area manager");
}

function lifeAreaManagerScopeSet(){
 if(
  !LIFE_AREA_MANAGER_SCOPE ||
  !Array.isArray(
   LIFE_AREA_MANAGER_SCOPE.branches
  )
 ){
  return new Set();
 }

 return new Set(
  LIFE_AREA_MANAGER_SCOPE.branches
   .map(
    lifeAreaManagerNormalizeBranch
   )
   .filter(Boolean)
 );
}

function lifeAreaManagerBranchAllowed(branch){
 if(
  !LIFE_AREA_MANAGER_SCOPE ||
  !LIFE_AREA_MANAGER_SCOPE.isAreaManager
 ){
  return true;
 }

 const key =
  lifeAreaManagerNormalizeBranch(
   branch
  );

 if(!key) return false;

 return lifeAreaManagerScopeSet()
  .has(key);
}

async function lifeLoadAreaManagerScope(){
 if(
  LIFE_AREA_MANAGER_SCOPE_READY
 ){
  return LIFE_AREA_MANAGER_SCOPE;
 }

 if(
  LIFE_AREA_MANAGER_SCOPE_LOADING
 ){
  /*
   * Wait briefly for the existing lookup.
   */
  while(
   LIFE_AREA_MANAGER_SCOPE_LOADING
  ){
   await new Promise(
    resolve =>
     setTimeout(resolve,50)
   );
  }

  return LIFE_AREA_MANAGER_SCOPE;
 }

 LIFE_AREA_MANAGER_SCOPE_LOADING = true;

 try{
  const user =
   String(
    currentPortalUser &&
    currentPortalUser() ||
    frappe &&
    frappe.session &&
    frappe.session.user ||
    ""
   ).trim();

  if(
   !user ||
   user === "Guest"
  ){
   LIFE_AREA_MANAGER_SCOPE = {
    isAreaManager:false,
    user:user,
    employee:null,
    branches:[]
   };

   return LIFE_AREA_MANAGER_SCOPE;
  }

  let rows = [];

  /*
   * Find Employee by user_id.
   */
  try{
   rows = await apiGetList(
    "Employee",
    [
     "name",
     "employee_name",
     "designation",
     "branch",
     "custom_branch_list",
     "user_id",
     "status"
    ],
    [
     ["user_id","=",user],
     ["status","=","Active"]
    ],
    {
     limit_page_length:5
    }
   );
  }catch(error){
   console.warn(
    "Area Manager Employee lookup failed",
    error
   );
  }

  const employee =
   Array.isArray(rows) &&
   rows.length
    ? rows[0]
    : null;

  const isAreaManager =
   !!(
    employee &&
    lifeAreaManagerIsDesignation(
     employee.designation
    )
   );

  const branches =
   isAreaManager
    ? lifeAreaManagerSplitBranches(
      employee
     )
    : [];

  LIFE_AREA_MANAGER_SCOPE = {
   isAreaManager,
   user,
   employee,
   branches,
   branchKeys:
    branches.map(
     lifeAreaManagerNormalizeBranch
    )
  };

  console.log(
   "Area Manager branch scope",
   {
    user,
    employee:
     employee &&
     employee.name,
    designation:
     employee &&
     employee.designation,
    branches,
    active:isAreaManager
   }
  );

  return LIFE_AREA_MANAGER_SCOPE;

 }finally{
  LIFE_AREA_MANAGER_SCOPE_LOADING = false;
  LIFE_AREA_MANAGER_SCOPE_READY = true;
 }
}


