function lifeAreaManagerRestrictBranchSelect(){
 if(
  !LIFE_AREA_MANAGER_SCOPE ||
  !LIFE_AREA_MANAGER_SCOPE.isAreaManager
 ){
  return;
 }

 const select =
  byId("fBranch");

 if(!select) return;

 const allowed =
  lifeAreaManagerScopeSet();

 const current =
  String(
   F.branch ||
   select.value ||
   ""
  ).trim();

 /*
  * Remove unauthorized branch options.
  */
 [
  ...select.options
 ].forEach(option=>{
  const value =
   String(
    option.value ||
    option.textContent ||
    ""
   ).trim();

  if(
   !value ||
   value === "All Branches"
  ){
   return;
  }

  const key =
   lifeAreaManagerNormalizeBranch(
    value
   );

  if(
   !allowed.has(key)
  ){
   option.remove();
  }
 });

 /*
  * If current branch was unauthorized, reset to All Branches.
  */
 if(
  current &&
  current !== "All Branches" &&
  !allowed.has(
   lifeAreaManagerNormalizeBranch(
    current
   )
  )
 ){
  F.branch = "";
  select.value = "";
 }

 /*
  * Clarify what All Branches means for Area Manager.
  */
 const first =
  select.options &&
  select.options.length
   ? select.options[0]
   : null;

 if(
  first &&
  !String(first.value||"").trim()
 ){
  first.textContent =
   "All Assigned Branches";
 }
}


