  */
 if(
  typeof LIFE_CLUSTER_CACHE !== "undefined" &&
  LIFE_CLUSTER_CACHE instanceof Map &&
  LIFE_CLUSTER_CACHE.has(key)
 ){
  return (LIFE_CLUSTER_CACHE.get(key) || [])
   .map(row => Object.assign({}, row));
 }

 /*
  * Current dashboard range: reuse already loaded mapped records.
  */
 if(
  String(F && F.from || "") === String(from || "") &&
  String(F && F.to || "") === String(to || "") &&
  Array.isArray(RECORDS)
 ){
  const rows = RECORDS
   .map(row => Object.assign({}, row));

  if(
   typeof LIFE_CLUSTER_CACHE !== "undefined" &&
   LIFE_CLUSTER_CACHE instanceof Map
  ){
   LIFE_CLUSTER_CACHE.set(
    key,
    rows.map(row => Object.assign({}, row))
   );
  }

  return rows;
 }

 /*
  * Different date range: only fetch Leads first.
  * This is the fastest usable dataset for first paint.
  */
 const raw = await fetchLeads(from, to);

 const unique = [
  ...new Map(
   (raw || [])
    .filter(row => row && row.name)
