async function lifeClusterApplyRange(from, to, mode){
 from = String(from || "");
 to = String(to || "");

 if(!from || !to){
  toast("Select From and To dates");
  return;
 }

 if(from > to){
  toast("From date cannot be after To date");
  return;
 }

 LIFE_CLUSTER_FILTER.from = from;
 LIFE_CLUSTER_FILTER.to = to;
 LIFE_CLUSTER_QUICK = mode || "";

 const requestId = ++LIFE_CLUSTER_FAST_REQUEST_ID;
 window.LIFE_CLUSTER_FAST_REQUEST_ID =
  LIFE_CLUSTER_FAST_REQUEST_ID;
 const key = lifeClusterRangeKey(from, to);

 /*
  * Update controls immediately.
  */
 const fromInput = byId("lifeClusterFromDate");
 const toInput = byId("lifeClusterToDate");

 if(fromInput) fromInput.value = from;
 if(toInput) toInput.value = to;

 lifeClusterFastStatus(
  "Updating " +
  ccDisplayDate(from) +
  " → " +
  ccDisplayDate(to) +
  "…"
 );

 try{
  const rows = await lifeClusterFastBaseRows(from, to);

  if(requestId !== LIFE_CLUSTER_FAST_REQUEST_ID){
   return;
  }

  LIFE_CLUSTER_RECORDS = rows;
  LIFE_CLUSTER_RECORDS_KEY = key;

  /*
   * FIRST PAINT NOW.
   * lifeClusterRender uses the already-resolved Area Manager map when
   * available; its Employee lookup is cached after first load.
   */
  await lifeClusterRender(rows);

  if(requestId !== LIFE_CLUSTER_FAST_REQUEST_ID){
   return;
  }

  lifeClusterFastStatus("");

  /*
   * Heavy consultant / package / financial mapping continues after
   * the visible table is already updated.
   */
  try{
   lifeClusterEnrichBackground(
    from,
    to,
    rows
   );
  }catch(error){
   console.warn(
    "Cluster background enrichment start failed",
    error
   );
  }

  console.log(
   "Cluster FAST range applied",
   {
    from,
    to,
    appointments: rows.length
   }
  );

 }catch(error){
  console.error(
   "Cluster FAST range failed",
   error
  );

  lifeClusterFastStatus(
   "Could not update selected dates."
  );

  toast(
   "Could not load Cluster Report for selected dates"
  );
 }
}


