function LIFE_CLUSTER_PRINT_ONLY(){
 const html =
  lifeClusterPrintDocumentHtml();

 if(!html){
  toast(
   "Cluster Report is not ready to print."
  );
  return;
 }

 /*
  * Remove any old print iframe.
  */
 byId("lifeClusterPrintFrame")
  ?.remove();

 const frame =
  document.createElement(
   "iframe"
  );

 frame.id =
  "lifeClusterPrintFrame";

 frame.setAttribute(
  "aria-hidden",
  "true"
 );

 frame.style.cssText = `
  position:fixed;
  width:1px;
  height:1px;
  right:0;
  bottom:0;
  opacity:0;
  border:0;
  pointer-events:none;
 `;

 document.body.appendChild(
  frame
 );

 const doc =
  frame.contentDocument ||
  frame.contentWindow.document;

 doc.open();
 doc.write(html);
 doc.close();

 const cleanup=()=>{
  setTimeout(()=>{
   frame.remove();
  },1000);
 };

 const runPrint=()=>{
  try{
   frame.contentWindow.focus();
   frame.contentWindow.print();
  }catch(error){
   console.error(
    "Cluster iframe print failed",
    error
   );

   toast(
    "Could not open Cluster Report print dialog."
   );
  }

  cleanup();
 };

 if(
  doc.readyState === "complete"
 ){
  setTimeout(
   runPrint,
   150
  );
 }else{
  frame.onload=()=>{
   setTimeout(
    runPrint,
    150
   );
  };
 }
}

window.LIFE_CLUSTER_PRINT_ONLY =
 LIFE_CLUSTER_PRINT_ONLY;

globalThis.LIFE_CLUSTER_PRINT_ONLY =
 LIFE_CLUSTER_PRINT_ONLY;


/* =====================================================================
 * INTERCEPT CLUSTER PRINT BEFORE OLD GLOBAL PRINT HANDLERS
 * ===================================================================== */

function lifeClusterCapturePrintClick(event){
 const button =
  event.target &&
  event.target.closest
   ? event.target.closest(
     "#tabv5 .life-cluster-print"
    )
   : null;

 if(!button){
  return;
 }

 /*
  * Prevent every historical/global handler.
  */
 event.preventDefault();
 event.stopPropagation();

 if(
  typeof event.stopImmediatePropagation ===
  "function"
 ){
  event.stopImmediatePropagation();
 }

 LIFE_CLUSTER_PRINT_ONLY();
}


/*
 * Capture phase is important:
 * this runs BEFORE old bubble-phase onclick handlers.
 */
document.addEventListener(
 "click",
 lifeClusterCapturePrintClick,
 true
);


/* =====================================================================
 * AFTER EVERY CLUSTER RENDER, FORCE DIRECT PRINT HANDLER TOO
 * ===================================================================== */

function lifeClusterBindDedicatedPrint(){
 const button =
  document.querySelector(
   "#tabv5 .life-cluster-print"
  );

 if(!button){
  return;
 }

 button.removeAttribute(
  "onclick"
 );

 button.onclick=function(event){
  event.preventDefault();
  event.stopPropagation();

  if(
   typeof event.stopImmediatePropagation ===
   "function"
  ){
   event.stopImmediatePropagation();
  }

  LIFE_CLUSTER_PRINT_ONLY();

  return false;
 };
}

setTimeout(
 lifeClusterBindDedicatedPrint,
