/* =====================================================================
 * CLUSTER REPORT — ZERO AREA MANAGER / LOADING FINAL FIX
 * ---------------------------------------------------------------------
 * Root cause:
 * lifeClusterEnsureAreaManagers() previously returned an empty map after
 * a 4.5-second Promise.race fallback. The real Employee request could
 * finish later, but the already-rendered zero table was never repainted.
 *
 * Fix:
 * - prefetch Area Manager map on startup
 * - never return an artificial empty map just because 4.5 sec passed
 * - retry once if an earlier failed request permanently cached an empty map
 * - never replace a populated report with "0 Area Managers" while mapping
 *   is still resolving
 * ===================================================================== */

let LIFE_CLUSTER_MANAGER_RETRY_USED = false;
let LIFE_CLUSTER_MANAGER_PREFETCH_STARTED = false;

async function lifeClusterEnsureAreaManagers(){
 /*
  * Good cached mapping.
  */
 if(
  LIFE_CLUSTER_MANAGER_MAP_READY &&
  LIFE_CLUSTER_MANAGER_MAP instanceof Map &&
  LIFE_CLUSTER_MANAGER_MAP.size
 ){
  return LIFE_CLUSTER_MANAGER_MAP;
 }

 /*
  * If an earlier API failure marked an EMPTY map as permanently ready,
  * clear that false-ready state and retry once.
  */
 if(
  LIFE_CLUSTER_MANAGER_MAP_READY &&
  (
   !(LIFE_CLUSTER_MANAGER_MAP instanceof Map) ||
   LIFE_CLUSTER_MANAGER_MAP.size === 0
  ) &&
  !LIFE_CLUSTER_MANAGER_RETRY_USED
 ){
  LIFE_CLUSTER_MANAGER_RETRY_USED = true;

  LIFE_CLUSTER_MANAGER_MAP_READY = false;
  LIFE_CLUSTER_MANAGER_MAP_PROMISE = null;
  LIFE_CLUSTER_MANAGER_MAP = new Map();

  console.warn(
   "Cluster Area Manager map was empty — retrying Employee mapping once"
  );
 }

 /*
  * Await the REAL Employee mapping request.
  * No fake 4.5-second timeout.
  */
 try{
  const map =
   await lifeClusterBuildManagerMap();

  return (
   map instanceof Map
    ? map
    : new Map()
  );

 }catch(error){
  console.warn(
   "Cluster Area Manager mapping failed",
   error
  );

  return (
   LIFE_CLUSTER_MANAGER_MAP instanceof Map
    ? LIFE_CLUSTER_MANAGER_MAP
    : new Map()
  );
 }
}


/* =====================================================================
 * MANAGER MAP PREFETCH
 * Start before the user opens / filters Cluster Report.
 * ===================================================================== */

function lifeClusterPrefetchManagerMap(){
 if(LIFE_CLUSTER_MANAGER_PREFETCH_STARTED){
  return;
 }

 LIFE_CLUSTER_MANAGER_PREFETCH_STARTED = true;

 lifeClusterEnsureAreaManagers()
  .then(map=>{
   console.log(
    "Cluster Area Manager prefetch ready",
    {
     mapped_branches:
      map instanceof Map
       ? map.size
       : 0
    }
   );

   /*
    * If Cluster is currently visible and it had previously rendered zero
    * groups, repaint immediately using the now-ready map.
    */
   const root = byId("tabv5");
   const active =
    byId("tb5") &&
    (
     byId("tb5").classList.contains("on") ||
     byId("tb5").classList.contains("active")
    );

   if(
    active &&
    Array.isArray(LIFE_CLUSTER_RECORDS) &&
    LIFE_CLUSTER_RECORDS.length
   ){
    lifeClusterRender(
     LIFE_CLUSTER_RECORDS
    ).catch(error=>{
     console.warn(
      "Cluster repaint after manager prefetch failed",
      error
     );
    });
   }
  })
  .catch(error=>{
   console.warn(
    "Cluster Area Manager prefetch failed",
    error
   );
  });
}

setTimeout(
 lifeClusterPrefetchManagerMap,
 0
);


/* =====================================================================
 * RENDER GUARD
 * Do not render false zero groups while manager map is unresolved.
 * ===================================================================== */

const LIFE_CLUSTER_RENDER_ZERO_FIX_BASE =
 lifeClusterRender;

lifeClusterRender =
 async function(records){
  const root =
   byId("tabv5");

  if(!root){
   return;
  }

  const rowsInput =
   Array.isArray(records)
    ? records
    : [];

  /*
   * No appointments really means zero is valid.
   */
  if(!rowsInput.length){
   return LIFE_CLUSTER_RENDER_ZERO_FIX_BASE(
    rowsInput
   );
  }

  /*
   * Manager map must be resolved before we convert appointment rows
   * into Area Manager employee groups.
   */
  let managerMap =
   LIFE_CLUSTER_MANAGER_MAP instanceof Map
    ? LIFE_CLUSTER_MANAGER_MAP
    : new Map();

  if(
   !LIFE_CLUSTER_MANAGER_MAP_READY ||
   managerMap.size === 0
  ){
   /*
    * KEEP CURRENT TABLE VISIBLE.
    * Add only a small status note instead of replacing it with zeros.
    */
   byId("lifeClusterManagerWaitStatus")
    ?.remove();

   const status =
    document.createElement("div");

   status.id =
    "lifeClusterManagerWaitStatus";

   status.textContent =
    "Resolving Area Manager branch mapping…";

   status.style.cssText =
    "margin:5px 0 6px;padding:5px 8px;border:1px solid #d7e3d0;border-radius:7px;background:#f8fbf5;color:#54675a;font-size:9px;font-weight:750;";

   const bar =
    root.querySelector(
     ".life-cluster-date-bar"
    );

   if(bar){
    bar.insertAdjacentElement(
     "afterend",
     status
    );
   }else if(
    !root.querySelector(
     ".life-cluster-report-shell"
    )
   ){
    root.prepend(status);
   }

   managerMap =
    await lifeClusterEnsureAreaManagers();

   status.remove();
  }

  /*
   * If manager mapping is genuinely still empty, do NOT manufacture
   * a false zero report from valid appointment rows.
   */
  if(
   !(managerMap instanceof Map) ||
   managerMap.size === 0
  ){
   const existing =
    root.querySelector(
     ".life-cluster-report-shell"
    );

   if(existing){
    const note =
     document.createElement("div");

    note.id =
     "lifeClusterManagerMappingError";

    note.style.cssText =
     "margin:5px 0 6px;padding:7px 9px;border:1px solid #efcf9c;border-radius:7px;background:#fff9ec;color:#72521b;font-size:9px;font-weight:750;";

    note.textContent =
     "Area Manager mapping is still loading. Existing report is kept on screen.";

    existing.prepend(note);

    return;
   }
  }

  return LIFE_CLUSTER_RENDER_ZERO_FIX_BASE(
   rowsInput
  );
 };


