/* =====================================================================
 * CLUSTER REPORT — CALL CENTER SALES ONLY + PAID FIX + CLEAN COLUMNS
 * ---------------------------------------------------------------------
 * Financial rules:
 * - only Therapy Plan media = Call Center
 * - Already Taken = No
 * - New Package With GST = new Call Center package amount
 * - Paid Amount = New Package Paid + Old Package Paid
 * - Balance Amount = new Call Center package balance
 *
 * Removed table columns:
 * - Total Appointment
 * - Visit Pending
 * - Not Booked
 * - Not Visited
 * ===================================================================== */

function lifeClusterExactCcRows(){
 const key =
  lifeClusterRangeKey(
   LIFE_CLUSTER_FILTER.from,
   LIFE_CLUSTER_FILTER.to
  );

 const summary =
  CC_INVOICE_REPORT_SUMMARY_MAP.get(key);

 let rows =
  summary &&
  Array.isArray(summary.rows)
   ? summary.rows.filter(
     isStrictCallCenterPackageRow
    )
   : [];

 /*
  * Area Manager login safety.
  */
 if(
  typeof LIFE_AREA_MANAGER_SCOPE !== "undefined" &&
  LIFE_AREA_MANAGER_SCOPE &&
  LIFE_AREA_MANAGER_SCOPE.isAreaManager
 ){
  rows = rows.filter(row=>
   lifeAreaManagerBranchAllowed(
    row && (
     row.lead_branch ||
     row.branch ||
     row.invoice_branch ||
     row.custom_branch ||
     ""
    )
   )
  );
 }

 return rows;
}


function lifeClusterCallCenterFinancials(groupRows){
 const rows =
  Array.isArray(groupRows)
   ? groupRows
   : [];

 const exactRows =
  lifeClusterExactCcRows();

 if(!rows.length || !exactRows.length){
  return {
   withGst:0,
   withoutGst:0,
   paid:0,
   newPackagePaid:0,
   oldPackagePaid:0,
   balance:0
  };
 }

 const invoiceIds = new Set();
 const therapyPlans = new Set();
 const consultantKeys = new Set();

 rows.forEach(record=>{
  [
   record && record.salesInvoiceName,
   record && record.financial_sales_invoice,
   record && record.sales_invoice
  ].forEach(value=>{
   const clean = consultantClean(value);
   if(clean) invoiceIds.add(clean);
  });

  [
   record && record.consultantTherapyPlanName,
   record && record.therapyPlanName,
   record && record.therapy_plan,
   record && record.financial_therapy_plan
  ].forEach(value=>{
   const clean = consultantClean(value);
   if(clean) therapyPlans.add(clean);
  });

  [
   record && record.consultantEmployeeName,
   record && record.clientConsultant,
   record && record.cons,
   record && record.consultantEmployeeId
  ].forEach(value=>{
   const clean = consultantClean(value);

   if(
    clean &&
    clean !== "—" &&
    clean !== "Consultant Unmapped"
   ){
    consultantKeys.add(
     consultantKeyPart(clean)
    );
   }
  });
 });

 /*
  * Current/new packages:
  * exact invoice or therapy-plan match only.
  */
 const currentMatches =
  exactRows.filter(row=>{
   const invoice =
    consultantClean(
     row && (
      row.invoice ||
      row.sales_invoice ||
      row.name
     )
    );

   const therapyPlan =
    consultantClean(
     row && (
      row.therapy_plan ||
      row.therapy_plan_reference_id ||
      row.custom_therapy_plan
     )
    );

   return (
    (invoice && invoiceIds.has(invoice)) ||
    (therapyPlan && therapyPlans.has(therapyPlan))
   );
  });

 const matchedKeys =
  new Set(
   currentMatches.map(row=>{
    const invoice =
     consultantClean(
      row && (
       row.invoice ||
       row.sales_invoice ||
       row.name
      )
     );

    const paymentRef =
     consultantClean(
      row && (
       row.payment_entry ||
       row.payment_reference ||
       row.reference_name
      )
     );

    return invoice + "|" + paymentRef;
   })
  );

 /*
  * Old Call Center package collections:
  * invoice was created before Cluster From Date but payment belongs to
  * the same consultant/employee identity.
  */
 const oldMatches =
  exactRows.filter(row=>{
   const invoiceDate =
    String(
     row && row.invoice_date || ""
    ).slice(0,10);

   const paid =
    Math.max(
     Number(row && row.paid || 0),
     0
    );

   if(
    !invoiceDate ||
    invoiceDate >= LIFE_CLUSTER_FILTER.from ||
    !paid
   ){
    return false;
   }

   const candidates = [
    row && row.cc_agent,
    row && row.agent_name,
    row && row.consultant,
    row && row.consultant_name,
    row && row.consultant_employee,
    row && row.employee_name,
    row && row.lead_owner
      ? (
        AGENT_NAME[row.lead_owner] ||
        agName(row.lead_owner)
       )
      : ""
   ];

   const consultantMatch =
    candidates.some(value=>{
     const clean =
      consultantClean(value);

     return (
      clean &&
      consultantKeys.has(
       consultantKeyPart(clean)
      )
     );
    });

   if(!consultantMatch){
    return false;
   }

   const invoice =
    consultantClean(
     row && (
      row.invoice ||
      row.sales_invoice ||
      row.name
     )
    );

   const paymentRef =
    consultantClean(
     row && (
      row.payment_entry ||
      row.payment_reference ||
      row.reference_name
     )
    );

   return !matchedKeys.has(
    invoice + "|" + paymentRef
   );
  });

 const totals =
  ccInvoicePackageSplitTotals(
   currentMatches.concat(
    oldMatches
   )
  );

 /*
  * CLUSTER FINANCIAL FALLBACK
  * --------------------------
  * Some Cluster appointment rows already contain the exact linked
  * Sales Invoice / Therapy Plan amounts, but the CC Invoice summary
  * join can miss the invoice/therapy-plan key. In that case the old
  * code returned ₹0 for Package With GST and Balance Amount even while
  * Paid Amount was visible.
  *
  * Reconcile the strict Call Center summary with the secure appointment
  * row financial fields and keep the larger valid amount per metric.
  * De-duplicate by invoice / therapy plan so one invoice is not counted
  * more than once when there are multiple appointment rows.
  */
 const recordTotals = {
  withGst:0,
  withoutGst:0,
  paid:0,
  balance:0
 };

 const seenRecordFinancialKeys = new Set();

 rows.forEach(record=>{
  if(!record)return;

  const invoice = consultantClean(
   record.salesInvoiceName ||
   record.financial_sales_invoice ||
   record.sales_invoice ||
   ""
  );

  const therapyPlan = consultantClean(
   record.consultantTherapyPlanName ||
   record.therapyPlanName ||
   record.therapy_plan ||
   record.financial_therapy_plan ||
   ""
  );

  const uniqueKey =
   invoice ||
   therapyPlan ||
   consultantClean(record.name || "");

  if(uniqueKey && seenRecordFinancialKeys.has(uniqueKey)){
   return;
  }

  if(uniqueKey){
   seenRecordFinancialKeys.add(uniqueKey);
  }

  recordTotals.withGst += Math.max(
   Number(
    record.clientPackageAmountWithGst ||
    record.financial_with_gst ||
    0
   ),
   0
  );

  recordTotals.withoutGst += Math.max(
   Number(
    record.clientPackageAmountWithoutGst ||
    record.clientPackageAmount ||
    record.financial_without_gst ||
    0
   ),
   0
  );

  recordTotals.paid += Math.max(
   Number(
    record.clientPaidAmount ||
    record.financial_paid_amount ||
    record.paid_amount ||
    0
   ),
   0
  );

  recordTotals.balance += Math.max(
   Number(
    record.clientBalanceAmount ||
    record.financial_balance_amount ||
    record.outstanding_amount ||
    0
   ),
   0
  );
 });

 const withGst = Math.max(
  Number(totals.withGst || 0),
  Number(recordTotals.withGst || 0)
 );

 const withoutGst = Math.max(
  Number(totals.withoutGst || 0),
  Number(recordTotals.withoutGst || 0)
 );

 const newPackagePaid = Math.max(
  Number(totals.paid || 0),
  Number(recordTotals.paid || 0)
 );

 const oldPackagePaid =
  Number(totals.oldPackagePaid || 0);

 /*
  * Balance Amount must be the CURRENT/NEW package outstanding only.
  * Do not trust clientBalanceAmount / financial_balance_amount here because
  * some Cluster rows carry the full package amount in those fields. That is
  * why Package With GST and Balance were appearing identical.
  *
  * Correct rule:
  *   Balance Amount = New Package With GST - New Package Paid
  * Old-package collections are intentionally excluded from this calculation.
  */
 const balance = Math.max(
  Number(withGst || 0) -
  Number(newPackagePaid || 0),
  0
 );

 return {
  withGst,

  withoutGst,

  newPackagePaid,

  oldPackagePaid,

  /*
   * Paid Amount = New Package Paid + Old Package Paid
   */
  paid:
   newPackagePaid +
   oldPackagePaid,

  balance
 };
}


/*
 * Authoritative Cluster financial helper.
 * No record-level fallback from non-Call-Center sales.
 */
lifeClusterFinancials =
 function(rows){
  return lifeClusterCallCenterFinancials(
   rows
  );
 };


