   ["Paid Amount (New + Old)", dashboardMoney(totals.financial.paid)],
   ["Balance Amount", dashboardMoney(totals.financial.balance)],
   ["Avg Ticket", dashboardMoney(totals.ticket || 0)],
   ["Joining Ratio", totals.joiningRatio + "%"]
  ];

  const body = [];
  let previousManager = "";

  rows.forEach(row=>{
   const same =
    previousManager === row.managerId;

   const rowspan =
    same
     ? 0
     : rows.filter(
       item =>
        item.managerId === row.managerId
      ).length;

   previousManager =
    row.managerId;

   body.push(`
