    </div>

    ${lifeClusterDateControlsHtml()}

    <div class="life-cluster-kpis">
     ${
      cards.map(([label,value])=>`
       <div class="life-cluster-card">
        <b>${value}</b>
        <span>${label}</span>
       </div>
      `).join("")
     }
    </div>

    <div class="life-cluster-summary-head">
     <h3>
      👥 Area Manager Employee Summary
     </h3>

     <span>
      ${rows.length}
      employee group${rows.length===1?"":"s"}
     </span>
    </div>

    <div class="life-cluster-table-wrap">
     <table class="life-cluster-table">
      <colgroup>
       <col style="width:12%">
