    function arrangeAgentBranchTable(){
        const headings = Array.from(
            document.querySelectorAll("h1,h2,h3,h4,h5,.section-title,.card-title")
        );

        const heading = headings.find(el =>
            /Branch-wise Appointment Report/i.test(el.textContent || "")
        );

        if (!heading) return;

        let box = heading.closest(
            ".card,.card2,.panel,.report-card,.agent-section,section"
        );

        if (!box) box = heading.parentElement?.parentElement;
        if (!box) return;

        const table = box.querySelector("table");
        if (!table) return;

        box.classList.add("life-agent-branch-report");
        table.classList.add("life-agent-branch-table");

        const wrap = table.closest(".table-responsive") || table.parentElement;
        if (wrap) wrap.classList.add("agent-branch-table-wrap");

        /* Keep existing sort behavior but clean the visible header text. */
        const labels = [
            "Branch",
            "Appointments",
            "Visited",
            "Booked",
            "Not Booked",
            "Not Visited",
            "With GST",
            "Without GST",
            "Paid",
            "Balance",
            "Booking %"
        ];

        const headers = table.querySelectorAll("thead th");

        labels.forEach((label, i) => {
            const th = headers[i];
            if (!th) return;

            /* Run only once per rendered header cell so sort listeners/elements survive. */
            if (th.dataset.lifeAgentHeaderFixed === "1") return;
            th.dataset.lifeAgentHeaderFixed = "1";

            const existingText = (th.textContent || "").trim();
            const arrowText = /▲/.test(existingText) ? " ▲" : /▼/.test(existingText) ? " ▼" : "";
            const keepNodes = Array.from(th.children).filter(el =>
                el.matches("button,.sort-icon,.sort-indicator,.sorting,[data-sort],svg")
            );

            th.childNodes.forEach(node => {
                if (!keepNodes.includes(node)) {
                    try { node.remove(); } catch(e) {}
                }
            });

            th.insertAdjacentText("afterbegin", label + arrowText);
            keepNodes.forEach(node => {
                if (!th.contains(node)) th.appendChild(node);
            });
        });
    }

    arrangeAgentBranchTable();
    setTimeout(arrangeAgentBranchTable, 500);
    setTimeout(arrangeAgentBranchTable, 1500);
    setTimeout(arrangeAgentBranchTable, 3000);

