    const observer = new MutationObserver(() => {
        clearTimeout(window.__lifeAgentBranchArrangeTimer);
        window.__lifeAgentBranchArrangeTimer = setTimeout(arrangeAgentBranchTable, 120);
    });

    observer.observe(document.body, {
        childList:true,
        subtree:true
    });

})();

