 function cleanName(value){
  return String(value || "")
   .toLowerCase()
   .replace(/[^a-z0-9]+/g, "")
   .trim();
 }

 function managerDisplayName(employee){
  return String(
   employee && (
    employee.employee_name ||
    employee.name ||
    ""
   ) || ""
  ).trim();
 }

 function findManagerObject(map, wantedName){
  const wanted = cleanName(wantedName);
  const values = [];

  if(map instanceof Map){
   map.forEach(value => {
    if(value && !values.includes(value)) values.push(value);
   });
  }

  const found = values.find(employee => {
   return cleanName(managerDisplayName(employee)) === wanted;
  });

  if(found) return found;

  /*
   * Fallback object is enough for the Cluster renderer because it uses
   * name / employee_name / designation only. The real Employee object is
   * preferred whenever available.
   */
  return {
   name: "LIFE-AREA-" + wanted.toUpperCase(),
   employee_name: wantedName,
   designation: "Area Manager",
   status: "Active"
  };
 }

 function applyRequiredMap(inputMap){
  const map = inputMap instanceof Map ? inputMap : new Map();

  REQUIRED.forEach(rule => {
   const manager = findManagerObject(map, rule.manager);

   rule.branches.forEach(branch => {
    const key = normalizedBranchKey(branch || "");
    if(!key) return;

    /* Required mapping overrides any stale Employee branch mapping. */
    map.set(key, manager);
   });
  });

  LIFE_CLUSTER_MANAGER_MAP = map;
  LIFE_CLUSTER_MANAGER_MAP_READY = true;

  try{
   console.table(
    REQUIRED.flatMap(rule =>
     rule.branches.map(branch => ({
      branch,
      normalized_branch: normalizedBranchKey(branch),
      area_manager: rule.manager
     }))
    )
   );
  }catch(e){}

  return map;
 }

 /* Wrap the Employee-map builder. */
 const originalBuild = lifeClusterBuildManagerMap;
 lifeClusterBuildManagerMap = async function(){
  const map = await originalBuild();
  return applyRequiredMap(map);
 };

 /*
  * Also wrap ensure(), because an already-cached map can otherwise bypass
  * lifeClusterBuildManagerMap completely.
  */
 const originalEnsure = lifeClusterEnsureAreaManagers;
 lifeClusterEnsureAreaManagers = async function(){
  let map;

  try{
   map = await originalEnsure();
  }catch(error){
   console.warn("Cluster manager ensure failed; applying fixed mapping", error);
   map = LIFE_CLUSTER_MANAGER_MAP instanceof Map
    ? LIFE_CLUSTER_MANAGER_MAP
    : new Map();
  }

  return applyRequiredMap(map);
 };

 /* Apply immediately to a map that may already have been built. */
 if(LIFE_CLUSTER_MANAGER_MAP instanceof Map && LIFE_CLUSTER_MANAGER_MAP.size){
  applyRequiredMap(LIFE_CLUSTER_MANAGER_MAP);
 }

