 * Hima Bindu : SR Nagar, Banjara Hills, Himayathnagar, Dilsukhnagar
 * Teena Mahur: Madhapur, Kukatpally, Gachibowli, Chandanagar
 * PREETHI M  : Vijayawada, Nellore
 * NAVYA      : Vizag
 *
 * It also keeps branch rows when Consultant Employee is not populated,
 * instead of silently dropping those appointments.
 * ===================================================================== */

const LIFE_CLUSTER_FIXED_AREA_RULES = [
 {
  managerName:"Kesagani Hima Bindu",
  designation:"Area Manager (Trainee)",
  branches:["SR Nagar","Banjara Hills","Himayathnagar","Dilsukhnagar"],
  aliases:["SR N","Himayatnagar"]
 },
 {
