  aliases:[]
 }
];

function lifeClusterFixedCleanName(value){
 return String(value||"")
  .toLowerCase()
  .replace(/[^a-z0-9]+/g,"")
  .trim();
}

function lifeClusterFixedBranchKey(value){
 const raw = String(value||"").trim();
 const direct = normalizedBranchKey(raw);

 /* Explicit spelling aliases used in ERP records. */
 const aliases = {
  "srnagar":"srnagar",
  "srn":"srnagar",
  "himayatnagar":"himayathnagar",
  "himayathnagar":"himayathnagar",
  "chandanagar":"chandanagar",
  "chandhanagar":"chandanagar"
 };

 return aliases[direct] || direct;
}

const LIFE_CLUSTER_FIXED_BRANCH_TO_RULE = new Map();
LIFE_CLUSTER_FIXED_AREA_RULES.forEach(rule=>{
 [...rule.branches,...(rule.aliases||[])].forEach(branch=>{
  const key = lifeClusterFixedBranchKey(branch);
  if(key) LIFE_CLUSTER_FIXED_BRANCH_TO_RULE.set(key,rule);
 });
});

function lifeClusterFindRealAreaManager(managerMap, rule){
 const wanted = lifeClusterFixedCleanName(rule.managerName);
 let found = null;

 if(managerMap instanceof Map){
  managerMap.forEach(employee=>{
   if(found || !employee) return;
   const candidate = lifeClusterFixedCleanName(
    employee.employee_name || employee.name || ""
   );
   if(candidate === wanted) found = employee;
  });
 }

 return found || {
  name:"LIFE-FIXED-AREA-" + wanted.toUpperCase(),
  employee_name:rule.managerName,
  designation:rule.designation || "Area Manager",
  status:"Active"
 };
}

function lifeClusterResolveManagerForBranch(branchValue, managerMap){
 const branchKey = lifeClusterFixedBranchKey(branchValue);
 const fixedRule = LIFE_CLUSTER_FIXED_BRANCH_TO_RULE.get(branchKey);

 if(fixedRule){
  return {
   employee:lifeClusterFindRealAreaManager(managerMap,fixedRule),
   rule:fixedRule,
   branchKey
  };
 }

 /* Keep legacy Employee mapping only for branches not covered above. */
 const employee = managerMap instanceof Map
  ? (managerMap.get(branchKey) || managerMap.get(normalizedBranchKey(branchValue)))
  : null;

 if(!employee) return null;

 return {
  employee,
  rule:{
   managerName:lifeClusterManagerLabel(employee),
   designation:String(employee.designation||"Area Manager"),
   branches:[consultantBranchLabel(branchValue)],
   aliases:[]
  },
  branchKey
 };
}

/*
 * Replace the final Cluster grouping function itself.
 * This is the important part: branch ownership is resolved HERE, while
 * rows are being built, so no earlier cached manager map can undo it.
 */
lifeClusterRows = function(records, managerMap){
 const groups = new Map();

 (records || []).forEach(record=>{
  const rawBranch = record && record.br || "";
  const resolution = lifeClusterResolveManagerForBranch(rawBranch,managerMap);
  if(!resolution) return;

  const areaManager = resolution.employee;
  const rule = resolution.rule;
  const branchKey = resolution.branchKey;

  /*
   * Do NOT drop a branch just because Consultant Employee is blank.
   * Keep one explicit Unmapped group per branch so Area Manager totals
   * and branch coverage remain correct.
   */
  let consultantKey = lifeClusterConsultantKey(record);
  if(!consultantKey){
   consultantKey = "UNMAPPED:" + branchKey;
  }

  const managerId = "FIXED:" + lifeClusterFixedCleanName(rule.managerName);
  const groupKey = managerId + "|" + consultantKey;

  if(!groups.has(groupKey)){
   const employeeName = lifeClusterConsultantName(record);

   groups.set(groupKey,{
    key:groupKey,
    managerId,
    managerName:rule.managerName,
    managerDesignation:String(
     areaManager.designation || rule.designation || "Area Manager"
    ).trim(),
    managerBranches:[...(rule.branches||[])],
    employeeName:
     employeeName && employeeName !== "Consultant Unmapped"
      ? employeeName
      : "Consultant Unmapped — " + consultantBranchLabel(rawBranch),
    designation:
     consultantClean(record && record.consultantDesignation) || "—",
    branches:new Set(),
    records:[]
   });
  }

  const group = groups.get(groupKey);
  group.records.push(record);
  group.branches.add(consultantBranchLabel(rawBranch));
 });

 return [...groups.values()]
  .map(group=>{
   const rows = group.records;
   const booked = rows.filter(r=>r.cat===CATS[0]).length;
   const notBooked = rows.filter(r=>r.cat===CATS[1]).length;
   const notVisited = rows.filter(r=>r.cat===CATS[2]).length;
   const pending = rows.filter(r=>r.cat===CATS[7]).length;
   const totalVisits = booked + notBooked;
   const walkins = rows.filter(lifeClusterIsWalkin).length;
   const financial = lifeClusterFinancials(rows);
   const ticket = booked>0
    ? Number(financial.withGst||0)/booked
    : 0;

   return {
    ...group,
    branches:[...group.branches]
     .filter(Boolean)
     .sort((a,b)=>a.localeCompare(b,"en",{sensitivity:"base"})),
    appointments:rows.length,
    pending,
    totalVisits,
    booked,
    notBooked,
    notVisited,
    financial,
    joiningRatio:walkins>0
     ? Math.round(booked/walkins*100)
     : 0,
    ticket
   };
  })
  .sort((a,b)=>{
   const managerOrder = LIFE_CLUSTER_FIXED_AREA_RULES.findIndex(
    rule=>lifeClusterFixedCleanName(rule.managerName)===lifeClusterFixedCleanName(a.managerName)
   ) - LIFE_CLUSTER_FIXED_AREA_RULES.findIndex(
    rule=>lifeClusterFixedCleanName(rule.managerName)===lifeClusterFixedCleanName(b.managerName)
   );

   if(managerOrder) return managerOrder;

   return (
    b.appointments-a.appointments ||
    a.employeeName.localeCompare(b.employeeName,"en",{sensitivity:"base"})
   );
  });
};

