/* =====================================================================
 * FINAL 3M PERIOD FILTER
 * ---------------------------------------------------------------------
 * Adds two period modes to "Last 3 Business Months Comparison":
 *
 * 1) Business Month-wise
 *    JUL: 06-Jul -> 05-Aug
 *    AUG: 06-Aug -> 05-Sep
 *    SEP: 06-Sep -> current/end date
 *
 * 2) Date-wise
 *    Uses the CURRENT main report From/To DAY numbers for every month.
 *    Example main report = 06-Sep -> 22-Sep:
 *      JUL: 06-Jul -> 22-Jul
 *      AUG: 06-Aug -> 22-Aug
 *      SEP: 06-Sep -> 22-Sep
 * ===================================================================== */

let LIFE_3M_PERIOD_MODE = "business";

function life3mPeriodMainRange(){
 const from = String(
  (byId("fFrom") && byId("fFrom").value) ||
  (typeof F !== "undefined" && F && F.from) ||
  ""
 ).trim();

 const to = String(
  (byId("fTo") && byId("fTo").value) ||
  (typeof F !== "undefined" && F && F.to) ||
  ""
 ).trim();

 return {from,to};
}

function life3mPeriodInvalidate(){
 /* Full-data cache stores datasets with the cycle ranges embedded. */
 LIFE_3M_FULL_DATA = null;
 LIFE_3M_FULL_DATA_KEY = "";
 LIFE_3M_FULL_DATA_PROMISE = null;

 /* Older comparison caches, if present, must not repaint stale ranges. */
 try{ LIFE_3M_FAST_CACHE = null; }catch(e){}
 try{ LIFE_3M_FAST_CACHE_KEY = ""; }catch(e){}
 try{ LIFE_3M_FAST_PROMISE = null; }catch(e){}
 try{ LIFE_3M_LAST_RENDER_KEY = ""; }catch(e){}
 try{ LIFE_3M_SEP_DATA = null; }catch(e){}
 try{ LIFE_3M_SEP_KEY = ""; }catch(e){}
 try{ LIFE_3M_SEP_PROMISE = null; }catch(e){}

 LIFE_3M_MODE_RENDER_TOKEN++;
}

function life3mPeriodApply(mode){
 LIFE_3M_PERIOD_MODE = mode === "date" ? "date" : "business";

 if(LIFE_3M_PERIOD_MODE === "date"){
  const range = life3mPeriodMainRange();

  if(!range.from || !range.to){
   toast("Select the main From Date and To Date first");
   LIFE_3M_PERIOD_MODE = "business";
   LIFE_3M_FILTER_FROM = "";
   LIFE_3M_FILTER_TO = "";
  }else{
   LIFE_3M_FILTER_FROM = range.from;
   LIFE_3M_FILTER_TO = range.to;
  }
 }else{
  LIFE_3M_FILTER_FROM = "";
  LIFE_3M_FILTER_TO = "";
 }

 life3mPeriodInvalidate();

 const currentMode = life3mModeNormalize(GRP);
 life3mModeShell(currentMode);
 life3mModeLoad(currentMode,false);
