 const tp = String(range.to||"").split("-");
 const fd = Number(fp[2]||0);
 const td = Number(tp[2]||0);

 if(!fd || !td){
  return "Date-wise";
 }

 return "Date-wise · same " +
  String(fd).padStart(2,"0") +
  " → " +
  String(td).padStart(2,"0") +
  " dates in every month";
}

