 /* Repaint active Cluster tab immediately after this final override. */
 setTimeout(async function(){
  try{
   const tab = byId("tb5");
   const isActive = tab && (
    tab.classList.contains("on") ||
    tab.classList.contains("active")
   );

   if(isActive && Array.isArray(LIFE_CLUSTER_RECORDS)){
    await lifeClusterRender(LIFE_CLUSTER_RECORDS);
   }
  }catch(error){
   console.warn("Cluster unmapped-row hide repaint failed", error);
  }
 }, 100);
})();
